// =============================================================================
// 青空文庫＆文書 AI朗読プレイヤー - クライアントアプリケーション (app.js)
// =============================================================================

// ==============================================
// 1. プラットフォーム検出 & グローバルステート管理
// ==============================================
const isAndroidApp = !!(
  typeof window !== 'undefined' &&
  window.AndroidBridge &&
  typeof window.AndroidBridge.isAndroidApp === 'function' &&
  window.AndroidBridge.isAndroidApp()
);
/** 起動直後の注入レース対策: 呼び出し時点で再判定 */
function isAndroidAppNow() {
  try {
    return !!(
      typeof window !== 'undefined' &&
      window.AndroidBridge &&
      typeof window.AndroidBridge.isAndroidApp === 'function' &&
      window.AndroidBridge.isAndroidApp()
    );
  } catch (e) {
    return false;
  }
}
const isIOSDevice = typeof navigator !== 'undefined' && (
  /iPad|iPhone|iPod/.test(navigator.userAgent || '') ||
  (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1)
);
const isIOSStandalonePWA = isIOSDevice && typeof window !== 'undefined' && (
  window.navigator.standalone === true ||
  (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) ||
  window.location.search.includes('ios_app=1')
);
const isStandaloneMode = isAndroidApp || isAndroidAppNow() || (typeof window !== 'undefined' && (window.location.protocol === 'file:' || window.location.hostname.endsWith('github.io') || window.location.search.includes('standalone=1')));

// iOS Safari / WebClip 向け Web Speech API 初回タッチアンロック
if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
  let _iosSpeechUnlocked = false;
  const unlockIOSSpeech = () => {
    if (_iosSpeechUnlocked) return;
    _iosSpeechUnlocked = true;
    try {
      if (window.speechSynthesis.paused) window.speechSynthesis.resume();
      window.speechSynthesis.getVoices();
    } catch (_) {}
  };
  window.addEventListener('touchstart', unlockIOSSpeech, { passive: true, once: true });
  window.addEventListener('click', unlockIOSSpeech, { passive: true, once: true });
}

console.log(`[NarouAIReader] Platform Mode: ${isAndroidAppNow() ? 'Android Native App' : (isStandaloneMode ? 'Standalone Client' : 'Web/Server Connected')}`);

/** 探すタブ等の小説ダウンロード同時実行ロック（同時に1件まで） */
const NovelDownloadGate = {
  activeNcode: null,
  activeBtnEl: null,
  abortRequested: false,
  tryAcquire(ncode, btnEl = null) {
    const key = String(ncode || '').toLowerCase();
    if (!key) return false;
    if (this.activeNcode) {
      const label = this.activeNcode.toUpperCase();
      const same = this.activeNcode === key;
      if (typeof showToast === 'function') {
        showToast(
          same
            ? `『${label}』はすでにダウンロード中です。完了までお待ちください`
            : `別の作品（${label}）をダウンロード中です。完了後に再度お試しください`,
          'warning'
        );
      } else if (typeof showMiniToast === 'function') {
        showMiniToast(same ? `ダウンロード中（${label}）` : `別作品ダウンロード中（${label}）`);
      }
      return false;
    }
    this.activeNcode = key;
    this.activeBtnEl = btnEl || null;
    this.abortRequested = false;
    this.setSearchDownloadButtonsDisabled(true);
    return true;
  },
  release(ncode) {
    const key = String(ncode || '').toLowerCase();
    if (!this.activeNcode) return;
    if (key && this.activeNcode !== key) return;
    this.activeNcode = null;
    this.activeBtnEl = null;
    this.abortRequested = false;
    this.setSearchDownloadButtonsDisabled(false);
    hideSearchDownloadLiveBanner();
  },
  requestAbort() {
    if (!this.activeNcode) return false;
    this.abortRequested = true;
    return true;
  },
  shouldAbort() {
    return !!this.abortRequested;
  },
  isBusy() {
    return !!this.activeNcode;
  },
  setSearchDownloadButtonsDisabled(disabled) {
    const mainBtn = document.getElementById('downloadNovelBtn');
    if (mainBtn) {
      mainBtn.disabled = !!disabled;
      mainBtn.classList.toggle('opacity-60', !!disabled);
      mainBtn.classList.toggle('pointer-events-none', !!disabled);
    }
    document.querySelectorAll('button[onclick*="downloadNovelDirect"], button[onclick*="downloadAozoraNovelDirect"]').forEach((btn) => {
      const isActiveBtn = this.activeBtnEl && btn === this.activeBtnEl;
      if (disabled) {
        if (!btn.dataset.dlLockPrevDisabled) {
          btn.dataset.dlLockPrevDisabled = btn.disabled ? '1' : '0';
        }
        if (!isActiveBtn) {
          btn.disabled = true;
          btn.classList.add('opacity-60');
        } else {
          // 進行中ボタンは見えるように残す
          btn.disabled = true;
          btn.classList.remove('opacity-60');
          btn.classList.add('ring-1', 'ring-emerald-500/50');
        }
      } else {
        const prev = btn.dataset.dlLockPrevDisabled;
        if (prev === '0') btn.disabled = false;
        delete btn.dataset.dlLockPrevDisabled;
        btn.classList.remove('ring-1', 'ring-emerald-500/50');
        if (!btn.innerHTML.includes('保存済')) {
          btn.classList.remove('opacity-60');
        }
      }
    });
  }
};

function cancelActiveNovelDownload() {
  if (!NovelDownloadGate.isBusy()) {
    if (typeof showMiniToast === 'function') showMiniToast('現在ダウンロード中の作品はありません');
    return;
  }
  NovelDownloadGate.requestAbort();
  if (typeof showMiniToast === 'function') showMiniToast('ダウンロードを中止しています…');
  if (typeof reportNovelDownloadProgress === 'function') {
    reportNovelDownloadProgress({
      ncode: NovelDownloadGate.activeNcode,
      statusText: '中止処理中（保存済み話は保持されます）…',
      phase: 'running'
    });
  }
  // バナーの中止ボタンを無効化
  const cancelBtn = document.getElementById('btnCancelNovelDownload');
  if (cancelBtn) {
    cancelBtn.disabled = true;
    cancelBtn.textContent = '中止中…';
  }
  const tocCancel = document.getElementById('btnCancelNovelDownloadToc');
  if (tocCancel) {
    tocCancel.disabled = true;
    tocCancel.textContent = '中止中…';
  }
}

/** 保存済タブの過剰リロード防止 */
let _downloadsRefreshTimer = null;
function scheduleDownloadsTabRefresh(delayMs = 400) {
  if (_downloadsRefreshTimer) clearTimeout(_downloadsRefreshTimer);
  _downloadsRefreshTimer = setTimeout(() => {
    _downloadsRefreshTimer = null;
    if (typeof loadDownloadsData === 'function') {
      loadDownloadsData(true).catch(() => {});
    }
  }, delayMs);
}

/**
 * 1話以上保存された時点で小説を「保存済」に登録し、保存済タブへ反映する
 */
async function persistPartialDownloadToLibrary(novel, downloadedCount) {
  if (!novel || !novel.ncode) return;
  try {
    const count = Math.max(0, Number(downloadedCount) || 0);
    if (count < 1) return;
    const patch = {
      ...novel,
      is_downloaded: true,
      downloaded_episodes: count,
      saved_at: novel.saved_at || Date.now()
    };
    await NarouIDB.saveNovel(patch, true);
    scheduleDownloadsTabRefresh(300);
  } catch (e) {
    console.warn('[Download] persistPartialDownloadToLibrary failed:', e);
  }
}

/**
 * ダウンロード進捗の単一更新入口（目次UI + 探すカード + ライブバナー）
 */
function reportNovelDownloadProgress(info = {}) {
  const ncode = String(info.ncode || NovelDownloadGate.activeNcode || '').toLowerCase();
  const startEp = Math.max(1, Number(info.startEp) || 1);
  const endEp = Math.max(startEp, Number(info.endEp) || startEp);
  const currentEp = Math.max(startEp, Number(info.currentEp) || startEp);
  const downloadedCount = Number(info.downloadedCount) || 0;
  const totalSpan = Math.max(1, endEp - startEp + 1);
  const pct = Number.isFinite(info.pct)
    ? Math.max(0, Math.min(100, Math.round(info.pct)))
    : Math.max(0, Math.min(100, Math.round(((currentEp - startEp + 1) / totalSpan) * 100)));
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = uiLang === 'ja';
  const statusText = info.statusText
    || (info.phase === 'done'
      ? (isJa ? `✔ ${downloadedCount}話の取得が完了しました` : `✔ Downloaded ${downloadedCount} ep.`)
      : (isJa ? `第${currentEp}話 / 全${endEp}話を取得中…` : `Downloading Ep. ${currentEp} / ${endEp}…`));
  const counterText = info.counterText || (isJa ? `${downloadedCount} / ${endEp}話完了` : `${downloadedCount} / ${endEp}`);

  // 目次タブの進捗バー
  const progressBarFill = document.getElementById('downloadProgressBarFill');
  const percentLabel = document.getElementById('downloadPercentLabel');
  const statusLabel = document.getElementById('downloadStatusLabel');
  const epProgressLabel = document.getElementById('downloadEpisodeCounter')
    || document.getElementById('downloadEpisodeProgress');
  const progressContainer = document.getElementById('downloadProgressBarContainer');
  if (progressContainer && info.phase !== 'idle') {
    progressContainer.classList.remove('hidden');
  }
  const tocCancelBtn = document.getElementById('btnCancelNovelDownloadToc');
  if (tocCancelBtn) {
    const showTocCancel = info.phase === 'running' && NovelDownloadGate.isBusy();
    tocCancelBtn.classList.toggle('hidden', !showTocCancel);
    if (showTocCancel && !NovelDownloadGate.shouldAbort()) {
      tocCancelBtn.disabled = false;
      tocCancelBtn.textContent = isJa ? '中止' : ({ en: 'Cancel', zh: '取消', ko: '중지', es: 'Cancelar', fr: 'Annuler', pt: 'Cancelar' }[uiLang] || 'Cancel');
    }
  }
  if (progressBarFill) progressBarFill.style.width = `${pct}%`;
  if (percentLabel) percentLabel.textContent = `${pct}%`;
  if (statusLabel) {
    const spin = info.phase === 'done'
      ? '<i class="ph-bold ph-check-circle text-emerald-400"></i>'
      : '<i class="ph ph-spinner animate-spin text-emerald-400"></i>';
    statusLabel.innerHTML = `<span class="flex items-center space-x-1.5">${spin}<span>${escapeHtml(statusText)}</span></span>`;
  }
  if (epProgressLabel) epProgressLabel.textContent = counterText;

  // 探すカード上の進捗
  updateSearchCardDownloadProgress(ncode, {
    pct,
    statusText,
    counterText,
    phase: info.phase || 'running'
  });

  // 探すタブ上部のライブバナー（カードが画面外でも状況が分かる）
  if (info.phase !== 'idle') {
    showSearchDownloadLiveBanner({
      ncode,
      title: info.title || ncode.toUpperCase(),
      pct,
      statusText,
      counterText,
      phase: info.phase || 'running'
    });
  }
}

function updateSearchCardDownloadProgress(ncode, { pct, statusText, counterText, phase }) {
  const key = String(ncode || '').toLowerCase();
  if (!key) return;
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const savedLabel = typeof tUi === 'function' ? tUi('toc_btn_saved') : (uiLang === 'ja' ? '保存済' : 'Saved');
  const failedLabel = uiLang === 'ja' ? '失敗' : ({ en: 'Failed', zh: '失败', ko: '실패', es: 'Error', fr: 'Échec', pt: 'Falha' }[uiLang] || 'Failed');

  const btn = NovelDownloadGate.activeBtnEl
    || document.querySelector(`button[data-dl-ncode="${key}"]`);
  if (btn) {
    if (phase === 'done') {
      btn.className = 'h-8 px-2.5 bg-emerald-900/60 text-emerald-300 rounded-xl text-xs font-medium border border-emerald-500/40 transition flex items-center space-x-1';
      btn.innerHTML = `<i class="ph-bold ph-check text-sm"></i><span class="text-[11px]">${escapeHtml(savedLabel)}</span>`;
      btn.disabled = true;
    } else if (phase === 'error') {
      btn.innerHTML = `<i class="ph-bold ph-warning text-sm"></i><span class="text-[11px]">${escapeHtml(failedLabel)}</span>`;
    } else {
      btn.innerHTML = `<i class="ph ph-spinner animate-spin text-sm"></i><span class="text-[11px] font-mono">${pct}%</span>`;
      btn.title = statusText;
    }
  }

  const card = btn?.closest('[data-novel-card]')
    || document.querySelector(`[data-novel-card="${key}"]`);
  if (!card) return;
  let strip = card.querySelector('[data-dl-progress-strip]');
  if (!strip) {
    strip = document.createElement('div');
    strip.setAttribute('data-dl-progress-strip', key);
    strip.className = 'mt-2 p-2 rounded-xl bg-emerald-950/40 border border-emerald-500/30 space-y-1.5';
    const actions = card.querySelector('[data-dl-actions-row]');
    if (actions && actions.parentNode) {
      actions.parentNode.insertBefore(strip, actions.nextSibling);
    } else {
      card.appendChild(strip);
    }
  }
  if (phase === 'done') {
    strip.innerHTML = `
      <div class="flex items-center justify-between text-[10px] text-emerald-300 font-medium">
        <span class="flex items-center space-x-1"><i class="ph-bold ph-check-circle"></i><span>オフライン保存完了</span></span>
        <span class="font-mono">${escapeHtml(counterText)}</span>
      </div>`;
    setTimeout(() => { try { strip.remove(); } catch (e) {} }, 4000);
    return;
  }
  strip.innerHTML = `
    <div class="flex items-center justify-between gap-2 text-[10px] text-emerald-300 font-medium">
      <span class="truncate flex items-center space-x-1 min-w-0">
        <i class="ph ph-spinner animate-spin shrink-0"></i>
        <span class="truncate">${escapeHtml(statusText)}</span>
      </span>
      <span class="font-mono shrink-0">${pct}%</span>
    </div>
    <div class="w-full h-1.5 bg-slate-900 rounded-full overflow-hidden border border-slate-800">
      <div class="h-full bg-gradient-to-r from-emerald-500 to-teal-400 rounded-full transition-all duration-300" style="width:${pct}%"></div>
    </div>
    <div class="flex items-center justify-between gap-2">
      <div class="text-[10px] text-slate-400 font-mono">${escapeHtml(counterText)}</div>
      <button type="button" onclick="cancelActiveNovelDownload()" class="shrink-0 px-2 py-0.5 rounded-lg bg-rose-950/80 text-rose-300 border border-rose-500/40 text-[10px] font-bold active:scale-95">中止</button>
    </div>
  `;
}

function showSearchDownloadLiveBanner({ ncode, title, pct, statusText, counterText, phase }) {
  let banner = document.getElementById('searchDownloadLiveBanner');
  if (!banner) {
    const listEl = document.getElementById('novelResultsList')
      || document.getElementById('resultsList')
      || document.getElementById('searchResultsList');
    const host = listEl?.parentElement || document.getElementById('tab-search') || document.body;
    banner = document.createElement('div');
    banner.id = 'searchDownloadLiveBanner';
    banner.className = 'sticky top-0 z-20 mb-2 p-2.5 rounded-xl bg-emerald-950/95 border border-emerald-500/40 shadow-lg backdrop-blur-md';
    if (listEl && listEl.parentNode) {
      listEl.parentNode.insertBefore(banner, listEl);
    } else {
      host.prepend(banner);
    }
  }
  banner.classList.remove('hidden');
  const label = phase === 'done' ? '取得完了' : (phase === 'cancelled' ? '取得中止' : '小説を取得中');
  const showCancel = phase === 'running';
  banner.innerHTML = `
    <div class="flex items-center justify-between gap-2 mb-1.5">
      <div class="min-w-0 flex items-center space-x-2">
        <span class="w-6 h-6 rounded-lg bg-emerald-500/20 text-emerald-300 flex items-center justify-center shrink-0">
          <i class="ph ${phase === 'done' ? 'ph-bold ph-check' : phase === 'cancelled' ? 'ph-bold ph-stop' : 'ph-bold ph-download-simple'} text-sm"></i>
        </span>
        <div class="min-w-0">
          <p class="text-[11px] font-bold text-emerald-200 truncate">${escapeHtml(label)} — ${escapeHtml(title || String(ncode).toUpperCase())}</p>
          <p class="text-[10px] text-emerald-300/90 truncate">${escapeHtml(statusText || '')}</p>
        </div>
      </div>
      <div class="flex items-center gap-1.5 shrink-0">
        ${showCancel ? `<button type="button" id="btnCancelNovelDownload" onclick="cancelActiveNovelDownload()" class="px-2.5 py-1 rounded-lg bg-rose-600/90 hover:bg-rose-500 text-white text-[10px] font-bold border border-rose-400/40 active:scale-95">中止</button>` : ''}
        <span class="text-xs font-extrabold font-mono text-emerald-300">${pct}%</span>
      </div>
    </div>
    <div class="w-full h-1.5 bg-slate-950 rounded-full overflow-hidden border border-emerald-900/60">
      <div class="h-full bg-gradient-to-r from-emerald-500 to-teal-400 rounded-full transition-all duration-300" style="width:${pct}%"></div>
    </div>
    <p class="text-[10px] text-slate-400 font-mono mt-1 text-right">${escapeHtml(counterText || '')}</p>
  `;
  if (phase === 'done' || phase === 'cancelled') {
    setTimeout(() => hideSearchDownloadLiveBanner(), 4500);
  }
}

function hideSearchDownloadLiveBanner() {
  const banner = document.getElementById('searchDownloadLiveBanner');
  if (banner) banner.classList.add('hidden');
}

/** 製品デフォルト: 地の文=標準TTS / セリフ=VOICEVOX */
const DEFAULT_TTS_ENGINE = 'hybrid_mix';
const TTS_ENGINE_DEFAULT_REV = 'hybrid_mix_v1';

function getPreferredTtsEngine() {
  try {
    // 旧デフォルト (edge_tts) からの一回限りの移行。明示選択の android_native / voicevox は維持
    if (localStorage.getItem('narou_tts_engine_default_rev') !== TTS_ENGINE_DEFAULT_REV) {
      const cur = localStorage.getItem('narou_tts_engine');
      if (!cur || cur === 'edge_tts') {
        localStorage.setItem('narou_tts_engine', DEFAULT_TTS_ENGINE);
      }
      localStorage.setItem('narou_tts_engine_default_rev', TTS_ENGINE_DEFAULT_REV);
    }
    return localStorage.getItem('narou_tts_engine') || DEFAULT_TTS_ENGINE;
  } catch (e) {
    return DEFAULT_TTS_ENGINE;
  }
}

/** hybrid_mix: 地の文は標準TTS、セリフは VOICEVOX */
function shouldUseNativeTtsForSegment(seg, voiceProfile) {
  const engine = getPreferredTtsEngine();
  if (engine === 'android_native') return true;
  if (voiceProfile && voiceProfile.isNativeTts) return true;
  if (engine === 'hybrid_mix') {
    const speaker = String(seg?.speaker || '');
    if (seg?.type === 'narration') return true;
    if (speaker === 'ナレーション' || speaker.includes('地の文')) return true;
  }
  return false;
}

function resolveSpeakVoiceToken(seg, voiceProfile) {
  if (shouldUseNativeTtsForSegment(seg, voiceProfile)) {
    return (voiceProfile && (voiceProfile.id || voiceProfile.voiceId)) || 'tts_narration';
  }
  let assignedVoice = state.currentCast && state.currentCast[seg.speaker];
  if (!assignedVoice || assignedVoice === 'ja-JP-language' || String(assignedVoice).startsWith('ja-JP-') || String(assignedVoice).startsWith('Microsoft')) {
    assignedVoice = voiceProfile.voicevoxId || voiceProfile.voiceId || voiceProfile.category || 'voicevox_11';
  }
  if (String(assignedVoice).startsWith('tts_') || String(assignedVoice).includes('native_tts')) {
    assignedVoice = voiceProfile.voicevoxId || 'voicevox_11';
  }
  return assignedVoice;
}

// 初期化時に保存された音声エンジン設定をネイティブブリッジへ反映 (デフォルト: VOICEVOX+標準TTS ハイブリッド)
try {
  const initialEngine = getPreferredTtsEngine();
  if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.setVoicevoxEnabled === 'function') {
    window.AndroidBridge.setVoicevoxEnabled(initialEngine === 'voicevox' || initialEngine === 'hybrid_mix');
  }
} catch (e) {}

const state = {
  currentNovel: null,        // { ncode, title, author, synopsis, total_episodes, episodes: [...] }
  currentEpisodeNum: 1,
  currentSegments: [],       // [ { id, type, speaker, display_text, tts_text, emotion, voice_type, audio_url } ]
  currentSegmentIndex: 0,
  currentCharacters: [],     // [ { name, gender, description, voice_type } ]
  currentCast: {},           // { [speaker_name]: voice_id }
  currentCastProfiles: {},   // { [speaker_name]: { id, name, category, pitch, rateMultiplier, voiceId } } - 500+ 音声バリエーション
  currentNovelCharacters: [],// 小説全体スキャンで特定された全登場人物
  currentNovelCast: {},      // 小説全体の配役キャッシュ { [speaker_name]: voice_id }
  availableVoices: [],       // [ { id, name, gender, quality, engine } ]
  isPlaying: false,
  autoScroll: true,
  playbackSpeed: 0.8,
  searchPage: 1,
  systemInfo: null,
  isPixelDevice: false,
  hasBuiltInAI: false,
  isAndroidNative: isAndroidApp,
  currentTab: 'search',
  readerFontSize: localStorage.getItem('narou_reader_font_size') || 'md',
  readerFontFamily: localStorage.getItem('narou_reader_font_family') || 'mincho',
  readerTheme: localStorage.getItem('narou_reader_theme') || 'paper',
  tocSortAscending: true,
  tocRangeIndex: 0,
  selectedSearchSite: 'aozora', // 'aozora', 'document'
  isCarMode: false,
  currentTranslatedLang: null, // null: 原文, 'ja': 現代語超訳, その他: 多言語コード
  readingMode: 'original', // 'original' | 'modern_ja' | 'multilingual'
};

