function detectSiteFromUrlOrNcode(input) {
  if (!input) return 'aozora';
  const str = String(input).trim().toLowerCase();
  if (str.startsWith('doc_') || str.startsWith('doc:') || str.startsWith('document:')) return 'document';
  if (str.includes('aozora.gr.jp') || str.startsWith('aozora_') || str.startsWith('aozora:')) return 'aozora';
  if (str.includes('kakuyomu.jp') || str.startsWith('kakuyomu_') || str.startsWith('kakuyomu:')) return 'kakuyomu';
  if (str.includes('syosetu.org') || str.startsWith('hameln_') || str.startsWith('hameln:')) return 'hameln';
  if (str.includes('alphapolis.co.jp') || str.startsWith('alphapolis_') || str.startsWith('alphapolis:')) return 'alphapolis';
  if (str.includes('syosetu.com') || str.startsWith('narou_') || str.startsWith('narou:')) return 'narou';
  return 'aozora';
}

/** 検索欄への小説ページURL貼り付けを検出（URL直接検索は廃止） */
function looksLikeNovelPageUrl(input) {
  if (!input) return false;
  const str = String(input).trim().toLowerCase();
  if (/^https?:\/\//i.test(str)) return true;
  if (/^(www\.)?(ncode\.|novel18\.)?syosetu\.com\//.test(str)) return true;
  if (/^(www\.)?kakuyomu\.jp\//.test(str)) return true;
  if (/^(www\.)?syosetu\.org\//.test(str)) return true;
  if (/^(www\.)?alphapolis\.co\.jp\//.test(str)) return true;
  if (/^(www\.)?aozora\.gr\.jp\//.test(str)) return true;
  return false;
}

function getLocalizedSiteBadgeText(siteKey) {
  const def = SITE_DEFINITIONS[siteKey] || SITE_DEFINITIONS.narou;
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  if (uiLang === 'ja') return def.badgeText;
  if (siteKey === 'aozora') {
    return ({
      en: 'Aozora Bunko (Public Domain)',
      zh: '青空文库 (公有领域)',
      ko: '아오조라 문고 (퍼블릭 도메인)',
      es: 'Aozora Bunko (Dominio Público)',
      fr: 'Aozora Bunko (Domaine Public)',
      pt: 'Aozora Bunko (Domínio Público)'
    })[uiLang] || 'Aozora Bunko (Public Domain)';
  }
  if (siteKey === 'document') {
    return ({
      en: 'Local Document (PDF/TXT)',
      zh: '本地文档 (PDF/TXT)',
      ko: '로컬 문서 (PDF/TXT)',
      es: 'Documento local (PDF/TXT)',
      fr: 'Document local (PDF/TXT)',
      pt: 'Documento local (PDF/TXT)'
    })[uiLang] || 'Local Document (PDF/TXT)';
  }
  if (siteKey === 'narou') {
    return ({
      en: 'Saved',
      zh: '已保存',
      ko: '저장됨',
      es: 'Guardado',
      fr: 'Enregistré',
      pt: 'Salvo'
    })[uiLang] || 'Saved';
  }
  return def.badgeText;
}

function getSiteBadgeHtml(siteKey) {
  const def = SITE_DEFINITIONS[siteKey] || SITE_DEFINITIONS.narou;
  const label = getLocalizedSiteBadgeText(siteKey);
  return `<span class="inline-flex items-center space-x-1 px-2 py-0.5 rounded-full text-[10px] font-bold ${def.badgeClass} border"><i class="${def.icon}"></i><span>${escapeHtml(label)}</span></span>`;
}

function updateElementSiteBadge(elementId, textElementId, siteKey) {
  const el = document.getElementById(elementId);
  const def = SITE_DEFINITIONS[siteKey] || SITE_DEFINITIONS.narou;
  if (!el) return;
  const label = getLocalizedSiteBadgeText(siteKey);
  el.className = `inline-flex items-center space-x-1 px-2 py-0.5 rounded-full text-[10px] font-bold ${def.badgeClass} border`;
  el.innerHTML = `<i class="${def.icon}"></i><span id="${textElementId}">${escapeHtml(label)}</span>`;
}

