function getSelectedModelContextInfo(explicitModel = null) {
  const provider = document.getElementById('settingLlmProvider')?.value || state.systemInfo?.settings?.llm_provider || getActiveCastLlmProvider();
  
  if (provider === 'gemini') {
    const customInput = document.getElementById('settingGeminiModelCustom');
    const selectEl = document.getElementById('settingGeminiModelSelect');
    let modelId = explicitModel;
    if (!modelId) {
      modelId = (customInput && !customInput.classList.contains('hidden') && customInput.value.trim()) 
        ? customInput.value.trim() 
        : (selectEl?.value || 'gemini-3.8-flash');
    }
    modelId = (modelId || 'gemini-3.8-flash').toLowerCase();
    
    if (MODEL_CONTEXT_LIMITS[modelId]) {
      return MODEL_CONTEXT_LIMITS[modelId];
    }
    if (modelId.includes('pro') || modelId.includes('ultra')) {
      return { maxEpisodes: 1000, contextTokens: '2M tokens', label: `${modelId} (最大1000話 / 200万トークン)` };
    }
    return { maxEpisodes: 500, contextTokens: '1M tokens', label: `${modelId} (最大500話 / 100万トークン)` };
  }

  if (provider === 'local_llm') {
    return MODEL_CONTEXT_LIMITS['local_llm'];
  }
  if (provider === 'openai') {
    return MODEL_CONTEXT_LIMITS['openai'];
  }
  if (provider === 'claude') {
    return MODEL_CONTEXT_LIMITS['claude'];
  }
  return MODEL_CONTEXT_LIMITS['embedded_llm'];
}

function updateScanEpisodesForSelectedModel(forceDefaultToMax = false, explicitModel = null) {
  const info = getSelectedModelContextInfo(explicitModel);
  const maxEps = info.maxEpisodes || 1000;
  
  const sliderEl = document.getElementById('settingScanEpisodesSlider');
  const inputEl = document.getElementById('settingScanEpisodesInput');
  const valEl = document.getElementById('settingScanEpisodesVal');
  const textEl = document.getElementById('modelContextLimitText');
  
  if (sliderEl) {
    sliderEl.max = maxEps;
  }
  if (inputEl) {
    inputEl.max = maxEps;
  }
  if (textEl) {
    textEl.textContent = `モデル最大: ${maxEps}話 (${info.contextTokens})`;
  }
  
  if (forceDefaultToMax) {
    if (sliderEl) sliderEl.value = maxEps;
    if (inputEl) inputEl.value = maxEps;
    if (valEl) valEl.textContent = `${maxEps}話`;
    localStorage.setItem('narou_ai_cast_scan_episodes', String(maxEps));
  } else {
    let currentVal = parseInt(inputEl?.value || sliderEl?.value || localStorage.getItem('narou_ai_cast_scan_episodes') || '10', 10);
    if (isNaN(currentVal) || currentVal < 1) currentVal = 10;
    if (currentVal > maxEps) currentVal = maxEps;
    if (sliderEl) sliderEl.value = currentVal;
    if (inputEl) inputEl.value = currentVal;
    if (valEl) valEl.textContent = `${currentVal}話`;
    localStorage.setItem('narou_ai_cast_scan_episodes', String(currentVal));
  }
}

function updateScanEpisodesContextBadge(explicitModel = null) {
  updateScanEpisodesForSelectedModel(false, explicitModel);
}

function applyModelMaxContextEpisodes(explicitModel = null) {
  updateScanEpisodesForSelectedModel(true, explicitModel);
  const info = getSelectedModelContextInfo(explicitModel);
  const maxEps = info.maxEpisodes || 1000;
  if (typeof scheduleImmediateSettingsSave === 'function') {
    scheduleImmediateSettingsSave({ debounceMs: 50 });
  }
  showToast(`スキャン話数を選択中モデルの最大コンテキスト（${maxEps}話）に設定しました！`, 'success');
}

// AI配役解析のスキャン話数ヘルパー関数 (デフォルト10話、1〜1000話)
function getSettingScanEpisodes() {
  const stored = localStorage.getItem('narou_ai_cast_scan_episodes');
  if (stored) {
    const v = parseInt(stored, 10);
    if (!isNaN(v) && v >= 1 && v <= 1000) return v;
  }
  const sysVal = state.systemInfo?.settings?.ai_cast_scan_episodes;
  if (sysVal) {
    const v = parseInt(sysVal, 10);
    if (!isNaN(v) && v >= 1 && v <= 1000) return v;
  }
  return 10;
}

function onScanEpisodesSliderChange(val) {
  const sliderEl = document.getElementById('settingScanEpisodesSlider');
  const maxLimit = sliderEl ? (parseInt(sliderEl.max, 10) || 1000) : 1000;
  const v = Math.max(1, Math.min(maxLimit, parseInt(val, 10) || 10));
  const valEl = document.getElementById('settingScanEpisodesVal');
  const inputEl = document.getElementById('settingScanEpisodesInput');
  if (valEl) valEl.textContent = `${v}話`;
  if (inputEl) inputEl.value = v;
  if (sliderEl) sliderEl.value = v;
  localStorage.setItem('narou_ai_cast_scan_episodes', String(v));
  if (typeof scheduleImmediateSettingsSave === 'function') {
    scheduleImmediateSettingsSave({ debounceMs: 250 });
  }
}

function onScanEpisodesInputChange(val) {
  let v = parseInt(val, 10);
  if (isNaN(v)) return;
  const inputEl = document.getElementById('settingScanEpisodesInput');
  const maxLimit = inputEl ? (parseInt(inputEl.max, 10) || 1000) : 1000;
  v = Math.max(1, Math.min(maxLimit, v));
  const valEl = document.getElementById('settingScanEpisodesVal');
  const sliderEl = document.getElementById('settingScanEpisodesSlider');
  if (valEl) valEl.textContent = `${v}話`;
  if (sliderEl) sliderEl.value = v;
  if (inputEl) inputEl.value = v;
  localStorage.setItem('narou_ai_cast_scan_episodes', String(v));
  if (typeof scheduleImmediateSettingsSave === 'function') {
    scheduleImmediateSettingsSave({ debounceMs: 250 });
  }
}

