const GENERIC_ROLE_NAMES = new Set([
  'お嬢様・貴族令嬢', '長老・老人', '侍・武士', '荒くれ者・ドワーフ', 'マスコット・子供',
  'ヒロイン (女)', '主人公 (男)', '相手キャラ', '俺 (主人公)', '僕 (主人公)', '私 (主人公)', '主人公',
  '少女', '少年', '老人', '男', '女', '通行人', 'モブ', '登場人物'
]);

function isGenericRoleName(name) {
  if (!name) return true;
  return GENERIC_ROLE_NAMES.has(name) || /^(?:主人公|ヒロイン|モブ|通行人|登場人物|相手キャラ|男|女|少年|少女)/.test(name);
}

function cleanExtractedNameJs(name) {
  if (!name) return "";
  let n = name.trim();
  // 特殊な役割名（主人公など）はそのまま保持
  if (isGenericRoleName(n)) {
    return n;
  }

  n = n.replace(/^[ \t\r\n、。！？!?「」『』…―～~・]+|[ \t\r\n、。！？!?「」『』…―～~・]+$/g, '');
  // 修飾節の除去 (例: "白い横顔にスバル" -> "スバル", "少女たちとスバル" -> "スバル")
  n = n.replace(/^.+?(?:[にへでとを]|から|より|のは|たちと|げに|そうに|ながら)+/, '');
  // 接頭接続詞・副詞句の除去
  n = n.replace(/^(?:そして|すると|だが|しかし|また|ふと|突如|その時|ただ|と、?|に、?|へ、?|で、?|から、?|ずらわしげに|煩わしげに)+/, '');
  if (n.includes('・')) {
    const parts = n.split('・').filter(p => p.length >= 2);
    if (parts.length > 0) n = parts[parts.length - 1];
  }
  if (n.includes('の') && n.split('の').pop().length >= 2) {
    n = n.split('の').pop();
  }
  n = n.replace(/^[ \t\r\n、。！？!?…―～~]+|[ \t\r\n、。！？!?…―～~]+$/g, '');
  n = n.replace(/(?:は|が|と|も|へ|に|の|を|で|から|より|だ|である|です)$/, '');
  n = n.trim();

  // 欧文・ハングル名の判定
  const isLatinName = /^[A-ZÀ-ÖØ-Þ][a-zA-ZÀ-ÿ'-]{1,17}$/.test(n);
  const isHangulName = /^[\uac00-\ud7af]{2,6}$/.test(n);
  if (isLatinName) {
    if (/^(?:The|And|But|Then|When|What|Where|Why|How|Who|Yes|No|He|She|They|We|You|It|His|Her|Their|This|That|There|Here|Chapter|Part|Episode|System|Status|Sudden|Suddenly|However|Although|Meanwhile|After|Before|Inside|Outside|Without|Everything|Nothing|Someone|Everyone|Anyone|Nobody|El|La|Los|Las|Un|Una|Pero|Como|Para|Por|Con|Sin|Le|Les|Des|Mais|Avec|Pour|Dans|Sans|Elle|Ils|Elles|Nous|Vous|Oui|Non)$/i.test(n)) {
      return "";
    }
    return n;
  }
  if (isHangulName) {
    if (/^(?:그러나|그리고|하지만|그래서|그때|갑자기|정말|진짜|지금|여기|거기|우리|그녀|그들|누구|무엇)$/.test(n)) return "";
    return n;
  }

  // 1文字や長すぎる単語、ストップワードは除外
  if (n.length < 2 || n.length > 8) return "";
  // 中国語の発話副詞・動作修飾語が末尾に付着していた場合は除去
  n = n.replace(/(?:大声|小声|轻声|低声|冷冷|微笑|苦笑|点头|摇头|看着|望着|对着|向着|忽然|突然|连忙|急忙|缓缓|慢慢)+(?:地|着)?$/, '').replace(/[地着]$/, '').trim();
  if (n.length < 2 || /^(?:大声|小声|轻声|低声|冷冷|微笑|苦笑|点头|摇头|忽然|突然|连忙|急忙|缓缓|慢慢|他们|她们|我们|你们|自己|大家|有人|那人)$/.test(n)) return "";
  // ひらがなを含むものは「爺」付き（例: ロム爺）を除き、一般文節とみなして除外
  if (/[ぁ-ん]/.test(n) && !n.endsWith('爺')) return "";
  if (CLIENT_IGNORE_SPEAKER_WORDS.has(n)) return "";
  if (/^(?:丸損|間違い|不倶戴天|お粗末|思う|感じ|考え|正直|実は|本当|ため息|溜息|血泡|損が|マズ|ヤバ|スゴ|キツ|性格|英語|日本語)/.test(n) || /(?:間違い|丸損|思う|感じ|考え|悪|苦手|下手|得意|不能|難|苦)$/.test(n)) return "";
  // 擬音・オノマトペ（ドキドキ、プルプル等）
  if (n.length >= 4 && n.length % 2 === 0 && n.slice(0, n.length / 2) === n.slice(n.length / 2)) return "";
  return n;
}

function canonicalizeCharacterName(rawName, protagonistName = null) {
  if (!rawName) return '';
  if (rawName === 'ナレーション' || rawName === 'システム') return rawName;

  let n = cleanExtractedNameJs(rawName);
  if (!n || CLIENT_IGNORE_SPEAKER_WORDS.has(n)) {
    if (rawName && isGenericRoleName(rawName)) return protagonistName && (rawName.includes('主人公') || rawName.includes('俺') || rawName.includes('僕')) ? protagonistName : rawName;
    return '';
  }

  // 主人公への自動統合
  if (protagonistName) {
    if (n === '主人公' || n === '俺 (主人公)' || n === '僕 (主人公)' || n === '私 (主人公)' || n === '主人公 (男)' || n === '俺' || n === '僕' || n === '私') {
      return protagonistName;
    }
    if ((n === 'ナツキ' || n === 'スバル') && (protagonistName.includes('スバル') || protagonistName.includes('ナツキ'))) {
      return 'スバル';
    }
    if ((n === '向田' || n === '剛志' || n === 'ムコウダ') && (protagonistName.includes('向田') || protagonistName.includes('ムコウダ'))) {
      return 'ムコウダ';
    }
    if ((n === '三上' || n === '三上悟' || n === 'リムル') && (protagonistName.includes('リムル') || protagonistName.includes('三上'))) {
      return 'リムル';
    }
    if (protagonistName.includes(n) && n.length >= 3) {
      return protagonistName;
    }
  }

  // 一般的な別名・敬称統合
  if (n === 'ロム') return 'ロム爺';
  if (n === 'エミリアたん') return 'エミリア';
  if (n === 'ナツキ') return 'スバル';
  if (n === '向田' || n === '剛志') return 'ムコウダ';
  if (n === '三上' || n === '三上悟') return 'リムル';

  return n;
}

function extractPotentialSpeakersJs(text) {
  const found = new Set();
  if (!text) return [];

  // 1. 敬称付きの名前 (例: スバル君, ロム爺さん, エミリア様, フェルトちゃん, エルランドさん, カバルさん)
  const honorificRegex = /([一-龠ァ-ヶー]{2,8})(?:さん|ちゃん|君|くん|様|さま|殿|どの|先生|先輩|後輩|爺|おじさん|お兄さん|お姉さん|伯爵|公爵|国王|姫|隊長|ギルドマスター|マスター|店主)/g;
  let m;
  while ((m = honorificRegex.exec(text)) !== null) {
    const cand = cleanExtractedNameJs(m[1]);
    if (cand && !CLIENT_IGNORE_SPEAKER_WORDS.has(cand)) found.add(cand);
  }

  // 2. 名乗り・自己紹介・ステータス名前表記 (例: 名前：リムル / 俺の名前はナツキ・スバル)
  const nameLabelRegex = /(?:名前|名)[は：:\s]+([ァ-ヶー]{2,8}|[一-龠]{2,6})/g;
  while ((m = nameLabelRegex.exec(text)) !== null) {
    const cand = cleanExtractedNameJs(m[1]);
    if (cand && !CLIENT_IGNORE_SPEAKER_WORDS.has(cand)) found.add(cand);
  }

  const introRegex = /(?:俺|オレ|僕|ボク|私|わたし)の名前は\s*([一-龠]{2,6}|[ァ-ヶー]{2,8})/g;
  while ((m = introRegex.exec(text)) !== null) {
    const cand = cleanExtractedNameJs(m[1]);
    if (cand && !CLIENT_IGNORE_SPEAKER_WORDS.has(cand)) found.add(cand);
  }

  // 3. 発話・動作動詞を伴うカタカナ固有名詞 (例: ヴェルドラは笑った / リムルがつぶやいた)
  const actionKatakanaRegex = /([ァ-ヶー]{2,8})(?:は|が|と|も)(?:言っ|つぶや|叫|呟|語|答|尋ね|笑|睨|口を開|告げ|命じ|促し|唸|吠え|抗議|嘆|要求|懇願)/g;
  while ((m = actionKatakanaRegex.exec(text)) !== null) {
    const rawK = m[1];
    if (!/^[ァィゥェォッャュョヮー]/.test(rawK) && !rawK.endsWith('ッ') && !rawK.endsWith('ーッ')) {
      const cand = cleanExtractedNameJs(rawK);
      if (cand && !CLIENT_IGNORE_SPEAKER_WORDS.has(cand)) found.add(cand);
    }
  }

  // 4. セリフ内での直接呼びかけ (例: 「おい、スバル！」「ねえ、エミリア？」)
  const callRegex = /(?:^|[「『\s])(?:おい|なぁ|ねえ|あ、?|おいおい)[！!、\s]+([ァ-ヶー]{2,8})[！!？?、\s]/g;
  while ((m = callRegex.exec(text)) !== null) {
    const cand = cleanExtractedNameJs(m[1]);
    if (cand && !CLIENT_IGNORE_SPEAKER_WORDS.has(cand)) found.add(cand);
  }

  // 5. 多言語（英語・中国語・韓国語・スペイン語・フランス語）の敬称・発話動詞からの話者抽出
  const foreignHonorificRegex = /\b(?:Mr\.|Mrs\.|Ms\.|Miss|Lord|Lady|Sir|Princess|Prince|King|Queen|Duke|Duchess|Count|Captain|Master|Doctor|Dr\.|Professor|Prof\.|Sister|Brother|Father|Mother|Señor|Señora|Señorita|Don|Doña|Monsieur|Madame|Mademoiselle)\s+([A-ZÀ-ÖØ-Þ][a-zA-ZÀ-ÿ'-]{1,16})/g;
  while ((m = foreignHonorificRegex.exec(text)) !== null) {
    const cand = cleanExtractedNameJs(m[1]);
    if (cand) found.add(cand);
  }

  const foreignVerbAfterRegex = /\b([A-ZÀ-ÖØ-Þ][a-zA-ZÀ-ÿ'-]{1,16})\s+(?:said|asked|shouted|whispered|replied|answered|cried|laughed|smiled|sighed|muttered|murmured|called|yelled|snapped|growled|gasped|exclaimed|dijo|preguntó|gritó|susurró|respondió|sonrió|dit|demanda|cria|murmura|répondit|sourit)\b/g;
  while ((m = foreignVerbAfterRegex.exec(text)) !== null) {
    const cand = cleanExtractedNameJs(m[1]);
    if (cand) found.add(cand);
  }

  const foreignVerbBeforeRegex = /\b(?:said|asked|shouted|whispered|replied|answered|cried|muttered|murmured|yelled|exclaimed|dijo|preguntó|gritó|susurró|respondió|dit|demanda|cria|murmura|répondit)\s+([A-ZÀ-ÖØ-Þ][a-zA-ZÀ-ÿ'-]{1,16})\b/g;
  while ((m = foreignVerbBeforeRegex.exec(text)) !== null) {
    const cand = cleanExtractedNameJs(m[1]);
    if (cand) found.add(cand);
  }

  const zhActionRegex = /(?:^|[，。！？；：\n\s"“”「」『』])([\u4e00-\u9fff]{2,4}?)(?:大声|小声|轻声|低声|冷冷|微笑|苦笑|点头|摇头)?(?:地|着)?(?:说道|说|问道|问|喊道|叫道|低声道|笑道|冷笑道|回答道|回答|叹了口气|喃喃道)/g;
  while ((m = zhActionRegex.exec(text)) !== null) {
    const cand = cleanExtractedNameJs(m[1]);
    if (cand && !/^(?:他们|她们|我们|你们|自己|大家|有人|那人|少女|少年|男人|女人)$/.test(cand)) found.add(cand);
  }

  const koActionRegex = /([\uac00-\ud7af]{2,5})(?:이|가|은|는)\s*(?:말했다|물었다|외쳤다|속삭였다|대답했다|웃었다|중얼거렸다|소리쳤다|한숨을)/g;
  while ((m = koActionRegex.exec(text)) !== null) {
    const cand = cleanExtractedNameJs(m[1]);
    if (cand) found.add(cand);
  }

  return Array.from(found);
}

