// クライアントサイド内包 高精度AI話者・配役解析エンジン
function getActiveOnDeviceModelProfile() {
  const rawInstalled = (typeof localStorage !== 'undefined') ? localStorage.getItem('narou_installed_local_llm') : null;
  const currentModelId = (typeof normalizeInstalledOnDeviceProfileId === 'function')
    ? normalizeInstalledOnDeviceProfileId(rawInstalled)
    : (rawInstalled || '');
  if (currentModelId && typeof ON_DEVICE_LLM_MODELS !== 'undefined' && ON_DEVICE_LLM_MODELS[currentModelId]) {
    return ON_DEVICE_LLM_MODELS[currentModelId];
  }
  if (typeof detectOptimalOnDeviceModel === 'function' && typeof ON_DEVICE_LLM_MODELS !== 'undefined') {
    const optimal = detectOptimalOnDeviceModel();
    return ON_DEVICE_LLM_MODELS[optimal.modelId] || ON_DEVICE_LLM_MODELS['ministral-3b'] || { id: 'builtin-fast-lite', name: '内包軽量AI' };
  }
  return { id: 'ministral-3b', name: 'Ministral 3B', shortBadge: 'Ministral 3B' };
}

function analyzeSegmentsLocally(segments, novelTitle, targetModelId = null) {
  if (typeof normalizeAndMergeBrokenSegments === 'function' && Array.isArray(segments) && segments.length > 1) {
    segments = normalizeAndMergeBrokenSegments(segments);
  }
  const activeProfile = targetModelId && typeof ON_DEVICE_LLM_MODELS !== 'undefined' && ON_DEVICE_LLM_MODELS[targetModelId]
    ? ON_DEVICE_LLM_MODELS[targetModelId]
    : getActiveOnDeviceModelProfile();
  const isFlagshipModel = activeProfile.id === 'ministral-8b';

  const narratorName = 'ナレーション';
  const systemName = 'システム';
  const detectedCharacters = {
    [narratorName]: { name: narratorName, gender: '女性', description: '地の文・朗読', voice_type: 'neutral_narration', voiceId: 'voicevox_2' },
    [systemName]: { name: systemName, gender: '女性', description: 'システムメッセージ・念話', voice_type: 'female_calm', voiceId: 'voicevox_2' }
  };

  // 0. 作品タイトルからナレッジベース照合
  let matchedMaster = null;
  const nTitle = novelTitle || state.currentNovel?.title || '';
  for (const [key, data] of Object.entries(MASTER_NOVEL_CAST_KNOWLEDGE)) {
    if (nTitle.includes(key)) {
      matchedMaster = data;
      break;
    }
  }

  // 1. 全文からの登場人物出現頻度および一人称分析
  let bokuCount = 0, oreCount = 0, watashiCount = 0, atashiCount = 0;
  const speakerFreq = {};

  segments.forEach(seg => {
    const t = seg.display_text || '';
    if (t.includes('僕') || t.includes('ボク') || t.includes('ぼく')) bokuCount++;
    if (t.includes('俺') || t.includes('オレ') || t.includes('おれ')) oreCount++;
    if (t.includes('私') || t.includes('わたし') || t.includes('ワタシ')) watashiCount++;
    if (t.includes('あたし') || t.includes('アタシ')) atashiCount++;

    const candidates = extractPotentialSpeakersJs(t);
    candidates.forEach(spk => {
      speakerFreq[spk] = (speakerFreq[spk] || 0) + 1;
    });
  });

  // 主人公のデフォルト特定（一人称が一度も登場しない評論文・古典等では誤って 'ore' にしない）
  let protagonistName = matchedMaster?.protagonist || null;
  let povFirstPerson = null;
  const totalFirstPersonCount = bokuCount + oreCount + watashiCount + atashiCount;
  if (totalFirstPersonCount > 0) {
    if (bokuCount > oreCount && bokuCount > watashiCount) povFirstPerson = 'boku';
    else if (oreCount >= bokuCount && oreCount >= watashiCount && oreCount > 0) povFirstPerson = 'ore';
    else if (watashiCount >= bokuCount && watashiCount >= oreCount && watashiCount > 0) povFirstPerson = 'watashi';
    else if (atashiCount > bokuCount && atashiCount > watashiCount) povFirstPerson = 'atashi';
  }

  if (!protagonistName) {
    for (const seg of segments) {
      const t = seg.display_text || '';
      const mIntro = t.match(/(?:俺|オレ|僕|ボク|私|わたし)の(?:名前|名)は\s*([一-龠ぁ-んァ-ヶー]{1,8})/) ||
                     t.match(/(?:俺|オレ|僕|ボク|私|わたし)は\s*([一-龠ぁ-んァ-ヶー]{1,8})(?:と申します|と申す|といい|と申し|だ|です|という)/) ||
                     t.match(/(?:名前|名)[は：:\s]+([ァ-ヶー]{2,8}|[一-龠]{2,6})/);
      if (mIntro) {
        const cand = canonicalizeCharacterName(mIntro[1]);
        if (cand && !CLIENT_IGNORE_SPEAKER_WORDS.has(cand) && !isGenericRoleName(cand)) {
          protagonistName = cand;
          break;
        }
      }
    }
  }

  // 既知キャラクターのセットアップ（マスター知識 ＋ 小説全体スキャン結果 ＋ 今回検出）
  const knownSpeakersSet = new Set();
  if (protagonistName) knownSpeakersSet.add(protagonistName);

  if (matchedMaster?.characters) {
    Object.keys(matchedMaster.characters).forEach(name => knownSpeakersSet.add(name));
  }

  if (state.currentNovelCharacters && Array.isArray(state.currentNovelCharacters)) {
    state.currentNovelCharacters.forEach(c => {
      if (c && c.name && !CLIENT_IGNORE_SPEAKER_WORDS.has(c.name) && !isGenericRoleName(c.name)) {
        knownSpeakersSet.add(c.name);
      }
    });
  }

  Object.keys(speakerFreq).forEach(k => {
    const c = canonicalizeCharacterName(k, protagonistName);
    if (c && !CLIENT_IGNORE_SPEAKER_WORDS.has(c) && !isGenericRoleName(c)) {
      knownSpeakersSet.add(c);
    }
  });

  const knownSpeakers = Array.from(knownSpeakersSet);
  let lastDialogueSpeaker = null;

  // 2. 高精度述語・セリフ境界マッチングによる話者判定
  const enriched = segments.map((seg, i) => {
    // 地の文
    if (seg.type === 'narration') {
      const engine = typeof getPreferredTtsEngine === 'function' ? getPreferredTtsEngine() : 'hybrid_mix';
      const voiceId = (engine === 'voicevox') ? 'voicevox_2' : 'tts_narration';
      return { ...seg, speaker: narratorName, emotion: 'normal', voice_type: 'neutral_narration', voiceId };
    }

    // システム音声・念話・二重山括弧
    const dText = String(seg.display_text || seg.text || '');
    if (seg.type === 'system' || dText.startsWith('《') || dText.startsWith('【') || dText.startsWith('＜')) {
      const sysSpk = (matchedMaster && matchedMaster.characters['大賢者']) ? '大賢者' : systemName;
      return { ...seg, speaker: sysSpk, emotion: 'normal', voice_type: 'female_calm', voiceId: 'voicevox_2' };
    }

    const text = dText;
    let speaker = null;
    let emotion = 'normal';

    // 感情推定 (日本語 + 多言語対応)
    if (/[！!]{2,}|(?:うわ|ぎゃ|きゃ|死ね|殺す|許さん|くそ|ちくしょう|邪魔だ)|\b(?:damn|bastard|idiot|shut up|kill you|unforgivable|how dare|curse you)\b|混蛋|该死|可恶|杀了你|젠장|죽여|닥쳐|maldita|idiota|merde|imbécile/i.test(text)) emotion = 'angry';
    else if (/悲し|泣|涙|うぅ|ううっ|ごめん|すまな|さよなら|死にたく|寂し|つらい|辛い|\b(?:sorry|forgive me|goodbye|farewell|sobs?|crying|tears|lonely|hopeless)\b|对不起|难过|流泪|悲伤|미안|슬프|눈물|lo siento|triste|lágrimas|désolé|larmes/i.test(text)) emotion = 'sad';
    else if (/[！!]/.test(text)) emotion = 'excited';
    else if (/[？\?]/.test(text)) emotion = 'excited';
    else if (/……|…|\.{3,}|っ……|ふぅ|はぁ|\b(?:whisper|murmur|sigh|shh|hush)\b|低声|小声|叹气|속삭|한숨|susurr|chuchot/i.test(text)) emotion = 'whisper';
    else if (/ありがとう|うれしい|よかった|えへへ|わーい|ふふっ|あはは|美味しい|おいしい|好き|\b(?:thank you|thanks|glad|happy|yay|hurray|wonderful|awesome|haha|hehe|giggle)\b|谢谢|太好了|开心|高兴|고마워|감사|기뻐|gracias|feliz|alegre|merci|heureux/i.test(text)) emotion = 'happy';

    // Ministral 8B / 高精度プロファイル: 深層文脈・微細感情拡張 (驚愕・安堵・愛情)
    if (isFlagshipModel && emotion === 'normal') {
      if (/えっ|まさか|何だって|嘘だろ|本当か|まさかそんな|\b(?:what|no way|impossible|really|seriously)\b/i.test(text)) {
        emotion = 'excited';
      } else if (/よかった……|助かった|ほっとした|やれやれ|\b(?:thank goodness|relieved|finally)\b/i.test(text)) {
        emotion = 'whisper';
      } else if (/べ、別に|恥ずかし|赤面|バカ……|\b(?:blush|idiot\.\.\.)\b/i.test(text)) {
        emotion = 'happy';
      }
    }

    // 一人称の検出
    let curFirstPerson = null;
    if (/俺|オレ|おれ|俺様|おいら/.test(text)) curFirstPerson = 'ore';
    else if (/僕|ボク|ぼく/.test(text)) curFirstPerson = 'boku';
    else if (/私|わたし|ワタシ|わたくし/.test(text)) curFirstPerson = 'watashi';
    else if (/あたし|アタシ|あたい/.test(text)) curFirstPerson = 'atashi';
    else if (/我|余|妾|我輩|某|拙者/.test(text)) curFirstPerson = 'ware';
    else if (/わし|儂|爺/.test(text)) curFirstPerson = 'washi';

    // 相手への呼びかけ（除外対象）
    const escapeRegExpStr = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const addressedNames = new Set();
    knownSpeakers.forEach(name => {
      const esc = escapeRegExpStr(name);
      if (new RegExp(esc + '(?:さん|君|くん|様|さま|ちゃん|殿|どの|ってば|よ|さ|ね|の|、|！|!|？|\\?)').test(text) ||
          new RegExp('(?:^|[「『\\s])(?:おい[！!、\\s]*|あ、?|ねえ[、\\s]*)' + esc).test(text)) {
        addressedNames.add(name);
      }
    });

    // A. 直前の地の文から主語・発言動詞を高精度解析 (日本語 + 多言語対応)
    if (!speaker && i > 0 && segments[i-1].type === 'narration') {
      const prevT = segments[i-1].display_text || '';
      for (const spk of knownSpeakers) {
        if (!addressedNames.has(spk) && prevT.includes(spk)) {
          const escSpk = escapeRegExpStr(spk);
          // 発話・思考・動作述語
          if (new RegExp(escSpk + '(?:は|が|も)(?:[^。！？\\n]*?)(?:口を開|言っ|尋ね|問い|微笑|振り返|呟|叫|命じ|促し|語り|告げ|駆|現れ|催促|唸|吠え|笑|睨|答え|返答|ため息|肩を|頷|うなず|首を|眉を|抗議|嘆|見つめ|見上げ|見下ろ|見送|遮)').test(prevT) ||
              new RegExp('\\b' + escSpk + '\\b[^.!?\\n]{0,40}\\b(?:said|asked|shouted|whispered|replied|answered|cried|laughed|smiled|sighed|muttered|murmured|called|yelled|exclaimed|dijo|preguntó|gritó|susurró|respondió|dit|demanda|cria|murmura|répondit)\\b', 'i').test(prevT) ||
              new RegExp(escSpk + '(?:[^。！？\\n]{0,20})(?:说道|说|问道|问|喊道|叫道|低声道|笑道|回答|말했다|물었다|외쳤다|속삭였다|대답했다|웃었다)').test(prevT)) {
            speaker = spk;
            break;
          }
        }
      }
    }

    // B. 直後の地の文から主語・発言動詞を高精度解析 (日本語 + 多言語対応)
    if (!speaker && i + 1 < segments.length && segments[i+1].type === 'narration') {
      const nextT = segments[i+1].display_text || '';
      for (const spk of knownSpeakers) {
        if (!addressedNames.has(spk) && nextT.includes(spk)) {
          const escSpk = escapeRegExpStr(spk);
          if (new RegExp('(?:「[^」]*」)?(?:と|、|\\s)*(?:その)?' + escSpk + '(?:は|が|も)(?:[^。！？\\n]*?)(?:言っ|つぶや|叫|呟|語|答|尋ね|笑|睨|口を開|告げ|命じ|促し|唸|吠え|抗議|嘆|要求|懇願|返答|苦笑|微笑|頷|うなず|首を|ため息)').test(nextT) ||
              new RegExp('\\b(?:' + escSpk + '\\s+(?:said|asked|shouted|whispered|replied|answered|cried|laughed|smiled|sighed|muttered|murmured|called|yelled|exclaimed|dijo|preguntó|gritó|susurró|respondió|dit|demanda|cria|murmura|répondit)|(?:said|asked|shouted|whispered|replied|answered|cried|dijo|preguntó|dit|demanda|répondit)\\s+' + escSpk + ')\\b', 'i').test(nextT) ||
              new RegExp(escSpk + '(?:[^。！？\\n]{0,20})(?:说道|说|问道|问|喊道|叫道|低声道|笑道|回答|말했다|물었다|외쳤다|속삭였다|대답했다|웃었다)').test(nextT)) {
            speaker = spk;
            break;
          }
        }
      }
    }

    // C. 特徴的口調・役割語からの特定
    if (!speaker) {
      if (/のだ|なのだ|のだよ|のだぞ|あるじ|主様|なのだ！/.test(text)) {
        if (matchedMaster?.characters['ずんだもん']) speaker = 'ずんだもん';
        else if (matchedMaster?.characters['ミリム']) speaker = 'ミリム';
      } else if (/ですわ|ますわ|おほほ|あそばせ/.test(text)) {
        const noble = knownSpeakers.find(s => /姫|令嬢|お嬢|エミリア|サテラ|シュナ/.test(s) && !addressedNames.has(s));
        if (noble) speaker = noble;
      } else if (/クハハ|グハハ|わはは|我が友|我が友よ|我は|我輩/.test(text)) {
        if (matchedMaster?.characters['ヴェルドラ']) speaker = 'ヴェルドラ';
      }
    }

    const defaultPovLabel = protagonistName
      || (povFirstPerson === 'boku' ? '僕 (主人公)' : (povFirstPerson === 'ore' ? '俺 (主人公)' : (povFirstPerson === 'watashi' ? '私 (主人公)' : '登場人物')));

    const isMonologueSeg = seg.subtype === 'monologue' || (text.startsWith('（') && text.endsWith('）')) || (text.startsWith('(') && text.endsWith(')'));
    if (isMonologueSeg) {
      emotion = 'whisper';
      if (!speaker) {
        speaker = defaultPovLabel;
      }
    }

    // D. 一人称の一致
    if (!speaker && curFirstPerson) {
      if (curFirstPerson === povFirstPerson && protagonistName) {
        speaker = protagonistName;
      } else if (curFirstPerson === 'atashi' || curFirstPerson === 'watashi') {
        const femaleCand = knownSpeakers.find(s => s !== protagonistName && !addressedNames.has(s) && /シュナ|シオン|エミリア|レム|ラム|めぐみん|アクア|ロキシー|エリス|猫猫/.test(s));
        if (femaleCand) speaker = femaleCand;
      }
    }

    // E. 交互掛け合い（ターン制フォールバック）
    if (!speaker) {
      if (lastDialogueSpeaker && lastDialogueSpeaker === (protagonistName || '主人公')) {
        const partner = knownSpeakers.find(s => s !== (protagonistName || '主人公') && !addressedNames.has(s));
        speaker = partner || (curFirstPerson === 'atashi' ? 'ヒロイン' : '相手キャラ');
      } else if (lastDialogueSpeaker) {
        speaker = protagonistName || (curFirstPerson === 'boku' ? '僕 (主人公)' : (curFirstPerson === 'ore' ? '俺 (主人公)' : defaultPovLabel));
      } else {
        const fallback = knownSpeakers.find(s => !addressedNames.has(s));
        speaker = fallback || defaultPovLabel;
      }
    }

    speaker = canonicalizeCharacterName(speaker, protagonistName);
    if (!speaker) speaker = protagonistName || '登場人物';
    // モノローグ（心内語）は音声会話ターンを上書きしない（直後のセリフの話者逆転を防止）
    if (!isMonologueSeg) {
      lastDialogueSpeaker = speaker;
    }

    // 3. キャラクター属性と最適VOICEVOXボイスの決定 (日本語 + 多言語コンテキスト対応)
    let charInfo = matchedMaster?.characters[speaker] || null;
    let gender = charInfo?.gender || '不明';
    let voiceType = charInfo?.voiceType || 'male_young';
    let voiceId = charInfo?.voiceId || null;
    const adjContext = ((i > 0 ? (segments[i-1].display_text || '') : '') + ' ' + (i + 1 < segments.length ? (segments[i+1].display_text || '') : '')).toLowerCase();

    if (!charInfo) {
      if (/女|妹|娘|姫|母|姉|婦|夫人|ヒロイン|少女|幼女|シュナ|シオン|ミリム|エレン|エミリア|レム|ラム|めぐみん|アクア|猫猫|ロキシー|シルフィ|エリス|公主|女王|小姐|소녀|공주|여왕|아씨/.test(speaker) ||
          /^(?:Alice|Emma|Sophia|Olivia|Isabella|Mia|Charlotte|Amelia|Elena|Aria|Luna|Stella|Chloe|Claire|Marie|Lucia|Lucy|Sofia|Lily|Rose|Anna|Mary|Sarah|Elizabeth|Grace|Victoria)$/i.test(speaker) ||
          /\b(?:she|her|hers|girl|woman|lady|princess|queen|maiden|sister|mother|daughter|elle|ella)\b|她|그녀/.test(adjContext) ||
          curFirstPerson === 'atashi') {
        gender = '女性';
        voiceType = /幼|少女|ミリム|めぐみん|ベアトリス|little girl|child/i.test(speaker + ' ' + adjContext) ? 'child_girl' : 'female_young';
        voiceId = voiceType === 'child_girl' ? 'voicevox_14' : 'voicevox_8';
      } else if (/男|父|兄|弟|爺|老|騎士|武士|魔王|王|主人公|リムル|ヴェルドラ|ベニマル|ソウエイ|ハクロウ|ゴブタ|ランガ|スバル|カズマ|ルーデウス|壬氏|王子|国王|先生|公子|소년|왕자|국왕|기사/.test(speaker) ||
                 /^(?:Arthur|John|William|James|Henry|Charles|Thomas|Edward|Richard|David|Alex|Leo|Lucas|Liam|Noah|Oliver|Carlos|Jean|Pierre|Louis|Jack|Harry|Peter|Michael|Daniel)$/i.test(speaker) ||
                 /\b(?:he|him|his|boy|man|lord|prince|king|knight|brother|father|son|il|él)\b|他|그가|그는/.test(adjContext) ||
                 curFirstPerson === 'ore' || curFirstPerson === 'boku') {
        gender = '男性';
        if (/爺|老|ハクロウ|ロム爺|高順|old man|elder/i.test(speaker + ' ' + adjContext)) {
          voiceType = 'male_elder';
          voiceId = 'voicevox_13';
        } else if (/少年|ゴブタ|パック|ルーデウス|little boy|young boy/i.test(speaker + ' ' + adjContext)) {
          voiceType = 'child_boy';
          voiceId = 'voicevox_12';
        } else if (/ヴェルドラ|オルステッド/.test(speaker)) {
          voiceType = 'male_elder';
          voiceId = 'voicevox_13';
        } else {
          voiceType = 'male_young';
          voiceId = 'voicevox_11';
        }
      } else {
        const inferred = inferGenderAdvancedJs(speaker, '', adjContext);
        gender = inferred === 'female' ? '女性' : '男性';
        voiceType = gender === '女性' ? 'female_young' : 'male_young';
        voiceId = gender === '女性' ? 'voicevox_8' : 'voicevox_11';
      }
    }

    if (!voiceId) {
      voiceId = (gender === '女性' || gender === 'female') ? 'voicevox_8' : 'voicevox_11';
    }

    if (!detectedCharacters[speaker]) {
      detectedCharacters[speaker] = {
        name: speaker,
        gender,
        description: speaker === protagonistName ? '主人公 (' + speaker + ')' : '登場人物 (' + speaker + ')',
        voice_type: voiceType,
        voiceId: voiceId
      };
    }

    return {
      ...seg,
      speaker,
      emotion,
      voice_type: voiceType,
      voice_id: voiceId,
      voiceId: voiceId
    };
  });

  return {
    characters: Object.values(detectedCharacters),
    segments: enriched,
    modelProfile: activeProfile
  };
}

// クライアントサイドでの配役・ボイス自動抽出＆ステート反映
async function clientSideExtractAndAssignVoices(segments) {
  const analysis = analyzeSegmentsLocally(segments, state.currentNovel?.title || '');
  state.currentSegments = analysis.segments;
  state.currentCharacters = analysis.characters || [];
  state.currentModelProfile = analysis.modelProfile;

  if (typeof mergeNovelCastIncremental === 'function') {
    const mergedCastData = mergeNovelCastIncremental(
      state.currentNovel?.ncode || 'standalone_work',
      null,
      state.currentCharacters,
      'クライアントAI配役解析'
    );
    state.currentCast = mergedCastData.cast || {};
    state.currentCastProfiles = mergedCastData.cast_profiles || {};
  }
  return analysis;
}

// =============================================================================
// 青空文庫 スタンドアロン/クライアント検索 & パースエンジン
// =============================================================================
window.__aozoraIndexData = null;
let __aozoraIndexLoadingPromise = null;

function _indexAozoraItems(list) {
  if (!Array.isArray(list)) return [];
  for (let i = 0, len = list.length; i < len; i++) {
    const item = list[i];
    if (item && item._t === undefined) {
      item._t = (item.title || '').toLowerCase();
      item._a = (item.author || '').toLowerCase();
    }
  }
  return list;
}

async function loadAozoraIndexIfNeeded() {
  if (window.__aozoraIndexData && window.__aozoraIndexData.length > 0) {
    return window.__aozoraIndexData;
  }
  // 静的 script タグで事前ロードされた aozora_index.js (全18,574作品) があれば即座に利用 (0ms・CORS/タイムアウト完全フリー)
  if (typeof window !== 'undefined' && Array.isArray(window.AOZORA_ALL_INDEX) && window.AOZORA_ALL_INDEX.length > 0) {
    window.__aozoraIndexData = _indexAozoraItems(window.AOZORA_ALL_INDEX);
    return window.__aozoraIndexData;
  }
  if (__aozoraIndexLoadingPromise) {
    return __aozoraIndexLoadingPromise;
  }
  __aozoraIndexLoadingPromise = (async () => {
    // 再度 window.AOZORA_ALL_INDEX を確認
    if (typeof window !== 'undefined' && Array.isArray(window.AOZORA_ALL_INDEX) && window.AOZORA_ALL_INDEX.length > 0) {
      window.__aozoraIndexData = _indexAozoraItems(window.AOZORA_ALL_INDEX);
      return window.__aozoraIndexData;
    }

    // 1. 通常の fetch をまず試行（高速かつWeb/ローカル両対応、4秒タイムアウト）
    const fetchCandidateUrls = ['aozora_index.json', '/aozora_index.json', './aozora_index.json'];
    for (const u of fetchCandidateUrls) {
      try {
        const controller = (typeof AbortController !== 'undefined') ? new AbortController() : null;
        const timeoutId = controller ? setTimeout(() => controller.abort(), 4000) : null;
        const res = await fetch(u, controller ? { signal: controller.signal } : {});
        if (timeoutId) clearTimeout(timeoutId);
        if (res && res.ok) {
          const raw = await res.json();
          if (Array.isArray(raw) && raw.length > 0) {
            window.__aozoraIndexData = _indexAozoraItems(raw);
            return window.__aozoraIndexData;
          }
        }
      } catch (e) {
        // 次のURL候補へ
      }
    }

    // 2. AndroidBridge 経由の nativeFetch (5秒タイムアウト)
    try {
      const res = await nativeFetch('aozora_index.json', { timeoutMs: 5000 });
      if (res && res.ok) {
        const raw = await res.json();
        if (Array.isArray(raw) && raw.length > 0) {
          window.__aozoraIndexData = _indexAozoraItems(raw);
          return window.__aozoraIndexData;
        }
      }
    } catch (e) {
      console.warn('[Aozora] Failed to load aozora_index.json via nativeFetch:', e);
    }

    // 失敗時は空配列（プリセット作品で検索続行可能）、次回再試行できるようにプロミスを解放
    __aozoraIndexLoadingPromise = null;
    return [];
  })();
  return __aozoraIndexLoadingPromise;
}

function parseAozoraHtmlBody(html) {
  if (!html) return '';
  try {
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');
    const mainTextEl = doc.querySelector('.main_text') || doc.body;
    if (!mainTextEl) return '';
    mainTextEl.querySelectorAll('.bibliographical_information, .afterword, .notes, script, style').forEach(e => e.remove());
    mainTextEl.querySelectorAll('br').forEach(br => br.replaceWith('\n'));
    mainTextEl.querySelectorAll('p, div, h1, h2, h3, h4, h5, h6, li').forEach(block => {
      block.append('\n');
    });
    mainTextEl.querySelectorAll('ruby').forEach(rb => {
      const rt = rb.querySelector('rt');
      const rubyText = rt ? rt.textContent.trim() : '';
      const rbEl = rb.querySelector('rb');
      let kanji = rbEl ? rbEl.textContent.trim() : '';
      if (!kanji) {
        const clone = rb.cloneNode(true);
        clone.querySelectorAll('rt, rp').forEach(e => e.remove());
        kanji = clone.textContent.trim();
      }
      if (rubyText) {
        rb.replaceWith(`｜${kanji}《${rubyText}》`);
      } else {
        rb.replaceWith(kanji);
      }
    });
    return (mainTextEl.textContent || mainTextEl.innerText || '').replace(/\n{3,}/g, '\n\n').trim();
  } catch (e) {
    console.warn('[Aozora] HTML parse error:', e);
    return html;
  }
}

const AOZORA_CLEAN_SEGMENT_REV = 5;

function splitAozoraWorkIntoEpisodesClient(rawText, workTitle, firstEpTitle, defaultYear, defaultUrl) {
  const text = String(rawText || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  if (!text) {
    return [{
      episode_number: 1,
      title: firstEpTitle || '全文朗読',
      date: defaultYear || 'パブリックドメイン',
      url: defaultUrl || '',
      raw_text: ''
    }];
  }

  // 短編〜中編（22,000文字以下）は1話全文としてそのまま分割せず収録（走れメロス・羅生門・蜘蛛の糸・注文の多い料理店・山月記・檸檬等）
  if (text.length <= 22000) {
    return [{
      episode_number: 1,
      title: firstEpTitle || '全文朗読',
      date: defaultYear || 'パブリックドメイン',
      url: defaultUrl || '',
      raw_text: text
    }];
  }

  // 長編小説（こころ・人間失格・坊っちゃん・吾輩は猫である・銀河鉄道の夜等）は章見出しまたは約12,000字単位の段落境界で章分割し、全文を余さず朗読可能にする
  const lines = text.split('\n');
  const rawChapters = [];
  let currentTitle = firstEpTitle || '第一章';
  let currentLines = [];

  const headingRegex = /^(?:［＃[^］]*見出し］)?\s*(?:第[一二三四五六七八九十百千0-9０-９]+[章話編部節回]|[一二三四五六七八九十百]+|[０-９0-9]+|[上中下]　[^\n]{1,20}|序章|終章|はしがき|あとがき|第[一二三四五六七八九十]+の手記)\s*(?:［＃[^］]*見出し終わり］)?$/;

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const trimmed = rawLine.trim();
    const cleanCheck = trimmed.replace(/［＃[^］]*］/g, '').trim();
    const isExplicitHeading = (trimmed.includes('見出し］') && cleanCheck.length > 0 && cleanCheck.length <= 35)
      || (headingRegex.test(trimmed) && cleanCheck.length > 0 && cleanCheck.length <= 25);

    if (isExplicitHeading && currentLines.join('\n').trim().length >= 1200) {
      rawChapters.push({
        title: currentTitle,
        text: currentLines.join('\n').trim()
      });
      currentTitle = cleanCheck;
      currentLines = [cleanCheck];
    } else {
      currentLines.push(rawLine);
    }
  }
  if (currentLines.join('\n').trim().length > 0) {
    rawChapters.push({
      title: currentTitle,
      text: currentLines.join('\n').trim()
    });
  }

  const TARGET_CHUNK_CHARS = 12000;
  const finalEpisodes = [];
  for (const ch of rawChapters) {
    if (ch.text.length <= TARGET_CHUNK_CHARS * 1.4) {
      finalEpisodes.push({
        title: ch.title,
        raw_text: ch.text
      });
    } else {
      const chParas = ch.text.split('\n');
      let buf = [];
      let bufLen = 0;
      let partNum = 1;
      for (const p of chParas) {
        buf.push(p);
        bufLen += p.length + 1;
        if (bufLen >= TARGET_CHUNK_CHARS) {
          finalEpisodes.push({
            title: rawChapters.length === 1 ? `第${partNum}章` : `${ch.title} (${partNum})`,
            raw_text: buf.join('\n').trim()
          });
          buf = [];
          bufLen = 0;
          partNum++;
        }
      }
      if (buf.join('\n').trim().length > 0) {
        if (finalEpisodes.length > 0 && bufLen < 2500) {
          finalEpisodes[finalEpisodes.length - 1].raw_text += '\n' + buf.join('\n').trim();
        } else {
          finalEpisodes.push({
            title: rawChapters.length === 1 ? `第${partNum}章` : `${ch.title} (${partNum})`,
            raw_text: buf.join('\n').trim()
          });
        }
      }
    }
  }

  return finalEpisodes.map((ep, idx) => ({
    episode_number: idx + 1,
    title: ep.title || `第${idx + 1}話`,
    date: defaultYear || 'パブリックドメイン',
    url: defaultUrl || '',
    raw_text: ep.raw_text
  }));
}

async function searchAozoraWorksClient(rawWord = '', author = '', page = 1, limit = 20) {
  const wLower = (rawWord || '').trim().toLowerCase();
  const aLower = (author || '').trim().toLowerCase();

  // 多言語クエリ（英語・中国語・韓国語等）を日本語キーワードへ解決
  let queryInfo = { jpKeyword: '', detectedLang: 'ja', isTranslated: false, origKeyword: rawWord };
  if (typeof resolveJapaneseQueryFromMultilingualQueryAsync === 'function' && wLower) {
    queryInfo = await resolveJapaneseQueryFromMultilingualQueryAsync(wLower);
  }
  const jpKeywordLower = (queryInfo.jpKeyword || '').trim().toLowerCase();
  const mappedAuthorJp = (typeof resolveJapaneseAuthorFromMultilingualQuery === 'function' && wLower)
    ? resolveJapaneseAuthorFromMultilingualQuery(wLower)
    : (queryInfo.isTranslated ? queryInfo.jpKeyword : null);

  const effectiveLang = (typeof getEffectiveAppUiLanguage === 'function') ? getEffectiveAppUiLanguage() : 'ja';
  // ユーザーの入力言語またはアプリUI言語に合わせてローカライズ
  const outputLang = (queryInfo.isTranslated && queryInfo.detectedLang && queryInfo.detectedLang !== 'ja')
    ? queryInfo.detectedLang
    : (effectiveLang !== 'ja' ? effectiveLang : 'ja');

  const presets = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS))
    ? window.AOZORA_MASTER_WORKS
    : (typeof AOZORA_MASTER_WORKS !== 'undefined' ? AOZORA_MASTER_WORKS : []);

  const toHira = (s) => String(s || '').replace(/[\u30a1-\u30f6]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0x60));
  const toKata = (s) => String(s || '').replace(/[\u3041-\u3096]/g, ch => String.fromCharCode(ch.charCodeAt(0) + 0x60));
  const buildTokenVariants = (tok) => {
    const vars = new Set();
    const addV = (v) => { if (v) vars.add(v); };
    addV(tok);
    addV(toHira(tok));
    addV(toKata(tok));
    return Array.from(vars);
  };

  // スペース区切りのAND検索トークン群（各トークンはいずれかの表記ゆれバリアントに一致すればOK）
  const rawTokens = wLower ? wLower.split(/[\s　]+/).filter(Boolean) : [];
  const jpTokens = jpKeywordLower ? jpKeywordLower.split(/[\s　]+/).filter(Boolean) : [];
  const rawTokenVariantGroups = rawTokens.map(buildTokenVariants);
  const jpTokenVariantGroups = jpTokens.map(buildTokenVariants);

  const matchesAllTokenGroups = (titleLower, authorLower, groups) => {
    if (!groups || groups.length === 0) return false;
    const tNoSpace = titleLower.replace(/[\s　]+/g, '');
    const aNoSpace = authorLower.replace(/[\s　]+/g, '');
    const tHira = toHira(tNoSpace);
    const aHira = toHira(aNoSpace);
    return groups.every(variants =>
      variants.some(v =>
        titleLower.includes(v) ||
        authorLower.includes(v) ||
        tNoSpace.includes(v) ||
        aNoSpace.includes(v) ||
        tHira.includes(v) ||
        aHira.includes(v)
      )
    );
  };

  const searchWords = [];
  if (wLower) {
    searchWords.push(wLower);
    if (jpKeywordLower && !searchWords.includes(jpKeywordLower)) {
      searchWords.push(jpKeywordLower);
    }
    const addVariants = (word) => {
      const h = toHira(word);
      if (h && !searchWords.includes(h)) searchWords.push(h);
      const k = toKata(word);
      if (k && !searchWords.includes(k)) searchWords.push(k);
      const noSpace = word.replace(/[\s　]+/g, '');
      if (noSpace && !searchWords.includes(noSpace)) searchWords.push(noSpace);
      const hNoSpace = toHira(noSpace);
      if (hNoSpace && !searchWords.includes(hNoSpace)) searchWords.push(hNoSpace);
    };
    addVariants(wLower);
    if (jpKeywordLower) addVariants(jpKeywordLower);
  }

  const results = [];
  const seenKeys = new Set();
  const seenIds = new Set();

  // 1. プリセットから優先抽出（作品名・作家名による排他的マッチング）
  for (const p of presets) {
    const t = p._t !== undefined ? p._t : (p._t = (p.title || '').toLowerCase());
    const a = p._a !== undefined ? p._a : (p._a = (p.author || '').toLowerCase());

    let match = true;
    let matchScore = 0;
    let matchSnippet = '';
    let matchType = 'title';

    if (wLower) {
      const matchedRaw = matchesAllTokenGroups(t, a, rawTokenVariantGroups);
      const matchedJp = jpTokenVariantGroups.length > 0 && matchesAllTokenGroups(t, a, jpTokenVariantGroups);
      const multiMatch = (typeof matchesAozoraMultilingualSearch === 'function')
        ? matchesAozoraMultilingualSearch(p, wLower)
        : false;

      if (matchedRaw || matchedJp || multiMatch) {
        for (const q of searchWords) {
          if (!q) continue;
          if (t === q) {
            matchScore = Math.max(matchScore, 1000); matchType = 'title_exact';
          } else if (t.startsWith(q)) {
            matchScore = Math.max(matchScore, 800); matchType = 'title_prefix';
          } else if (t.includes(q)) {
            matchScore = Math.max(matchScore, 500); matchType = 'title_partial';
          } else if (a === q) {
            matchScore = Math.max(matchScore, 450); matchType = 'author_exact';
          } else if (a.includes(q)) {
            matchScore = Math.max(matchScore, 350); matchType = 'author';
          }
        }
        if (matchScore === 0) {
          matchScore = multiMatch ? 300 : 250;
        }
      } else {
        match = false;
      }
    }

    if (aLower && !a.includes(aLower) && (!mappedAuthorJp || !a.includes(mappedAuthorJp.toLowerCase()))) {
      match = false;
    }

    if (match) {
      const id = p.id || p.ncode;
      const key = `${p.title}__${p.author}`;
      seenIds.add(id);
      if (p.ncode) seenIds.add(p.ncode);
      seenKeys.add(key);

      const loc = (typeof getLocalizedAozoraWork === 'function') ? getLocalizedAozoraWork(p, outputLang) : null;
      results.push({
        id: p.id || id,
        ncode: p.id || id,
        title: loc ? loc.displayTitle : p.title,
        _orig_title: p.title,
        author: loc ? loc.displayAuthor : p.author,
        _orig_author: p.author,
        synopsis: loc ? loc.displaySynopsis : (p.synopsis || ''),
        opening: loc ? loc.displayOpening : (p.opening || ''),
        opening_label: loc ? loc.openingLabel : '',
        quotes: p.quotes || [],
        characters: p.characters || [],
        keywords: p.keywords || [],
        matchSnippet: matchSnippet,
        matchType: matchType,
        matchScore: matchScore,
        card_url: p.card_url || '',
        html_url: p.html_url || '',
        text_url: p.text_url || '',
        genre: loc ? loc.displayGenre : (p.genre || '青空文庫名作'),
        is_preset: true,
        text: p.text || ''
      });
    }
  }

  // 2. 全作品インデックスのロードと高速走査（作品名・作家名による排他的マッチング）
  const indexData = await loadAozoraIndexIfNeeded();
  if (Array.isArray(indexData)) {
    const jpAuthorLower = mappedAuthorJp ? mappedAuthorJp.toLowerCase() : '';
    const summariesDict = (typeof window !== 'undefined' && window.AOZORA_SUMMARIES_DICT) ? window.AOZORA_SUMMARIES_DICT : null;

    for (let i = 0, len = indexData.length; i < len; i++) {
      const item = indexData[i];
      const t = item._t !== undefined ? item._t : (item.title || '').toLowerCase();
      const a = item._a !== undefined ? item._a : (item.author || '').toLowerCase();

      // 要約辞書に登録されている作品か確認（表示用メタデータとしてのみ使用）
      const sumMeta = summariesDict ? (summariesDict[item.title] || summariesDict[item.title.replace(/[\s　]+/g, '')]) : null;

      const matchesWord = !wLower ||
        matchesAllTokenGroups(t, a, rawTokenVariantGroups) ||
        (jpTokenVariantGroups.length > 0 && matchesAllTokenGroups(t, a, jpTokenVariantGroups)) ||
        (jpAuthorLower && a.includes(jpAuthorLower));

      if (!matchesWord) continue;
      if (aLower && !a.includes(aLower)) continue;

      const id = item.id;
      const key = `${item.title}__${item.author}`;
      if (!seenIds.has(id) && !seenKeys.has(key)) {
        seenIds.add(id);
        seenKeys.add(key);

        let matchScore = 100;
        if (searchWords.some(q => t === q)) matchScore = 900;
        else if (searchWords.some(q => t.startsWith(q))) matchScore = 600;
        else if (searchWords.some(q => t.includes(q))) matchScore = 400;

        results.push({
          ...item,
          matchScore: matchScore,
          _sumMeta: sumMeta
        });
      }
    }
  }

  // 関連度スコア順に降順ソート（タイトル完全一致や名言・要約一致が最上位に表示される）
  if (wLower) {
    results.sort((a, b) => (b.matchScore || 0) - (a.matchScore || 0));
  }

  const total = results.length;
  const start = (page - 1) * limit;
  const isJaSearch = outputLang === 'ja';
  const locGenreFallback = isJaSearch
    ? '青空文庫作品'
    : ({ en: 'Aozora Bunko Classic', zh: '青空文库作品', ko: '아오조라 문고 작품', es: 'Obra de Aozora Bunko', fr: 'Œuvre Aozora Bunko', pt: 'Obra da Aozora Bunko' }[effectiveLang] || 'Aozora Bunko Classic');

  const paged = results.slice(start, start + limit).map(entry => {
    if (entry.is_preset) return entry;
    const locAuthor = (typeof getLocalizedAozoraAuthor === 'function') ? getLocalizedAozoraAuthor(entry.author, effectiveLang) : entry.author;
    const sumMeta = entry._sumMeta;
    const locSynopsis = sumMeta
      ? sumMeta.synopsis
      : (isJaSearch
          ? `${locAuthor} - 『${entry.title}』`
          : `${locAuthor} — "${entry.title}"`);
    return {
      id: entry.id,
      ncode: entry.id,
      title: entry.title,
      author: locAuthor,
      synopsis: locSynopsis,
      opening: sumMeta ? sumMeta.opening : '',
      quotes: sumMeta ? sumMeta.quotes : [],
      characters: sumMeta ? sumMeta.characters : [],
      keywords: sumMeta ? sumMeta.keywords : [],
      card_url: entry.card_url || '',
      html_url: entry.html_url || '',
      text_url: entry.text_url || '',
      genre: (sumMeta && sumMeta.category) || locGenreFallback,
      is_preset: false,
      text: ''
    };
  });

  return {
    total_count: total,
    total: total,
    page: page,
    limit: limit,
    works: paged
  };
}

async function getAozoraNovelIndexClient(ncode) {
  const normNcode = (ncode || '').trim().toLowerCase();

  // 1. オフラインIndexedDBキャッシュを確認（旧要約テキストや旧ルビ正規表現キャッシュは _clean_rev で自動再生成）
  let cached = await NarouIDB.getNovel(normNcode);
  if (cached && cached._clean_rev === AOZORA_CLEAN_SEGMENT_REV && (cached.is_downloaded || (cached.episodes && cached.episodes.length > 0))) {
    return cached;
  }

  // 2. プリセットから検索
  const presets = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS))
    ? window.AOZORA_MASTER_WORKS
    : (typeof AOZORA_MASTER_WORKS !== 'undefined' ? AOZORA_MASTER_WORKS : []);
  let work = presets.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, normNcode) : ((w.id || '').toLowerCase() === normNcode || (w.ncode || '').toLowerCase() === normNcode));

  // 3. なければ全作品インデックスから検索
  if (!work) {
    const indexData = await loadAozoraIndexIfNeeded();
    if (Array.isArray(indexData)) {
      work = indexData.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, normNcode) : ((w.id || '').toLowerCase() === normNcode));
    }
  }

  const title = work?.title || normNcode.toUpperCase();
  const author = work?.author || '青空文庫作者';
  const synopsis = work?.synopsis || `${author}による青空文庫の文学作品『${title}』。`;
  const url = work?.html_url || work?.card_url || `https://www.aozora.gr.jp/${normNcode}`;

  const splitEps = splitAozoraWorkIntoEpisodesClient(
    work?.text || '',
    title,
    work?.firstEpisodeTitle || '全文朗読',
    work?.year || 'パブリックドメイン',
    url
  );

  const novelData = {
    ncode: normNcode,
    title,
    author,
    synopsis,
    story: synopsis,
    site: 'aozora',
    site_name: '青空文庫',
    genre_name: work?.genre || '名作文学',
    is_public_domain: true,
    _clean_rev: AOZORA_CLEAN_SEGMENT_REV,
    total_episodes: splitEps.length,
    episode_count: splitEps.length,
    card_url: work?.card_url || '',
    html_url: work?.html_url || '',
    text_url: work?.text_url || '',
    episodes: splitEps.map(ep => ({
      episode_number: ep.episode_number,
      title: ep.title,
      date: ep.date,
      url: ep.url
    }))
  };

  try {
    await NarouIDB.saveNovel(novelData, false);
  } catch (e) {}

  return novelData;
}

async function getAozoraEpisodeContentClient(ncode, epNum = 1) {
  const normNcode = (ncode || '').trim().toLowerCase();
  const targetEpNum = Math.max(1, parseInt(epNum, 10) || 1);

  // 1. IndexedDB確認（_clean_rev 一致時のみ使用し、旧要約・旧ルビバグキャッシュは無効化）
  const cachedEp = await NarouIDB.getEpisode(normNcode, targetEpNum);
  if (cachedEp && cachedEp._clean_rev === AOZORA_CLEAN_SEGMENT_REV && cachedEp.segments && cachedEp.segments.length > 0) {
    return cachedEp;
  }

  // 2. プリセットから本文確認
  const presets = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS))
    ? window.AOZORA_MASTER_WORKS
    : (typeof AOZORA_MASTER_WORKS !== 'undefined' ? AOZORA_MASTER_WORKS : []);
  let work = presets.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, normNcode) : ((w.id || '').toLowerCase() === normNcode || (w.ncode || '').toLowerCase() === normNcode));

  let fullRawText = work?.text || '';

  // 3. なければ全作品インデックスから取得情報を探す
  if (!fullRawText) {
    if (!work) {
      const indexData = await loadAozoraIndexIfNeeded();
      if (Array.isArray(indexData)) {
        work = indexData.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, normNcode) : ((w.id || '').toLowerCase() === normNcode));
      }
    }

    if (work && (work.html_url || work.card_url)) {
      const targetUrl = work.html_url || work.card_url;
      try {
        const res = await nativeFetch(targetUrl);
        if (res.ok) {
          let html = '';
          if (typeof res.arrayBuffer === 'function') {
            const buf = await res.arrayBuffer();
            try {
              html = new TextDecoder('shift_jis').decode(buf);
            } catch (e) {
              html = new TextDecoder('utf-8').decode(buf);
            }
          } else {
            html = await res.text();
          }
          fullRawText = parseAozoraHtmlBody(html);
          if (fullRawText && work) {
            work.text = fullRawText;
          }
        }
      } catch (e) {
        console.warn('[Aozora] Failed to fetch episode html:', e);
      }
    }
  }

  if (!fullRawText) {
    fullRawText = `${work?.title || '作品'}\n\n${work?.author || ''}\n\n（青空文庫の本文を読み込み中、または通信環境をご確認ください）`;
  }

  const splitEps = splitAozoraWorkIntoEpisodesClient(
    fullRawText,
    work?.title || normNcode,
    work?.firstEpisodeTitle || '全文朗読',
    work?.year || 'パブリックドメイン',
    work?.html_url || work?.card_url || `https://www.aozora.gr.jp/${normNcode}`
  );
  const selectedEp = splitEps[Math.min(splitEps.length - 1, targetEpNum - 1)] || splitEps[0];
  const epRawText = selectedEp?.raw_text || fullRawText;
  const epTitle = selectedEp?.title || work?.firstEpisodeTitle || work?.title || '全文朗読';

  const segments = splitNovelTextToSegments(epRawText);
  const episodeData = {
    ncode: normNcode,
    episode_number: targetEpNum,
    title: epTitle,
    subtitle: epTitle,
    raw_text: epRawText,
    segments,
    total_segments: segments.length,
    _clean_rev: AOZORA_CLEAN_SEGMENT_REV,
    is_cached: true
  };

  try {
    await NarouIDB.saveEpisode(normNcode, targetEpNum, episodeData, false);
  } catch (e) {}

  return episodeData;
}

// スタンドアロンAPIエミュレータ
async function handleStandaloneClientRequest(url, options = {}) {
  // 青空文庫 検索
  if (url.startsWith('/api/aozora/search')) {
    const params = new URL(url, 'http://localhost').searchParams;
    const word = params.get('keyword') || params.get('word') || '';
    const author = params.get('author') || '';
    const page = parseInt(params.get('page') || '1', 10);
    const limit = parseInt(params.get('limit') || '20', 10);

    const searchData = await searchAozoraWorksClient(word, author, page, limit);
    return {
      ok: true,
      json: async () => searchData
    };
  }

  // 青空文庫 プリセットカタログ取得
  if (url.startsWith('/api/aozora/presets')) {
    const presets = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS))
      ? window.AOZORA_MASTER_WORKS
      : (typeof AOZORA_MASTER_WORKS !== 'undefined' ? AOZORA_MASTER_WORKS : []);
    return {
      ok: true,
      json: async () => presets
    };
  }

  // なろう検索
  if (url.startsWith('/api/narou/search')) {
    const params = new URL(url, 'http://localhost').searchParams;
    const word = params.get('word') || '';
    const order = params.get('order') || 'hyoka';
    const genre = params.get('genre') || '';
    const page = params.get('page') || '1';
    const limit = params.get('limit') || '20';

    let narouApiUrl = `https://api.syosetu.com/novelapi/api/?out=json&lim=${limit}&st=${(page - 1) * limit + 1}&order=${order}`;
    if (word) narouApiUrl += `&word=${encodeURIComponent(word)}`;
    if (genre) narouApiUrl += `&genre=${genre}`;

    const res = await nativeFetch(narouApiUrl);
    const data = await res.json();
    const count = data[0]?.allcount || 0;
    const novels = (data.slice(1) || []).map(n => ({
      ncode: (n.ncode || '').toLowerCase(),
      title: n.title || '',
      author: n.writer || '',
      story: n.story || '',
      synopsis: n.story || '',
      genre: n.genre,
      genre_name: 'なろう作品',
      status_text: n.isstop === 2 ? '完結済' : (n.general_all_no === 1 ? '短編' : '連載中'),
      keywords: (n.keyword || '').split(' ').filter(Boolean),
      general_all_no: n.general_all_no || 1,
      total_episodes: n.general_all_no || 1,
      allcount: count,
      global_point: n.global_point || 0,
      fav_count: n.fav_novel_cnt || 0,
      review_cnt: n.review_cnt || 0,
      length: n.length || 0,
    }));

    return {
      ok: true,
      json: async () => ({ novels, total_count: count, page: Number(page), limit: Number(limit) })
    };
  }

  // 青空文庫 小説詳細 & 目次取得
  if (url.match(/\/api\/aozora\/novel\/([^\/?#]+)/i) || url.match(/\/api\/narou\/novel\/(aozora_[^\/?#]+)/i)) {
    const match = url.match(/\/api\/aozora\/novel\/([^\/?#]+)/i) || url.match(/\/api\/narou\/novel\/(aozora_[^\/?#]+)/i);
    const ncode = match[1].toLowerCase();
    const novelData = await getAozoraNovelIndexClient(ncode);
    return {
      ok: true,
      json: async () => novelData
    };
  }

  // なろう小説詳細 & 目次取得 (オフライン優先 & 堅牢パース)
  if (url.match(/\/api\/narou\/novel\/([^\/?#]+)/)) {
    const ncode = url.match(/\/api\/narou\/novel\/([^\/?#]+)/)[1].toLowerCase();

    // 1. オフラインIndexedDBキャッシュを優先確認
    // 短編（1話）も保存済みならネット再取得せず返す（旧条件 length > 1 だと短編が常にオンライン依存になっていた）
    let cachedNovel = await NarouIDB.getNovel(ncode);
    if (cachedNovel) {
      const eps = Array.isArray(cachedNovel.episodes) ? cachedNovel.episodes : [];
      if (cachedNovel.is_downloaded || eps.length >= 1) {
        if (eps.length === 0 && cachedNovel.is_downloaded) {
          const epCount = await NarouIDB.getEpisodeCount(ncode);
          if (epCount > 0) {
            cachedNovel = {
              ...cachedNovel,
              episodes: Array.from({ length: epCount }, (_, i) => ({
                episode_number: i + 1,
                title: `第${i + 1}話`,
                date: '',
                url: `https://ncode.syosetu.com/${ncode}/${i + 1}/`
              })),
              total_episodes: cachedNovel.total_episodes || epCount,
              episode_count: cachedNovel.episode_count || epCount
            };
          }
        }
        if ((cachedNovel.episodes && cachedNovel.episodes.length >= 1) || cachedNovel.is_downloaded) {
          return {
            ok: true,
            json: async () => cachedNovel
          };
        }
      }
    }

    try {
      const pageUrl = `https://ncode.syosetu.com/${ncode}/`;
      const res = await nativeFetch(pageUrl);
      const html = await res.text();

      const parser = new DOMParser();
      const doc = parser.parseFromString(html, 'text/html');

      const title = doc.querySelector('.novel_title, h1.p-novel__title, .p-novel__title')?.textContent?.trim()?.replace(/ - 小説家になろう$/, '') || ncode.toUpperCase();
      const author = doc.querySelector('.novel_writername, .p-novel__author a, .p-novel__author')?.textContent?.trim() || '作者不明';
      const story = doc.querySelector('#novel_ex, .p-novel__summary')?.textContent?.trim() || '';

      const episodes = [];
      const seenEps = new Set();

      // 新旧・SP/PCデザインの全目次セレクタに対応
      const epSublists = doc.querySelectorAll('.p-eplist__sublist, .novel_sublist2, .p-eplist__item, .p-novel__index-item');
      epSublists.forEach((el, i) => {
        const a = el.querySelector('a') || (el.tagName === 'A' ? el : null);
        if (a) {
          const href = a.getAttribute('href') || '';
          const m = href.match(new RegExp(`/${ncode}/(\\d+)/`, 'i'));
          if (m) {
            const epNum = parseInt(m[1], 10);
            if (!seenEps.has(epNum)) {
              seenEps.add(epNum);
              const epTitle = a.textContent?.trim() || `第${epNum}話`;
              const postDate = el.querySelector('.long_update, .p-novel__index-item-date, .p-eplist__update')?.textContent?.trim() || '';
              episodes.push({ episode_number: epNum, title: epTitle, date: postDate, url: `https://ncode.syosetu.com${href}` });
            }
          }
        }
      });

      // フォールバック: 全リンクから /ncode/(\d+)/ を抽出
      if (episodes.length === 0) {
        const allLinks = doc.querySelectorAll(`a[href*="/${ncode}/"]`);
        allLinks.forEach((a) => {
          const href = a.getAttribute('href') || '';
          const m = href.match(new RegExp(`/${ncode}/(\\d+)/`, 'i'));
          if (m) {
            const epNum = parseInt(m[1], 10);
            if (!seenEps.has(epNum)) {
              seenEps.add(epNum);
              const epTitle = a.textContent?.trim() || `第${epNum}話`;
              episodes.push({ episode_number: epNum, title: epTitle, date: '', url: href.startsWith('http') ? href : `https://ncode.syosetu.com${href}` });
            }
          }
        });
      }

      episodes.sort((a, b) => a.episode_number - b.episode_number);

      // なろうAPIから総話数を取得して後続エピソード枠を補完
      let totalAllNo = episodes.length;
      try {
        const apiRes = await nativeFetch(`https://api.syosetu.com/novelapi/api/?ncode=${ncode}&out=json`);
        const apiData = await apiRes.json();
        if (apiData && apiData[1] && apiData[1].general_all_no) {
          totalAllNo = Math.max(totalAllNo, apiData[1].general_all_no);
          for (let ep = episodes.length + 1; ep <= totalAllNo; ep++) {
            if (!seenEps.has(ep)) {
              seenEps.add(ep);
              episodes.push({ episode_number: ep, title: `第${ep}話`, date: '', url: `https://ncode.syosetu.com/${ncode}/${ep}/` });
            }
          }
          episodes.sort((a, b) => a.episode_number - b.episode_number);
        }
      } catch (e) {
        console.warn('Narou API count fetch fallback:', e);
      }

      if (episodes.length === 0) {
        episodes.push({ episode_number: 1, title: '本文 (短編)', date: '', url: pageUrl, is_short_story: true });
        totalAllNo = 1;
      }

      const novelResult = {
        ncode: ncode.toLowerCase(),
        title,
        author,
        synopsis: story,
        story,
        total_episodes: episodes.length,
        episode_count: episodes.length,
        episodes
      };

      // IndexedDBに一時メタデータを保持
      await NarouIDB.saveNovel(novelResult, false);

      return {
        ok: true,
        json: async () => novelResult
      };
    } catch (err) {
      if (cachedNovel) {
        return {
          ok: true,
          json: async () => cachedNovel
        };
      }
      throw err;
    }
  }

  // 青空文庫 エピソード本文取得
  if (url.match(/\/api\/(?:aozora|narou)\/episode\/(aozora_[^\/?#]+)\/(\d+)/i)) {
    const match = url.match(/\/api\/(?:aozora|narou)\/episode\/(aozora_[^\/?#]+)\/(\d+)/i);
    const ncode = match[1].toLowerCase();
    const epNum = parseInt(match[2], 10);
    const epData = await getAozoraEpisodeContentClient(ncode, epNum);
    return {
      ok: true,
      json: async () => epData
    };
  }

  // なろうエピソード本文取得 (完全オフライン朗読優先)
  if (url.match(/\/api\/narou\/episode\/([^\/?#]+)\/(\d+)/)) {
    const match = url.match(/\/api\/narou\/episode\/([^\/?#]+)\/(\d+)/);
    const ncode = match[1].toLowerCase();
    const epNum = parseInt(match[2], 10);

    // 1. オフラインキャッシュ確認（旧分割キャッシュの断片を自動結合）
    const cachedEp = await NarouIDB.getEpisode(ncode, epNum);
    if (cachedEp && cachedEp.segments && cachedEp.segments.length > 0) {
      if (typeof normalizeAndMergeBrokenSegments === 'function') {
        cachedEp.segments = normalizeAndMergeBrokenSegments(cachedEp.segments);
      }
      return {
        ok: true,
        json: async () => cachedEp
      };
    }

    // 2. なろう公式WEBから本文スクレイピング
    const epUrl = `https://ncode.syosetu.com/${ncode}/${epNum}/`;
    const res = await nativeFetch(epUrl);
    if (res.status === 403 || res.status === 404) {
      return {
        ok: false,
        status: res.status,
        json: async () => ({ detail: 'エピソードの取得に失敗しました（非公開または制限）' })
      };
    }
    const html = await res.text();
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');

    // Google Play R18 判定
    const docText = doc.body?.textContent || '';
    if (docText.includes('ノクターンノベルズ') || docText.includes('ムーンライトノベルズ') || docText.includes('ミッドナイトノベルズ') || docText.includes('18歳未満')) {
      return {
        ok: false,
        status: 403,
        json: async () => ({ detail: 'Google Playポリシー遵守のため、成人向け（R18）コンテンツの朗読はできません。' })
      };
    }

    const subtitle = doc.querySelector('.novel_subtitle, .p-novel__subtitle, .p-novel__title')?.textContent?.trim() || `第${epNum}話`;
    const honbunEl = doc.querySelector('#novel_honbun, .p-novel__text, .p-novel__body');
    const segments = splitNovelTextToSegments(honbunEl?.innerHTML || '');

    const episodeData = {
      ncode,
      episode_number: epNum,
      title: subtitle,
      subtitle,
      segments,
      total_segments: segments.length,
      is_cached: true
    };

    // 一時キャッシュとしてIndexedDBへ保存
    await NarouIDB.saveEpisode(ncode, epNum, episodeData, false);

    return {
      ok: true,
      json: async () => episodeData
    };
  }

  // なろう小説ダウンロード状態確認
  if (url.match(/\/api\/narou\/download\/status\/([^\/?#]+)/)) {
    const ncode = url.match(/\/api\/narou\/download\/status\/([^\/?#]+)/)[1].toLowerCase();
    const novel = await NarouIDB.getNovel(ncode);
    const savedCount = await NarouIDB.getEpisodeCount(ncode);
    const total = novel?.total_episodes || novel?.episodes?.length || savedCount;

    return {
      ok: true,
      json: async () => ({
        ncode,
        downloaded: (novel?.is_downloaded === true && savedCount > 0 && savedCount >= total) || (savedCount > 0 && total > 0 && savedCount >= total),
        downloaded_count: savedCount,
        total_episodes: total || 1,
        saved_at: novel?.saved_at || null
      })
    };
  }

  // なろう小説一括ダウンロード (スマホ本体単体スタンドアロン実行)
  if (url.match(/\/api\/narou\/download\/([^\/?#]+)/) && (options.method === 'POST' || !options.method)) {
    const ncode = url.match(/\/api\/narou\/download\/([^\/?#]+)/)[1].toLowerCase();
    const body = options.body ? (typeof options.body === 'string' ? JSON.parse(options.body) : options.body) : {};
    const startEp = Number(body.start_episode || 1);
    const requestedMaxEps = Number(body.max_episodes || 0);

    // 1. 小説目次情報の取得または確認
    let novel = await NarouIDB.getNovel(ncode);
    if (!novel || !novel.episodes || novel.episodes.length <= 1) {
      const novRes = await handleStandaloneClientRequest(`/api/narou/novel/${ncode}`);
      if (novRes.ok) {
        novel = await novRes.json();
      }
    }

    const totalEpCount = novel?.total_episodes || novel?.episodes?.length || 1;
    const maxEps = requestedMaxEps > 0 ? requestedMaxEps : totalEpCount;
    const endEp = Math.min(totalEpCount, startEp + maxEps - 1);
    let downloadedCount = 0;
    let totalBytes = 0;
    let aborted = false;
    let newlySavedCount = 0;

    const progressBarFill = document.getElementById('downloadProgressBarFill');
    const percentLabel = document.getElementById('downloadPercentLabel');
    const statusLabel = document.getElementById('downloadStatusLabel');
    const epProgressLabel = document.getElementById('downloadEpisodeCounter')
      || document.getElementById('downloadEpisodeProgress');

    // 取得開始時点でメタデータを保存（保存済タブに途中表示できるようにする）
    if (novel) {
      try {
        await NarouIDB.saveNovel({
          ...novel,
          downloaded_episodes: await NarouIDB.getEpisodeCount(ncode),
          saved_at: novel.saved_at || Date.now()
        }, false);
      } catch (e) {}
    }

    reportNovelDownloadProgress({
      ncode,
      title: novel?.title || ncode,
      startEp,
      endEp,
      currentEp: startEp,
      downloadedCount: 0,
      pct: 1,
      statusText: `『${novel?.title || ncode}』の取得を開始…`,
      counterText: `0 / ${endEp}話完了`,
      phase: 'running'
    });

    for (let ep = startEp; ep <= endEp; ep++) {
      if (NovelDownloadGate.shouldAbort()) {
        aborted = true;
        break;
      }

      // 既に保存済みか確認
      const existing = await NarouIDB.getEpisode(ncode, ep);
      if (existing && existing.segments && existing.segments.length > 0) {
        downloadedCount++;
        const pct = Math.round(((ep - startEp + 1) / (endEp - startEp + 1)) * 100);
        if (progressBarFill) progressBarFill.style.width = `${pct}%`;
        if (percentLabel) percentLabel.textContent = `${pct}%`;
        if (epProgressLabel) epProgressLabel.textContent = `${downloadedCount} / ${endEp}話完了`;
        reportNovelDownloadProgress({
          ncode,
          title: novel?.title || ncode,
          startEp,
          endEp,
          currentEp: ep,
          downloadedCount,
          pct,
          statusText: `第${ep}話は保存済（スキップ）`,
          counterText: `${downloadedCount} / ${endEp}話完了`,
          phase: 'running'
        });
        continue;
      }

      // UI進捗更新
      const pct = Math.round(((ep - startEp + 1) / (endEp - startEp + 1)) * 100);
      if (progressBarFill) progressBarFill.style.width = `${pct}%`;
      if (percentLabel) percentLabel.textContent = `${pct}%`;
      if (statusLabel) statusLabel.textContent = `第${ep}話 / 全${endEp}話をダウンロード中...`;
      if (epProgressLabel) epProgressLabel.textContent = `${downloadedCount} / ${endEp}話完了`;
      reportNovelDownloadProgress({
        ncode,
        title: novel?.title || ncode,
        startEp,
        endEp,
        currentEp: ep,
        downloadedCount,
        pct,
        statusText: `第${ep}話 / 全${endEp}話を取得中…`,
        counterText: `${downloadedCount} / ${endEp}話完了`,
        phase: 'running'
      });

      // サーバー配慮待機（0.6秒）— 中止要求時は早めに抜ける
      if (ep > startEp) {
        for (let w = 0; w < 6; w++) {
          if (NovelDownloadGate.shouldAbort()) break;
          await new Promise(r => setTimeout(r, 100));
        }
        if (NovelDownloadGate.shouldAbort()) {
          aborted = true;
          break;
        }
      }

      try {
        const epUrl = `https://ncode.syosetu.com/${ncode}/${ep}/`;
        const res = await nativeFetch(epUrl);
        if (NovelDownloadGate.shouldAbort()) {
          aborted = true;
          break;
        }
        const html = await res.text();
        totalBytes += html.length;

        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');
        const title = doc.querySelector('.novel_subtitle, .p-novel__subtitle')?.textContent?.trim() || `第${ep}話`;
        const honbunEl = doc.querySelector('#novel_honbun, .p-novel__text, .p-novel__body');
        const segments = splitNovelTextToSegments(honbunEl?.innerHTML || '');

        await NarouIDB.saveEpisode(ncode, ep, {
          ncode,
          episode_number: ep,
          title,
          subtitle: title,
          segments,
          total_segments: segments.length
        }, true);
        downloadedCount++;
        newlySavedCount++;
        reportNovelDownloadProgress({
          ncode,
          title: novel?.title || ncode,
          startEp,
          endEp,
          currentEp: ep,
          downloadedCount,
          pct,
          statusText: `第${ep}話を保存しました`,
          counterText: `${downloadedCount} / ${endEp}話完了`,
          phase: 'running'
        });

        // 1話でも保存できたら保存済タブへ即反映
        if (newlySavedCount === 1 || newlySavedCount % 5 === 0) {
          await persistPartialDownloadToLibrary(novel, await NarouIDB.getEpisodeCount(ncode));
        }

        // 新規取得30話ごとに全画面広告（閉じるまで一時停止）
        try {
          await maybeShowDownloadInterstitialAdBreak({
            ncode,
            title: novel?.title || ncode,
            startEp,
            endEp,
            currentEp: ep,
            downloadedCount,
            pct,
            counterText: `${downloadedCount} / ${endEp}話完了`
          });
        } catch (adErr) {
          console.warn('[Download] Interstitial break failed:', adErr);
        }
        if (NovelDownloadGate.shouldAbort()) {
          aborted = true;
          break;
        }
      } catch (err) {
        console.warn(`[Download] Episode ${ep} download failed:`, err);
      }
    }

    // 最終的な保存済反映（中止時も含む）
    const finalEpCount = await NarouIDB.getEpisodeCount(ncode);
    if (finalEpCount > 0 && novel) {
      await persistPartialDownloadToLibrary(novel, finalEpCount);
    }

    const endPhase = aborted ? 'cancelled' : 'done';
    const endStatus = aborted
      ? `⏹ 中止しました（${finalEpCount}話まで保存済み）`
      : `✔ ${downloadedCount}話の取得が完了しました`;

    reportNovelDownloadProgress({
      ncode,
      title: novel?.title || ncode,
      startEp,
      endEp,
      currentEp: Math.min(endEp, startEp + downloadedCount),
      downloadedCount: finalEpCount || downloadedCount,
      pct: aborted ? Math.round(((finalEpCount || downloadedCount) / Math.max(1, endEp)) * 100) : 100,
      statusText: endStatus,
      counterText: `${finalEpCount || downloadedCount} / ${endEp}話${aborted ? '（中止）' : '完了'}`,
      phase: endPhase
    });

    // 小説メタデータをダウンロード済みストレージとして更新保存
    if (novel && finalEpCount > 0) {
      novel.is_downloaded = true;
      novel.downloaded_episodes = finalEpCount;
      novel.saved_at = Date.now();
      await NarouIDB.saveNovel(novel, true);
      scheduleDownloadsTabRefresh(200);
    }

    // ダウンロード完了後の自動バックグラウンド音声生成 (VOICEVOXキャッシュ)
    if (!aborted && localStorage.getItem('narou_auto_generate_audio') !== 'false') {
      setTimeout(() => {
        try {
          triggerBackgroundAudioGeneration(ncode, startEp, endEp);
        } catch (e) {
          console.warn('[Download] Auto audio generation trigger failed:', e);
        }
      }, 500);
    }

    return {
      ok: true,
      json: async () => ({
        success: true,
        aborted: !!aborted,
        ncode,
        title: novel?.title || ncode,
        downloaded_count: finalEpCount || downloadedCount,
        start_episode: startEp,
        end_episode: endEp,
        total_episodes: totalEpCount,
        bytes_downloaded: totalBytes,
        message: aborted
          ? `『${novel?.title || ncode}』のダウンロードを中止しました（${finalEpCount || downloadedCount}話まで保存済み）`
          : `『${novel?.title || ncode}』の第${startEp}話〜第${endEp}話（計${downloadedCount}話）をオフライン保存しました！`
      })
    };
  }

  // 保存済み小説一覧 (GET: DLボタンで保存された作品のみを抽出)
  if (url.startsWith('/api/downloads/novels') && (!options.method || options.method === 'GET')) {
    const novels = await NarouIDB.getAllDownloadedNovels();
    const resultList = [];

    for (const n of novels) {
      const epCount = await NarouIDB.getEpisodeCount(n.ncode);
      const totalEps = n.total_episodes || n.episodes?.length || (epCount > 0 ? epCount : 1);
      const isComplete = totalEps > 0 && epCount >= totalEps;
      const progressPercent = totalEps > 0 ? Math.min(100, Math.round((epCount / totalEps) * 100)) : 100;
      const sizeMb = (epCount * 0.05).toFixed(1);

      resultList.push({
        ncode: n.ncode,
        title: n.title || n.ncode.toUpperCase(),
        author: n.author || '作者不明',
        synopsis: n.synopsis || n.story || '',
        total_episodes: totalEps,
        downloaded_count: epCount,
        downloaded_episodes_count: epCount,
        saved_episodes_count: epCount,
        is_complete: isComplete,
        progress_percent: progressPercent,
        size_mb: sizeMb,
        has_txt: true,
        has_full_txt: true,
        audio_cache_count: 0,
        saved_at: n.saved_at || Date.now(),
        last_updated: n.saved_at ? Math.floor(n.saved_at / 1000) : Math.floor(Date.now() / 1000)
      });
    }

    return {
      ok: true,
      json: async () => ({ success: true, novels: resultList, total_novels: resultList.length })
    };
  }

  // 個別小説の保存データ削除 (DELETE)
  if (url.match(/\/api\/downloads\/novels\/([^\/?#]+)/) && options.method === 'DELETE') {
    const ncode = url.match(/\/api\/downloads\/novels\/([^\/?#]+)/)[1].toLowerCase();
    await NarouIDB.deleteNovel(ncode);
    return {
      ok: true,
      json: async () => ({ success: true, ncode, freed_mb: "1.2" })
    };
  }

  // ストレージ使用量サマリー (GET)
  if (url.startsWith('/api/downloads/summary')) {
    const summary = await NarouIDB.estimateStorage();
    return {
      ok: true,
      json: async () => ({ success: true, summary })
    };
  }

  // 全保存データ削除 (DELETE)
  if (url.startsWith('/api/downloads/all') && options.method === 'DELETE') {
    await NarouIDB.clearAll();
    return {
      ok: true,
      json: async () => ({ success: true, freed_mb: "10.5" })
    };
  }

  // 音声キャッシュ削除 (DELETE)
  if (url.startsWith('/api/downloads/audio') && options.method === 'DELETE') {
    return {
      ok: true,
      json: async () => ({ success: true, freed_mb: "0.0" })
    };
  }

  // エピソード準備 (/api/narou/episode/prepare) のスタンドアロン・iOSオフライン対応
  if (url.startsWith('/api/narou/episode/prepare')) {
    const body = options.body ? (typeof options.body === 'string' ? JSON.parse(options.body) : options.body) : {};
    const ncode = String(body.ncode || state.currentNovel?.ncode || '').toLowerCase();
    const episodeNum = Number(body.episode_num || 1);
    const epRes = await handleStandaloneClientRequest(`/api/narou/episode/${encodeURIComponent(ncode)}/${episodeNum}`);
    if (!epRes.ok) return epRes;
    const epData = await epRes.json();
    const rawSegs = epData.segments || [];
    const analysis = await performAiAnalysisForEpisode(rawSegs, state.currentNovel?.title || epData.title || '', episodeNum);
    return {
      ok: true,
      status: 200,
      json: async () => ({
        ...epData,
        segments: analysis.segments || rawSegs,
        characters: analysis.characters || [],
        cast: analysis.cast || {},
        cast_profiles: analysis.cast_profiles || {},
        _engine: analysis._engine || 'standalone_ios'
      })
    };
  }

  // 話者・感情推定
  if (url.startsWith('/api/analyze/episode')) {
    const body = options.body ? (typeof options.body === 'string' ? JSON.parse(options.body) : options.body) : {};
    const segments = body.segments || [];
    const novelTitle = body.novel_title || '';
    const episodeNum = body.episode_num || 1;

    const result = await performAiAnalysisForEpisode(segments, novelTitle, episodeNum);
    return { ok: true, json: async () => result };
  }

  // TTSボイス一覧
  if (url.startsWith('/api/voices') || url.startsWith('/api/tts/voices')) {
    let voices = [];
    if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.getAvailableTtsVoices === 'function') {
      try {
        const nativeVoices = JSON.parse(window.AndroidBridge.getAvailableTtsVoices());
        voices = nativeVoices.map((v) => ({
          id: v.name,
          name: `Android ${v.name.split('#')[1] || v.name}`,
          gender: v.name.toLowerCase().includes('male') && !v.name.toLowerCase().includes('female') ? 'male' : 'female',
          quality: '標準 (端末内蔵)',
          engine: 'android_native'
        }));
      } catch (e) {}
    }

    if (voices.length === 0) {
      voices = [
        { id: 'ja-JP-NanamiNeural', name: 'Nanami (七海 - 女声/標準・推奨)', gender: 'female', quality: '高品質 (Edge-TTS)', engine: 'edge_tts' },
        { id: 'ja-JP-KeitaNeural', name: 'Keita (圭太 - 男声/標準・推奨)', gender: 'male', quality: '高品質 (Edge-TTS)', engine: 'edge_tts' },
        { id: 'ja-JP-AoiNeural', name: 'Aoi (葵 - 女声/朗読向け)', gender: 'female', quality: '高品質 (Edge-TTS)', engine: 'edge_tts' },
        { id: 'ja-JP-DaichiNeural', name: 'Daichi (大地 - 男声/重厚)', gender: 'male', quality: '高品質 (Edge-TTS)', engine: 'edge_tts' },
        { id: 'ja-JP-ShioriNeural', name: 'Shiori (詩織 - 女声/落ち着き)', gender: 'female', quality: '高品質 (Edge-TTS)', engine: 'edge_tts' },
      ];
    }
    return { ok: true, json: async () => ({ voices }) };
  }

  // Gemini 利用可能モデル一覧取得 (Androidスタンドアロン対応)
  if (url.startsWith('/api/gemini/models')) {
    const urlObj = new URL(url, 'http://localhost');
    const apiKey = urlObj.searchParams.get('api_key') || getSettingsFromStorage()?.gemini_api_key || '';
    
    let defaultModels = [
      { id: "gemini-3.8-flash", name: "Gemini 3.8 Flash (最新鋭・最速・推奨)" },
      { id: "gemini-3.8-pro", name: "Gemini 3.8 Pro (最新鋭・最高峰推論・高精度)" },
      { id: "gemini-3.7-flash", name: "Gemini 3.7 Flash" },
      { id: "gemini-3.7-pro", name: "Gemini 3.7 Pro" },
      { id: "gemini-3.6-flash", name: "Gemini 3.6 Flash" },
      { id: "gemini-3.5-flash", name: "Gemini 3.5 Flash" },
      { id: "gemini-3.5-pro", name: "Gemini 3.5 Pro" },
      { id: "gemini-3.0-flash", name: "Gemini 3.0 Flash" },
      { id: "gemini-3.0-pro", name: "Gemini 3.0 Pro" },
      { id: "gemini-3.0-ultra", name: "Gemini 3.0 Ultra (最上位フラグシップ)" },
      { id: "gemini-2.5-flash", name: "Gemini 2.5 Flash" },
      { id: "gemini-2.5-pro", name: "Gemini 2.5 Pro" },
      { id: "gemini-2.0-flash", name: "Gemini 2.0 Flash" },
      { id: "gemini-2.0-flash-lite", name: "Gemini 2.0 Flash-Lite (超軽量・低遅延)" },
      { id: "gemini-2.0-pro-exp-02-05", name: "Gemini 2.0 Pro Experimental" },
      { id: "gemini-2.0-flash-thinking-exp-01-21", name: "Gemini 2.0 Flash Thinking" },
      { id: "gemini-1.5-flash", name: "Gemini 1.5 Flash" },
      { id: "gemini-1.5-pro", name: "Gemini 1.5 Pro" },
      { id: "gemini-1.5-flash-8b", name: "Gemini 1.5 Flash-8B" }
    ];

    if (apiKey) {
      try {
        const fetchRes = await nativeFetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${encodeURIComponent(apiKey)}`, 'GET');
        const data = await fetchRes.json();
        if (data.models && Array.isArray(data.models)) {
          const apiModels = [];
          for (const m of data.models) {
            const methods = m.supportedGenerationMethods || [];
            if (methods.includes('generateContent')) {
              const mId = (m.name || '').replace('models/', '');
              const disp = m.displayName || mId;
              let tag = '';
              if (mId.includes('3.8')) tag = ' (Gemini 3.8系・最先端最新鋭)';
              else if (mId.includes('3.7')) tag = ' (Gemini 3.7系)';
              else if (mId.includes('3.')) tag = ' (Gemini 3系)';
              else if (mId.includes('flash')) tag = ' (高速・推奨)';

              apiModels.push({ id: mId, name: `${disp}${tag} [${mId}]` });
            }
          }
          if (apiModels.length > 0) {
            const existingIds = new Set(apiModels.map(x => x.id));
            for (const dm of defaultModels) {
              if (!existingIds.has(dm.id)) apiModels.push(dm);
            }
            apiModels.sort((a, b) => {
              const va = parseFloat((a.id.match(/(\d+\.\d+)/) || [0, 1.0])[1]);
              const vb = parseFloat((b.id.match(/(\d+\.\d+)/) || [0, 1.0])[1]);
              return vb - va;
            });
            return { ok: true, json: async () => ({ models: apiModels }) };
          }
        }
      } catch (err) {
        console.warn('Native Gemini models fetch failed, using default list:', err);
      }
    }

    return { ok: true, json: async () => ({ models: defaultModels }) };
  }

  return { ok: true, json: async () => ({}) };
}

// =============================================================================
// LLM配役標準エンジン（方針B）— チャンク解析・強化プロンプト・後処理
// =============================================================================
const CAST_LLM_CHUNK_SIZE = 20;
const CAST_LLM_OVERLAP = 2;

/** Gemini / OpenAI / Claude 429 クールダウン */
let _cloudCooldownUntil = { gemini: 0, openai: 0, claude: 0 };
let _localLlmCooldownUntil = 0;
let _lastCastFallbackToastAt = 0;

function isLlmQuotaError(err) {
  const msg = String(err?.message || err || '');
  return /\b429\b/.test(msg) || /quota|rate.?limit|exceeded your current quota|too many requests/i.test(msg);
}

function markCloudCooldownFromError(provider, err) {
  const msg = String(err?.message || err || '');
  const m = msg.match(/retry in ([\d.]+)\s*s/i) || msg.match(/try again in ([\d.]+)\s*s/i);
  const sec = m ? Math.ceil(parseFloat(m[1])) : 60;
  const ms = Math.min(5 * 60 * 1000, Math.max(15_000, sec * 1000 + 2000));
  _cloudCooldownUntil[provider] = Math.max(_cloudCooldownUntil[provider] || 0, Date.now() + ms);
  console.warn(`[CastLLM] ${provider} cooldown ${Math.round(ms / 1000)}s`);
}

function isCloudInCooldown(provider) {
  return Date.now() < (_cloudCooldownUntil[provider] || 0);
}

function isGeminiInCooldown() {
  return isCloudInCooldown('gemini');
}

function markGeminiCooldownFromError(err) {
  markCloudCooldownFromError('gemini', err);
}

function isLocalLlmInCooldown() {
  return Date.now() < _localLlmCooldownUntil;
}

function markLocalLlmCooldown(ms = 120_000) {
  _localLlmCooldownUntil = Math.max(_localLlmCooldownUntil, Date.now() + ms);
}

/** 廃止された pixel_ai を gemini へ正規化 */
function normalizeCastLlmProvider(provider) {
  if (!provider || provider === 'pixel_ai') return 'gemini';
  return provider;
}

function isLocalLlmLikelyReachable(settings = {}) {
  const url = settings.local_llm_url || 'http://127.0.0.1:11434/v1';
  // 手動で local_llm を選んだ場合は試行。非 localhost URL も試行。
  if (settings.llm_provider_manually_set && settings.llm_provider === 'local_llm') return true;
  if (url && !/127\.0\.0\.1|localhost/i.test(url)) return true;
  return false;
}

const CAST_VOICE_TYPES = [
  'female_young', 'female_mature', 'female_calm', 'child_girl',
  'male_young', 'male_elder', 'child_boy', 'neutral_narration'
];

function collectKnownCastContext(novelTitle) {
  const out = [];
  const seen = new Set();
  const push = (name, gender, voiceType, voiceId) => {
    if (!name || seen.has(name)) return;
    seen.add(name);
    out.push({
      name,
      gender: gender || '不明',
      voice_type: voiceType || '',
      voiceId: voiceId || null
    });
  };

  const nTitle = novelTitle || state.currentNovel?.title || '';
  for (const [key, data] of Object.entries(MASTER_NOVEL_CAST_KNOWLEDGE || {})) {
    if (!nTitle.includes(key)) continue;
    Object.entries(data.characters || {}).forEach(([name, c]) => {
      push(name, c.gender, c.voiceType, c.voiceId);
    });
  }

  (state.currentNovelCharacters || []).forEach((c) => {
    if (c?.name) push(c.name, c.gender, c.voice_type || c.voiceType, c.voiceId || c.voicevoxId);
  });

  Object.entries(state.currentCastProfiles || {}).forEach(([name, p]) => {
    push(name, p.gender, p.category, p.voiceId || p.id);
  });

  return out.slice(0, 48);
}

function buildCastAnalysisPrompt(chunkSegments, novelTitle, context = {}) {
  const known = context.knownCharacters || [];
  const knownBlock = known.length
    ? known.map((c) => `- ${c.name} / 性別:${c.gender || '不明'} / voice_type:${c.voice_type || '未定'}`).join('\n')
    : '- （まだ確定キャストなし。本文から推定すること）';
  const lastSpeaker = context.lastSpeaker ? `直前のセリフ話者: ${context.lastSpeaker}` : '直前のセリフ話者: （なし・話冒頭）';
  const linesText = chunkSegments.map((s) => {
    const t = String(s.display_text || '').replace(/\s+/g, ' ').slice(0, 220);
    return `[${s.id}] (${s.type || 'dialogue'}) ${t}`;
  }).join('\n');

  return `あなたは日本語Web小説の朗読演出家です。各行の話者(speaker)・感情(emotion)・キャラ属性を高精度に判定してください。

小説タイトル: ${novelTitle || '不明'}
${lastSpeaker}

【既知キャスト（同一人物は必ずこの名前で統一）】
${knownBlock}

【厳守ルール】
1. type=narration は speaker を必ず「ナレーション」
2. 《》【】＜＞のシステム文・念話は speaker「システム」（作品に大賢者等があればその名でも可）
3. セリフ内の呼びかけ（「スバル！」「エミリアさん」）は呼びかけ先であり話者ではない
4. 俺/僕/私 などの一人称は主人公またはその口調の人物へ。性別と矛盾させない
5. gender は「女性」または「男性」のみ（不明禁止。確信が薄いときも名前・口調・役割から推定）
6. voice_type は次のいずれか: ${CAST_VOICE_TYPES.join(', ')}
7. emotion は normal, happy, angry, sad, excited, whisper, shout のいずれか
8. 別名（敬称付き・短縮）は既知キャストの正式名へ統合
9. 出力はJSONのみ。説明文禁止

【本文】
${linesText}

出力JSON:
{"characters":[{"name":"名前","gender":"女性|男性","voice_type":"female_young"}],"assignments":[{"id":1,"speaker":"名前","emotion":"normal"}]}`;
}

function parseCastAnalysisJson(rawText) {
  if (!rawText || typeof rawText !== 'string') throw new Error('empty LLM cast response');
  let text = rawText.trim();
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) text = fence[1].trim();
  const firstB = text.indexOf('{');
  const lastB = text.lastIndexOf('}');
  if (firstB === -1 || lastB === -1 || lastB <= firstB) throw new Error('LLM cast JSON not found');
  const parsed = JSON.parse(text.slice(firstB, lastB + 1));
  if (!parsed || typeof parsed !== 'object') throw new Error('invalid cast JSON');
  return {
    characters: Array.isArray(parsed.characters) ? parsed.characters : [],
    assignments: Array.isArray(parsed.assignments) ? parsed.assignments : []
  };
}

function resolveVoiceTypeAndId(name, gender, voiceType, novelTitle) {
  const nTitle = novelTitle || state.currentNovel?.title || '';
  for (const [key, data] of Object.entries(MASTER_NOVEL_CAST_KNOWLEDGE || {})) {
    if (!nTitle.includes(key)) continue;
    const hit = data.characters?.[name];
    if (hit) {
      return {
        gender: hit.gender || gender,
        voice_type: hit.voiceType || voiceType,
        voiceId: hit.voiceId || null
      };
    }
  }

  let g = gender;
  if (!g || g === '不明' || g === 'unknown') {
    g = inferGenderAdvancedJs(name, '', '') === 'female' ? '女性' : '男性';
  } else if (g === 'female' || g === '女') {
    g = '女性';
  } else if (g === 'male' || g === '男') {
    g = '男性';
  }
  let vt = voiceType;
  if (!CAST_VOICE_TYPES.includes(vt)) {
    if (name === 'ナレーション' || name === 'システム') vt = 'neutral_narration';
    else if (g === '女性') vt = /幼|少女|姫|たん/.test(name) ? 'child_girl' : (/母|姉|夫人|先生|女王/.test(name) ? 'female_mature' : 'female_young');
    else vt = /爺|老|王|魔王/.test(name) ? 'male_elder' : (/少年|坊/.test(name) ? 'child_boy' : 'male_young');
  }
  const prof = getCharacterVoiceProfile(name, g, vt);
  const bundledPools = {
    female_young: ['voicevox_2', 'voicevox_8', 'voicevox_10', 'voicevox_0', 'voicevox_6'],
    female_mature: ['voicevox_20', 'voicevox_66', 'voicevox_46', 'voicevox_80', 'voicevox_4'],
    female_calm: ['voicevox_2', 'voicevox_10', 'voicevox_46', 'voicevox_80'],
    child_girl: ['voicevox_3', 'voicevox_1', 'voicevox_7'],
    male_young: ['voicevox_11', 'voicevox_21', 'voicevox_81', 'voicevox_83'],
    male_elder: ['voicevox_13', 'voicevox_82', 'voicevox_84'],
    child_boy: ['voicevox_11', 'voicevox_3'],
    neutral_narration: ['voicevox_2']
  };
  const pool = bundledPools[vt] || (g === '女性' ? bundledPools.female_young : bundledPools.male_young);
  const resolvedId = (prof && prof.voicevoxId) ? prof.voicevoxId : pool[stringHash(name) % pool.length];
  return { gender: g, voice_type: vt, voiceId: resolvedId };
}

function postProcessLlmCastResult(segments, characters, novelTitle) {
  const charMap = {};
  (characters || []).forEach((c) => {
    if (!c?.name) return;
    const name = canonicalizeCharacterName(c.name) || c.name;
    const resolved = resolveVoiceTypeAndId(name, c.gender, c.voice_type, novelTitle);
    charMap[name] = {
      name,
      gender: resolved.gender,
      description: c.description || `登場人物 (${name})`,
      voice_type: resolved.voice_type,
      voiceId: resolved.voiceId,
      voice_id: resolved.voiceId
    };
  });

  // 必ずナレーションを用意
  if (!charMap['ナレーション']) {
    const n = resolveVoiceTypeAndId('ナレーション', '女性', 'neutral_narration', novelTitle);
    charMap['ナレーション'] = {
      name: 'ナレーション',
      gender: n.gender,
      description: '地の文・朗読',
      voice_type: n.voice_type,
      voiceId: n.voiceId,
      voice_id: n.voiceId
    };
  }

  const enriched = (segments || []).map((seg) => {
    let speaker = seg.speaker || (seg.type === 'narration' ? 'ナレーション' : '登場人物');
    speaker = canonicalizeCharacterName(speaker) || speaker;
    if (seg.type === 'narration') speaker = 'ナレーション';
    if (!charMap[speaker]) {
      const resolved = resolveVoiceTypeAndId(speaker, seg.gender, seg.voice_type, novelTitle);
      charMap[speaker] = {
        name: speaker,
        gender: resolved.gender,
        description: `登場人物 (${speaker})`,
        voice_type: resolved.voice_type,
        voiceId: resolved.voiceId,
        voice_id: resolved.voiceId
      };
    }
    const c = charMap[speaker];
    return {
      ...seg,
      speaker,
      emotion: seg.emotion || 'normal',
      gender: c.gender,
      voice_type: c.voice_type,
      voiceId: c.voiceId,
      voice_id: c.voiceId
    };
  });

  return {
    characters: Object.values(charMap),
    segments: enriched
  };
}

async function analyzeSegmentsWithLlmChunked(segments, novelTitle, invokeChunkFn) {
  if (!segments?.length) {
    return { characters: [], segments: [] };
  }
  const knownCharacters = collectKnownCastContext(novelTitle);
  const allAssignments = [];
  const charMerge = {};
  let lastSpeaker = null;

  for (let start = 0; start < segments.length; start += CAST_LLM_CHUNK_SIZE) {
    const from = Math.max(0, start - (start === 0 ? 0 : CAST_LLM_OVERLAP));
    const to = Math.min(segments.length, start + CAST_LLM_CHUNK_SIZE);
    const chunk = segments.slice(from, to);
    const prompt = buildCastAnalysisPrompt(chunk, novelTitle, {
      knownCharacters: Object.keys(charMerge).length
        ? Object.values(charMerge).concat(knownCharacters).slice(0, 48)
        : knownCharacters,
      lastSpeaker
    });

    const parsed = await invokeChunkFn(prompt, chunk);
    (parsed.characters || []).forEach((c) => {
      if (!c?.name) return;
      const name = canonicalizeCharacterName(c.name) || c.name;
      charMerge[name] = { ...charMerge[name], ...c, name };
      if (!knownCharacters.find((k) => k.name === name)) {
        knownCharacters.push({ name, gender: c.gender, voice_type: c.voice_type });
      }
    });
    (parsed.assignments || []).forEach((a) => {
      if (a == null || a.id == null) return;
      allAssignments.push(a);
      if (a.speaker && a.speaker !== 'ナレーション') lastSpeaker = a.speaker;
    });
  }

  const assignMap = {};
  allAssignments.forEach((a) => {
    assignMap[Number(a.id)] = a;
  });

  const enriched = segments.map((seg) => {
    const a = assignMap[Number(seg.id)];
    const speaker = a?.speaker || (seg.type === 'narration' ? 'ナレーション' : '登場人物');
    const cInfo = charMerge[canonicalizeCharacterName(speaker) || speaker] || charMerge[speaker];
    return {
      ...seg,
      speaker,
      emotion: a?.emotion || 'normal',
      gender: cInfo?.gender || '不明',
      voice_type: cInfo?.voice_type || (seg.type === 'narration' ? 'neutral_narration' : 'male_young')
    };
  });

  return postProcessLlmCastResult(enriched, Object.values(charMerge), novelTitle);
}

function getDefaultCastLlmProvider(_settings = null) {
  // デフォルトは常に Gemini API。キー未設定・クォータ超過時は他クラウド／Local／ルールへフォールバック。
  return 'gemini';
}

function getActiveCastLlmProvider(settings = null) {
  const s = settings || getSettingsFromStorage() || {};
  if (s.llm_provider_manually_set && s.llm_provider) {
    return normalizeCastLlmProvider(s.llm_provider);
  }
  return getDefaultCastLlmProvider(s);
}

function hasCloudApiKey(provider, settings = {}) {
  if (provider === 'gemini') return !!(settings.gemini_api_key || '').trim();
  if (provider === 'openai') return !!(settings.openai_api_key || '').trim();
  if (provider === 'claude') return !!(settings.claude_api_key || '').trim();
  return false;
}

function resolveOpenaiModel(settings = {}) {
  const custom = (settings.openai_model_custom || '').trim();
  if (custom) return custom;
  return settings.openai_model || 'gpt-4o-mini';
}

function resolveClaudeModel(settings = {}) {
  const custom = (settings.claude_model_custom || '').trim();
  if (custom) return custom;
  return settings.claude_model || 'claude-sonnet-4-5';
}

const AI_TOKEN_USAGE_STORAGE_KEY = 'narou_ai_reader_token_usage_stats_v1';

function getAiTokenUsageStats() {
  try {
    const raw = localStorage.getItem(AI_TOKEN_USAGE_STORAGE_KEY);
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return {
    totalPromptTokens: 0,
    totalCandidatesTokens: 0,
    totalThinkingTokens: 0,
    totalTokens: 0,
    lastRequest: null,
    history: []
  };
}

function saveAiTokenUsageStats(stats) {
  try {
    localStorage.setItem(AI_TOKEN_USAGE_STORAGE_KEY, JSON.stringify(stats));
  } catch (e) {}
  updatePlayerTokenUsageBadgeUI();
  updateAiTokenUsageCardUI();
}

function recordAiTokenUsage(provider, model, usage = {}) {
  const stats = getAiTokenUsageStats();
  const promptTok = Number(usage.prompt_tokens || usage.promptTokenCount || usage.input_tokens || 0);
  const candTok = Number(usage.completion_tokens || usage.candidatesTokenCount || usage.output_tokens || 0);
  const thinkTok = Number(
    usage.reasoning_tokens ||
    usage.completion_tokens_details?.reasoning_tokens ||
    usage.thinking_tokens ||
    usage.candidatesTokensDetails?.thinkingTokens ||
    0
  );
  const totalTok = Number(usage.total_tokens || usage.totalTokenCount || (promptTok + candTok));

  stats.totalPromptTokens += promptTok;
  stats.totalCandidatesTokens += candTok;
  stats.totalThinkingTokens += thinkTok;
  stats.totalTokens += totalTok;

  stats.lastRequest = {
    provider,
    model,
    promptTokens: promptTok,
    candidatesTokens: candTok,
    thinkingTokens: thinkTok,
    totalTokens: totalTok,
    timestamp: Date.now()
  };

  if (!stats.history) stats.history = [];
  stats.history.unshift(stats.lastRequest);
  if (stats.history.length > 30) stats.history.pop();

  saveAiTokenUsageStats(stats);
}

function updatePlayerTokenUsageBadgeUI() {
  const badgeEl = document.getElementById('playerTokenUsageBadge');
  const textEl = document.getElementById('playerTokenUsageBadgeText');
  if (!badgeEl || !textEl) return;
  const stats = getAiTokenUsageStats();
  if (!stats.totalTokens && !stats.lastRequest) {
    badgeEl.classList.add('hidden');
    return;
  }
  badgeEl.classList.remove('hidden');
  const total = stats.totalTokens;
  const displayTok = total >= 1000000 ? `${(total / 1000000).toFixed(1)}M` : total >= 1000 ? `${(total / 1000).toFixed(1)}k` : `${total}`;
  textEl.textContent = `${displayTok} tok`;
  const last = stats.lastRequest;
  const lastInfo = last ? ` (直近: +${last.totalTokens} [${last.model}])` : '';
  badgeEl.title = `累計AIトークン: ${total.toLocaleString()} tokens${lastInfo} / タップで詳細`;
}

function updateAiTokenUsageCardUI() {
  const lastEl = document.getElementById('statTokenLastReq');
  const thinkEl = document.getElementById('statTokenThinking');
  const totalEl = document.getElementById('statTokenTotal');
  const detailEl = document.getElementById('statTokenDetailText');
  if (!lastEl || !thinkEl || !totalEl) return;

  const stats = getAiTokenUsageStats();
  const last = stats.lastRequest;
  lastEl.textContent = last ? `${last.totalTokens.toLocaleString()}` : '0';
  thinkEl.textContent = `${stats.totalThinkingTokens.toLocaleString()}`;
  totalEl.textContent = `${stats.totalTokens.toLocaleString()}`;

  if (detailEl) {
    if (last) {
      detailEl.textContent = `${last.provider.toUpperCase()} (${last.model}): 入力 ${last.promptTokens} + 出力 ${last.candidatesTokens}${last.thinkingTokens ? ` (思考 ${last.thinkingTokens})` : ''}`;
    } else {
      detailEl.textContent = 'まだリクエスト実績がありません';
    }
  }
}

function resetAiTokenUsageStats() {
  try {
    localStorage.removeItem(AI_TOKEN_USAGE_STORAGE_KEY);
  } catch (e) {}
  updatePlayerTokenUsageBadgeUI();
  updateAiTokenUsageCardUI();
  showToast('AIトークン使用量カウントをリセットしました', 'info');
}

function getSettingReasoningEffort(settings = null) {
  const s = settings || getSettingsFromStorage() || {};
  return (s.reasoning_effort || 'off').toLowerCase();
}

function onReasoningEffortChange(val) {
  const badge = document.getElementById('settingReasoningEffortBadge');
  if (badge) {
    const labels = {
      off: 'Off (速度最優先・推奨)',
      low: 'Low (軽快)',
      medium: 'Medium (標準)',
      high: 'High (深層思考)'
    };
    badge.textContent = labels[val] || val;
    badge.className = val === 'off'
      ? 'text-[10px] font-mono font-bold text-emerald-300 bg-emerald-950/60 px-2 py-0.5 rounded border border-emerald-500/30'
      : 'text-[10px] font-mono font-bold text-purple-300 bg-purple-950/60 px-2 py-0.5 rounded border border-purple-500/30';
  }
  if (typeof scheduleImmediateSettingsSave === 'function') {
    scheduleImmediateSettingsSave({ debounceMs: 50 });
  }
}

async function callGeminiDirectly(segments, novelTitle, apiKey, explicitModel = null) {
  const settings = getSettingsFromStorage() || {};
  const model = explicitModel || settings.gemini_model || 'gemini-3.8-flash';
  const effort = getSettingReasoningEffort(settings);

  return analyzeSegmentsWithLlmChunked(segments, novelTitle, async (prompt) => {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
    const generationConfig = { temperature: 0.15, responseMimeType: 'application/json' };
    
    // thinkingConfig サポート (Gemini 2.0 Flash Thinking, 2.5, 3.x Flash/Pro 等)
    const thinkingBudgetMap = { off: 0, low: 1024, medium: 2048, high: 4096 };
    if (effort === 'off') {
      generationConfig.thinkingConfig = { thinkingBudget: 0 };
    } else if (thinkingBudgetMap[effort] !== undefined) {
      generationConfig.thinkingConfig = { thinkingBudget: thinkingBudgetMap[effort] };
    }

    const payload = {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig
    };
    const res = await nativeFetch(url, 'POST', { 'Content-Type': 'application/json' }, JSON.stringify(payload));
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      const err = new Error(`Gemini API Error (${res.status}): ${errText}`);
      if (res.status === 429 || isLlmQuotaError(err)) markCloudCooldownFromError('gemini', err);
      throw err;
    }
    const data = await res.json();
    if (data.usageMetadata) {
      recordAiTokenUsage('gemini', model, data.usageMetadata);
    }
    const rawText = data.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!rawText) throw new Error('Gemini API returned empty candidate text');
    return parseCastAnalysisJson(rawText);
  });
}

async function callOpenAiDirectly(segments, novelTitle, apiKey, explicitModel = null) {
  const settings = getSettingsFromStorage() || {};
  const model = explicitModel || resolveOpenaiModel(settings);
  const effort = getSettingReasoningEffort(settings);

  return analyzeSegmentsWithLlmChunked(segments, novelTitle, async (prompt) => {
    const url = 'https://api.openai.com/v1/chat/completions';
    const payload = {
      model,
      messages: [
        { role: 'system', content: 'You are a novel cast director assistant. Output pure JSON only.' },
        { role: 'user', content: prompt }
      ],
      response_format: { type: 'json_object' }
    };

    // o1, o3, o4, gpt-6-astra 等の高度推論モデルは reasoning_effort をサポート
    const isReasoningModel = /^(o1|o3|o4|gpt-6-astra)/i.test(model);
    if (isReasoningModel) {
      if (['low', 'medium', 'high'].includes(effort)) {
        payload.reasoning_effort = effort;
      }
    } else {
      payload.temperature = 0.15;
    }

    const res = await nativeFetch(
      url,
      'POST',
      { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
      JSON.stringify(payload)
    );
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      const err = new Error(`OpenAI API Error (${res.status}): ${errText}`);
      if (res.status === 429 || isLlmQuotaError(err)) markCloudCooldownFromError('openai', err);
      throw err;
    }
    const data = await res.json();
    if (data.usage) {
      recordAiTokenUsage('openai', model, data.usage);
    }
    const content = data.choices?.[0]?.message?.content;
    if (!content) throw new Error('OpenAI API returned empty content');
    return parseCastAnalysisJson(content);
  });
}

async function callClaudeDirectly(segments, novelTitle, apiKey, explicitModel = null) {
  const settings = getSettingsFromStorage() || {};
  const model = explicitModel || resolveClaudeModel(settings);
  const effort = getSettingReasoningEffort(settings);

  return analyzeSegmentsWithLlmChunked(segments, novelTitle, async (prompt) => {
    const url = 'https://api.anthropic.com/v1/messages';
    const payload = {
      model,
      max_tokens: 8192,
      system: 'You are a novel cast director assistant. Output pure JSON only. No markdown fences.',
      messages: [{ role: 'user', content: prompt }]
    };

    // Claude 3.7+ / 4.x / Fable thinking budget 設定
    const supportsThinking = /claude-3-7|claude-4|claude-fable|fable/i.test(model);
    const thinkingBudgetMap = { low: 1024, medium: 2048, high: 4096 };
    if (supportsThinking && effort !== 'off' && thinkingBudgetMap[effort]) {
      payload.thinking = {
        type: 'enabled',
        budget_tokens: thinkingBudgetMap[effort]
      };
      payload.max_tokens = 8192 + thinkingBudgetMap[effort];
    } else {
      payload.temperature = 0.15;
    }

    const res = await nativeFetch(
      url,
      'POST',
      {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01'
      },
      JSON.stringify(payload)
    );
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      const err = new Error(`Claude API Error (${res.status}): ${errText}`);
      if (res.status === 429 || isLlmQuotaError(err)) markCloudCooldownFromError('claude', err);
      throw err;
    }
    const data = await res.json();
    if (data.usage) {
      recordAiTokenUsage('claude', model, data.usage);
    }
    const rawText = (data.content || []).filter((p) => p?.type === 'text').map((p) => p.text).join('\n');
    if (!rawText) throw new Error('Claude API returned empty content');
    return parseCastAnalysisJson(rawText);
  });
}

async function callLocalLlmDirectly(segments, novelTitle, endpointUrl, modelName) {
  return analyzeSegmentsWithLlmChunked(segments, novelTitle, async (prompt) => {
    const url = `${endpointUrl.replace(/\/+$/, '')}/chat/completions`;
    const payload = {
      model: modelName,
      messages: [
        { role: 'system', content: 'You are a novel cast director assistant. Output pure JSON only.' },
        { role: 'user', content: prompt }
      ],
      temperature: 0.15,
      response_format: { type: 'json_object' }
    };
    const res = await nativeFetch(url, 'POST', { 'Content-Type': 'application/json' }, JSON.stringify(payload));
    if (!res.ok) {
      if (res.status === 0) markLocalLlmCooldown();
      throw new Error(`Local LLM Error (${res.status})`);
    }
    const data = await res.json();
    if (data.usage) {
      recordAiTokenUsage('local_llm', modelName, data.usage);
    }
    const content = data.choices?.[0]?.message?.content;
    if (!content) throw new Error('Local LLM empty response');
    return parseCastAnalysisJson(content);
  });
}

function notifyCastLlmFallback(reason) {
  const now = Date.now();
  if (now - _lastCastFallbackToastAt < 45_000) return;
  _lastCastFallbackToastAt = now;
  if (typeof showToast === 'function') {
    showToast(`クラウドLLM不可のためロジック解析に切替（${reason}）`, 'warning');
  }
}

/**
 * 解析順: 選択クラウド → 他キー済みクラウド → Local LLM。
 * AI不使用(embedded/rules)はクラウドを飛ばす。最終失敗時はロジック判定。
 */
function pickCastLlmProviderOrder(preferred, settings = {}) {
  const p = normalizeCastLlmProvider(preferred);
  if (p === 'embedded_llm' || p === 'rules') return [];

  const clouds = ['gemini', 'openai', 'claude'];
  const order = [];

  if (p === 'local_llm') {
    order.push('local_llm');
    clouds.forEach((c) => { if (hasCloudApiKey(c, settings)) order.push(c); });
    return order;
  }

  if (clouds.includes(p)) order.push(p);
  clouds.forEach((c) => {
    if (c !== p && hasCloudApiKey(c, settings)) order.push(c);
  });
  order.push('local_llm');
  return order;
}

// ユーザー選択プロバイダーに基づくエピソードAI解析エンジンディスパッチャー
async function performAiAnalysisForEpisode(segments, novelTitle, episodeNum = 1) {
  if (typeof normalizeAndMergeBrokenSegments === 'function' && Array.isArray(segments) && segments.length > 1) {
    segments = normalizeAndMergeBrokenSegments(segments);
  }
  const settings = getSettingsFromStorage() || {};
  const preferred = getActiveCastLlmProvider(settings);
  const order = pickCastLlmProviderOrder(preferred, settings);
  const errors = [];

  for (const provider of order) {
    if (provider === 'gemini') {
      const apiKey = (settings.gemini_api_key || '').trim();
      const model = settings.gemini_model || 'gemini-3.8-flash';
      if (!apiKey) { errors.push('Geminiキー未設定'); continue; }
      if (isCloudInCooldown('gemini')) { errors.push('Geminiクォータ超過'); continue; }
      try {
        const geminiRes = await callGeminiDirectly(segments, novelTitle, apiKey, model);
        if (geminiRes?.segments?.length) {
          return { ...geminiRes, _engine: `Gemini (${model}) 全文チャンク`, _provider: 'gemini', _status: 'success' };
        }
        errors.push('Gemini空応答');
      } catch (e) {
        console.warn('Gemini analysis failed:', e);
        if (isLlmQuotaError(e)) markCloudCooldownFromError('gemini', e);
        errors.push(isLlmQuotaError(e) ? 'Geminiクォータ超過' : (e.message || 'Geminiエラー'));
      }
      continue;
    }

    if (provider === 'openai') {
      const apiKey = (settings.openai_api_key || '').trim();
      const model = resolveOpenaiModel(settings);
      if (!apiKey) { errors.push('OpenAIキー未設定'); continue; }
      if (isCloudInCooldown('openai')) { errors.push('OpenAIクォータ超過'); continue; }
      try {
        const openaiRes = await callOpenAiDirectly(segments, novelTitle, apiKey, model);
        if (openaiRes?.segments?.length) {
          return { ...openaiRes, _engine: `OpenAI (${model}) 全文チャンク`, _provider: 'openai', _status: 'success' };
        }
        errors.push('OpenAI空応答');
      } catch (e) {
        console.warn('OpenAI analysis failed:', e);
        if (isLlmQuotaError(e)) markCloudCooldownFromError('openai', e);
        errors.push(isLlmQuotaError(e) ? 'OpenAIクォータ超過' : (e.message || 'OpenAIエラー'));
      }
      continue;
    }

    if (provider === 'claude') {
      const apiKey = (settings.claude_api_key || '').trim();
      const model = resolveClaudeModel(settings);
      if (!apiKey) { errors.push('Claudeキー未設定'); continue; }
      if (isCloudInCooldown('claude')) { errors.push('Claudeクォータ超過'); continue; }
      try {
        const claudeRes = await callClaudeDirectly(segments, novelTitle, apiKey, model);
        if (claudeRes?.segments?.length) {
          return { ...claudeRes, _engine: `Claude (${model}) 全文チャンク`, _provider: 'claude', _status: 'success' };
        }
        errors.push('Claude空応答');
      } catch (e) {
        console.warn('Claude analysis failed:', e);
        if (isLlmQuotaError(e)) markCloudCooldownFromError('claude', e);
        errors.push(isLlmQuotaError(e) ? 'Claudeクォータ超過' : (e.message || 'Claudeエラー'));
      }
      continue;
    }

    if (provider === 'local_llm') {
      if (isLocalLlmInCooldown()) { errors.push('Local LLM接続不可'); continue; }
      if (!isLocalLlmLikelyReachable({ ...settings, llm_provider: preferred, llm_provider_manually_set: settings.llm_provider_manually_set || preferred === 'local_llm' })) {
        errors.push('Local LLM未設定');
        continue;
      }
      const localUrl = settings.local_llm_url || 'http://127.0.0.1:11434/v1';
      const localModel = typeof sanitizeCommercialLocalLlmModel === 'function'
        ? sanitizeCommercialLocalLlmModel(settings.local_llm_model)
        : (settings.local_llm_model || 'phi4-mini');
      try {
        const localRes = await callLocalLlmDirectly(segments, novelTitle, localUrl, localModel);
        if (localRes?.segments?.length) {
          return { ...localRes, _engine: `Local LLM (${localModel}) 全文チャンク`, _provider: 'local_llm', _status: 'success' };
        }
        errors.push('Local LLM空応答');
      } catch (e) {
        console.warn('Local LLM analysis failed:', e);
        const msg = e.message || 'Local LLMエラー';
        if (/Error \(0\)/.test(msg)) markLocalLlmCooldown();
        errors.push(msg);
      }
    }
  }

  const reason = errors.find((e) => /キー未設定|クォータ|空応答|エラー|接続/.test(e)) || errors[0] || 'AI不使用';
  const isCloudPreferred = ['gemini', 'openai', 'claude'].includes(preferred);
  if (isCloudPreferred && (errors.some((e) => /キー未設定|クォータ/.test(e)) || errors.length)) {
    notifyCastLlmFallback(reason);
  } else if (preferred === 'local_llm' && settings.llm_provider_manually_set) {
    notifyCastLlmFallback(reason);
  }

  const localRes = analyzeSegmentsLocally(segments, novelTitle);
  const engineName = preferred === 'rules'
    ? 'ルールベース解析エンジン'
    : 'アプリ内包 ロジック解析';
  return {
    ...localRes,
    _engine: `${engineName}${errors.length ? ' (クラウド/Local代替)' : ''}`,
    _provider: preferred === 'rules' ? 'rules' : 'embedded_llm',
    _status: errors.length ? 'fallback' : 'success',
    _fallback_error: errors.length ? reason : undefined
  };
}

// ==============================================
// 4. Pixel端末検出（Pixel AI / Prompt API は廃止）
// ==============================================
async function detectPixelAndBuiltInAI() {
  const ua = navigator.userAgent;
  let isPixel = false;

  if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.getPlatformInfo === 'function') {
    try {
      const pInfo = JSON.parse(window.AndroidBridge.getPlatformInfo());
      if (pInfo.isPixel) isPixel = true;
    } catch (e) {
      console.warn('Failed to parse getPlatformInfo:', e);
    }
  }
  if (!isPixel && /Pixel/i.test(ua)) isPixel = true;

  state.isPixelDevice = isPixel;
  state.hasBuiltInAI = false;

  const storageSettings = getSettingsFromStorage() || {};
  let changed = false;

  // 旧 pixel_ai 設定を Gemini へ移行
  if (storageSettings.llm_provider === 'pixel_ai') {
    storageSettings.llm_provider = 'gemini';
    changed = true;
  }
  if (!storageSettings.llm_provider_manually_set && storageSettings.llm_provider !== 'gemini') {
    storageSettings.llm_provider = 'gemini';
    changed = true;
  }
  if (changed) {
    try {
      localStorage.setItem('narou_reader_settings', JSON.stringify(storageSettings));
    } catch (e) {}
  }

  const activeProvider = getActiveCastLlmProvider(storageSettings);
  updateLlmBadge(activeProvider);

  const providerEl = document.getElementById('settingLlmProvider');
  if (providerEl) {
    // 残存 option があれば除去
    providerEl.querySelectorAll('option[value="pixel_ai"]').forEach((opt) => opt.remove());
    if (!storageSettings.llm_provider_manually_set) {
      providerEl.value = activeProvider;
      if (typeof toggleLlmFields === 'function') toggleLlmFields();
    } else if (providerEl.value === 'pixel_ai') {
      providerEl.value = 'gemini';
    }
  }
  console.log(`[NarouAIReader] Cast LLM default=gemini (Pixel=${isPixel}, PixelAI=removed)`);
}

// ==============================================
// 5. DOM 要素キャッシュ & Audio リスナー
// ==============================================
let audio = null;
let playPauseBtn = null;
let playPauseIcon = null;
let currentSegIndexEl = null;
let currentPlayingSpeakerEl = null;
let segmentsContainer = null;
let isPlayerSeeking = false;
let isCarModeSeeking = false;

function initDomRefs() {
  audio = document.getElementById('audioPlayer');
  playPauseBtn = document.getElementById('playPauseBtn');
  playPauseIcon = document.getElementById('playPauseIcon');
  currentSegIndexEl = document.getElementById('currentSegIndex');
  currentPlayingSpeakerEl = document.getElementById('currentPlayingSpeaker');
  segmentsContainer = document.getElementById('segmentsContainer');
}

function setupAudioListeners() {
  if (!audio) return;

  // 1節の朗読完了時に自動的に次の節へ進行
  audio.addEventListener('ended', () => {
    if (!state.isPlaying) return;
    playNextSegment();
  });

  // 音声再生エラー時の自動スキップ＆継続
  audio.addEventListener('error', (e) => {
    console.warn('Audio element error during playback:', e);
    if (!state.isPlaying) return;
    setTimeout(() => {
      if (state.isPlaying) playNextSegment();
    }, 400);
  });

  // カラオケバー＆シークバーの滑らかな追従
  audio.addEventListener('timeupdate', () => {
    if (audio.duration && state.currentSegments.length > 0) {
      const segPercent = (state.currentSegmentIndex / state.currentSegments.length) * 100;
      const innerPercent = (audio.currentTime / audio.duration) * (100 / state.currentSegments.length);
      const totalPercent = Math.min(100, segPercent + innerPercent);

      // インタラクティブ・シークスライドバーの同期
      if (!isPlayerSeeking) {
        const seekSlider = document.getElementById('playerSeekSlider');
        const percentEl = document.getElementById('playerSeekPercentText');
        if (seekSlider) seekSlider.value = Math.round(totalPercent);
        if (percentEl) percentEl.textContent = `${Math.round(totalPercent)}%`;
      }

      // 現在のカード内カラオケバーの更新
      const currentCard = document.getElementById(`seg-${state.currentSegmentIndex}`);
      if (currentCard) {
        const kBar = currentCard.querySelector('.karaoke-progress-bar');
        if (kBar) {
          const kPercent = Math.min(100, (audio.currentTime / audio.duration) * 100);
          kBar.style.width = `${kPercent}%`;
        }
      }
    }
  });

  // 再生/一時停止イベントとの同期
  audio.addEventListener('play', () => {
    state.isPlaying = true;
    updatePlayButtonUI(true);
    if (typeof BackgroundAudioCacheOrchestrator !== 'undefined') {
      BackgroundAudioCacheOrchestrator.onPlaybackStateChanged();
    }
  });

  audio.addEventListener('pause', () => {
    if (!state.isAndroidNative && state.isPlaying) {
      state.isPlaying = false;
      updatePlayButtonUI(false);
      if (typeof BackgroundAudioCacheOrchestrator !== 'undefined') {
        BackgroundAudioCacheOrchestrator.onPlaybackStateChanged();
      }
    }
  });
}

// ==============================================
// 6. UI ハイライト & プレイヤー状態更新関数
// ==============================================
let _lastHighlightedIndex = -1;

function highlightCurrentSegment(index) {
  if (index < 0 || index >= state.currentSegments.length) return;

  const currentEl = document.getElementById(`seg-${index}`);
  if (_lastHighlightedIndex >= 0 && _lastHighlightedIndex < state.currentSegments.length) {
    const startIdx = Math.min(_lastHighlightedIndex, index);
    const endIdx = Math.max(_lastHighlightedIndex, index);
    for (let i = startIdx; i <= endIdx; i++) {
      const card = i === index ? currentEl : document.getElementById(`seg-${i}`);
      if (!card) continue;
      if (i === index) {
        card.classList.add('active');
      } else {
        card.classList.remove('active');
        const bar = card.querySelector('.karaoke-progress-bar');
        if (bar) bar.style.width = i < index ? '100%' : '0%';
      }
    }
  } else {
    for (let i = 0; i <= index; i++) {
      const card = i === index ? currentEl : document.getElementById(`seg-${i}`);
      if (!card) continue;
      if (i === index) {
        card.classList.add('active');
      } else {
        card.classList.remove('active');
        const bar = card.querySelector('.karaoke-progress-bar');
        if (bar) bar.style.width = '100%';
      }
    }
  }
  _lastHighlightedIndex = index;

  const middlePane = document.getElementById('playerMiddlePane');
  const resumeFab = document.getElementById('resumeAutoScrollBtn');

  if (currentEl && middlePane && state.autoScroll && !isUserScrolling && !_isUserTouchingReader) {
    const isVertical = document.getElementById('segmentsContainer')?.classList.contains('vertical-reader');
    if (isVertical) {
      const paneWidth = middlePane.clientWidth;
      const cardLeft = currentEl.offsetLeft;
      const cardWidth = currentEl.clientWidth;
      const targetLeft = cardLeft - (paneWidth / 2) + (cardWidth / 2);
      middlePane.scrollTo({
        left: targetLeft,
        behavior: 'smooth'
      });
    } else {
      const paneHeight = middlePane.clientHeight;
      const cardTop = currentEl.offsetTop;
      const cardHeight = currentEl.clientHeight;
      const targetScroll = cardTop - (paneHeight / 2) + (cardHeight / 2);
      middlePane.scrollTo({
        top: Math.max(0, targetScroll),
        behavior: 'smooth'
      });
    }
    if (resumeFab) {
      resumeFab.classList.add('hidden');
      resumeFab.classList.remove('flex');
    }
  } else if (isUserScrolling && resumeFab) {
    resumeFab.classList.remove('hidden');
    resumeFab.classList.add('flex');
  }

  // 進捗状況をローカルストレージ・Heroカードへ自動保存
  if (state.currentNovel && typeof saveReadingProgress === 'function') {
    const epTitle = state.currentNovel.episodes?.find(e => e.number === state.currentEpisodeNum)?.title || '';
    saveReadingProgress(
      state.currentNovel.ncode,
      state.currentNovel.title,
      state.currentEpisodeNum,
      epTitle,
      index,
      state.currentSegments.length
    );
  }
}

function updatePlayerStatusUI() {
  const playable = canPlayAudio();
  const total = state.currentSegments ? state.currentSegments.length : 0;
  const current = (playable && total > 0) ? (state.currentSegmentIndex + 1) : 0;
  const seg = (playable && total > 0) ? state.currentSegments[state.currentSegmentIndex] : null;
  const totalPercent = (playable && total > 1) ? Math.round((state.currentSegmentIndex / (total - 1)) * 100) : (total === 1 ? 100 : 0);
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = uiLang === 'ja';

  if (currentSegIndexEl) {
    const unit = isJa ? ' 文' : ({ zh: ' 句', ko: ' 문장', en: '', es: '', fr: '', pt: '' }[uiLang] ?? '');
    currentSegIndexEl.textContent = (playable && total > 0) ? `${current} / ${total}${unit}` : `0 / 0${unit}`;
  }

  // 想定読了時間プログレス表示 (再生速度・文間ポーズ連動 + 残り時間表示)
  const timeProgressEl = document.getElementById('playerTimeProgressText');
  if (timeProgressEl) {
    if (playable && total > 0) {
      const speed = Math.max(0.4, Number(state.playbackSpeed) || 0.8);
      const pauseSec = (typeof getSentencePauseMs === 'function' ? getSentencePauseMs() : 0) / 1000;
      const avgSecPerSeg = (4.0 / speed) + pauseSec;
      const curSec = Math.round(state.currentSegmentIndex * avgSecPerSeg);
      const totalSec = Math.round(total * avgSecPerSeg);
      const remainSec = Math.max(0, totalSec - curSec);
      const fmt = s => `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
      const remainMin = Math.ceil(remainSec / 60);
      const remLabel = isJa
        ? `(残約${remainMin}分)`
        : ({ zh: `(剩余约${remainMin}分)`, ko: `(약 ${remainMin}분 남음)`, es: `(~${remainMin}m rest.)`, fr: `(~${remainMin}m rest.)`, pt: `(~${remainMin}m rest.)` }[uiLang] || `(~${remainMin}m left)`);
      timeProgressEl.textContent = remainSec > 0 ? `${fmt(curSec)} / ${fmt(totalSec)} ${remLabel}` : `${fmt(curSec)} / ${fmt(totalSec)}`;
    } else {
      timeProgressEl.textContent = '00:00 / 00:00';
    }
  }

  if (!isPlayerSeeking) {
    const seekSlider = document.getElementById('playerSeekSlider');
    const percentEl = document.getElementById('playerSeekPercentText');
    if (seekSlider) seekSlider.value = totalPercent;
    if (percentEl) percentEl.textContent = `${totalPercent}%`;
  }

  if (currentPlayingSpeakerEl) {
    if (!playable) {
      currentPlayingSpeakerEl.textContent = isJa ? '未選択' : ({ en: 'None', zh: '未选择', ko: '미선택', es: 'Ninguno', fr: 'Aucun', pt: 'Nenhum' }[uiLang] || 'None');
    } else {
      const rawSp = seg?.speaker || 'ナレーション';
      const hasTrans = state.currentTranslatedLang && seg?.translated_speaker && (!seg.translated_lang || seg.translated_lang === state.currentTranslatedLang);
      if (hasTrans) {
        currentPlayingSpeakerEl.textContent = seg.translated_speaker;
      } else if (!isJa && typeof translateSpeakerOnDevice === 'function') {
        currentPlayingSpeakerEl.textContent = translateSpeakerOnDevice(rawSp, uiLang);
      } else if (rawSp === '地の文' || rawSp === 'ナレーション') {
        currentPlayingSpeakerEl.textContent = typeof tUi === 'function' ? tUi('cast_narration_label') : 'ナレーション';
      } else {
        currentPlayingSpeakerEl.textContent = rawSp;
      }
    }
  }

  // VOICEVOX / TTS クレジット＆動作エンジン表示の動的同期
  const creditBadge = document.getElementById('voicevoxCreditBadge');
  const creditEl = document.getElementById('voicevoxCreditText');
  const currentEngine = getPreferredTtsEngine();

  if (creditBadge) {
    if (!playable) {
      creditBadge.classList.add('hidden');
    } else {
      creditBadge.classList.remove('hidden');
      const speaker = seg?.speaker || 'ナレーション';
      const profile = getCharacterVoiceProfile(speaker);

      if (currentEngine === 'android_native' || profile.isNativeTts || !isJa) {
        const ttsBadgeLabel = isJa ? '標準TTS' : ({ en: 'Native TTS', zh: '系统TTS', ko: '기본 TTS', es: 'TTS Nativo', fr: 'TTS Natif', pt: 'TTS Nativo' }[uiLang] || 'Native TTS');
        creditBadge.className = 'inline-flex items-center space-x-1 font-mono text-[9px] text-blue-300 bg-blue-950/80 px-2 py-0.5 rounded border border-blue-600/50 truncate max-w-[140px] shadow-sm cursor-pointer';
        creditBadge.onclick = () => openVoicevoxCreditModal();
        creditBadge.innerHTML = `<i class="ph-bold ph-device-mobile text-blue-400"></i><span>${escapeHtml(ttsBadgeLabel)}</span>`;
      } else {
        const creditInfo = getOfficialVoicevoxCreditInfo(profile);
        creditBadge.className = 'inline-flex items-center space-x-1 font-mono text-[9px] text-emerald-300 bg-emerald-950/80 px-2 py-0.5 rounded border border-emerald-600/50 truncate max-w-[205px] shadow-sm cursor-pointer';
        creditBadge.onclick = () => openVoicevoxCreditModal();
        creditBadge.title = isJa ? `${creditInfo.credit} (タップで規約・クレジット詳細)` : `${creditInfo.credit}`;
        creditBadge.innerHTML = `<i class="ph-bold ph-seal-check text-emerald-400"></i><span>${escapeHtml(creditInfo.credit)}</span>`;
      }
    }
  }

  // ミニプレイヤーをリアルタイム同期
  updateMiniPlayer();
  updateCarModeUI();

  const locWork = (state.currentNovel && typeof getLocalizedAozoraWork === 'function')
    ? getLocalizedAozoraWork(state.currentNovel, uiLang)
    : null;
  const dispNovelTitle = locWork?.displayTitle || state.currentNovel?.title || (isJa ? '作品名' : 'Title');
  const epSuffix = isJa ? `第${state.currentEpisodeNum}話` : `Ep. ${state.currentEpisodeNum}`;

  // ヘッダーの現在の作品名表示
  const headerNovelEl = document.getElementById('headerCurrentNovelTitle');
  if (headerNovelEl && state.currentNovel) {
    headerNovelEl.textContent = `${dispNovelTitle} (${epSuffix})`;
    headerNovelEl.classList.remove('hidden');
  }

  // プレイヤーペインの作品名・エピソード名・話数バッジの動的同期
  const playerNovelTitleEl = document.getElementById('playerNovelTitle');
  const playerSubtitleEl = document.getElementById('playerSubtitle');
  const playerEpisodeBadgeEl = document.getElementById('playerEpisodeBadge');
  if (playerNovelTitleEl && state.currentNovel) {
    playerNovelTitleEl.textContent = dispNovelTitle;
    if (!isJa && (!locWork || !locWork.isTranslatedPreset) && /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF]/.test(dispNovelTitle) && typeof translatePreviewTextAsync === 'function') {
      const targetNcode = state.currentNovel.ncode;
      translatePreviewTextAsync(dispNovelTitle, uiLang).then(tr => {
        if (tr && state.currentNovel?.ncode === targetNcode && playerNovelTitleEl) {
          playerNovelTitleEl.textContent = tr;
        }
      }).catch(() => {});
    }
  }
  if (playerSubtitleEl && state.currentNovel) {
    const curEp = state.currentNovel.episodes?.find(e => (e.number === state.currentEpisodeNum || e.episode_number === state.currentEpisodeNum));
    let rawSub = curEp?.title || (state.currentNovel.total_episodes === 1 ? '全文朗読' : `第${state.currentEpisodeNum}話`);
    if (!isJa) {
      const fullReadMap = { en: 'Full Text Reading', zh: '全文朗读', ko: '전문 낭독', es: 'Lectura completa', fr: 'Lecture intégrale', pt: 'Leitura completa' };
      if (rawSub === '全文朗読' || rawSub === '本文' || rawSub === '全文' || rawSub === '本文 (短編)' || state.currentNovel.total_episodes === 1) {
        rawSub = fullReadMap[uiLang] || 'Full Text Reading';
      } else {
        const mPart = rawSub.match(/^(.*)\s*\((\d+)\)$/);
        if (mPart && (mPart[1] === '全文朗読' || mPart[1] === state.currentNovel.title)) {
          rawSub = `${dispNovelTitle} (${mPart[2]})`;
        } else if (/^第\s*\d+\s*[話章節編]$/.test(rawSub)) {
          rawSub = `Ep. ${state.currentEpisodeNum}`;
        }
      }
    }
    playerSubtitleEl.textContent = rawSub;
  }
  if (playerEpisodeBadgeEl && state.currentNovel) {
    if (isJa) {
      playerEpisodeBadgeEl.textContent = state.currentNovel.site === 'aozora' ? '名作' : `第${state.currentEpisodeNum}話`;
    } else {
      const classicMap = { en: 'Classic', zh: '名作', ko: '명작', es: 'Clásico', fr: 'Classique', pt: 'Clássico' };
      playerEpisodeBadgeEl.textContent = state.currentNovel.site === 'aozora' ? (classicMap[uiLang] || 'Classic') : `Ep. ${state.currentEpisodeNum}`;
    }
  }

  updatePlayButtonUI(state.isPlaying);
  updateMediaSessionMetadata();
  updateReadingModeUI();
}

/**
 * 朗読モード（原文モード vs 現代語超訳 vs 多言語翻訳）の視覚的UI・背景色・バッジを同期する
 */
function updateReadingModeUI() {
  const middlePane = document.getElementById('playerMiddlePane');
  const banner = document.getElementById('playerReadingModeBanner');
  const quickBtn = document.getElementById('aiTranslateQuickBtn');
  const quickBadge = document.getElementById('aiTranslateQuickBadge');

  const isOriginal = !state.currentTranslatedLang;
  const isModernJa = state.currentTranslatedLang === 'ja';
  const isMultilingual = !isOriginal && !isModernJa;
  const transLang = state.currentTranslatedLang || '';

  // 1. 本文スクロールペインの背景色・枠線クラスの切り替え
  if (middlePane) {
    middlePane.classList.remove('reading-mode-original', 'reading-mode-modern-ja', 'reading-mode-multilingual');
    if (isModernJa) {
      middlePane.classList.add('reading-mode-modern-ja');
    } else if (isMultilingual) {
      middlePane.classList.add('reading-mode-multilingual');
    } else {
      middlePane.classList.add('reading-mode-original');
    }
  }

  // 2. クイックツールバーの「翻訳・超訳」ボタンのハイライト連動
  if (quickBtn && quickBadge) {
    quickBtn.classList.remove(
      'bg-amber-500/25', 'border-amber-500/60', 'text-amber-200',
      'from-indigo-900/80', 'to-purple-900/80', 'border-indigo-500/40', 'text-indigo-100',
      'bg-sky-500/25', 'border-sky-500/60', 'text-sky-200'
    );
    if (isModernJa) {
      quickBtn.classList.add('bg-amber-500/25', 'border-amber-500/60', 'text-amber-200');
      quickBadge.textContent = '✨ 超訳';
    } else if (isMultilingual) {
      quickBtn.classList.add('bg-sky-500/25', 'border-sky-500/60', 'text-sky-200');
      const langUpper = transLang.toUpperCase();
      quickBadge.textContent = `🌐 ${langUpper}`;
    } else {
      quickBtn.classList.add('from-indigo-900/80', 'to-purple-900/80', 'border-indigo-500/40', 'text-indigo-100');
      quickBadge.textContent = '超訳';
    }
  }

  // 3. モードステータスバー (playerReadingModeBanner) の表示更新
  if (banner) {
    const iconBadge = document.getElementById('readingModeIconBadge');
    const titleEl = document.getElementById('readingModeTitle');
    const subBadge = document.getElementById('readingModeSubBadge');
    const descEl = document.getElementById('readingModeDesc');
    const switchBtn = document.getElementById('readingModeSwitchQuickBtn');

    if (isModernJa) {
      banner.className = 'reading-mode-banner mode-banner-modern-ja px-2.5 py-1 rounded-xl flex items-center justify-between gap-1.5 shadow-sm transition-all duration-300';
      if (iconBadge) {
        iconBadge.className = 'w-5 h-5 rounded-lg flex items-center justify-center text-xs shrink-0 font-bold bg-amber-500/25 text-amber-300 border border-amber-500/50';
        iconBadge.textContent = '✨';
      }
      if (titleEl) {
        titleEl.className = 'text-[11px] font-bold text-amber-300 truncate';
        titleEl.textContent = '✨ 現代語超訳';
      }
      if (subBadge) {
        subBadge.className = 'hidden sm:inline-block text-[9px] px-1.5 py-0.5 rounded font-bold bg-amber-500/25 text-amber-300 border border-amber-500/40';
        subBadge.textContent = '超訳朗読中';
      }
      if (descEl) descEl.textContent = '難しい文語や旧仮名遣いを耳馴染みのよい現代語に変換中';
      if (switchBtn) {
        switchBtn.className = 'px-2 py-0.5 rounded-lg text-[10px] font-bold bg-slate-800/90 hover:bg-slate-700 text-slate-200 border border-slate-600 transition active:scale-95 shadow-sm flex items-center space-x-1 shrink-0';
        switchBtn.innerHTML = '<i class="ph-bold ph-arrow-u-up-left text-xs"></i><span>原文へ</span>';
      }
    } else if (isMultilingual) {
      banner.className = 'reading-mode-banner mode-banner-multilingual px-2.5 py-1 rounded-xl flex items-center justify-between gap-1.5 shadow-sm transition-all duration-300';
      const m = (typeof SUPPORTED_MAJOR_LANGUAGES !== 'undefined' && SUPPORTED_MAJOR_LANGUAGES[transLang]) || { flag: '🌐', name: transLang };
      if (iconBadge) {
        iconBadge.className = 'w-5 h-5 rounded-lg flex items-center justify-center text-xs shrink-0 font-bold bg-sky-500/25 text-sky-300 border border-sky-500/50';
        iconBadge.textContent = m.flag || '🌐';
      }
      if (titleEl) {
        titleEl.className = 'text-[11px] font-bold text-sky-300 truncate';
        titleEl.textContent = `${m.flag || ''} ${m.uiName || m.nativeName || transLang.toUpperCase()} 翻訳`;
      }
      if (subBadge) {
        subBadge.className = 'hidden sm:inline-block text-[9px] px-1.5 py-0.5 rounded font-bold bg-sky-500/25 text-sky-300 border border-sky-500/40';
        subBadge.textContent = 'AI翻訳中';
      }
      if (descEl) descEl.textContent = `${m.nativeName || m.uiName}音声で多言語AI朗読中`;
      if (switchBtn) {
        switchBtn.className = 'px-2 py-0.5 rounded-lg text-[10px] font-bold bg-slate-800/90 hover:bg-slate-700 text-slate-200 border border-slate-600 transition active:scale-95 shadow-sm flex items-center space-x-1 shrink-0';
        switchBtn.innerHTML = '<i class="ph-bold ph-arrow-u-up-left text-xs"></i><span>原文へ</span>';
      }
    } else {
      // 原文モード
      banner.className = 'reading-mode-banner mode-banner-original px-2.5 py-1 rounded-xl flex items-center justify-between gap-1.5 shadow-sm transition-all duration-300';
      if (iconBadge) {
        iconBadge.className = 'w-5 h-5 rounded-lg flex items-center justify-center text-xs shrink-0 font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40';
        iconBadge.textContent = '📖';
      }
      if (titleEl) {
        titleEl.className = 'text-[11px] font-bold text-emerald-300 truncate';
        titleEl.textContent = '📖 原文モード';
      }
      if (subBadge) {
        subBadge.className = 'hidden sm:inline-block text-[9px] px-1.5 py-0.5 rounded font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40';
        subBadge.textContent = '原文';
      }
      if (descEl) descEl.textContent = '執筆当時の原文（旧仮名・ルビ）のまま朗読中';
      if (switchBtn) {
        switchBtn.className = 'px-2 py-0.5 rounded-lg text-[10px] font-bold bg-amber-500/20 hover:bg-amber-500/30 text-amber-300 border border-amber-500/40 transition active:scale-95 shadow-sm flex items-center space-x-1 shrink-0';
        switchBtn.innerHTML = '<i class="ph-bold ph-sparkle text-xs"></i><span>超訳にする</span>';
      }
    }
  }
}

/**
 * 朗読モードのクイック切替ハンドラ (原文 <-> 現代語超訳)
 */
async function handleReadingModeQuickSwitch() {
  if (state.currentTranslatedLang) {
    // 現代語超訳または多言語翻訳中 -> 原文に戻す
    restoreOriginalEpisodeLanguage();
  } else {
    // 原文モード -> 現代語超訳をワンタップで実行
    if (!state.currentSegments || state.currentSegments.length === 0) {
      if (typeof showToast === 'function') {
        showToast(typeof tUi === 'function' ? tUi('toast_open_episode_first') : '作品を開いてください', 'warning');
      }
      return;
    }
    _selectedTargetTranslationLang = 'ja';
    if (typeof executeAiEpisodeTranslation === 'function') {
      await executeAiEpisodeTranslation({ isAuto: false });
    }
  }
}

function canPlayAudio() {
  return !!(state.currentNovel && state.currentSegments && state.currentSegments.length > 0);
}

function updatePlayButtonUI(isPlaying) {
  const playable = canPlayAudio();
  const total = state.currentSegments ? state.currentSegments.length : 0;
  const totalEps = state.currentNovel?.total_episodes || state.currentNovel?.episode_count || state.currentNovel?.episodes?.length || 1;

  if (playPauseBtn) {
    if (!playable) {
      playPauseBtn.disabled = true;
      playPauseBtn.classList.add('btn-playback-disabled');
      playPauseBtn.classList.remove('playing-aura');
    } else {
      playPauseBtn.disabled = false;
      playPauseBtn.classList.remove('btn-playback-disabled');
      playPauseBtn.classList.toggle('playing-aura', Boolean(isPlaying));
    }
  }

  if (playPauseIcon) {
    if (isPlaying && playable) {
      playPauseIcon.className = 'ph-fill ph-pause text-2xl';
    } else {
      playPauseIcon.className = 'ph-fill ph-play text-2xl ml-0.5';
    }
  }

  const seekSlider = document.getElementById('playerSeekSlider');
  if (seekSlider) {
    seekSlider.disabled = !playable;
    if (!playable) {
      seekSlider.classList.add('opacity-40', 'cursor-not-allowed');
    } else {
      seekSlider.classList.remove('opacity-40', 'cursor-not-allowed');
    }
  }

  // 前の文 / 次の文 端点制御（端点での半透明 & 無効化）
  const btnPrevSeg = document.getElementById('btnPrevSegment');
  const btnNextSeg = document.getElementById('btnNextSegment');
  if (btnPrevSeg) {
    const isFirstSeg = !playable || state.currentSegmentIndex <= 0;
    btnPrevSeg.disabled = isFirstSeg;
    btnPrevSeg.classList.toggle('btn-playback-disabled', isFirstSeg);
  }
  if (btnNextSeg) {
    const isLastSeg = !playable || state.currentSegmentIndex >= total - 1;
    btnNextSeg.disabled = isLastSeg;
    btnNextSeg.classList.toggle('btn-playback-disabled', isLastSeg);
  }

  // 前の話 / 次の話 端点制御（第1話 / 最終話での半透明 & 無効化）
  const btnPrevEp = document.getElementById('btnPrevEpisode');
  const btnNextEp = document.getElementById('btnNextEpisode');
  if (btnPrevEp) {
    const isFirstEp = !playable || state.currentEpisodeNum <= 1;
    btnPrevEp.disabled = isFirstEp;
    btnPrevEp.classList.toggle('btn-playback-disabled', isFirstEp);
  }
  if (btnNextEp) {
    const isLastEp = !playable || state.currentEpisodeNum >= totalEps;
    btnNextEp.disabled = isLastEp;
    btnNextEp.classList.toggle('btn-playback-disabled', isLastEp);
  }

  // ミニプレイヤーボタン同期
  const miniPlayBtn = document.getElementById('miniPlayPauseBtn');
  const miniPlayIcon = document.getElementById('miniPlayPauseIcon');
  if (miniPlayBtn) {
    miniPlayBtn.disabled = !playable;
    if (!playable) miniPlayBtn.classList.add('opacity-40', 'pointer-events-none');
    else miniPlayBtn.classList.remove('opacity-40', 'pointer-events-none');
  }
  if (miniPlayIcon) {
    miniPlayIcon.className = (isPlaying && playable) ? 'ph-fill ph-pause text-lg ml-0.5' : 'ph-fill ph-play text-lg ml-0.5';
  }

  const carPlayBtn = document.getElementById('carModePlayBtn');
  if (carPlayBtn) {
    carPlayBtn.disabled = !playable;
    if (!playable) carPlayBtn.classList.add('opacity-40', 'pointer-events-none');
    else carPlayBtn.classList.remove('opacity-40', 'pointer-events-none');
  }

  const dot = document.getElementById('playerTabDot');
  if (dot) {
    if (isPlaying && playable) {
      dot.classList.remove('hidden');
    } else {
      dot.classList.add('hidden');
    }
  }

  // カーモードUI同期
  updateCarModeUI();
}

// ==============================================
// 7. Android Native Bridge コールバック (堅牢版)
// ==============================================
let androidTtsRetryCount = 0;
const MAX_ANDROID_TTS_RETRIES = 2;

window.onAndroidTtsStart = function(segmentId) {
  if (!state.isPlaying) return;
  androidTtsRetryCount = 0;
  const idx = state.currentSegments.findIndex(s => String(s.id) === String(segmentId));
  if (idx !== -1) {
    state.currentSegmentIndex = idx;
    highlightCurrentSegment(idx);
    updatePlayerStatusUI();
  }
  if (typeof BackgroundAudioCacheOrchestrator !== 'undefined') {
    BackgroundAudioCacheOrchestrator.onPlaybackStateChanged();
  }
};

window.onAndroidTtsDone = function(segmentId) {
  androidTtsRetryCount = 0;
  if (state.isPlaying) {
    if (segmentId !== undefined && segmentId !== null && segmentId !== '') {
      const currentSeg = state.currentSegments[state.currentSegmentIndex];
      if (currentSeg && String(currentSeg.id) !== String(segmentId)) {
        return;
      }
    }
    const pause = window._currentDirectorPauseMs || 0;
    if (pause > 40) {
      window._sentencePauseTimer = setTimeout(() => {
        if (state.isPlaying) playNextSegment();
      }, pause);
    } else {
      playNextSegment();
    }
  }
};

window.onAndroidTtsError = function(segmentId, errorCode) {
  console.warn(`[AndroidTTS] Error on segment ${segmentId} (code: ${errorCode}), retryCount: ${androidTtsRetryCount}`);
  if (!state.isPlaying) return;

  const currentSeg = state.currentSegments[state.currentSegmentIndex];
  if (segmentId !== undefined && segmentId !== null && segmentId !== '') {
    if (currentSeg && String(currentSeg.id) !== String(segmentId)) {
      console.log(`[AndroidTTS] Ignoring stale error for segment ${segmentId} (active: ${currentSeg.id})`);
      return;
    }
  }

  if (androidTtsRetryCount < MAX_ANDROID_TTS_RETRIES) {
    androidTtsRetryCount++;
    console.log(`[AndroidTTS] Retrying segment ${segmentId} with fallback voice (attempt ${androidTtsRetryCount})...`);
    if (currentSeg && isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.speakText === 'function') {
      const retrySegId = String(currentSeg.id);
      setTimeout(() => {
        if (!state.isPlaying) return;
        const activeNow = state.currentSegments[state.currentSegmentIndex];
        if (!activeNow || String(activeNow.id) !== retrySegId) return;
        const textToSpeak = cleanTtsTextJs(activeNow.tts_text || activeNow.display_text);
        if (!textToSpeak) {
          playNextSegment();
          return;
        }
        window.AndroidBridge.speakText(textToSpeak, '', 1.0, state.playbackSpeed || 0.8, retrySegId);
      }, 200);
      return;
    }
  }

  androidTtsRetryCount = 0;
  setTimeout(() => {
    if (!state.isPlaying) return;
    const activeNow = state.currentSegments[state.currentSegmentIndex];
    if (segmentId && activeNow && String(activeNow.id) !== String(segmentId)) return;
    playNextSegment();
  }, 400);
};

// ==============================================
// 7.5 Studio LampKeep オープニングロゴ動画 スプラッシュ (スキップ不可・全画面没入)
// ==============================================
let _studioLogoDismissed = false;
let _studioLogoFallbackTimer = null;

function initStudioLogoSplash() {
  const overlay = document.getElementById('studioLogoSplashOverlay');
  const video = document.getElementById('studioLogoVideo');
  if (!overlay || !video) return;
  if (_studioLogoDismissed) return;

  // 起動時は広告・他UIを確実に非表示に保つ (ネイティブ側AdMobバナーを非表示)
  if (window.AndroidBridge && typeof window.AndroidBridge.showBannerAd === 'function') {
    try {
      window.AndroidBridge.showBannerAd(false);
    } catch (_) {}
  }

  // Web / PWA 側でも可能な環境では横画面ロックを試行
  if (screen.orientation && typeof screen.orientation.lock === 'function') {
    try {
      screen.orientation.lock('landscape').catch(() => {});
    } catch (_) {}
  }

  // 動画尺(3.6s)に基づく安全フォールバックタイマー(万が一の再生エラー・フリーズ保護)
  if (!_studioLogoFallbackTimer) {
    _studioLogoFallbackTimer = setTimeout(() => {
      dismissStudioLogoSplash();
    }, 4500);
  }

  // オープニングMV動画が最後まで再生完了した瞬間に自動でメイン画面へ移行
  video.onended = () => {
    if (_studioLogoFallbackTimer) clearTimeout(_studioLogoFallbackTimer);
    dismissStudioLogoSplash();
  };

  video.onerror = (err) => {
    console.warn('[StudioLogo] Video playback error:', err);
    if (_studioLogoFallbackTimer) clearTimeout(_studioLogoFallbackTimer);
    dismissStudioLogoSplash();
  };

  // 音声付き自動再生を試行
  try {
    const playPromise = video.play();
    if (playPromise !== undefined) {
      playPromise.catch((e) => {
        console.log('[StudioLogo] Unmuted autoplay blocked, playing muted:', e);
        video.muted = true;
        video.play().catch((err2) => {
          console.warn('[StudioLogo] Muted autoplay also failed:', err2);
          dismissStudioLogoSplash();
        });
      });
    }
  } catch (ex) {
    console.warn('[StudioLogo] Play invocation failed:', ex);
    dismissStudioLogoSplash();
  }
}

function dismissStudioLogoSplash(event) {
  // スキップ不可要件: ユーザーの画面タップ等による手動スキップは遮断 (動画終了またはフォールバックのみ受付)
  if (event && event.type === 'click') {
    return;
  }
  if (_studioLogoDismissed) return;
  _studioLogoDismissed = true;

  if (_studioLogoFallbackTimer) {
    clearTimeout(_studioLogoFallbackTimer);
    _studioLogoFallbackTimer = null;
  }

  const overlay = document.getElementById('studioLogoSplashOverlay');
  const video = document.getElementById('studioLogoVideo');
  if (video) {
    try {
      video.pause();
    } catch (_) {}
  }
  if (overlay) {
    overlay.classList.add('splash-fade-out');
    setTimeout(() => {
      try { overlay.remove(); } catch (_) { overlay.style.display = 'none'; }
    }, 500);
  }

  // 🎬 オープニングMV再生完了: 縦画面へ復帰 ＆ ネイティブバナー広告の表示を開始
  if (screen.orientation) {
    try {
      if (typeof screen.orientation.unlock === 'function') {
        screen.orientation.unlock();
      }
      if (typeof screen.orientation.lock === 'function') {
        screen.orientation.lock('portrait').catch(() => {});
      }
    } catch (_) {}
  }
  if (window.AndroidBridge && typeof window.AndroidBridge.onSplashFinished === 'function') {
    try {
      window.AndroidBridge.onSplashFinished();
    } catch (e) {
      console.warn('[StudioLogo] Failed to notify onSplashFinished:', e);
    }
  } else if (window.AndroidBridge && typeof window.AndroidBridge.showBannerAd === 'function') {
    try {
      window.AndroidBridge.showBannerAd(true);
    } catch (e) {
      console.warn('[StudioLogo] Failed to showBannerAd:', e);
    }
  }

  // ロゴスプラッシュ完了後、もし初回規約同意モーダルが保留されていれば表示
  if (window._pendingPolicyConsentAfterSplash) {
    window._pendingPolicyConsentAfterSplash = false;
    setTimeout(() => {
      const modal = document.getElementById('policyConsentModal');
      if (modal) modal.classList.remove('hidden');
    }, 350);
  }
}

window.initStudioLogoSplash = initStudioLogoSplash;
window.dismissStudioLogoSplash = dismissStudioLogoSplash;

// ==============================================
// 8. 初期化 (DOMContentLoaded)
// ==============================================
document.addEventListener('DOMContentLoaded', async () => {
  // オープニングロゴスプラッシュを即時再生開始
  initStudioLogoSplash();

  initDomRefs();
  try { initPlayerScrollCompactListener(); } catch(e) {}

  // Android アプリ環境へのアダプティブ最適化
  initAndroidAdaptation();
  try { updateAppVersionBadges(); } catch (e) {}

  // 保存済み再生速度の復元 (デフォルト 0.8x)
  state.playbackSpeed = getSavedPlaybackSpeed();
  const speedTextEl = document.getElementById('playbackSpeedText');
  if (speedTextEl) {
    speedTextEl.textContent = `${state.playbackSpeed}x`;
  }
  const floatSpeedTextEl = document.getElementById('floatPlaybackSpeedText');
  if (floatSpeedTextEl) {
    floatSpeedTextEl.textContent = `${state.playbackSpeed}x`;
  }
  const speedSelect = document.getElementById('playbackSpeedSelect');
  if (speedSelect) {
    speedSelect.value = String(state.playbackSpeed);
  }

  // リーダーフォント・文字サイズの復元
  applyReaderTypography();

  // AIトークン使用量バッジ・UIの初期化
  updatePlayerTokenUsageBadgeUI();
  updateAiTokenUsageCardUI();

  if (!isAndroidApp && 'serviceWorker' in navigator) {
    try {
      await navigator.serviceWorker.register('./service-worker.js');
      console.log('PWA ServiceWorker registered');
    } catch (e) {
      console.warn('ServiceWorker registration failed:', e);
    }
  }

  await detectPixelAndBuiltInAI();
  await loadSystemInfo();
  await loadVoices();
  await loadGenres();
  loadLoadReductionPolicies();
  loadDownloadsData();

  setupAudioListeners();
  setupMediaSession();
  setupUserScrollDetection();
  initMonetizationAndGamification();

  updatePlayerStatusUI();
  updatePlayButtonUI(false);
  renderSegments();

  if (typeof BackgroundAudioCacheOrchestrator !== 'undefined') {
    BackgroundAudioCacheOrchestrator.init();
  }
  scheduleAudioGenQueueResume(2200);

  // 初回起動時のタブアクティブカプセルハイライトを確実に適用
  switchTab(state.currentTab || 'search', false);

  // AIのAPIキーが何も設定されていない場合、起動2回に1回の頻度で設定促進ダイアログを表示
  if (typeof checkApiKeyPromptOnStartup === 'function') {
    checkApiKeyPromptOnStartup();
  }
});


// ==============================================
// 9. Android ネイティブ最適化 & Backキー・共有連携
// ==============================================
function initAndroidAdaptation() {
  if (isAndroidApp) {
    document.body.classList.add('is-android');

    // Android APK 内では PWA バナー・ADB配備関連を完全隠蔽
    const pwaBanner = document.getElementById('pwaInstallBanner');
    if (pwaBanner) pwaBanner.remove();

    const qrRow = document.getElementById('settingsQrLinkRow');
    if (qrRow) qrRow.classList.add('hidden');

    const vvBadge = document.getElementById('vvStatusBadge');
    if (vvBadge) vvBadge.classList.add('hidden');

    // Android版の動作モードは「アプリ内包限定」に完全制限・固定
    const vvModeEl = document.getElementById('settingVvMode');
    if (vvModeEl) {
      const extOpt = vvModeEl.querySelector('option[value="external"]');
      if (extOpt) extOpt.remove();
      const autoOpt = vvModeEl.querySelector('option[value="auto"]');
      if (autoOpt) autoOpt.textContent = '📦 アプリ内包限定 (内蔵)';
      vvModeEl.value = 'auto';
      vvModeEl.disabled = true;
      vvModeEl.classList.add('opacity-80', 'cursor-not-allowed');
    }

    // Android版では外部ローカルLLMサーバー(Ollama等)オプションを除外
    const llmEl = document.getElementById('settingLlmProvider');
    if (llmEl) {
      const localLlmOpt = llmEl.querySelector('option[value="local_llm"]');
      if (localLlmOpt) localLlmOpt.remove();
    }

    // Android版では外部接続用URL・Windowsバイナリパス・DLエリアを非表示
    const vvUrlField = document.getElementById('vvUrlField');
    if (vvUrlField) vvUrlField.classList.add('hidden');
    const vvEnginePathField = document.getElementById('vvEnginePathField');
    if (vvEnginePathField) vvEnginePathField.classList.add('hidden');
    const vvDownloadArea = document.getElementById('vvDownloadArea');
    if (vvDownloadArea) vvDownloadArea.classList.add('hidden');

    // Android版インストール時・初回起動時は Gemini API キーを確実に空白とする
    const currentSettings = getSettingsFromStorage();
    if (!currentSettings || currentSettings.gemini_api_key === undefined) {
      const initialSettings = currentSettings || {};
      initialSettings.gemini_api_key = '';
      try {
        localStorage.setItem('narou_reader_settings', JSON.stringify(initialSettings));
      } catch (e) {}
    }

    // 起動時からバナー広告を常時表示（収益最大化）
    updateAdMobBannerVisibility(false);
  }
}

// Android Backキー / ジェスチャー統合ディスパッチャ
window.handleAndroidBackPressed = function() {
  // ① 未同意の規約モーダルは閉じない（Play / 同意フロー要件）
  const consentModal = document.getElementById('policyConsentModal');
  if (consentModal && !consentModal.classList.contains('hidden')) {
    const agreed = localStorage.getItem('narou_policy_consent_v1');
    if (!agreed) {
      if (typeof showMiniToast === 'function') {
        showMiniToast('利用を開始するには規約への同意が必要です');
      }
      return true;
    }
  }

  // ② カーモード（ドライブモード全画面）が開いていれば終了
  const carMode = document.getElementById('carModeOverlay');
  if (carMode && !carMode.classList.contains('hidden')) {
    if (typeof exitCarMode === 'function') {
      exitCarMode();
    } else {
      carMode.classList.add('hidden');
    }
    return true;
  }

  // ③ 開いているモーダル/シートを正規のclose関数で閉じる（優先度順）
  const modalHandlers = [
    { id: 'aiTranslationModal', close: () => typeof closeAiTranslationModal === 'function' ? closeAiTranslationModal() : document.getElementById('aiTranslationModal')?.classList.add('hidden') },
    { id: 'apiKeyTutorialModal', close: () => typeof closeApiKeyTutorialModal === 'function' ? closeApiKeyTutorialModal() : document.getElementById('apiKeyTutorialModal')?.classList.add('hidden') },
    { id: 'sleepTimerModal', close: () => typeof closeSleepTimerModal === 'function' ? closeSleepTimerModal() : document.getElementById('sleepTimerModal')?.classList.add('hidden') },
    { id: 'bookmarksModal', close: () => typeof closeBookmarksModal === 'function' ? closeBookmarksModal() : document.getElementById('bookmarksModal')?.classList.add('hidden') },
    { id: 'pronunciationDictModal', close: () => typeof closePronunciationDictModal === 'function' ? closePronunciationDictModal() : document.getElementById('pronunciationDictModal')?.classList.add('hidden') },
    { id: 'ambientBgmModal', close: () => typeof closeAmbientBgmModal === 'function' ? closeAmbientBgmModal() : document.getElementById('ambientBgmModal')?.classList.add('hidden') },
    { id: 'voicePickerModal', close: () => typeof closeVoicePickerModal === 'function' ? closeVoicePickerModal() : document.getElementById('voicePickerModal')?.classList.add('hidden') },
    { id: 'readerTypographyModal', close: () => typeof closeTypographyModal === 'function' ? closeTypographyModal() : document.getElementById('readerTypographyModal')?.classList.add('hidden') },
    { id: 'speakerSwitchModal', close: () => typeof closeSpeakerSwitchModal === 'function' ? closeSpeakerSwitchModal() : document.getElementById('speakerSwitchModal')?.classList.add('hidden') },
    { id: 'settingsModal', close: () => typeof closeSettingsModal === 'function' ? closeSettingsModal() : document.getElementById('settingsModal')?.classList.add('hidden') },
    { id: 'webPreviewModal', close: () => typeof closeWebPreviewModal === 'function' ? closeWebPreviewModal() : document.getElementById('webPreviewModal')?.classList.add('hidden') },
    { id: 'onlineManualModal', close: () => typeof closeOnlineManualModal === 'function' ? closeOnlineManualModal() : document.getElementById('onlineManualModal')?.classList.add('hidden') },
    { id: 'voicevoxCreditModal', close: () => typeof closeVoicevoxCreditModal === 'function' ? closeVoicevoxCreditModal() : document.getElementById('voicevoxCreditModal')?.classList.add('hidden') },
    { id: 'novelAiReanalyzeModal', close: () => typeof closeNovelAiReanalyzeModal === 'function' ? closeNovelAiReanalyzeModal() : document.getElementById('novelAiReanalyzeModal')?.classList.add('hidden') },
    { id: 'aiAnalyzeProgressModal', close: () => typeof closeAiAnalyzeModal === 'function' ? closeAiAnalyzeModal() : document.getElementById('aiAnalyzeProgressModal')?.classList.add('hidden') },
    { id: 'rewardedBackgroundModal', close: () => typeof closeRewardedBackgroundModal === 'function' ? closeRewardedBackgroundModal() : document.getElementById('rewardedBackgroundModal')?.classList.add('hidden') },
    { id: 'qrModal', close: () => typeof closeQRModal === 'function' ? closeQRModal() : document.getElementById('qrModal')?.classList.add('hidden') },
    { id: 'gdriveAuthModal', close: () => typeof closeGdriveAuthModal === 'function' ? closeGdriveAuthModal() : document.getElementById('gdriveAuthModal')?.classList.add('hidden') },
    { id: 'playStoreRatingModal', close: () => typeof dismissRatingModal === 'function' ? dismissRatingModal(true) : document.getElementById('playStoreRatingModal')?.classList.add('hidden') },
    { id: 'appPolicyModal', close: () => typeof closeAppPolicyModal === 'function' ? closeAppPolicyModal() : document.getElementById('appPolicyModal')?.classList.add('hidden') },
    { id: 'ugcReportModal', close: () => typeof closeUgcReportModal === 'function' ? closeUgcReportModal() : document.getElementById('ugcReportModal')?.classList.add('hidden') },
    { id: 'bulkDownloadModal', close: () => document.getElementById('bulkDownloadModal')?.classList.add('hidden') },
    { id: 'bgPlaybackPromptModal', close: () => document.getElementById('bgPlaybackPromptModal')?.classList.add('hidden') }
  ];

  if (localStorage.getItem('narou_policy_consent_v1')) {
    modalHandlers.push({ id: 'policyConsentModal', close: () => document.getElementById('policyConsentModal')?.classList.add('hidden') });
  }

  for (const item of modalHandlers) {
    const el = document.getElementById(item.id);
    if (el && !el.classList.contains('hidden')) {
      item.close();
      if (typeof unlockBodyScroll === 'function') unlockBodyScroll();
      return true; // Native側に「Back処理完了」を返す
    }
  }

  // ④ タブ履歴の巻き戻し (例: player -> toc -> search)
  if (window.tabHistory && window.tabHistory.length > 1) {
    window.tabHistory.pop(); // 現在のタブをpop
    const prevTab = window.tabHistory[window.tabHistory.length - 1];
    switchTab(prevTab, false);
    return true;
  } else if (state.currentTab && state.currentTab !== 'search') {
    switchTab('search', false);
    return true;
  }

  return false; // ルート画面なのでNative側に終了確認トーストを委ねる
};

// 共有アクション (Android標準共有シート or Web共有/コピー)
function handleShareAction() {
  vibrateFeedback(15);
  const title = state.currentNovel ? state.currentNovel.title : '小説AI朗読プレイヤー';
  const url = state.currentNovel ? `https://ncode.syosetu.com/${state.currentNovel.ncode}/` : window.location.href;

  if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.shareNovel === 'function') {
    window.AndroidBridge.shareNovel(title, url);
    return;
  }

  if (navigator.share) {
    navigator.share({
      title: title,
      text: `${title}\n小説AI朗読でリスニング中！`,
      url: url
    }).catch(() => {});
  } else {
    // クリップボードへコピー
    navigator.clipboard.writeText(`${title} - ${url}`).then(() => {
      showMiniToast('作品リンクをコピーしました');
    }).catch(() => {
      openQRModal();
    });
  }
}

// ==============================================
// 9.1 PWA インストールプロンプト制御 (Web時のみ)
// ==============================================
let deferredPrompt = null;
window.addEventListener('beforeinstallprompt', (e) => {
  if (isAndroidApp) return; // Android APK 内では一切表示しない
  e.preventDefault();
  deferredPrompt = e;
  const banner = document.getElementById('pwaInstallBanner');
  if (banner) banner.classList.remove('hidden');
});

async function triggerPWAInstall() {
  if (!deferredPrompt) return;
  deferredPrompt.prompt();
  const { outcome } = await deferredPrompt.userChoice;
  if (outcome === 'accepted') {
    document.getElementById('pwaInstallBanner')?.classList.add('hidden');
  }
  deferredPrompt = null;
}

function dismissInstallPrompt() {
  document.getElementById('pwaInstallBanner')?.classList.add('hidden');
}

// ==============================================
// 10. システム情報 & 設定モーダル
// ==============================================
async function loadSystemInfo() {
  try {
    const res = await apiFetch('/api/system/info');
    const data = await res.json();
    state.systemInfo = data;

    const currentProvider = data.settings?.llm_provider || 'embedded_llm';
    updateLlmBadge(currentProvider);

    const vvDot = document.getElementById('vvStatusDot');
    const vvText = document.getElementById('vvStatusText');
    if (vvDot && vvText) {
      const vvStatus = data.voicevox_status || {};
      if (data.voicevox_running || vvStatus.available) {
        vvDot.className = 'w-2 h-2 rounded-full bg-emerald-400 animate-pulse';
        if (vvStatus.managed_by_app) {
          vvText.textContent = `VOICEVOX内包 (v${vvStatus.version || ''})`.trim();
        } else {
          vvText.textContent = `VOICEVOX接続中 (v${vvStatus.version || ''})`.trim();
        }
        vvText.className = 'text-emerald-400';
      } else if (vvStatus.download_state && vvStatus.download_state.status === 'downloading') {
        vvDot.className = 'w-2 h-2 rounded-full bg-amber-400 animate-ping';
        vvText.textContent = 'VOICEVOX取得中...';
        vvText.className = 'text-amber-400';
      } else {
        vvDot.className = 'w-2 h-2 rounded-full bg-slate-500';
        vvText.textContent = 'VOICEVOX未接続';
        vvText.className = 'text-slate-400';
      }
    }

    const lanUrlEl = document.getElementById('lanUrlText');
    if (lanUrlEl && data.lan_url) {
      lanUrlEl.textContent = data.lan_url;
    }
  } catch (e) {
    console.error('Failed to load system info:', e);
  }
}

function updateLlmBadge(provider) {
  const badgeText = document.getElementById('llmEngineBadgeText');
  if (!badgeText) return;
  const p = normalizeCastLlmProvider(provider);
  if (p === 'embedded_llm') {
    badgeText.textContent = 'アプリ内包ロジック';
  } else if (p === 'local_llm') {
    badgeText.textContent = '外部サーバーLLM';
  } else if (p === 'gemini') {
    badgeText.textContent = 'Google Gemini';
  } else if (p === 'openai') {
    badgeText.textContent = 'OpenAI';
  } else if (p === 'claude') {
    badgeText.textContent = 'Claude';
  } else {
    badgeText.textContent = 'ルールベース';
  }
}

async function loadVoices() {
  try {
    const res = await apiFetch('/api/voices');
    const data = await res.json();
    state.availableVoices = data.voices || [];
  } catch (e) {
    console.error('Failed to load voices:', e);
  }
}

async function loadGenres() {
  try {
    await apiFetch('/api/narou/genres');
  } catch (e) {
    console.error('Failed to load genres:', e);
  }
}

function toggleLlmFields(autoSetToMax = false) {
  const providerEl = document.getElementById('settingLlmProvider');
  const provider = normalizeCastLlmProvider(providerEl ? providerEl.value : 'gemini');
  if (providerEl && providerEl.value === 'pixel_ai') providerEl.value = 'gemini';
  const embeddedGroup = document.getElementById('fieldGroupEmbedded');
  const localGroup = document.getElementById('fieldGroupLocalLLM');
  const geminiGroup = document.getElementById('fieldGroupGemini');
  const openaiGroup = document.getElementById('fieldGroupOpenAI');
  const claudeGroup = document.getElementById('fieldGroupClaude');

  [embeddedGroup, localGroup, geminiGroup, openaiGroup, claudeGroup].forEach((el) => {
    if (el) el.classList.add('hidden');
  });

  if (provider === 'embedded_llm' && embeddedGroup) {
    embeddedGroup.classList.remove('hidden');
    if (typeof updateLocalLlmStatusUI === 'function') updateLocalLlmStatusUI();
  } else if (provider === 'local_llm' && localGroup) {
    localGroup.classList.remove('hidden');
  } else if (provider === 'gemini' && geminiGroup) {
    geminiGroup.classList.remove('hidden');
  } else if (provider === 'openai' && openaiGroup) {
    openaiGroup.classList.remove('hidden');
  } else if (provider === 'claude' && claudeGroup) {
    claudeGroup.classList.remove('hidden');
  }

  updateScanEpisodesForSelectedModel(autoSetToMax);
  if (typeof scheduleImmediateSettingsSave === 'function') {
    scheduleImmediateSettingsSave({ debounceMs: 50 });
  }
}

function toggleTtsEngineFields() {
  const engineEl = document.getElementById('settingTtsEngine');
  const vvGroup = document.getElementById('vvSettingsGroup');
  if (typeof refreshSwitchStateIndicators === 'function') refreshSwitchStateIndicators();
  if (typeof scheduleImmediateSettingsSave === 'function') {
    scheduleImmediateSettingsSave({ debounceMs: 50 });
  }
  if (!engineEl || !vvGroup) return;

  if (isAndroidApp) {
    vvGroup.classList.add('hidden');
    return;
  }

  if (engineEl.value === 'voicevox') {
    vvGroup.classList.remove('hidden');
    toggleVvModeFields();
    fetchVoicevoxStatus();
  } else {
    vvGroup.classList.add('hidden');
  }
}

function toggleVvModeFields() {
  const modeEl = document.getElementById('settingVvMode');
  const urlField = document.getElementById('vvUrlField');
  const pathField = document.getElementById('vvEnginePathField');
  const downloadArea = document.getElementById('vvDownloadArea');
  if (typeof scheduleImmediateSettingsSave === 'function') {
    scheduleImmediateSettingsSave({ debounceMs: 50 });
  }
  if (!modeEl) return;

  if (isAndroidApp) {
    if (urlField) urlField.classList.add('hidden');
    if (pathField) pathField.classList.add('hidden');
    if (downloadArea) downloadArea.classList.add('hidden');
    return;
  }

  const isExternal = modeEl.value === 'external';
  if (urlField) {
    if (isExternal) urlField.classList.remove('hidden');
    else urlField.classList.add('hidden');
  }
  if (pathField) {
    if (isExternal) pathField.classList.add('hidden');
    else pathField.classList.remove('hidden');
  }
}

let vvDownloadPollingInterval = null;

async function fetchVoicevoxStatus() {
  try {
    const res = await apiFetch('/api/voicevox/status');
    const status = await res.json();
    updateVoicevoxModalStatusUI(status);
  } catch (e) {
    console.warn('Failed to fetch VOICEVOX status:', e);
  }
}

function updateVoicevoxModalStatusUI(status) {
  const dot = document.getElementById('vvModalStatusDot');
  const text = document.getElementById('vvModalStatusText');
  const pathText = document.getElementById('vvEnginePathText');
  const startBtn = document.getElementById('vvStartBtn');
  const stopBtn = document.getElementById('vvStopBtn');
  const dlArea = document.getElementById('vvDownloadArea');

  if (!dot || !text) return;

  if (status.available) {
    dot.className = 'w-2 h-2 rounded-full bg-emerald-400';
    text.textContent = status.managed_by_app
      ? `稼働中 (アプリ内包管理 v${status.version || ''})`
      : `稼働中 (外部サーバー接続 v${status.version || ''})`;
    text.className = 'text-emerald-400 font-semibold';
    if (startBtn) {
      startBtn.textContent = '再起動';
      startBtn.classList.remove('hidden');
    }
    if (stopBtn) {
      if (status.managed_by_app) stopBtn.classList.remove('hidden');
      else stopBtn.classList.add('hidden');
    }
    if (dlArea) dlArea.classList.add('hidden');
  } else {
    dot.className = 'w-2 h-2 rounded-full bg-slate-500';
    text.textContent = '未稼働 (停止中)';
    text.className = 'text-slate-400 font-semibold';
    if (startBtn) {
      startBtn.textContent = '起動する';
      startBtn.classList.remove('hidden');
    }
    if (stopBtn) stopBtn.classList.add('hidden');

    if (!status.engine_found && dlArea) {
      dlArea.classList.remove('hidden');
    } else if (dlArea) {
      dlArea.classList.add('hidden');
    }
  }

  if (pathText) {
    if (status.engine_path) {
      pathText.textContent = `エンジン: ${status.engine_path}`;
      pathText.className = 'text-[10px] font-mono text-slate-400 truncate';
    } else {
      pathText.textContent = '内包エンジン未検出 (下のセットアップまたはインストール先を指定)';
      pathText.className = 'text-[10px] font-mono text-amber-300/80 truncate';
    }
  }

  // ダウンロード進捗チェック
  if (status.download_state && (status.download_state.status === 'downloading' || status.download_state.status === 'extracting')) {
    renderDownloadProgress(status.download_state);
    if (!vvDownloadPollingInterval) {
      vvDownloadPollingInterval = setInterval(pollVoicevoxDownloadProgress, 1000);
    }
  }
}

async function triggerVoicevoxStart() {
  const startBtn = document.getElementById('vvStartBtn');
  if (startBtn) {
    startBtn.disabled = true;
    startBtn.textContent = '起動中...';
  }
  try {
    const res = await apiFetch('/api/voicevox/start', { method: 'POST' });
    const data = await res.json();
    if (data.success) {
      await fetchVoicevoxStatus();
      await loadSystemInfo();
      await loadVoices();
    } else {
      alert(data.error || 'VOICEVOXの起動に失敗しました。');
    }
  } catch (e) {
    alert('VOICEVOX起動リクエストエラー: ' + e.message);
  } finally {
    if (startBtn) startBtn.disabled = false;
    await fetchVoicevoxStatus();
  }
}

async function triggerVoicevoxStop() {
  const stopBtn = document.getElementById('vvStopBtn');
  if (stopBtn) {
    stopBtn.disabled = true;
    stopBtn.textContent = '停止中...';
  }
  try {
    await apiFetch('/api/voicevox/stop', { method: 'POST' });
    await fetchVoicevoxStatus();
    await loadSystemInfo();
  } catch (e) {
    alert('VOICEVOX停止エラー: ' + e.message);
  } finally {
    if (stopBtn) stopBtn.disabled = false;
  }
}

async function triggerVoicevoxDownload() {
  const dlBtn = document.getElementById('vvDownloadBtn');
  const dlType = document.getElementById('vvDownloadType')?.value || 'directml';
  if (dlBtn) {
    dlBtn.disabled = true;
    dlBtn.textContent = '準備中...';
  }
  try {
    const res = await apiFetch('/api/voicevox/download', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ engine_type: dlType })
    });
    const data = await res.json();
    if (data.success) {
      const box = document.getElementById('vvDownloadProgressBox');
      if (box) box.classList.remove('hidden');
      if (!vvDownloadPollingInterval) {
        vvDownloadPollingInterval = setInterval(pollVoicevoxDownloadProgress, 1000);
      }
    } else {
      alert(data.error || 'ダウンロードの開始に失敗しました。');
      if (dlBtn) {
        dlBtn.disabled = false;
        dlBtn.textContent = 'セットアップ開始';
      }
    }
  } catch (e) {
    alert('ダウンロード開始エラー: ' + e.message);
    if (dlBtn) {
      dlBtn.disabled = false;
      dlBtn.textContent = 'セットアップ開始';
    }
  }
}

async function pollVoicevoxDownloadProgress() {
  try {
    const res = await apiFetch('/api/voicevox/download/progress');
    const dlState = await res.json();
    renderDownloadProgress(dlState);

    if (dlState.status === 'completed' || dlState.status === 'error') {
      clearInterval(vvDownloadPollingInterval);
      vvDownloadPollingInterval = null;
      const dlBtn = document.getElementById('vvDownloadBtn');
      if (dlBtn) {
        dlBtn.disabled = false;
        dlBtn.textContent = 'セットアップ開始';
      }
      await fetchVoicevoxStatus();
      await loadSystemInfo();
      await loadVoices();
    }
  } catch (e) {
    console.warn('Failed to poll DL progress:', e);
  }
}

function renderDownloadProgress(dlState) {
  const box = document.getElementById('vvDownloadProgressBox');
  const msg = document.getElementById('vvDownloadMsg');
  const pct = document.getElementById('vvDownloadPct');
  const bar = document.getElementById('vvDownloadProgressBar');

  if (!box || !msg || !pct || !bar) return;
  box.classList.remove('hidden');
  msg.textContent = dlState.message || '処理中...';
  pct.textContent = `${dlState.progress_percent || 0}%`;
  bar.style.width = `${dlState.progress_percent || 0}%`;

  if (dlState.status === 'error') {
    msg.className = 'text-rose-400 text-[10px] font-semibold';
  } else if (dlState.status === 'completed') {
    msg.className = 'text-emerald-400 text-[10px] font-semibold';
  } else {
    msg.className = 'text-blue-300 text-[10px]';
  }
}

