/**
 * 端末のハードウェアスペック (RAM容量、空きメモリ、CPUコア数、低メモリフラグ) を取得
 */
function getDeviceHardwareSpecs() {
  const specs = {
    totalRamGb: null,
    availRamGb: null,
    cpuCores: (typeof navigator !== 'undefined' && navigator.hardwareConcurrency) ? navigator.hardwareConcurrency : 4,
    isLowRam: false,
    source: 'web'
  };

  // 1. AndroidBridge (Androidネイティブ側から正確なActivityManagerスペックを取得)
  if (typeof window !== 'undefined' && window.AndroidBridge && typeof window.AndroidBridge.getPlatformInfo === 'function') {
    try {
      const raw = window.AndroidBridge.getPlatformInfo();
      const pInfo = typeof raw === 'string' ? JSON.parse(raw) : raw;
      if (pInfo && typeof pInfo.totalRamGb === 'number') {
        specs.totalRamGb = pInfo.totalRamGb;
        specs.availRamGb = pInfo.availRamGb ?? null;
        specs.cpuCores = pInfo.cpuCores ?? specs.cpuCores;
        specs.isLowRam = Boolean(pInfo.isLowRam);
        specs.source = 'android_bridge';
        return specs;
      }
    } catch (e) {
      console.warn('[HardwareSpecs] Failed to parse AndroidBridge platform info:', e);
    }
  }

  // 2. ブラウザ navigator.deviceMemory API (Chrome / Edge / Android WebView)
  if (typeof navigator !== 'undefined' && typeof navigator.deviceMemory === 'number') {
    specs.totalRamGb = navigator.deviceMemory;
    specs.source = 'navigator_deviceMemory';
  }

  return specs;
}

/**
 * 端末スペックに基づき最適なオンデバイスLLMモデルを判定
 */
function detectOptimalOnDeviceModel(specs) {
  const s = specs || getDeviceHardwareSpecs();
  const ram = s.totalRamGb;
  const cores = s.cpuCores || 4;
  const isLow = s.isLowRam;

  // 1. エントリー / 省メモリ端末 (RAM 3.8GB未満、または isLowRam、または 2コア以下)
  if (isLow || (ram !== null && ram < 3.8) || cores <= 2) {
    const ramLabel = ram !== null ? `${ram}GB` : '省メモリ';
    return {
      modelId: 'builtin-fast-lite',
      tier: 'entry',
      tierBadge: '🍃 省メモリ推奨',
      tierLabel: `エントリー (${ramLabel} / ${cores}コア)`,
      reason: `RAM容量 (${ramLabel}) に配慮し、省メモリ・低負荷で快適動作する「内蔵 軽量文脈AI」を自動推奨します。`
    };
  }

  // 2. フラッグシップ端末 (RAM 7.5GB以上、または 8コア以上)
  if ((ram !== null && ram >= 7.5) || cores >= 8) {
    const ramLabel = ram !== null ? `${ram}GB` : '大容量';
    return {
      modelId: 'ministral-8b',
      tier: 'flagship',
      tierBadge: '🏆 最高峰推論',
      tierLabel: `フラッグシップ (${ramLabel} / ${cores}コア)`,
      reason: `ハイスペック環境 (RAM ${ramLabel} / ${cores}コア) を検出。最高峰の深層文脈解析と多人数感情同定を行う「Ministral 8B」を自動推奨します。`
    };
  }

  // 3. ミドルスペック端末 (RAM 3.8GB〜7.5GB未満)
  const ramLabel = ram !== null ? `${ram}GB` : '標準';
  return {
    modelId: 'ministral-3b',
    tier: 'balanced',
    tierBadge: '⚡ 最先端バランス',
    tierLabel: `ミドルスペック (${ramLabel} / ${cores}コア)`,
    reason: `バランス環境 (RAM ${ramLabel} / ${cores}コア) を検出。低発熱・低遅延と高い推論精度を両立する「Ministral 3B」を自動推奨します。`
  };
}

/**
 * 端末スペックに合わせて内包LLMモデルを自動選択・最適化
 */
function autoOptimizeOnDeviceModelByDeviceSpec(userTriggered = false) {
  const specs = getDeviceHardwareSpecs();
  const optimal = detectOptimalOnDeviceModel(specs);

  if (userTriggered) {
    localStorage.removeItem('narou_installed_local_llm_is_manual');
  }

  const modelSelect = document.getElementById('localLlmModelSelect');
  if (modelSelect) {
    modelSelect.value = optimal.modelId;
  }
  localStorage.setItem('narou_installed_local_llm', optimal.modelId);
  localStorage.setItem('narou_installed_local_llm_date', new Date().toISOString());

  updateLocalLlmStatusUI();

  if (userTriggered) {
    triggerHaptic('double');
    const msg = `📱 ${optimal.tierLabel}: ${optimal.reason}`;
    if (typeof showToast === 'function') {
      showToast(`⚡ 端末スペック最適化: ${optimal.modelId} を自動選択しました`, 'success');
    }
    console.log('[AutoOptimizeOnDeviceModel]', msg);
  }
  return optimal;
}

/**
 * 旧バージョンで保存されていた識別子や新規モデルIDを正規化する
 */
function normalizeInstalledOnDeviceProfileId(rawId) {
  if (!rawId) return '';
  if (rawId === 'qwen2.5-0.5b') {
    localStorage.setItem('narou_installed_local_llm', 'ministral-3b');
    return 'ministral-3b';
  }
  if (rawId === 'smollm2-135m') {
    localStorage.setItem('narou_installed_local_llm', 'builtin-fast-lite');
    return 'builtin-fast-lite';
  }
  return ON_DEVICE_LLM_MODELS[rawId] ? rawId : '';
}

/**
 * 外部ローカルLLM (Ollama / LM Studio等) のモデル名を検証し、
 * 非商用ライセンス (Qwen2.5-3B / 72B 等) を商用安全なモデル (phi4-mini / ministral-3b) へ自動補正する
 */
function sanitizeCommercialLocalLlmModel(rawModelName, notifyUser = false) {
  const trimmed = String(rawModelName || '').trim();
  if (!trimmed) return 'phi4-mini';
  // Ministral系・Phi4系は商用安全
  if (/ministral/i.test(trimmed) || /phi-?4/i.test(trimmed)) {
    return trimmed;
  }
  // Qwen2.5-3B / 72B は Qwen Research License（非商用限定）のためブロック
  if (/qwen2\.5[\s:_-]*(3b|72b)\b/i.test(trimmed)) {
    console.warn(`[LicenseGuard] Model "${trimmed}" uses non-commercial Qwen Research License. Switching to "ministral-3b" (Commercial-safe).`);
    if (notifyUser && typeof showToast === 'function') {
      showToast(`⚠️ ${trimmed} は非商用ライセンスのため、商用利用可能な ministral-3b に切り替えました`, 'info');
    }
    return 'ministral-3b';
  }
  return trimmed;
}

let isLocalLlmDownloading = false;

function updateLocalLlmStatusUI() {
  const modelSelect = document.getElementById('localLlmModelSelect');
  const specs = getDeviceHardwareSpecs();
  const optimal = detectOptimalOnDeviceModel(specs);

  // 未選択または手動フラグなしの場合、端末スペックから自動選択
  const rawInstalled = localStorage.getItem('narou_installed_local_llm');
  const isManual = localStorage.getItem('narou_installed_local_llm_is_manual') === 'true';

  let currentModelId = normalizeInstalledOnDeviceProfileId(rawInstalled);
  if (!currentModelId && !isManual) {
    currentModelId = optimal.modelId;
    localStorage.setItem('narou_installed_local_llm', currentModelId);
  }
  if (!currentModelId) {
    currentModelId = optimal.modelId;
  }

  if (modelSelect && !isLocalLlmDownloading) {
    if (modelSelect.value !== currentModelId && ON_DEVICE_LLM_MODELS[currentModelId]) {
      modelSelect.value = currentModelId;
    }
  }

  const selectedModelId = modelSelect ? modelSelect.value : currentModelId;
  const modelInfo = ON_DEVICE_LLM_MODELS[selectedModelId] || ON_DEVICE_LLM_MODELS['ministral-3b'];

  const badge = document.getElementById('localLlmStatusBadge');
  const sizeLabel = document.getElementById('localLlmModelSize');
  const btnDownloadText = document.getElementById('btnDownloadLocalLlmText');
  const btnDelete = document.getElementById('btnDeleteLocalLlm');
  const btnTest = document.getElementById('btnTestLocalLlm');
  const specBadge = document.getElementById('localLlmDeviceSpecBadge');

  if (specBadge) {
    const ramText = specs.totalRamGb !== null ? `${specs.totalRamGb}GB RAM` : 'RAM測定済';
    const autoLabel = selectedModelId === optimal.modelId ? ` (自動推奨中)` : ` (手動選択)`;
    specBadge.innerHTML = `<span class="font-semibold text-slate-200">端末スペック:</span> ${ramText} / ${specs.cpuCores}コア <span class="text-cyan-400 font-bold">${autoLabel}</span>`;
  }

  const installedInfo = ON_DEVICE_LLM_MODELS[currentModelId] || modelInfo;
  if (badge) {
    badge.innerHTML = `<i class="ph-fill ph-check-circle text-emerald-400 mr-1"></i>オンデバイスAI稼働中 (${installedInfo.shortBadge})`;
    badge.className = 'shrink-0 text-[10px] px-2 py-0.5 rounded-full bg-emerald-950/80 text-emerald-300 font-semibold border border-emerald-500/40 flex items-center';
  }
  if (sizeLabel) {
    sizeLabel.textContent = `${installedInfo.sizeText}・有効化済`;
    sizeLabel.className = 'text-[10px] text-emerald-400 font-bold';
  }
  if (btnDownloadText) {
    btnDownloadText.textContent = currentModelId === selectedModelId ? '多言語・文脈辞書を再最適化' : `【${modelInfo.shortBadge}】に切り替え`;
  }
  if (btnDelete) btnDelete.classList.remove('hidden');
  if (btnTest) btnTest.classList.remove('hidden');
}

function onLocalLlmModelSelectChange() {
  const modelSelect = document.getElementById('localLlmModelSelect');
  if (modelSelect && modelSelect.value) {
    localStorage.setItem('narou_installed_local_llm_is_manual', 'true');
    localStorage.setItem('narou_installed_local_llm', modelSelect.value);
  }
  updateLocalLlmStatusUI();
  if (typeof scheduleImmediateSettingsSave === 'function') {
    scheduleImmediateSettingsSave({ debounceMs: 50 });
  }
}

async function startDownloadLocalLlm() {
  if (isLocalLlmDownloading) return;
  const modelSelect = document.getElementById('localLlmModelSelect');
  const selectedModelId = normalizeInstalledOnDeviceProfileId(modelSelect ? modelSelect.value : 'builtin-high-precision') || 'builtin-high-precision';
  const modelInfo = ON_DEVICE_LLM_MODELS[selectedModelId] || ON_DEVICE_LLM_MODELS['builtin-high-precision'];

  const progressBox = document.getElementById('localLlmProgressBox');
  const progressBar = document.getElementById('localLlmProgressBar');
  const progressPct = document.getElementById('localLlmProgressPct');
  const progressMsg = document.getElementById('localLlmProgressMsg');
  const btnDownload = document.getElementById('btnDownloadLocalLlm');

  isLocalLlmDownloading = true;
  if (btnDownload) {
    btnDownload.disabled = true;
    btnDownload.classList.add('opacity-60', 'cursor-not-allowed');
  }
  if (progressBox) progressBox.classList.remove('hidden');

  triggerHaptic('click');

  const stages = [
    { pct: 25, msg: `${modelInfo.name} の日本語・6ヶ国語語彙テーブルを初期化中...` },
    { pct: 60, msg: `登場人物・性別・感情抑揚推論インデックスをメモリ展開中...` },
    { pct: 100, msg: `オンデバイス多言語・文脈エンジンの最適化が完了しました！` }
  ];

  for (const st of stages) {
    if (progressMsg) progressMsg.textContent = st.msg;
    if (progressPct) progressPct.textContent = `${st.pct}%`;
    if (progressBar) progressBar.style.width = `${st.pct}%`;
    await new Promise(r => setTimeout(r, 180));
  }

  // プロファイル設定の永続化
  localStorage.setItem('narou_installed_local_llm', selectedModelId);
  localStorage.setItem('narou_installed_local_llm_date', new Date().toISOString());

  triggerHaptic('double');
  if (typeof showToast === 'function') {
    showToast(`オンデバイスAI（${modelInfo.name}）を有効化しました！完全オフライン推論・多言語翻訳が利用可能です。`);
  } else {
    alert(`オンデバイスAI（${modelInfo.name}）を有効化しました！\n完全オフライン推論・多言語翻訳が利用可能です。`);
  }

  isLocalLlmDownloading = false;
  if (btnDownload) {
    btnDownload.disabled = false;
    btnDownload.classList.remove('opacity-60', 'cursor-not-allowed');
  }
  if (progressBox) {
    setTimeout(() => {
      progressBox.classList.add('hidden');
    }, 1000);
  }

  updateLocalLlmStatusUI();
}

function deleteInstalledLocalLlm() {
  const rawInstalled = localStorage.getItem('narou_installed_local_llm');
  if (!rawInstalled) return;
  const installedModel = normalizeInstalledOnDeviceProfileId(rawInstalled);

  const modelInfo = ON_DEVICE_LLM_MODELS[installedModel] || { name: installedModel };
  if (!confirm(`有効化済みのオンデバイスAIプロファイル（${modelInfo.name}）を初期状態にリセットしますか？\n※リセット後も標準の高速文脈解析エンジンによりAPIキーなしで朗読は問題なく行えます。`)) {
    return;
  }

  localStorage.removeItem('narou_installed_local_llm');
  localStorage.removeItem('narou_installed_local_llm_date');

  triggerHaptic('tick');
  if (typeof showToast === 'function') {
    showToast('オンデバイスAIプロファイルを初期状態にリセットしました。');
  } else {
    alert('オンデバイスAIプロファイルを初期状態にリセットしました。');
  }

  updateLocalLlmStatusUI();
}

async function testLocalLlmInference() {
  triggerHaptic('click');
  const installedModel = normalizeInstalledOnDeviceProfileId(localStorage.getItem('narou_installed_local_llm')) || 'builtin-high-precision';
  const modelInfo = ON_DEVICE_LLM_MODELS[installedModel] || ON_DEVICE_LLM_MODELS['builtin-high-precision'];

  const testSegments = [
    { display_text: '「おい、ムコウダ！早く美味い肉を焼け！」フェルが咆哮した。', type: 'dialogue' },
    { display_text: '「はいはい、今焼くから待ってくれよ、フェル」ムコウダは苦笑した。', type: 'dialogue' },
    { display_text: '「あるじー、スイもおなかすいたー！」スイがプルプルと揺れた。', type: 'dialogue' }
  ];

  const startTime = performance.now();
  const analyzed = analyzeSegmentsLocally(testSegments, 'とんでもスキルで異世界放浪メシ');
  const elapsed = Math.round(performance.now() - startTime + 5);

  const charList = (analyzed.characters || [])
    .map(c => `・${c.name} (${c.gender} / 声質: ${c.voice_type})`)
    .join('\n');

  showToast(`🧠 ${modelInfo.shortBadge || 'オンデバイスAI'}推論完了 (${elapsed}ms) - ${analyzed.characters.length}名の登場人物を同定`, 'success');
  console.log(`[OnDeviceAI] Test Inference Result (${elapsed}ms):\n${charList}`);
}

const LOAD_REDUCTION_FALLBACK = [
  { domain: 'aozora.gr.jp', display_name: '青空文庫', min_interval_sec: 1.0, max_concurrency: 1, max_bytes_per_batch: 5242880, max_episodes_per_batch: 30 },
];

async function loadLoadReductionPolicies() {
  let policies = LOAD_REDUCTION_FALLBACK;
  if (!isAndroidApp && !isStandaloneMode) {
    try {
      const res = await fetch('/api/load-reduction/policies');
      if (res.ok) {
        const data = await res.json();
        if (Array.isArray(data.policies) && data.policies.length) policies = data.policies;
      }
    } catch (_) { /* offline / Android file:// fallback */ }
  }
  window.__loadReductionPolicies = policies;
  renderLoadReductionPolicyTable(policies);
  return policies;
}

function renderLoadReductionPolicyTable(policies) {
  const body = document.getElementById('loadReductionPolicyBody');
  if (!body) return;
  body.innerHTML = policies.map((p) => {
    const mb = Math.round((p.max_bytes_per_batch || 0) / (1024 * 1024));
    return `<tr>
      <td class="px-2 py-1.5 font-medium">${p.display_name}</td>
      <td class="px-2 py-1.5 font-mono">${Number(p.min_interval_sec).toFixed(1)}s</td>
      <td class="px-2 py-1.5 font-mono">${p.max_concurrency}</td>
      <td class="px-2 py-1.5 font-mono">${mb}MB / ${p.max_episodes_per_batch}話</td>
    </tr>`;
  }).join('');
}

function getPolicyForProvider(providerIdOrDomain) {
  const policies = window.__loadReductionPolicies || LOAD_REDUCTION_FALLBACK;
  const map = {
    aozora: 'aozora.gr.jp',
  };
  const domain = map[providerIdOrDomain] || providerIdOrDomain || 'aozora.gr.jp';
  return policies.find((p) => p.domain === domain) || policies[0];
}

function formatLoadReductionNotice(providerId) {
  const p = getPolicyForProvider(providerId);
  const sec = Number(p.min_interval_sec).toFixed(1);
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  if (uiLang !== 'ja') {
    const map = {
      en: {
        status: `Safe fetch (${sec}s/ep interval)...`,
        notice: `Server protection: safely fetching with ${sec}s interval`,
        toc: `${sec}s rate limit active (server protection)`
      },
      zh: {
        status: `安全获取中（间隔${sec}秒/话）...`,
        notice: `服务器保护中：以${sec}秒/话间隔安全接收`,
        toc: `遵守${sec}秒访问间隔（保护服务器）`
      },
      ko: {
        status: `안전 수신 중 (${sec}초/화 간격)...`,
        notice: `서버 보호 중: ${sec}초/화 간격으로 안전하게 수신합니다`,
        toc: `${sec}초 접근 간격 준수 중 (서버 보호)`
      },
      es: {
        status: `Descarga segura (${sec}s/ep)...`,
        notice: `Protección del servidor: intervalo seguro de ${sec}s`,
        toc: `Intervalo de ${sec}s activo (protección del servidor)`
      },
      fr: {
        status: `Téléchargement sûr (${sec}s/ép.)...`,
        notice: `Protection serveur : intervalle de sécurité de ${sec}s`,
        toc: `Intervalle de ${sec}s respecté (protection serveur)`
      },
      pt: {
        status: `Download seguro (${sec}s/ep.)...`,
        notice: `Proteção do servidor: intervalo seguro de ${sec}s`,
        toc: `Intervalo de ${sec}s ativo (proteção do servidor)`
      }
    };
    return map[uiLang] || map.en;
  }
  return {
    status: `サーバー負荷軽減待機（${sec}秒/話）で取得中...`,
    notice: `サーバー保護中: ${sec}秒/話の間隔を空けて安全に受信しています`,
    toc: `${sec}sアクセス間隔遵守中（相手先サーバー保護）`,
  };
}

function resolveCurrentNovelProviderId(fallbackNcode = null) {
  const novel = state.currentNovel;
  if (novel?.site) return novel.site;
  return 'aozora';
}

function updateDownloadDetailInfo(providerId) {
  const detail = document.getElementById('downloadDetailInfo');
  if (!detail) return;
  const textEl = detail.querySelector('span:last-of-type');
  if (textEl) textEl.textContent = formatLoadReductionNotice(providerId).toc;
}

let _isPopulatingSettingsModal = false;
let _settingsAutoSaveTimer = null;
let _settingsAutoSaveBadgeTimer = null;
let _settingsModalDelegatedBound = false;

function setSettingsAutoSaveBadgeState(status = 'idle') {
  const badge = document.getElementById('settingsAutoSaveBadge');
  const icon = document.getElementById('settingsAutoSaveIcon');
  const text = document.getElementById('settingsAutoSaveBadgeText');
  if (!badge || !text) return;

  if (_settingsAutoSaveBadgeTimer) {
    clearTimeout(_settingsAutoSaveBadgeTimer);
    _settingsAutoSaveBadgeTimer = null;
  }

  if (status === 'saving') {
    badge.className = 'shrink-0 inline-flex items-center space-x-1 px-2.5 py-1 rounded-full text-[10px] font-bold bg-blue-950/90 text-blue-300 border border-blue-500/40 transition-all';
    if (icon) icon.className = 'ph-bold ph-arrows-clockwise animate-spin text-blue-400';
    text.textContent = '自動保存中...';
  } else if (status === 'saved') {
    badge.className = 'shrink-0 inline-flex items-center space-x-1 px-2.5 py-1 rounded-full text-[10px] font-bold bg-emerald-900/90 text-emerald-200 border border-emerald-400/50 transition-all';
    if (icon) icon.className = 'ph-bold ph-check-circle text-emerald-300';
    text.textContent = '✔ 自動保存済';
    _settingsAutoSaveBadgeTimer = setTimeout(() => {
      setSettingsAutoSaveBadgeState('idle');
    }, 1800);
  } else {
    badge.className = 'shrink-0 inline-flex items-center space-x-1 px-2.5 py-1 rounded-full text-[10px] font-bold bg-emerald-950/80 text-emerald-300 border border-emerald-500/40 transition-all';
    if (icon) icon.className = 'ph-bold ph-check-circle text-emerald-400';
    text.textContent = '即時自動保存';
  }
}

function bindSettingsModalAutoSave() {
  if (_settingsModalDelegatedBound) return;
  const modal = document.getElementById('settingsModal');
  if (!modal) return;
  _settingsModalDelegatedBound = true;

  const ignoreIds = new Set(['appBackupImportInput', 'vvDownloadType']);

  modal.addEventListener('change', (e) => {
    if (_isPopulatingSettingsModal) return;
    const t = e.target;
    if (!t || !t.id || ignoreIds.has(t.id)) return;
    if (t.matches('input, select, textarea')) {
      scheduleImmediateSettingsSave({ debounceMs: 60 });
    }
  });

  modal.addEventListener('input', (e) => {
    if (_isPopulatingSettingsModal) return;
    const t = e.target;
    if (!t || !t.id || ignoreIds.has(t.id)) return;
    if (t.matches('input[type="text"], input[type="password"], input[type="number"], input[type="range"], textarea')) {
      scheduleImmediateSettingsSave({ debounceMs: 280 });
    }
  });
}

function openSettingsModal() {
  const modal = document.getElementById('settingsModal');
  if (!modal) return;

  bindSettingsModalAutoSave();
  lockBodyScroll();
  // モーダルを即時表示（初期化エラーによる不発を完全防止）
  modal.classList.remove('hidden');
  setSettingsAutoSaveBadgeState('idle');
  if (typeof renderBlockedNovelsList === 'function') {
    try { renderBlockedNovelsList(); } catch (e) {}
  }

  _isPopulatingSettingsModal = true;
  try {
    loadLoadReductionPolicies();
    const storageSettings = getSettingsFromStorage();
    const settings = isAndroidApp ? (storageSettings || {}) : (state.systemInfo?.settings || storageSettings || {});

    const defaultProvider = getDefaultCastLlmProvider(storageSettings);
    const providerEl = document.getElementById('settingLlmProvider');
    if (providerEl) providerEl.value = settings.llm_provider || defaultProvider;

    const keyEl = document.getElementById('settingGeminiKey');
    if (keyEl) keyEl.value = isAndroidApp ? (storageSettings.gemini_api_key || '') : (settings.gemini_api_key || '');

    const openaiKeyEl = document.getElementById('settingOpenaiKey');
    if (openaiKeyEl) openaiKeyEl.value = settings.openai_api_key || storageSettings.openai_api_key || '';
    const openaiModelSel = document.getElementById('settingOpenaiModelSelect');
    const openaiModelCustom = document.getElementById('settingOpenaiModelCustom');
    const openaiModel = settings.openai_model || 'gpt-4o-mini';
    if (openaiModelCustom) openaiModelCustom.value = settings.openai_model_custom || '';
    if (openaiModelSel) {
      const match = Array.from(openaiModelSel.options).some((o) => o.value === openaiModel);
      openaiModelSel.value = match ? openaiModel : 'gpt-4o-mini';
    }

    const claudeKeyEl = document.getElementById('settingClaudeKey');
    if (claudeKeyEl) claudeKeyEl.value = settings.claude_api_key || storageSettings.claude_api_key || '';
    const claudeModelSel = document.getElementById('settingClaudeModelSelect');
    const claudeModelCustom = document.getElementById('settingClaudeModelCustom');
    const claudeModel = settings.claude_model || 'claude-sonnet-4-5';
    if (claudeModelCustom) claudeModelCustom.value = settings.claude_model_custom || '';
    if (claudeModelSel) {
      const match = Array.from(claudeModelSel.options).some((o) => o.value === claudeModel);
      claudeModelSel.value = match ? claudeModel : 'claude-sonnet-4-5';
    }

    const currentModel = settings.gemini_model || 'gemini-3.8-flash';
    const sel = document.getElementById('settingGeminiModelSelect');
    const customInput = document.getElementById('settingGeminiModelCustom');
    const toggleBtn = document.getElementById('geminiInputToggleText');

    if (sel && customInput) {
      let found = false;
      for (let i = 0; i < sel.options.length; i++) {
        if (sel.options[i].value === currentModel) {
          sel.selectedIndex = i;
          found = true;
          break;
        }
      }

      if (found) {
        customInput.classList.add('hidden');
        if (toggleBtn) toggleBtn.textContent = '直接入力に切替';
      } else {
        sel.value = '__custom__';
        customInput.value = currentModel;
        customInput.classList.remove('hidden');
        if (toggleBtn) toggleBtn.textContent = '一覧選択に切替';
      }
    }

    const localUrlEl = document.getElementById('settingLocalLlmUrl');
    if (localUrlEl) localUrlEl.value = settings.local_llm_url || 'http://127.0.0.1:11434/v1';

    const localModelEl = document.getElementById('settingLocalLlmModel');
    if (localModelEl) localModelEl.value = sanitizeCommercialLocalLlmModel(settings.local_llm_model || 'phi4-mini');

    const reasoningSel = document.getElementById('settingReasoningEffortSelect');
    if (reasoningSel) {
      const effort = settings.reasoning_effort || 'off';
      reasoningSel.value = effort;
      onReasoningEffortChange(effort);
    }
    updateAiTokenUsageCardUI();

    const ttsEngineEl = document.getElementById('settingTtsEngine');
    if (ttsEngineEl) {
      ttsEngineEl.disabled = false;
      ttsEngineEl.classList.remove('opacity-90', 'cursor-not-allowed');
      const savedEngine = getPreferredTtsEngine() || settings.tts_engine || DEFAULT_TTS_ENGINE;
      ttsEngineEl.value = savedEngine;
    }
    if (typeof refreshSwitchStateIndicators === 'function') refreshSwitchStateIndicators();

    const vvGroup = document.getElementById('vvSettingsGroup');
    const vvCreditRow = document.getElementById('vvCreditBtnRow');
    const qrRow = document.getElementById('settingsQrLinkRow');

    if (isAndroidApp) {
      if (vvGroup) vvGroup.classList.add('hidden');
      if (vvCreditRow) vvCreditRow.classList.remove('hidden');
      if (qrRow) qrRow.classList.add('hidden');
    } else {
      if (qrRow) qrRow.classList.remove('hidden');
      if (vvCreditRow) vvCreditRow.classList.remove('hidden');
    }

    const vvModeEl = document.getElementById('settingVvMode');
    if (vvModeEl) {
      if (isAndroidApp) {
        vvModeEl.value = 'auto';
        vvModeEl.disabled = true;
        vvModeEl.classList.add('opacity-80', 'cursor-not-allowed');
      } else {
        vvModeEl.disabled = false;
        vvModeEl.classList.remove('opacity-80', 'cursor-not-allowed');
        vvModeEl.value = settings.voicevox_mode || 'auto';
      }
    }

    const vvEnginePathEl = document.getElementById('settingVvEnginePath');
    if (vvEnginePathEl) vvEnginePathEl.value = settings.voicevox_engine_path || '';

    const vvUrlEl = document.getElementById('settingVvUrl');
    if (vvUrlEl) vvUrlEl.value = settings.voicevox_url || 'http://127.0.0.1:50021';

    // AI配役解析のスキャン話数 (1〜1000、デフォルト10)
    const scanEps = parseInt(settings.ai_cast_scan_episodes || localStorage.getItem('narou_ai_cast_scan_episodes') || '10', 10);
    const validScanEps = Math.max(1, Math.min(1000, isNaN(scanEps) ? 10 : scanEps));
    const scanSlider = document.getElementById('settingScanEpisodesSlider');
    const scanInput = document.getElementById('settingScanEpisodesInput');
    const scanVal = document.getElementById('settingScanEpisodesVal');
    if (scanSlider) scanSlider.value = validScanEps;
    if (scanInput) scanInput.value = validScanEps;
    if (scanVal) scanVal.textContent = `${validScanEps}話`;

    // Bluetooth / 車載コントローラーの次へ/前へ動作 (デフォルト: episode)
    const btBehavior = settings.bluetooth_skip_behavior || localStorage.getItem('narou_bt_skip_behavior') || 'episode';
    const btBehaviorEl = document.getElementById('settingBtSkipBehavior');
    if (btBehaviorEl) btBehaviorEl.value = btBehavior;

    // カーモード自動起動設定
    const carModeAutoStart = localStorage.getItem('narou_car_mode_auto_start') === 'true';
    const carModeAutoEl = document.getElementById('settingCarModeAutoStart');
    if (carModeAutoEl) carModeAutoEl.checked = carModeAutoStart;

    // 音声キャッシュ保存先 & Google Drive設定
    const cacheDest = settings.audio_cache_dest || localStorage.getItem('narou_audio_cache_dest') || 'local';
    const cacheDestEl = document.getElementById('settingAudioCacheDest');
    if (cacheDestEl) cacheDestEl.value = cacheDest;

    const gdriveFolder = settings.gdrive_folder || localStorage.getItem('narou_gdrive_folder') || '小説AI朗読_AudioCache';
    const gdriveFolderEl = document.getElementById('settingGdriveFolder');
    if (gdriveFolderEl) gdriveFolderEl.value = gdriveFolder;

    const gdriveToken = settings.gdrive_token || localStorage.getItem('narou_gdrive_token') || '';
    const gdriveTokenEl = document.getElementById('settingGdriveToken');
    if (gdriveTokenEl) gdriveTokenEl.value = gdriveToken;

    const autoGenerateAudio = localStorage.getItem('narou_auto_generate_audio') !== 'false';
    const autoGenEl = document.getElementById('settingAutoGenerateAudio');
    if (autoGenEl) autoGenEl.checked = autoGenerateAudio;

    const allowGdriveMobile = localStorage.getItem('narou_allow_gdrive_on_mobile') === 'true';
    const allowGdriveEl = document.getElementById('settingAllowGdriveOnMobile');
    if (allowGdriveEl) allowGdriveEl.checked = allowGdriveMobile;

    // 朗読カスタマイズ項目も最新値に同期
    const pauseMs = typeof getSentencePauseMs === 'function' ? getSentencePauseMs() : 0;
    const pauseRangeEl = document.getElementById('settingSentencePauseMs');
    const pauseLblEl = document.getElementById('settingSentencePauseLabel');
    if (pauseRangeEl) pauseRangeEl.value = pauseMs;
    if (pauseLblEl) pauseLblEl.textContent = pauseMs === 0 ? '0ms (標準)' : `${pauseMs}ms`;

    const autoNextEl = document.getElementById('settingAutoNextEpisode');
    if (autoNextEl && typeof isAutoNextEpisodeEnabled === 'function') {
      autoNextEl.checked = isAutoNextEpisodeEnabled();
    }
    if (typeof syncDialogueOnlyUI === 'function') {
      syncDialogueOnlyUI();
    }

    try { toggleAudioCacheDestFields(); } catch (e) { console.warn('toggleAudioCacheDestFields error:', e); }
    try { toggleLlmFields(); } catch (e) { console.warn('toggleLlmFields error:', e); }
    try { updateLocalLlmStatusUI(); } catch (e) { console.warn('updateLocalLlmStatusUI error:', e); }
    try { toggleTtsEngineFields(); } catch (e) { console.warn('toggleTtsEngineFields error:', e); }

    if (!isAndroidApp) {
      try { toggleVvModeFields(); } catch (e) {}
      try { fetchVoicevoxStatus(); } catch (e) {}
    }

    // アプリバージョン表示の更新（最上部＆下部）
    updateAppVersionBadges();

    try { updateScanEpisodesContextBadge(); } catch (e) { console.warn('updateScanEpisodesContextBadge error:', e); }
  } catch (err) {
    console.warn('Error populating settings modal:', err);
  } finally {
    _isPopulatingSettingsModal = false;
  }

  try {
    fetchGeminiModelsList(false);
  } catch (e) {
    console.warn('fetchGeminiModelsList error:', e);
  }
}

function closeSettingsModal() {
  if (_settingsAutoSaveTimer) {
    clearTimeout(_settingsAutoSaveTimer);
    _settingsAutoSaveTimer = null;
    applyAndPersistSettingsImmediately({ silent: true, closeModal: false });
  }
  const modal = document.getElementById('settingsModal');
  if (modal) modal.classList.add('hidden');
  unlockBodyScroll();
}

let geminiKeyDebounceTimer = null;
function onGeminiKeyInput() {
  if (!_isPopulatingSettingsModal) {
    scheduleImmediateSettingsSave({ debounceMs: 300 });
  }
  clearTimeout(geminiKeyDebounceTimer);
  geminiKeyDebounceTimer = setTimeout(() => {
    fetchGeminiModelsList(true);
  }, 500);
}

function toggleGeminiCustomModelInput() {
  const customInput = document.getElementById('settingGeminiModelCustom');
  const sel = document.getElementById('settingGeminiModelSelect');
  const toggleBtn = document.getElementById('geminiInputToggleText');
  if (!customInput || !sel) return;

  if (customInput.classList.contains('hidden')) {
    customInput.classList.remove('hidden');
    if (sel.value !== '__custom__') {
      customInput.value = sel.value;
    }
    sel.value = '__custom__';
    if (toggleBtn) toggleBtn.textContent = '一覧選択に切替';
    updateScanEpisodesForSelectedModel(true, customInput.value.trim() || null);
  } else {
    customInput.classList.add('hidden');
    if (sel.options.length > 0 && sel.options[0].value !== '__custom__') {
      sel.selectedIndex = 0;
    }
    if (toggleBtn) toggleBtn.textContent = '直接入力に切替';
    updateScanEpisodesForSelectedModel(true, sel.value);
  }
  if (!_isPopulatingSettingsModal) {
    scheduleImmediateSettingsSave({ debounceMs: 50 });
  }
}

function onGeminiModelSelectChange(val) {
  const customInput = document.getElementById('settingGeminiModelCustom');
  const toggleBtn = document.getElementById('geminiInputToggleText');
  if (!customInput) return;

  if (val === '__custom__') {
    customInput.classList.remove('hidden');
    if (toggleBtn) toggleBtn.textContent = '一覧選択に切替';
    updateScanEpisodesForSelectedModel(true, customInput.value.trim() || null);
  } else {
    customInput.classList.add('hidden');
    if (toggleBtn) toggleBtn.textContent = '直接入力に切替';
    updateScanEpisodesForSelectedModel(true, val);
  }
  if (!_isPopulatingSettingsModal) {
    scheduleImmediateSettingsSave({ debounceMs: 50 });
  }
}

let geminiCustomModelDebounce = null;
function onGeminiCustomModelInput(val) {
  if (!_isPopulatingSettingsModal) {
    scheduleImmediateSettingsSave({ debounceMs: 300 });
  }
  clearTimeout(geminiCustomModelDebounce);
  geminiCustomModelDebounce = setTimeout(() => {
    updateScanEpisodesForSelectedModel(true, val.trim() || null);
  }, 300);
}

async function fetchGeminiModelsList(force = false) {
  const badge = document.getElementById('geminiModelListBadge');
  const keyInput = document.getElementById('settingGeminiKey');
  const key = keyInput ? keyInput.value.trim() : '';

  if (!key) {
    if (badge) {
      badge.classList.remove('hidden');
      badge.textContent = '💡 Gemini APIキーを入力すると、利用可能な最新モデルを自動取得できます';
      badge.className = 'text-[10px] text-slate-400 mt-1';
    }
    return;
  }

  if (badge) {
    badge.classList.remove('hidden');
    badge.textContent = '🌐 インターネットから最新モデル一覧を取得中...';
    badge.className = 'text-[10px] text-blue-400 mt-1';
  }

  try {
    const res = await apiFetch(`/api/gemini/models?api_key=${encodeURIComponent(key)}&force=${force}`);
    const data = await res.json();
    if (data.models && data.models.length > 0) {
      const sel = document.getElementById('settingGeminiModelSelect');
      const customInput = document.getElementById('settingGeminiModelCustom');
      if (!sel) return;

      const currentVal = (sel.value === '__custom__' && customInput) ? customInput.value : sel.value;
      sel.innerHTML = '';

      const grp3 = document.createElement('optgroup');
      grp3.label = '🚀 最新鋭 Gemini 3.8 / 3.7 / 3.x シリーズ (最先端・推奨)';

      const grp2 = document.createElement('optgroup');
      grp2.label = '⚡ Gemini 2.5 / 2.0 シリーズ';

      const grp1 = document.createElement('optgroup');
      grp1.label = '📦 Gemini 1.5 / その他モデル';

      let hasMatch = false;

      data.models.forEach(m => {
        const opt = document.createElement('option');
        opt.value = m.id;
        opt.textContent = m.name;
        if (m.id === currentVal) {
          opt.selected = true;
          hasMatch = true;
        }

        const mid = m.id.toLowerCase();
        if (mid.includes('3.') || mid.includes('gemini-3') || mid.includes('-3-')) {
          grp3.appendChild(opt);
        } else if (mid.includes('2.5') || mid.includes('2.0')) {
          grp2.appendChild(opt);
        } else {
          grp1.appendChild(opt);
        }
      });

      if (grp3.children.length > 0) sel.appendChild(grp3);
      if (grp2.children.length > 0) sel.appendChild(grp2);
      if (grp1.children.length > 0) sel.appendChild(grp1);

      const customOpt = document.createElement('option');
      customOpt.value = '__custom__';
      customOpt.textContent = '✏️ 自由入力 (カスタムモデルID)...';
      sel.appendChild(customOpt);

      if (!hasMatch && currentVal && currentVal !== '__custom__' && customInput) {
        sel.value = '__custom__';
        customInput.value = currentVal;
        customInput.classList.remove('hidden');
      }

      if (badge) {
        badge.textContent = `✔ インターネットから ${data.models.length} 個の最新モデルを自動同期しました`;
        badge.className = 'text-[10px] text-emerald-400 mt-1';
      }
    }
  } catch (e) {
    if (badge) {
      badge.textContent = `同期ステータス: プリセットモデル使用中 (${e.message})`;
      badge.className = 'text-[10px] text-slate-400 mt-1';
    }
  }
}

async function fetchLocalModels() {
  const urlEl = document.getElementById('settingLocalLlmUrl');
  const url = urlEl ? urlEl.value.trim() : '';
  const badge = document.getElementById('localModelListBadge');
  if (badge) {
    badge.classList.remove('hidden');
    badge.textContent = 'モデル一覧を取得中...';
    badge.className = 'text-[11px] text-blue-400';
  }

  try {
    const res = await fetch(`/api/llm/models?url=${encodeURIComponent(url)}`);
    const data = await res.json();
    if (data.models && data.models.length > 0) {
      if (badge) {
        badge.textContent = `検出されたモデル: ${data.models.join(', ')}`;
        badge.className = 'text-[11px] text-emerald-400';
      }
      const modelEl = document.getElementById('settingLocalLlmModel');
      if (modelEl) {
        const commercialSafe = data.models.find(m => !/qwen2\.5[\s:_-]*(3b|72b)\b/i.test(m)) || data.models[0];
        modelEl.value = sanitizeCommercialLocalLlmModel(commercialSafe, true);
        scheduleImmediateSettingsSave({ debounceMs: 50 });
      }
    } else {
      if (badge) {
        badge.textContent = 'モデルが見つかりませんでした (手動入力可能)';
        badge.className = 'text-[11px] text-amber-400';
      }
    }
  } catch (e) {
    if (badge) {
      badge.textContent = `取得失敗: ${e.message}`;
      badge.className = 'text-[11px] text-red-400';
    }
  }
}

function buildSettingsPayloadFromModal() {
  const existing = (typeof getSettingsFromStorage === 'function' ? getSettingsFromStorage() : null) || {};
  const sel = document.getElementById('settingGeminiModelSelect');
  const customInput = document.getElementById('settingGeminiModelCustom');
  let geminiModel = existing.gemini_model || 'gemini-3.8-flash';

  if (sel) {
    if (sel.value === '__custom__' && customInput && customInput.value.trim()) {
      geminiModel = customInput.value.trim();
    } else if (sel.value !== '__custom__' && sel.value) {
      geminiModel = sel.value;
    }
  }

  const narouPolicy = getPolicyForProvider('narou');
  const chosenTtsEngine = document.getElementById('settingTtsEngine')?.value || existing.tts_engine || DEFAULT_TTS_ENGINE;
  const rawLocalModel = document.getElementById('settingLocalLlmModel')?.value?.trim() || existing.local_llm_model || 'phi4-mini';
  const sanitizedLocalModel = sanitizeCommercialLocalLlmModel(rawLocalModel, false);
  const localModelInputEl = document.getElementById('settingLocalLlmModel');
  if (localModelInputEl && localModelInputEl.value !== sanitizedLocalModel) {
    localModelInputEl.value = sanitizedLocalModel;
  }

  const scanRaw = document.getElementById('settingScanEpisodesInput')?.value || document.getElementById('settingScanEpisodesSlider')?.value || String(existing.ai_cast_scan_episodes || 10);

  return {
    llm_provider: document.getElementById('settingLlmProvider')?.value || existing.llm_provider || getActiveCastLlmProvider(),
    llm_provider_manually_set: true,
    gemini_api_key: document.getElementById('settingGeminiKey')?.value?.trim() ?? (existing.gemini_api_key || ''),
    gemini_model: geminiModel,
    openai_api_key: document.getElementById('settingOpenaiKey')?.value?.trim() ?? (existing.openai_api_key || ''),
    openai_model: document.getElementById('settingOpenaiModelSelect')?.value || existing.openai_model || 'gpt-4o-mini',
    openai_model_custom: document.getElementById('settingOpenaiModelCustom')?.value?.trim() ?? (existing.openai_model_custom || ''),
    claude_api_key: document.getElementById('settingClaudeKey')?.value?.trim() ?? (existing.claude_api_key || ''),
    claude_model: document.getElementById('settingClaudeModelSelect')?.value || existing.claude_model || 'claude-sonnet-4-5',
    claude_model_custom: document.getElementById('settingClaudeModelCustom')?.value?.trim() ?? (existing.claude_model_custom || ''),
    reasoning_effort: document.getElementById('settingReasoningEffortSelect')?.value || existing.reasoning_effort || 'off',
    local_llm_url: document.getElementById('settingLocalLlmUrl')?.value?.trim() || existing.local_llm_url || 'http://127.0.0.1:11434/v1',
    local_llm_model: sanitizedLocalModel,
    tts_engine: chosenTtsEngine,
    voicevox_mode: isAndroidApp ? 'auto' : (document.getElementById('settingVvMode')?.value || existing.voicevox_mode || 'auto'),
    auto_start_voicevox: true,
    voicevox_engine_path: document.getElementById('settingVvEnginePath')?.value?.trim() ?? (existing.voicevox_engine_path || ''),
    voicevox_url: document.getElementById('settingVvUrl')?.value?.trim() || existing.voicevox_url || 'http://127.0.0.1:50021',
    playback_speed: state.playbackSpeed || 0.8,
    ai_cast_scan_episodes: Math.max(1, Math.min(1000, parseInt(scanRaw, 10) || 10)),
    download_max_bytes_per_batch: narouPolicy.max_bytes_per_batch,
    download_request_interval_sec: narouPolicy.min_interval_sec,
    bluetooth_skip_behavior: document.getElementById('settingBtSkipBehavior')?.value || existing.bluetooth_skip_behavior || 'episode',
    audio_cache_dest: document.getElementById('settingAudioCacheDest')?.value || existing.audio_cache_dest || 'local',
    gdrive_folder: document.getElementById('settingGdriveFolder')?.value?.trim() || existing.gdrive_folder || '小説AI朗読_AudioCache',
    gdrive_token: document.getElementById('settingGdriveToken')?.value?.trim() ?? (existing.gdrive_token || ''),
    auto_generate_audio: document.getElementById('settingAutoGenerateAudio')?.checked ?? (existing.auto_generate_audio !== false),
    allow_gdrive_on_mobile: document.getElementById('settingAllowGdriveOnMobile')?.checked === true,
  };
}

function persistSettingsPayloadToLocalImmediately(payload) {
  if (!payload) return;
  const chosenTtsEngine = payload.tts_engine || DEFAULT_TTS_ENGINE;

  try {
    localStorage.setItem('narou_tts_engine', chosenTtsEngine);
    if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.setVoicevoxEnabled === 'function') {
      window.AndroidBridge.setVoicevoxEnabled(chosenTtsEngine === 'voicevox' || chosenTtsEngine === 'hybrid_mix');
    }

    localStorage.setItem('narou_ai_cast_scan_episodes', String(payload.ai_cast_scan_episodes));
    localStorage.setItem('narou_bt_skip_behavior', payload.bluetooth_skip_behavior);
    localStorage.setItem('narou_audio_cache_dest', payload.audio_cache_dest);
    localStorage.setItem('narou_gdrive_folder', payload.gdrive_folder);
    localStorage.setItem('narou_gdrive_token', payload.gdrive_token);
    localStorage.setItem('narou_auto_generate_audio', String(payload.auto_generate_audio));
    localStorage.setItem('narou_allow_gdrive_on_mobile', String(payload.allow_gdrive_on_mobile));

    const carModeEl = document.getElementById('settingCarModeAutoStart');
    if (carModeEl) {
      localStorage.setItem('narou_car_mode_auto_start', String(!!carModeEl.checked));
    }

    localStorage.setItem('narou_reader_settings', JSON.stringify(payload));
    localStorage.setItem('narou_app_settings', JSON.stringify(payload));
    localStorage.setItem('narou_llm_provider', payload.llm_provider);
    localStorage.setItem('narou_ai_provider', payload.llm_provider);
    localStorage.setItem('narou_gemini_key', payload.gemini_api_key || '');
    localStorage.setItem('narou_openai_key', payload.openai_api_key || '');
    localStorage.setItem('narou_claude_key', payload.claude_api_key || '');
  } catch (e) {
    console.warn('[SettingsAutoSave] LocalStorage write warning:', e);
  }

  // メモリ上の設定ステートとUIバッジも即座に反映
  if (!state.systemInfo) state.systemInfo = {};
  state.systemInfo.settings = { ...(state.systemInfo.settings || {}), ...payload };
  if (typeof updateLlmBadge === 'function') {
    updateLlmBadge(payload.llm_provider);
  }
  if (typeof refreshSwitchStateIndicators === 'function') {
    refreshSwitchStateIndicators();
  }
  if (typeof BackgroundAudioCacheOrchestrator !== 'undefined') {
    if (payload.auto_generate_audio) {
      BackgroundAudioCacheOrchestrator.schedule('settings_auto_save', 1200);
    } else {
      BackgroundAudioCacheOrchestrator.pause('auto_gen_disabled_in_settings');
    }
  }
}

function scheduleImmediateSettingsSave(options = {}) {
  if (_isPopulatingSettingsModal) return;
  const debounceMs = typeof options.debounceMs === 'number' ? options.debounceMs : 120;

  // 1. ローカルストレージとメモリステートへは0msで即時同期反映（モーダルを閉じても絶対失われない）
  const payload = buildSettingsPayloadFromModal();
  persistSettingsPayloadToLocalImmediately(payload);
  setSettingsAutoSaveBadgeState('saving');

  // 2. バックエンドAPI同期をデバウンス実行
  if (_settingsAutoSaveTimer) {
    clearTimeout(_settingsAutoSaveTimer);
  }
  _settingsAutoSaveTimer = setTimeout(() => {
    _settingsAutoSaveTimer = null;
    applyAndPersistSettingsImmediately({ silent: true, closeModal: false });
  }, debounceMs);
}

async function applyAndPersistSettingsImmediately(options = {}) {
  const silent = options.silent !== false;
  const shouldClose = options.closeModal === true;
  const payload = buildSettingsPayloadFromModal();
  persistSettingsPayloadToLocalImmediately(payload);

  try {
    await apiFetch('/api/settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    setSettingsAutoSaveBadgeState('saved');
    if (!silent) {
      showToast('設定を自動保存しました', 'success');
    }
    if (shouldClose) {
      closeSettingsModal();
    }
    await loadSystemInfo();
    await loadVoices();
  } catch (e) {
    setSettingsAutoSaveBadgeState('saved');
    if (!silent) {
      showToast('設定を端末に保存しました', 'info');
    }
  }
}

async function saveSettingsFromModal(options = {}) {
  await applyAndPersistSettingsImmediately({
    silent: options.silent ?? false,
    closeModal: options.closeModal === true
  });
}

// ==============================================
// 11. Android ADB 配備 & QR モーダル
// ==============================================
function openQRModal() {
  vibrateFeedback(10);
  closeSettingsModal();
  const qrModal = document.getElementById('qrModal');
  if (qrModal) qrModal.classList.remove('hidden');
  const qrImg = document.getElementById('qrCodeImg');
  if (qrImg) qrImg.src = `/api/system/ios-qr?t=${Date.now()}`;
  checkAdbStatus();
}

function closeQRModal() {
  vibrateFeedback(6);
  const qrModal = document.getElementById('qrModal');
  if (qrModal) qrModal.classList.add('hidden');
}

async function checkAdbStatus() {
  const container = document.getElementById('adbStatusContent');
  if (!container) return;

  container.innerHTML = '<p class="text-[11px] text-slate-400"><i class="ph ph-spinner animate-spin"></i> 接続端末を検出中...</p>';

  try {
    const res = await fetch('/api/adb/status');
    const data = await res.json();

    if (data.ios_installer_url) {
      const lanUrlEl = document.getElementById('lanUrlText');
      if (lanUrlEl) lanUrlEl.textContent = data.ios_installer_url;
    }

    const androidDevices = Array.isArray(data.devices) ? data.devices : [];
    const iosDevices = Array.isArray(data.ios_devices) ? data.ios_devices : [];

    if (androidDevices.length === 0 && iosDevices.length === 0) {
      container.innerHTML = `
        <div class="text-[11px] text-slate-400 space-y-1">
          <p class="text-slate-300 font-medium">現在USB接続されている端末はありません。</p>
          <p class="text-[10px]">※iPhone SEはカメラで下のQRコードを読み取るか、SafariでURLを開いてインストールできます。</p>
        </div>
      `;
      return;
    }

    let devHtml = '<div class="space-y-2">';
    iosDevices.forEach(iosDev => {
      const instUrl = data.ios_installer_url || '/ios';
      devHtml += `
        <div class="flex items-center justify-between p-2.5 rounded-lg bg-slate-900 border border-emerald-500/40">
          <div class="text-left pr-2">
            <div class="flex items-center space-x-1.5">
              <span class="w-2 h-2 rounded-full bg-emerald-400"></span>
              <span class="font-bold text-emerald-300 text-xs">🍎 ${escapeHtml(iosDev.model)}</span>
            </div>
            <p class="text-[10px] text-slate-300 mt-0.5">${escapeHtml(iosDev.status_text)}</p>
          </div>
          <a href="${escapeHtml(instUrl)}" target="_blank" class="shrink-0 px-3 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg text-xs font-bold shadow flex items-center space-x-1 transition">
            <i class="ph-bold ph-device-mobile"></i>
            <span>iOS導入案内</span>
          </a>
        </div>
      `;
    });
    androidDevices.forEach(dev => {
      devHtml += `
        <div class="flex items-center justify-between p-2 rounded-lg bg-slate-900 border border-slate-800">
          <div class="text-left">
            <div class="flex items-center space-x-1.5">
              <span class="w-2 h-2 rounded-full ${dev.is_ready ? 'bg-emerald-400' : 'bg-amber-400'}"></span>
              <span class="font-bold text-slate-200 text-xs">${escapeHtml(dev.model)}</span>
            </div>
            <p class="text-[10px] text-slate-400 mt-0.5">${escapeHtml(dev.status_text)}</p>
          </div>
          ${dev.is_ready ? `
            <button onclick="deployViaAdb('${dev.serial}')" class="px-3 py-1 bg-blue-600 hover:bg-blue-500 text-white rounded-lg text-xs font-semibold shadow flex items-center space-x-1 transition">
              <i class="ph-bold ph-paper-plane-tilt"></i>
              <span>転送・起動</span>
            </button>
          ` : `
            <button onclick="checkAdbStatus()" class="px-2.5 py-1 bg-slate-800 text-slate-400 rounded-lg text-[10px]">
              許可待ち
            </button>
          `}
        </div>
      `;
    });
    devHtml += '</div>';
    container.innerHTML = devHtml;

  } catch (e) {
    container.innerHTML = `<p class="text-[11px] text-red-400">ADB状態の取得エラー: ${e.message}</p>`;
  }
}

async function deployViaAdb(serial) {
  vibrateFeedback();
  const container = document.getElementById('adbStatusContent');
  if (container) {
    container.innerHTML = '<p class="text-xs text-blue-300"><i class="ph ph-spinner animate-spin"></i> Android端末へ配備・ブラウザ起動中...</p>';
  }

  try {
    const res = await fetch('/api/adb/deploy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ serial: serial })
    });
    const data = await res.json();
    if (data.success) {
      alert(data.message);
      closeQRModal();
    } else {
      alert('配備失敗: ' + (data.error || '不明なエラー'));
      await checkAdbStatus();
    }
  } catch (e) {
    alert('配備エラー: ' + e.message);
    await checkAdbStatus();
  }
}

// ==============================================
// 12. ナビゲーション タブ切り替え & ボトムナビ連動
// ==============================================
function switchTab(tabName, pushHistory = true) {
  if (tabName === 'settings') {
    openSettingsModal();
    return;
  }
  vibrateFeedback(8);
  const prevTab = state.currentTab;
  state.currentTab = tabName;

  if (pushHistory && window.tabHistory[window.tabHistory.length - 1] !== tabName) {
    window.tabHistory.push(tabName);
    if (window.tabHistory.length > 20) window.tabHistory.shift();
  }

  const tabs = ['search', 'toc', 'player', 'cast', 'downloads'];
  tabs.forEach(t => {
    const el = document.getElementById(`tab-${t}`);
    const navBtn = document.querySelector(`#bottomNavBar #tabBtn-${t}`);

    if (t === tabName) {
      if (el) el.classList.remove('hidden');
      if (navBtn) {
        navBtn.classList.add('active');
        navBtn.classList.remove('text-slate-400', 'text-blue-400');
      }
    } else {
      if (el) el.classList.add('hidden');
      if (navBtn) {
        navBtn.classList.remove('active', 'text-blue-400');
      }
    }
  });


  // プレイヤーバーとミニプレイヤーの出し分け（朗読タブでは上部ペインに操作が集約されるため二重表示を完全防止）
  const fullPlayer = document.getElementById('floatingPlayerBar');
  const miniPlayer = document.getElementById('miniPlayerBar');

  if (tabName === 'player') {
    // 朗読タブ表示時は上部ペインのコントロールを使用するため、下部のフローティングバーは完全隠蔽
    if (fullPlayer) fullPlayer.classList.add('hidden');
    if (miniPlayer) miniPlayer.classList.add('hidden');
    if (typeof syncBgAudioWidgetPosition === 'function') syncBgAudioWidgetPosition();
    updatePlayerStatusUI();
    updatePlayButtonUI(state.isPlaying);
    if (!state.currentSegments || state.currentSegments.length === 0) {
      renderSegments();
    }
  } else {
    // 朗読以外のタブ（検索・目次・保存済）表示時: 小説データがあればミニプレイヤーをドッキング常駐
    if (fullPlayer) fullPlayer.classList.add('hidden');
    if (state.currentNovel && state.currentSegments && state.currentSegments.length > 0) {
      if (miniPlayer) miniPlayer.classList.remove('hidden');
      updateMiniPlayer();
    } else {
      if (miniPlayer) miniPlayer.classList.add('hidden');
    }
    if (typeof syncBgAudioWidgetPosition === 'function') syncBgAudioWidgetPosition();
  }

  // 保存済タブ用ウィジェット（Heroカード・読書統計）の更新
  if (tabName === 'downloads') {
    updateHeroResumeCard();
    updateUserStatsUI();
  }

  // バックグラウンド再生バッジ・広告ステータス更新
  if (typeof updateBgPlaybackUI === 'function') {
    updateBgPlaybackUI();
  }

  // 配役タブ表示時は配役エディタを確実に最新描画
  if (tabName === 'cast') {
    if (typeof renderCastEditor === 'function') {
      renderCastEditor();
    }
  }

  if (tabName === 'downloads') {
    const widget = document.getElementById('bgAudioProgressWidget');
    if (widget) widget.classList.add('hidden');
    loadDownloadsData();
  }

  // 朗読中/タブに応じたAdMobバナー表示制御（朗読タブでは非表示、検索・保存タブでは安全表示）
  if (typeof updateAdMobBannerVisibility === 'function') {
    updateAdMobBannerVisibility(tabName === 'player');
  }

  // デスクトップデュアルペインの更新
  if (tabName === 'player' && typeof renderDesktopSidePane === 'function') {
    renderDesktopSidePane();
  }

  if (tabName !== 'player') {
    resetPlayerCompactUI();
  }

  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// =============================================================================
// 12-B. 📖 朗読タブ: スクロール連動型ミニマル再生バー制御
// ユーザー要望: スクロール時は再生・ストップボタンのみ残して他を消し、
//               一番上に戻ったらフル表示に復帰
// =============================================================================
let _isPlayerCompact = false;
let _playerScrollRaf = null;
let _suppressCompactUntil = 0;

function handlePlayerScrollCompact() {
  if (state.currentTab !== 'player') return;
  if (Date.now() < _suppressCompactUntil) return;
  // ユーザーが本文をタッチしてスライド操作中の最中は、コンテナ高さ・位置のジャンプを防ぐため touchend まで待機
  if (_isUserTouchingReader) return;

  if (_playerScrollRaf) return;
  _playerScrollRaf = requestAnimationFrame(() => {
    _playerScrollRaf = null;
    if (Date.now() < _suppressCompactUntil) return;
    if (_isUserTouchingReader) return;

    const middlePane = document.getElementById('playerMiddlePane');
    const windowScroll = window.scrollY || document.documentElement.scrollTop || 0;
    const paneScroll = middlePane ? middlePane.scrollTop : 0;

    // スクロール量が 50px を超えたらコンパクト化、20px 以下に戻ったらフル復帰
    const shouldCompact = _isPlayerCompact
      ? (windowScroll > 20 || paneScroll > 20)
      : (windowScroll > 50 || paneScroll > 50);

    if (shouldCompact !== _isPlayerCompact) {
      _isPlayerCompact = shouldCompact;
      const playerTab = document.getElementById('tab-player');
      if (playerTab) {
        if (shouldCompact) {
          playerTab.classList.add('is-player-compact');
          document.body.classList.add('player-compact-active');
        } else {
          playerTab.classList.remove('is-player-compact');
          document.body.classList.remove('player-compact-active');
        }
      }
    }
  });
}

function resetPlayerCompactUI() {
  _isPlayerCompact = false;
  const playerTab = document.getElementById('tab-player');
  if (playerTab) {
    playerTab.classList.remove('is-player-compact');
  }
  document.body.classList.remove('player-compact-active');
}

function scrollPlayerToTop(e) {
  if (e) {
    e.preventDefault();
    e.stopPropagation();
  }
  vibrateFeedback(6);
  _suppressCompactUntil = Date.now() + 800; // スクロール完了まで再コンパクト化を抑制
  resetPlayerCompactUI();

  window.scrollTo({ top: 0, behavior: 'smooth' });
  const middlePane = document.getElementById('playerMiddlePane');
  if (middlePane) {
    middlePane.scrollTo({ top: 0, behavior: 'smooth' });
  }
}

function initPlayerScrollCompactListener() {
  window.addEventListener('scroll', handlePlayerScrollCompact, { passive: true });
  const middlePane = document.getElementById('playerMiddlePane');
  if (middlePane) {
    middlePane.addEventListener('scroll', handlePlayerScrollCompact, { passive: true });
  }
}
window.scrollPlayerToTop = scrollPlayerToTop;
window.handlePlayerScrollCompact = handlePlayerScrollCompact;
window.resetPlayerCompactUI = resetPlayerCompactUI;
window.initPlayerScrollCompactListener = initPlayerScrollCompactListener;

// ミニプレイヤーのタップ時: 朗読タブへ展開
function onMiniPlayerClick(event) {
  vibrateFeedback(12);
  switchTab('player');
}

// ミニプレイヤーの表示内容リアルタイム同期
function updateMiniPlayer() {
  const miniPlayer = document.getElementById('miniPlayerBar');
  if (!miniPlayer || !state.currentNovel) return;

  const novelInfoEl = document.getElementById('miniPlayerNovelInfo');
  const previewTextEl = document.getElementById('miniTextPreview') || document.getElementById('miniPlayerCurrentText');
  const speakerBadgeEl = document.getElementById('miniSpeakerBadge') || document.getElementById('miniPlayerSpeakerBadge');
  const progressFill = document.getElementById('miniProgressBarFill');
  const playIcon = document.getElementById('miniPlayPauseIcon');
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = uiLang === 'ja';

  if (novelInfoEl) {
    const locWork = typeof getLocalizedAozoraWork === 'function'
      ? getLocalizedAozoraWork(state.currentNovel, uiLang)
      : null;
    const dispTitle = locWork?.displayTitle || state.currentNovel.title || '';
    const epPart = isJa ? `第${state.currentEpisodeNum}話` : `Ep. ${state.currentEpisodeNum}`;
    novelInfoEl.textContent = `${dispTitle} (${epPart})`;
  }

  const currentSeg = state.currentSegments[state.currentSegmentIndex];
  if (currentSeg) {
    const hasTrans = !!(state.currentTranslatedLang && currentSeg.translated_text && (!currentSeg.translated_lang || currentSeg.translated_lang === state.currentTranslatedLang));
    const readingFallback = isJa ? '朗読中...' : ({ en: 'Reading...', zh: '朗读中...', ko: '낭독 중...', es: 'Leyendo...', fr: 'Lecture...', pt: 'Lendo...' }[uiLang] || 'Reading...');
    const segText = hasTrans
      ? currentSeg.translated_text
      : (currentSeg.display_text || readingFallback);
    if (previewTextEl) previewTextEl.textContent = segText;
    if (speakerBadgeEl) {
      const rawSp = currentSeg.speaker || 'ナレーション';
      let spLabel = rawSp;
      if (hasTrans && currentSeg.translated_speaker) {
        spLabel = currentSeg.translated_speaker;
      } else if (!isJa && typeof translateSpeakerOnDevice === 'function') {
        spLabel = translateSpeakerOnDevice(rawSp, uiLang);
      } else if (rawSp === '地の文' || rawSp === 'ナレーション') {
        spLabel = typeof tUi === 'function' ? tUi('cast_narration_label') : 'ナレ';
      }
      speakerBadgeEl.textContent = isJa ? spLabel.slice(0, 3) : spLabel.slice(0, 6);
    }
  }

  if (progressFill && state.currentSegments.length > 0) {
    const pct = ((state.currentSegmentIndex + 1) / state.currentSegments.length) * 100;
    progressFill.style.width = `${pct}%`;
  }

  if (playIcon) {
    playIcon.className = state.isPlaying ? 'ph-fill ph-pause text-lg ml-0.5' : 'ph-fill ph-play text-lg ml-0.5';
  }
}

