function selectSearchSite(siteKey) {
  if (siteKey !== 'document' && siteKey !== 'aozora') {
    siteKey = 'aozora';
  }
  state.selectedSearchSite = siteKey;
  vibrateFeedback(10);

  const aozoraBtn = document.getElementById('siteTab-aozora');
  const docBtn = document.getElementById('siteTab-document');
  const aozoraSection = document.getElementById('aozoraSearchSection');
  const docSection = document.getElementById('documentImportSection');
  const noticeEl = document.getElementById('siteBadgeNotice');

  if (siteKey === 'document') {
    if (docBtn) {
      docBtn.classList.add('active');
      docBtn.className = 'site-tab-btn active py-2.5 px-3 rounded-xl font-bold bg-blue-600 text-white shadow-md shadow-blue-600/30 border border-blue-500 transition flex items-center justify-center space-x-2';
    }
    if (aozoraBtn) {
      aozoraBtn.classList.remove('active');
      aozoraBtn.className = 'site-tab-btn py-2.5 px-3 rounded-xl font-medium bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 transition flex items-center justify-center space-x-2';
    }
    if (aozoraSection) aozoraSection.classList.add('hidden');
    if (docSection) docSection.classList.remove('hidden');
    if (noticeEl) {
      noticeEl.textContent = getLocalizedSiteBadgeText('document');
      noticeEl.className = 'text-[10px] text-blue-400 font-medium';
    }
  } else {
    // aozora
    if (aozoraBtn) {
      aozoraBtn.classList.add('active');
      aozoraBtn.className = 'site-tab-btn active py-2.5 px-3 rounded-xl font-bold bg-emerald-600 text-white shadow-md shadow-emerald-600/30 border border-emerald-500 transition flex items-center justify-center space-x-2';
    }
    if (docBtn) {
      docBtn.classList.remove('active');
      docBtn.className = 'site-tab-btn py-2.5 px-3 rounded-xl font-medium bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 transition flex items-center justify-center space-x-2';
    }
    if (aozoraSection) aozoraSection.classList.remove('hidden');
    if (docSection) docSection.classList.add('hidden');
    if (noticeEl) {
      noticeEl.textContent = typeof tUi === 'function' ? tUi('aozora_badge_notice') : getLocalizedSiteBadgeText('aozora');
      noticeEl.className = 'text-[10px] text-emerald-400 font-medium';
    }
    renderAozoraCatalog(currentAozoraAuthorFilter);
  }
}

// =============================================================================
// 文書流し込み（PDF・テキストファイル・直接入力）制御
// =============================================================================
function onDocumentDragOver(event) {
  event.preventDefault();
  event.stopPropagation();
  const dropZone = document.getElementById('documentDropZone');
  if (dropZone) dropZone.classList.add('border-blue-400', 'bg-blue-950/30');
}

function onDocumentDragLeave(event) {
  event.preventDefault();
  event.stopPropagation();
  const dropZone = document.getElementById('documentDropZone');
  if (dropZone) dropZone.classList.remove('border-blue-400', 'bg-blue-950/30');
}

function triggerDocumentPicker() {
  if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.pickDocumentFile === 'function') {
    window.AndroidBridge.pickDocumentFile();
  } else {
    const input = document.getElementById('documentFileInput');
    if (input) input.click();
  }
}

// Androidネイティブ (Googleドライブ / スマホローカル) からファイルが渡されたときのコールバック
window.onNativeDocumentSelected = async function(fileName, fileType, content, uri) {
  try {
    const loadingEl = document.getElementById('documentImportLoading');
    const loadingText = document.getElementById('documentImportLoadingText');
    if (loadingEl) loadingEl.classList.remove('hidden');
    if (loadingText) loadingText.textContent = `「${fileName}」を読み込み中...`;

    if (fileType === 'pdf' || fileType === 'doc' || fileType === 'docx') {
      // PDFまたはWordバイナリの場合: Base64データをBlob化して処理
      let base64Data = content;
      if (base64Data.startsWith('base64:')) {
        base64Data = base64Data.substring(7);
      }
      const byteChars = atob(base64Data);
      const byteNumbers = new Array(byteChars.length);
      for (let i = 0; i < byteChars.length; i++) {
        byteNumbers[i] = byteChars.charCodeAt(i);
      }
      const byteArray = new Uint8Array(byteNumbers);
      const mime = fileType === 'pdf' ? 'application/pdf' :
                   fileType === 'docx' ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' :
                   'application/msword';
      const file = new File([byteArray], fileName, { type: mime });
      await submitDocumentFileUpload(file);
    } else {
      // テキスト / Markdown の場合
      const title = fileName.replace(/\.[^/.]+$/, "");
      await processAndImportDocumentText(title, '私的文書', content, 'auto');
    }
  } catch (err) {
    console.error('[DocImport] onNativeDocumentSelected failed:', err);
    showToast(`ファイル読み込みエラー: ${err.message}`, 'error');
  } finally {
    const loadingEl = document.getElementById('documentImportLoading');
    if (loadingEl) loadingEl.classList.add('hidden');
  }
};

function onDocumentDrop(event) {
  event.preventDefault();
  event.stopPropagation();
  const dropZone = document.getElementById('documentDropZone');
  if (dropZone) dropZone.classList.remove('border-blue-400', 'bg-blue-950/30');

  const files = event.dataTransfer ? event.dataTransfer.files : null;
  if (files && files.length > 0) {
    submitDocumentFileUpload(files[0]);
  }
}

function onDocumentFileSelected(event) {
  const file = event.target.files && event.target.files[0];
  if (file) {
    submitDocumentFileUpload(file);
  }
  // リセットして同じファイルの再選択を可能にする
  event.target.value = '';
}

// クライアント側でテキストを章・話に分割
function splitTextIntoEpisodesLocally(fullText, splitMode = 'auto') {
  if (splitMode === 'single' || !fullText.trim()) {
    return [{
      episode_number: 1,
      title: '本文',
      body: fullText.trim()
    }];
  }

  // 一般的な章・話パターン: 「第X章」「第X話」「第X節」「Chapter X」「【X】」
  const chapterPattern = /(?:\r?\n){1,3}(?=(?:第[0-9〇一二三四五六七八九十百千万]+[章話節編部][^\n]{0,30}|Chapter\s+[0-9]+[^\n]{0,30}|【[^\n]{1,20}】|[0-9]{1,3}\s+[^\n]{2,30}))/i;
  const chunks = fullText.split(chapterPattern).map(c => c.trim()).filter(c => c.length > 0);

  if (chunks.length >= 2) {
    return chunks.map((chunk, idx) => {
      const lines = chunk.split('\n', 1);
      const title = (lines[0] || '').trim().slice(0, 40) || `第${idx + 1}章`;
      return {
        episode_number: idx + 1,
        title,
        body: chunk
      };
    });
  }

  // 見出しがない場合: 3000文字目安で分割
  if (fullText.length > 4000) {
    const paragraphs = fullText.split(/\r?\n\r?\n/);
    const episodes = [];
    let currentBody = [];
    let currentLen = 0;
    let epNum = 1;

    for (const p of paragraphs) {
      currentBody.push(p);
      currentLen += p.length;
      if (currentLen >= 3000) {
        const body = currentBody.join('\n\n').trim();
        episodes.push({
          episode_number: epNum,
          title: `第${epNum}部`,
          body
        });
        currentBody = [];
        currentLen = 0;
        epNum++;
      }
    }
    if (currentBody.length > 0) {
      const body = currentBody.join('\n\n').trim();
      if (body) {
        episodes.push({
          episode_number: epNum,
          title: `第${epNum}部`,
          body
        });
      }
    }
    return episodes;
  }

  return [{
    episode_number: 1,
    title: '本文',
    body: fullText.trim()
  }];
}

// 文書データをアプリ内（IndexedDB / state）へインポートして目次を開く
async function processAndImportDocumentText(title, author, text, splitMode = 'auto', usedOcr = false) {
  const hash = Math.abs(Array.from(title + text.slice(0, 500)).reduce((acc, char) => (acc << 5) - acc + char.charCodeAt(0), 0)).toString(36);
  const docId = `doc_${hash}_${Date.now().toString(36)}`;

  const episodes = splitTextIntoEpisodesLocally(text, splitMode);
  const totalEps = episodes.length;

  const novelData = {
    ncode: docId,
    title: title || '無題の文書',
    author: author || '私的文書',
    synopsis: text.slice(0, 200) + (text.length > 200 ? '...' : ''),
    total_episodes: totalEps,
    site: 'local_doc',
    is_downloaded: true,
    downloaded_episodes: totalEps,
    saved_at: Date.now(),
    used_ocr: usedOcr,
    episodes: episodes.map(ep => ({
      episode_number: ep.episode_number,
      title: ep.title,
      posted_at: new Date().toISOString()
    }))
  };

  // IndexedDBに小説メタデータと各エピソードの本文を保存
  if (typeof NarouIDB !== 'undefined' && NarouIDB.saveNovel) {
    await NarouIDB.saveNovel(novelData, true);
    for (const ep of episodes) {
      // 高精度セグメント分割（行内引用・長文分割・ルビ保護に対応）
      const parsedSegments = splitNovelTextToSegments(ep.body);
      const segments = parsedSegments.map((seg, idx) => ({
        ...seg,
        segment_id: `${docId}_${ep.episode_number}_${idx + 1}`,
        text: seg.display_text,
        reading_text: seg.tts_text || seg.display_text,
        voice: '標準'
      }));
      await NarouIDB.saveEpisode(docId, ep.episode_number, {
        episode_number: ep.episode_number,
        title: ep.title,
        body: ep.body,
        segments
      });
    }
  }

  const ocrSuffix = usedOcr ? '（✨AI OCR文書化）' : '';
  showToast(`『${novelData.title}』をインポートしました${ocrSuffix}（全${totalEps}話）`, 'success');

  // 目次表示
  displayNovelTOC(novelData);
  switchTab('toc');
}

// PDF ArrayBufferからテキストを抽出する高精度パーサー (DecompressionStream + Tj/TJパース)
async function extractTextFromPdfArrayBuffer(arrayBuffer) {
  const uint8 = new Uint8Array(arrayBuffer);
  const extractedTexts = [];

  function findSubarray(source, sub, startPos = 0) {
    for (let i = startPos; i <= source.length - sub.length; i++) {
      let match = true;
      for (let j = 0; j < sub.length; j++) {
        if (source[i + j] !== sub[j]) { match = false; break; }
      }
      if (match) return i;
    }
    return -1;
  }

  // 1. ストリーム境界 (stream ... endstream) を探索して FlateDecode 解凍
  const streamKw = [115, 116, 114, 101, 97, 109]; // 'stream'
  const endKw = [101, 110, 100, 115, 116, 114, 101, 97, 109]; // 'endstream'

  let pos = 0;
  while (pos < uint8.length) {
    const sStart = findSubarray(uint8, streamKw, pos);
    if (sStart === -1) break;

    let dataStart = sStart + 6;
    if (uint8[dataStart] === 13) dataStart++;
    if (uint8[dataStart] === 10) dataStart++;

    const sEnd = findSubarray(uint8, endKw, dataStart);
    if (sEnd === -1) break;

    let streamEnd = sEnd;
    while (streamEnd > dataStart && (uint8[streamEnd - 1] === 10 || uint8[streamEnd - 1] === 13 || uint8[streamEnd - 1] === 32)) {
      streamEnd--;
    }

    const streamSlice = uint8.slice(dataStart, streamEnd);
    pos = sEnd + 9;

    let decompText = '';
    try {
      if (typeof DecompressionStream !== 'undefined') {
        const ds = new DecompressionStream('deflate');
        const writer = ds.writable.getWriter();
        writer.write(streamSlice);
        writer.close();
        const resp = new Response(ds.readable);
        decompText = await resp.text();
      }
    } catch (e) {
      try {
        decompText = new TextDecoder('utf-8', { fatal: false }).decode(streamSlice);
      } catch (e2) {}
    }

    if (decompText) {
      // (テキスト) Tj
      const tjMatches = decompText.match(/\(([^()]*)\)\s*Tj/g) || [];
      tjMatches.forEach(m => {
        const t = m.replace(/^[\(]/, '').replace(/\)\s*Tj$/, '').trim();
        if (t.length > 0) extractedTexts.push(t);
      });

      // 16進表現 <hex> Tj (日本語PDFで非常に一般的)
      const hexTjMatches = decompText.match(/<([0-9a-fA-F]+)>\s*Tj/g) || [];
      hexTjMatches.forEach(m => {
        const hex = m.replace(/<|>|\s*Tj/g, '');
        const dec = decodePdfHexString(hex);
        if (dec && dec.trim()) extractedTexts.push(dec.trim());
      });

      // [(テ)(キ)(ス)(ト)] または [<hex>] TJ
      const tjArrMatches = decompText.match(/\[(.*?)\]\s*TJ/g) || [];
      tjArrMatches.forEach(m => {
        const inner = m.replace(/^\[/, '').replace(/\]\s*TJ$/, '');
        // 16進チャンク <hex>
        const hexPieces = inner.match(/<([0-9a-fA-F]+)>/g) || [];
        if (hexPieces.length > 0) {
          const combinedHex = hexPieces.map(h => h.replace(/<|>/g, '')).join('');
          const dec = decodePdfHexString(combinedHex);
          if (dec && dec.trim()) extractedTexts.push(dec.trim());
        }
        // 文字列チャンク (text)
        const strPieces = inner.match(/\(([^()]*)\)/g) || [];
        if (strPieces.length > 0) {
          const combinedStr = strPieces.map(p => p.slice(1, -1)).join('');
          if (combinedStr && combinedStr.trim().length > 0) extractedTexts.push(combinedStr.trim());
        }
      });
    }
  }

  // 2. 平文フォールバック (圧縮されていないストリームや直接テキスト)
  if (extractedTexts.length === 0) {
    const rawString = new TextDecoder('utf-8', { fatal: false }).decode(uint8);
    const plainMatches = rawString.match(/\(([^()]{2,})\)[\s]*Tj/g) || rawString.match(/\[([^\[\]]{2,})\][\s]*TJ/g) || [];
    plainMatches.forEach(m => {
      const clean = m.replace(/^[\(\[]/, '').replace(/[\)\]].*$/, '').trim();
      if (clean) extractedTexts.push(clean);
    });

    // 16進は Tj / TJ に付随するもののみを抽出（/ID 等のメタデータ誤認を防止）
    const hexPlainMatches = rawString.match(/<([0-9a-fA-F]{4,})>\s*Tj/g) || [];
    hexPlainMatches.forEach(m => {
      const hex = m.replace(/<|>|\s*Tj/g, '');
      const dec = decodePdfHexString(hex);
      if (dec && dec.trim() && dec.length > 1) extractedTexts.push(dec.trim());
    });
  }

  return extractedTexts.join('\n');
}

// PDFの16進数文字列をUTF-16BE / UTF-8 / Shift_JISデコードするヘルパー
function decodePdfHexString(hex) {
  if (!hex || hex.length < 2) return '';
  const cleanHex = (hex.length % 2 !== 0) ? hex + '0' : hex;
  const bytes = new Uint8Array(cleanHex.length / 2);
  for (let i = 0; i < cleanHex.length; i += 2) {
    bytes[i / 2] = parseInt(cleanHex.substr(i, 2), 16);
  }
  // 1. UTF-16BE 試行
  try {
    const text16 = new TextDecoder('utf-16be', { fatal: false }).decode(bytes);
    if (text16 && text16.length > 0 && !/^[\x00-\x08\x0e-\x1f]+$/.test(text16)) {
      return text16;
    }
  } catch (e) {}
  // 2. UTF-8 試行 (厳格判定)
  try {
    const text8 = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    if (text8 && text8.length > 0) return text8;
  } catch (e) {}
  // 3. Shift_JIS 試行 (古い日本語PDF向け)
  try {
    const textSjis = new TextDecoder('shift_jis', { fatal: true }).decode(bytes);
    if (textSjis && textSjis.length > 0) return textSjis;
  } catch (e) {}
  return '';
}

// ファイルオブジェクトからUTF-8 / Shift_JIS / EUC-JP / UTF-16を厳格に自動判別・デコードする関数
async function readFileAsTextSmart(file) {
  const arrayBuffer = await file.arrayBuffer();
  // 1. UTF-8 (厳格判定: 不正なバイト列がある場合は fatal: true で例外をスロー)
  try {
    const utf8Decoder = new TextDecoder('utf-8', { fatal: true });
    return utf8Decoder.decode(arrayBuffer);
  } catch (e) {}

  // 2. Shift_JIS / CP932 (Windowsのメモ帳や青空文庫のテキストなど)
  try {
    const sjisDecoder = new TextDecoder('shift_jis', { fatal: true });
    return sjisDecoder.decode(arrayBuffer);
  } catch (e) {}

  // 3. EUC-JP
  try {
    const eucDecoder = new TextDecoder('euc-jp', { fatal: true });
    return eucDecoder.decode(arrayBuffer);
  } catch (e) {}

  // 4. UTF-16LE (BOMまたはWindowsメモ帳のUnicode)
  try {
    const u16Decoder = new TextDecoder('utf-16le', { fatal: true });
    return u16Decoder.decode(arrayBuffer);
  } catch (e) {}

  // 5. 最終フォールバック
  return new TextDecoder('utf-8').decode(arrayBuffer);
}

// DOCX (.docx) ArrayBufferからテキストを抽出するクライアント側パーサー (ZIP内のword/document.xmlを抽出)
async function extractTextFromDocxArrayBuffer(arrayBuffer) {
  const uint8 = new Uint8Array(arrayBuffer);
  
  // 1. DecompressionStream('deflate-raw') を用いたZIPエントリ探索
  try {
    let pos = 0;
    while (pos < uint8.length - 30) {
      // PK\x03\x04 シグネチャ
      if (uint8[pos] === 0x50 && uint8[pos + 1] === 0x4B && uint8[pos + 2] === 0x03 && uint8[pos + 3] === 0x04) {
        const compMethod = uint8[pos + 8] | (uint8[pos + 9] << 8);
        const compSize = uint8[pos + 18] | (uint8[pos + 19] << 8) | (uint8[pos + 20] << 16) | (uint8[pos + 21] << 24);
        const fnLen = uint8[pos + 26] | (uint8[pos + 27] << 8);
        const extraLen = uint8[pos + 28] | (uint8[pos + 29] << 8);

        const fnBytes = uint8.slice(pos + 30, pos + 30 + fnLen);
        const fileName = new TextDecoder('utf-8').decode(fnBytes);

        const dataStart = pos + 30 + fnLen + extraLen;
        if (fileName === 'word/document.xml') {
          const compData = uint8.slice(dataStart, dataStart + compSize);
          let xmlText = '';
          if (compMethod === 8 && typeof DecompressionStream !== 'undefined') {
            try {
              const ds = new DecompressionStream('deflate-raw');
              const writer = ds.writable.getWriter();
              writer.write(compData);
              writer.close();
              xmlText = await new Response(ds.readable).text();
            } catch (deErr) {
              // zlibラッパー試行
              try {
                const ds2 = new DecompressionStream('deflate');
                const writer2 = ds2.writable.getWriter();
                writer2.write(compData);
                writer2.close();
                xmlText = await new Response(ds2.readable).text();
              } catch (e2) {}
            }
          } else if (compMethod === 0) {
            xmlText = new TextDecoder('utf-8').decode(compData);
          }

          if (xmlText) {
            // XMLから <w:p>段落と <w:t>テキストを抽出
            const paragraphs = [];
            const pMatches = xmlText.match(/<w:p(?:\s+[^>]*)?>[\s\S]*?<\/w:p>/g) || [];
            for (const pXml of pMatches) {
              const tMatches = pXml.match(/<w:t(?:\s+[^>]*)?>([\s\S]*?)<\/w:t>/g) || [];
              const pText = tMatches.map(t => t.replace(/<[^>]+>/g, '')).join('').trim();
              if (pText) paragraphs.push(pText);
            }
            if (paragraphs.length > 0) return paragraphs.join('\n\n');
          }
        }
        pos = dataStart + (compSize > 0 ? compSize : 1);
      } else {
        pos++;
      }
    }
  } catch (err) {
    console.warn('[DocImport] Client DOCX parse error:', err);
  }

  // 2. フォールバック: 生バイナリから <w:t> テキスト抽出
  const rawString = new TextDecoder('utf-8', { fatal: false }).decode(uint8);
  const wtMatches = rawString.match(/<w:t(?:\s+[^>]*)?>([\s\S]*?)<\/w:t>/g) || [];
  if (wtMatches.length > 0) {
    const pieces = wtMatches.map(t => t.replace(/<[^>]+>/g, '')).filter(t => t.trim().length > 0);
    if (pieces.length > 0) return pieces.join('\n');
  }

  return '';
}

// DOC (.doc / Word 97-2003) ArrayBufferからテキストを抽出するクライアント側パーサー
function extractTextFromDocArrayBuffer(arrayBuffer) {
  const uint8 = new Uint8Array(arrayBuffer);
  const results = [];

  // UTF-16LE 連続テキストブロック抽出
  let currentChars = [];
  for (let i = 0; i < uint8.length - 1; i += 2) {
    const code = uint8[i] | (uint8[i + 1] << 8);
    // 印字可能ASCII、改行、または日本語Unicode範囲
    if ((code >= 0x20 && code <= 0x7E) || code === 0x0A || code === 0x0D || (code >= 0x3000 && code <= 0x9FFF) || (code >= 0xFF00 && code <= 0xFFEF)) {
      currentChars.push(String.fromCharCode(code));
    } else {
      if (currentChars.length >= 6) {
        const str = currentChars.join('').trim();
        if (str && !str.startsWith('Normal') && !str.startsWith('Microsoft')) {
          results.push(str);
        }
      }
      currentChars = [];
    }
  }
  if (currentChars.length >= 6) {
    results.push(currentChars.join('').trim());
  }

  if (results.length > 0) return results.join('\n\n');

  // フォールバック: UTF-8 / CP932 生テキスト抽出
  try {
    const raw = new TextDecoder('utf-8', { fatal: false }).decode(uint8);
    const matches = raw.match(/[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FFF\w\s.,!?-]{6,}/g) || [];
    return matches.join('\n\n');
  } catch (e) {
    return '';
  }
}

// クライアント側から Google Gemini API を直接呼んで画像・スキャンPDFをOCR文書化
async function ocrPdfWithGeminiClient(arrayBuffer, apiKey, explicitModel = null) {
  const settings = getSettingsFromStorage() || {};
  const model = explicitModel || settings.gemini_model || 'gemini-2.0-flash';

  // ArrayBuffer -> Base64 変換
  const uint8 = new Uint8Array(arrayBuffer);
  let binary = '';
  const chunkSize = 8192;
  for (let i = 0; i < uint8.length; i += chunkSize) {
    binary += String.fromCharCode.apply(null, uint8.subarray(i, i + chunkSize));
  }
  const base64Pdf = btoa(binary);

  const prompt = `あなたは極めて高精度な書籍・文書OCRおよび文章構造化の専門家です。
提供されたPDF文書（スキャン画像・電子書籍・原稿）の全ページを精査し、本文テキストを余すところなく正確に日本語テキストとして書き起こしてください。
【要件】
1. 見出し（「第〇章」「第〇話」「Chapter」「節」など）がある場合はそのまま記載してください。
2. 会話文のカギ括弧「」や段落の改行はそのまま保持してください。
3. 余計な前置き、挨拶、注釈（「以下は文字起こしです」等）は一切含めず、本文のみを出力してください。`;

  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
  const payload = {
    contents: [{
      parts: [
        {
          inlineData: {
            mimeType: 'application/pdf',
            data: base64Pdf
          }
        },
        { text: prompt }
      ]
    }],
    generationConfig: {
      temperature: 0.1
    }
  };

  const res = await nativeFetch(url, 'POST', { 'Content-Type': 'application/json' }, JSON.stringify(payload));
  if (!res.ok) {
    const errText = await res.text().catch(() => '');
    throw new Error(`Gemini OCR API エラー (${res.status}): ${errText}`);
  }
  const data = await res.json();
  const rawText = data.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!rawText || !rawText.trim()) {
    throw new Error('Gemini APIからOCRテキストを取得できませんでした');
  }
  return rawText.trim();
}

async function submitDocumentFileUpload(file) {
  if (!file) return;

  const validExts = ['.pdf', '.txt', '.md', '.text', '.doc', '.docx'];
  const ext = file.name.substring(file.name.lastIndexOf('.')).toLowerCase();
  if (!validExts.includes(ext)) {
    showToast('対応ファイル形式は .pdf, .txt, .md, .doc, .docx です', 'warning');
    return;
  }

  const settings = getSettingsFromStorage() || {};
  const geminiApiKey = (settings.gemini_api_key || '').trim();

  const loadingEl = document.getElementById('documentImportLoading');
  const loadingText = document.getElementById('documentImportLoadingText');
  if (loadingEl) loadingEl.classList.remove('hidden');
  if (loadingText) loadingText.textContent = `「${file.name}」を解析して章分割中...`;

  try {
    // サーバーが稼働している場合はFastAPIの /api/documents/import-file を試行
    if (!isAndroidApp) {
      try {
        const formData = new FormData();
        formData.append('file', file);
        formData.append('split_mode', 'auto');
        if (geminiApiKey) {
          formData.append('gemini_api_key', geminiApiKey);
        }

        const res = await fetch('/api/documents/import-file', {
          method: 'POST',
          body: formData,
        });

        if (res.ok) {
          const data = await res.json();
          showToast(data.message || '文書を正常にインポートしました', 'success');
          if (data.novel) {
            displayNovelTOC(data.novel);
            switchTab('toc');
          }
          return;
        } else {
          const errData = await res.json().catch(() => ({}));
          console.warn('[DocImport] Server API returned error:', errData);
          if (errData.detail && errData.detail.includes('Gemini APIキー')) {
            showToast(errData.detail, 'warning');
          }
        }
      } catch (netErr) {
        console.warn('[DocImport] Server API not available, using offline parser:', netErr);
      }
    }

    // オフライン・Android端末内ローカル処理
    const title = file.name.replace(/\.[^/.]+$/, "");
    let documentBody = '';
    let usedOcr = false;

    if (ext === '.pdf') {
      const arrayBuffer = await file.arrayBuffer();
      let pdfText = '';
      try {
        pdfText = await extractTextFromPdfArrayBuffer(arrayBuffer);
      } catch (pdfErr) {
        console.warn('[DocImport] Client PDF parse failed:', pdfErr);
      }

      // テキストが極小または空の場合、画像PDFと判定してGemini API OCRを試行
      const textLen = (pdfText || '').replace(/\s+/g, '').length;
      if (textLen < 60) {
        if (geminiApiKey) {
          if (loadingText) loadingText.textContent = `画像・スキャンPDFを検出しました。Google Geminiで全文文字起こし(OCR)中...`;
          try {
            pdfText = await ocrPdfWithGeminiClient(arrayBuffer, geminiApiKey);
            usedOcr = true;
          } catch (ocrErr) {
            console.warn('[DocImport] Client Gemini OCR error:', ocrErr);
            showToast(`画像PDFのAI文字起こしエラー: ${ocrErr.message}`, 'error');
          }
        } else {
          if (!pdfText || !pdfText.trim()) {
            showToast('画像PDFの文字を読み取るには、設定画面でGoogle Gemini APIキーを設定してください', 'warning');
            pdfText = `『${file.name}』\n\n画像PDFが読み込まれました。設定画面でGoogle Gemini APIキーを設定すると、AIが画像を全文文字起こし（OCR）して正確に朗読できます。`;
          }
        }
      }

      documentBody = pdfText || `『${file.name}』\n\nPDF文書を端末からインポートしました。`;

    } else if (ext === '.docx') {
      // Word (.docx) ファイル
      const arrayBuffer = await file.arrayBuffer();
      if (loadingText) loadingText.textContent = `Word文書 (.docx) を解析中...`;
      documentBody = await extractTextFromDocxArrayBuffer(arrayBuffer);
      if (!documentBody || !documentBody.trim()) {
        throw new Error('Word文書 (.docx) からテキストを抽出できませんでした');
      }

    } else if (ext === '.doc') {
      // Word (.doc) ファイル
      const arrayBuffer = await file.arrayBuffer();
      if (loadingText) loadingText.textContent = `Word文書 (.doc) を解析中...`;
      documentBody = extractTextFromDocArrayBuffer(arrayBuffer);
      if (!documentBody || !documentBody.trim()) {
        throw new Error('Word文書 (.doc) からテキストを抽出できませんでした');
      }

    } else {
      // テキスト・Markdownファイル (UTF-8 / Shift_JIS / EUC-JP 自動判別)
      const text = await readFileAsTextSmart(file);

      if (!text || !text.trim()) {
        throw new Error('ファイル内容が空です');
      }
      documentBody = text;
    }

    await processAndImportDocumentText(title, '私的文書', documentBody, 'auto', usedOcr);

  } catch (error) {
    console.error('[DocImport] File import error:', error);
    showToast(error.message || 'インポート中にエラーが発生しました', 'error');
  } finally {
    if (loadingEl) loadingEl.classList.add('hidden');
  }
}

async function submitDocumentTextImport() {
  const titleInput = document.getElementById('docImportTitle');
  const authorInput = document.getElementById('docImportAuthor');
  const bodyInput = document.getElementById('docImportBody');
  const splitSelect = document.getElementById('docImportSplitMode');

  const title = (titleInput ? titleInput.value : '').trim();
  const author = (authorInput ? authorInput.value : '').trim() || '私的文書';
  const body = (bodyInput ? bodyInput.value : '').trim();
  const splitMode = splitSelect ? splitSelect.value : 'auto';

  if (!title) {
    showToast('文書タイトルを入力してください', 'warning');
    if (titleInput) titleInput.focus();
    return;
  }

  if (!body) {
    showToast('本文テキストを入力してください', 'warning');
    if (bodyInput) bodyInput.focus();
    return;
  }

  const loadingEl = document.getElementById('documentImportLoading');
  const loadingText = document.getElementById('documentImportLoadingText');
  if (loadingEl) loadingEl.classList.remove('hidden');
  if (loadingText) loadingText.textContent = `テキストを解析して章分割中...`;

  try {
    await processAndImportDocumentText(title, author, body, splitMode);
    clearDocumentPasteForm();
  } catch (error) {
    console.error('[DocImport] Text import error:', error);
    showToast(error.message || 'インポート中にエラーが発生しました', 'error');
  } finally {
    if (loadingEl) loadingEl.classList.add('hidden');
  }
}

function clearDocumentPasteForm() {
  const titleInput = document.getElementById('docImportTitle');
  const authorInput = document.getElementById('docImportAuthor');
  const bodyInput = document.getElementById('docImportBody');
  if (titleInput) titleInput.value = '';
  if (authorInput) authorInput.value = '';
  if (bodyInput) bodyInput.value = '';
}

// =============================================================================
// 13-B. 文書・小説 全文プレビュー機能
// =============================================================================
let currentPreviewNovelData = null;
let currentPreviewEpisodes = [];
let docPreviewFontSizeIndex = 2; // 0: 極小, 1: 小, 2: 標準, 3: 大, 4: 特大
const docPreviewFontSizes = ['text-xs', 'text-sm', 'text-base', 'text-lg', 'text-xl'];
const docPreviewFontSizeLabels = ['極小', '小', '標準', '大', '特大'];

async function openCurrentDocumentFullPreview() {
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  if (!state.currentNovel) {
    const msg = uiLang === 'ja' ? '作品が読み込まれていません' : ({ en: 'No work loaded', zh: '未加载作品', ko: '작품이 로드되지 않았습니다', es: 'No hay obra cargada', fr: 'Aucune œuvre chargée', pt: 'Nenhuma obra carregada' }[uiLang] || 'No work loaded');
    showToast(msg, 'warning');
    return;
  }
  await openDocumentFullPreview(state.currentNovel.ncode || state.currentNovel.novel_id);
}

function formatLocalizedDocChapterTitle(rawTitle, epNum, lang) {
  const isJa = lang === 'ja';
  const chPrefix = { ja: `第${epNum}話`, en: `Ch. ${epNum}`, zh: `第${epNum}话`, ko: `제${epNum}화`, es: `Cap. ${epNum}`, fr: `Chap. ${epNum}`, pt: `Cap. ${epNum}` }[lang] || `Ch. ${epNum}`;
  const fullTextMap = { ja: '全文朗読', en: 'Full Text', zh: '全文', ko: '전문', es: 'Texto completo', fr: 'Texte intégral', pt: 'Texto completo' };
  if (!rawTitle) return chPrefix;
  if (isJa) return rawTitle;
  const t = String(rawTitle).trim();
  if (t === '全文朗読' || t === '全文' || t === '本文' || t === '本文 (短編)') {
    return fullTextMap[lang] || 'Full Text';
  }
  const mEp = t.match(/^第\s*(\d+)\s*[話章節編]$/);
  if (mEp) {
    const n = mEp[1];
    return ({ en: `Ch. ${n}`, zh: `第${n}话`, ko: `제${n}화`, es: `Cap. ${n}`, fr: `Chap. ${n}`, pt: `Cap. ${n}` })[lang] || `Ch. ${n}`;
  }
  const mPart = t.match(/^全文朗読\s*\((\d+)\)$/);
  if (mPart) {
    return `${fullTextMap[lang] || 'Full Text'} (${mPart[1]})`;
  }
  return t;
}

async function openDocumentFullPreview(novelIdOrNcode) {
  try {
    const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
    const isJa = effectiveLang === 'ja';
    const superModeOn = isJa && typeof isAozoraModernSuperTranslateEnabled === 'function' && isAozoraModernSuperTranslateEnabled();
    const loadingMsg = {
      ja: '全文プレビューを読み込み中...',
      en: 'Loading full text preview...',
      zh: '正在加载全文预览...',
      ko: '전문 미리보기를 불러오는 중...',
      es: 'Cargando vista previa completa...',
      fr: 'Chargement de l\'aperçu complet...',
      pt: 'Carregando prévia do texto completo...'
    }[effectiveLang] || 'Loading full text preview...';
    showToast(loadingMsg, 'info');

    const pickSegText = (s) => {
      if ((!isJa || superModeOn) && s.translated_text && (!s.translated_lang || s.translated_lang === effectiveLang)) {
        return s.translated_text;
      }
      return s.display_text || s.text || '';
    };

    let novelData = null;
    let episodes = [];
    let totalChars = 0;

    // 1. IndexedDB から小説メタデータとエピソード本文を探索（body / raw_text / segments 全対応）
    if (typeof NarouIDB !== 'undefined' && NarouIDB.getNovel) {
      novelData = await NarouIDB.getNovel(novelIdOrNcode);
      if (novelData) {
        const epCount = novelData.total_episodes || novelData.episodes?.length || 1;
        for (let i = 1; i <= epCount; i++) {
          const ep = await NarouIDB.getEpisode(novelIdOrNcode, i);
          if (ep) {
            const hasMatchingTranslatedSegs = Array.isArray(ep.segments) && (!isJa || superModeOn) &&
              ep.segments.some(s => s.translated_text && s.translated_lang === effectiveLang);
            const epText = hasMatchingTranslatedSegs
              ? ep.segments.map(pickSegText).join('\n')
              : (ep.body || ep.raw_text || ep.text || (Array.isArray(ep.segments) ? ep.segments.map(pickSegText).join('\n') : ''));
            if (epText) {
              episodes.push({
                episode_number: i,
                title: formatLocalizedDocChapterTitle(ep.title, i, effectiveLang),
                body: epText
              });
              totalChars += epText.length;
            }
          }
        }
      }
    }

    // 2. サーバーAPI (/api/documents/{novelId}/full-text) を試行
    if (episodes.length === 0 && !isAndroidApp) {
      try {
        const res = await fetch(`/api/documents/${encodeURIComponent(novelIdOrNcode)}/full-text`);
        if (res.ok) {
          const srvData = await res.json();
          if (srvData && srvData.success) {
            novelData = srvData;
            episodes = srvData.episodes || [];
            totalChars = srvData.total_characters || 0;
          }
        }
      } catch (e) {
        console.warn('[DocPreview] Server full-text fetch error:', e);
      }
    }

    // 3. state.currentNovel からフォールバック
    if (!novelData && state.currentNovel && (state.currentNovel.ncode === novelIdOrNcode || state.currentNovel.novel_id === novelIdOrNcode)) {
      novelData = state.currentNovel;
    }

    // 4. 青空文庫作品で未キャッシュの場合はクライアント取得関数から取得
    if (episodes.length === 0 && (String(novelIdOrNcode || '').startsWith('aozora_') || novelData?.site === 'aozora')) {
      try {
        const epData = await getAozoraEpisodeContentClient(novelIdOrNcode, 1);
        if (epData && (epData.raw_text || epData.segments)) {
          const hasMatchingSegs = Array.isArray(epData.segments) && (!isJa || superModeOn) &&
            epData.segments.some(s => s.translated_text && s.translated_lang === effectiveLang);
          const bodyText = hasMatchingSegs
            ? epData.segments.map(pickSegText).join('\n')
            : (epData.raw_text || (Array.isArray(epData.segments) ? epData.segments.map(pickSegText).join('\n') : ''));
          episodes = [{
            episode_number: 1,
            title: formatLocalizedDocChapterTitle(epData.title || '全文', 1, effectiveLang),
            body: bodyText
          }];
          totalChars = bodyText.length;
        }
      } catch (e) {
        console.warn('[DocPreview] Aozora fallback fetch error:', e);
      }
    }

    if (!novelData) {
      const notFoundMsg = {
        ja: '文書データが見つかりませんでした',
        en: 'Document data not found',
        zh: '未找到文档数据',
        ko: '문서 데이터를 찾을 수 없습니다',
        es: 'No se encontraron datos del documento',
        fr: 'Données du document introuvables',
        pt: 'Dados do documento não encontrados'
      }[effectiveLang] || 'Document data not found';
      showToast(notFoundMsg, 'error');
      return;
    }

    // エピソードがまだ取得できていない場合、state.currentSegments またはダミー
    if (episodes.length === 0) {
      if (state.currentSegments && state.currentSegments.length > 0) {
        const text = state.currentSegments.map(pickSegText).join('\n');
        episodes = [{
          episode_number: state.currentEpisodeNum || 1,
          title: formatLocalizedDocChapterTitle(state.currentEpisodeTitle || '本文', state.currentEpisodeNum || 1, effectiveLang),
          body: text
        }];
        totalChars = text.length;
      } else {
        const loc = getLocalizedAozoraWork(novelData, effectiveLang);
        const fallbackBody = (!isJa && loc && loc.displayOpening)
          ? `${loc.displayOpening}\n\n${loc.displaySynopsis || ''}`
          : (novelData.synopsis || (isJa ? '本文を読み込み中...' : 'Loading text...'));
        episodes = [{
          episode_number: 1,
          title: formatLocalizedDocChapterTitle('本文', 1, effectiveLang),
          body: fallbackBody
        }];
        totalChars = fallbackBody.length;
      }
    }

    currentPreviewNovelData = novelData;
    currentPreviewEpisodes = episodes;

    // UIへ反映
    renderDocumentFullPreviewModal(novelData, episodes, totalChars);

    const modal = document.getElementById('documentFullPreviewModal');
    if (modal) modal.classList.remove('hidden');
  } catch (err) {
    console.error('[DocPreview] Failed to open preview:', err);
    showToast(`Preview Error: ${err.message}`, 'error');
  }
}

function renderDocumentFullPreviewModal(novelData, episodes, totalChars) {
  const titleEl = document.getElementById('docPreviewTitle');
  const authorEl = document.getElementById('docPreviewAuthor');
  const charBadge = document.getElementById('docPreviewCharCountBadge');
  const epBadge = document.getElementById('docPreviewEpisodeCountBadge');
  const ocrBadge = document.getElementById('docPreviewOcrBadge');
  const navContainer = document.getElementById('docPreviewChapterNav');
  const contentContainer = document.getElementById('docPreviewContent');

  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = effectiveLang === 'ja';
  const superModeOn = isJa && typeof isAozoraModernSuperTranslateEnabled === 'function' && isAozoraModernSuperTranslateEnabled();
  const locWork = typeof getLocalizedAozoraWork === 'function' ? getLocalizedAozoraWork(novelData, effectiveLang) : null;

  const playChapterLabelByLang = {
    ja: 'この章を再生',
    en: 'Play Chapter',
    zh: '朗读本章',
    ko: '이 장을 재생',
    es: 'Reproducir capítulo',
    fr: 'Lire ce chapitre',
    pt: 'Ouvir capítulo'
  };
  const playChapterLabel = playChapterLabelByLang[effectiveLang] || playChapterLabelByLang.en;

  const untitledMap = { ja: '無題の文書', en: 'Untitled', zh: '无标题文档', ko: '제목 없는 문서', es: 'Sin título', fr: 'Sans titre', pt: 'Sem título' };
  const authorPrefixMap = { ja: '作成者: ', en: 'Author: ', zh: '作者: ', ko: '작가: ', es: 'Autor: ', fr: 'Auteur : ', pt: 'Autor: ' };
  const docAuthorFallbackMap = { ja: '私的文書', en: 'Document', zh: '个人文档', ko: '개인 문서', es: 'Documento', fr: 'Document', pt: 'Documento' };
  const charsUnitMap = { ja: '文字', en: 'chars', zh: '字', ko: '자', es: 'caract.', fr: 'caract.', pt: 'caract.' };
  const epBadgeFmt = (n) => isJa ? `全${n}話` : ({ zh: `共${n}话`, ko: `총 ${n}화`, en: `${n} ch.`, es: `${n} cap.`, fr: `${n} chap.`, pt: `${n} cap.` }[effectiveLang] || `${n} ch.`);

  const rawDispTitle = (locWork && locWork.displayTitle) || novelData.title || untitledMap[effectiveLang] || 'Untitled';
  const rawDispAuthor = (locWork && locWork.displayAuthor) || novelData.author || docAuthorFallbackMap[effectiveLang] || 'Document';
  if (titleEl) titleEl.textContent = rawDispTitle;
  if (authorEl) {
    const authorPrefix = authorPrefixMap[effectiveLang] || 'Author: ';
    authorEl.textContent = `${authorPrefix}${rawDispAuthor}`;
  }
  if (!isJa && (!locWork || !locWork.isTranslatedPreset) && typeof translatePreviewTextAsync === 'function') {
    if (titleEl && /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF]/.test(rawDispTitle)) {
      translatePreviewTextAsync(rawDispTitle, effectiveLang).then(tr => {
        if (tr && titleEl && currentPreviewNovelData === novelData) titleEl.textContent = tr;
      }).catch(() => {});
    }
    if (authorEl && /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF]/.test(rawDispAuthor)) {
      translatePreviewTextAsync(rawDispAuthor, effectiveLang).then(tr => {
        if (tr && authorEl && currentPreviewNovelData === novelData) {
          authorEl.textContent = `${authorPrefixMap[effectiveLang] || 'Author: '}${tr}`;
        }
      }).catch(() => {});
    }
  }
  if (charBadge) charBadge.textContent = `${totalChars.toLocaleString()} ${charsUnitMap[effectiveLang] || 'chars'}`;
  if (epBadge) epBadge.textContent = epBadgeFmt(episodes.length);

  if (ocrBadge) {
    if (novelData.used_ocr) {
      ocrBadge.textContent = isJa ? '✨ AI OCR文字起こし' : ({ en: '✨ AI OCR', zh: '✨ AI OCR识别', ko: '✨ AI OCR 텍스트', es: '✨ OCR con IA', fr: '✨ OCR IA', pt: '✨ OCR com IA' }[effectiveLang] || '✨ AI OCR');
      ocrBadge.classList.remove('hidden');
    } else {
      ocrBadge.classList.add('hidden');
    }
  }

  // 章ジャンプピル描画
  if (navContainer) {
    navContainer.innerHTML = '';
    if (episodes.length > 1) {
      navContainer.classList.remove('hidden');
      episodes.forEach(ep => {
        const pill = document.createElement('button');
        pill.type = 'button';
        pill.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 font-medium shrink-0 transition active:scale-95';
        pill.textContent = formatLocalizedDocChapterTitle(ep.title, ep.episode_number, effectiveLang);
        pill.onclick = () => scrollToDocPreviewChapter(ep.episode_number);
        navContainer.appendChild(pill);
      });
    } else {
      navContainer.classList.add('hidden');
    }
  }

  // 本文描画
  if (contentContainer) {
    contentContainer.innerHTML = '';
    const currentSizeClass = docPreviewFontSizes[docPreviewFontSizeIndex] || 'text-base';

    episodes.forEach(ep => {
      const chapterCard = document.createElement('div');
      chapterCard.id = `docPreviewChapter-${ep.episode_number}`;
      chapterCard.className = 'bg-slate-950/60 border border-slate-800/80 rounded-2xl p-4 sm:p-5 space-y-3 shadow-md scroll-mt-4';

      // 章ヘッダー
      const head = document.createElement('div');
      head.className = 'flex items-center justify-between border-b border-slate-800/60 pb-2.5 gap-2';

      const locEpTitle = formatLocalizedDocChapterTitle(ep.title, ep.episode_number, effectiveLang);
      const titleSpan = document.createElement('h4');
      titleSpan.className = 'font-bold text-sm sm:text-base text-blue-300 flex items-center space-x-1.5 truncate';
      titleSpan.innerHTML = `<i class="ph-bold ph-bookmark-simple text-blue-400"></i><span>${escapeHtml(locEpTitle)}</span>`;

      const playBtn = document.createElement('button');
      playBtn.type = 'button';
      playBtn.className = 'px-3 py-1 bg-blue-600/30 hover:bg-blue-600/50 text-blue-200 border border-blue-500/40 rounded-lg text-xs font-semibold flex items-center space-x-1 transition active:scale-95 shrink-0';
      playBtn.innerHTML = `<i class="ph-fill ph-play text-[10px]"></i><span>${escapeHtml(playChapterLabel)}</span>`;
      playBtn.onclick = () => startReadingFromDocPreview(ep.episode_number);

      head.appendChild(titleSpan);
      head.appendChild(playBtn);
      chapterCard.appendChild(head);

      // 本文段落
      const bodyDiv = document.createElement('div');
      bodyDiv.className = `leading-relaxed text-slate-200 ${currentSizeClass} space-y-2 whitespace-pre-wrap font-sans`;

      const rawEpBody = String(ep.body || '').replace(/（青空文庫の本文を読み込み中、または通信環境をご確認ください）/g, '').trim();
      const cleanedObj = typeof resolveAozoraRubyAndNotesJs === 'function' ? resolveAozoraRubyAndNotesJs(rawEpBody) : rawEpBody;
      const cleanedBody = (cleanedObj && typeof cleanedObj === 'object') ? (cleanedObj.displayText || '') : String(cleanedObj || '');
      const paras = cleanedBody.split(/\r?\n+/).map(p => p.trim()).filter(p => p.length > 0);
      if (paras.length === 0) {
        const noTextLabel = isJa ? '（本文なし）' : ({ en: '(No text)', zh: '（无正文）', ko: '(본문 없음)', es: '(Sin texto)', fr: '(Aucun texte)', pt: '(Sem texto)' }[effectiveLang] || '(No text)');
        bodyDiv.innerHTML = `<p class="text-slate-500 text-xs italic">${escapeHtml(noTextLabel)}</p>`;
      } else {
        const pElements = paras.map(p => {
          const pEl = document.createElement('p');
          pEl.textContent = p;
          bodyDiv.appendChild(pEl);
          return pEl;
        });

        // 外国語UI時または現代語超訳ON時に、冒頭段落から優先して翻訳反映
        if ((!isJa || superModeOn) && typeof _translateLinesViaGtx === 'function') {
          const hasJa = /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF]/.test(paras.slice(0, 5).join(' '));
          if (hasJa) {
            (async () => {
              try {
                // まず冒頭8段落を即座に翻訳してプレビュー反映
                const openingParas = paras.slice(0, 8);
                const trOpening = await _translateLinesViaGtx(openingParas, effectiveLang);
                if (Array.isArray(trOpening)) {
                  trOpening.forEach((trText, idx) => {
                    if (trText && pElements[idx]) {
                      pElements[idx].textContent = trText;
                    }
                  });
                }
                // 残りの段落も最大24段落までUIスレッドを譲りながら順次翻訳
                for (let start = 8; start < Math.min(paras.length, 24); start += 8) {
                  await new Promise(r => setTimeout(r, 24));
                  if (currentPreviewNovelData !== novelData) break;
                  const batch = paras.slice(start, start + 8);
                  const trBatch = await _translateLinesViaGtx(batch, effectiveLang);
                  if (Array.isArray(trBatch)) {
                    trBatch.forEach((trText, idx) => {
                      if (trText && pElements[start + idx]) {
                        pElements[start + idx].textContent = trText;
                      }
                    });
                  }
                }
              } catch (e) {
                console.warn('[DocPreview] Opening body translation error:', e);
              }
            })();
          }
        }
      }

      chapterCard.appendChild(bodyDiv);
      contentContainer.appendChild(chapterCard);
    });
  }

  updateDocPreviewFontSizeUI();
}

function scrollToDocPreviewChapter(epNum) {
  const target = document.getElementById(`docPreviewChapter-${epNum}`);
  if (target) {
    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    vibrateFeedback(6);
  }
}

function adjustDocPreviewFontSize(delta) {
  docPreviewFontSizeIndex = Math.max(0, Math.min(docPreviewFontSizes.length - 1, docPreviewFontSizeIndex + delta));
  updateDocPreviewFontSizeUI();

  // 本文コンテナ内のフォントクラスを置換
  const contentContainer = document.getElementById('docPreviewContent');
  if (contentContainer) {
    docPreviewFontSizes.forEach(cls => {
      contentContainer.querySelectorAll(`.${cls}`).forEach(el => el.classList.remove(cls));
    });
    const newClass = docPreviewFontSizes[docPreviewFontSizeIndex];
    contentContainer.querySelectorAll('.space-y-2').forEach(el => el.classList.add(newClass));
  }
}

function updateDocPreviewFontSizeUI() {
  const labelEl = document.getElementById('docPreviewFontSizeLabel');
  if (labelEl) {
    const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
    const labelsByLang = {
      ja: ['極小', '小', '標準', '大', '特大'],
      en: ['XS', 'Small', 'Normal', 'Large', 'XL'],
      zh: ['极小', '小', '标准', '大', '特大'],
      ko: ['극소', '소', '표준', '대', '특대'],
      es: ['XS', 'Peq.', 'Normal', 'Grande', 'XL'],
      fr: ['XS', 'Petit', 'Normal', 'Grand', 'XL'],
      pt: ['XS', 'Peq.', 'Normal', 'Grande', 'XL']
    };
    const arr = labelsByLang[uiLang] || labelsByLang.en;
    labelEl.textContent = arr[docPreviewFontSizeIndex] || arr[2];
  }
}

function copyDocumentFullPreviewText() {
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = uiLang === 'ja';
  if (!currentPreviewEpisodes || currentPreviewEpisodes.length === 0) {
    showToast(isJa ? 'コピー可能なテキストがありません' : 'No text available to copy', 'warning');
    return;
  }
  const locWork = (currentPreviewNovelData && typeof getLocalizedAozoraWork === 'function')
    ? getLocalizedAozoraWork(currentPreviewNovelData, uiLang)
    : null;
  const title = locWork?.displayTitle || currentPreviewNovelData?.title || (isJa ? '文書' : 'Document');
  const author = locWork?.displayAuthor || currentPreviewNovelData?.author || (isJa ? '私的文書' : 'Document');
  const headerStr = isJa ? `タイトル: ${title}\n作者: ${author}\n\n` : `Title: ${title}\nAuthor: ${author}\n\n`;
  const fullText = headerStr +
    currentPreviewEpisodes.map(ep => `■ ${ep.title}\n\n${ep.body}`).join('\n\n' + '-'.repeat(30) + '\n\n');

  const copiedMsg = isJa
    ? '文書全文をクリップボードにコピーしました'
    : ({ en: 'Copied full text to clipboard', zh: '已将全文复制到剪贴板', ko: '전문 텍스트를 클립보드에 복사했습니다', es: 'Texto completo copiado al portapapeles', fr: 'Texte intégral copié dans le presse-papiers', pt: 'Texto completo copiado para a área de transferência' }[uiLang] || 'Copied full text to clipboard');

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(fullText).then(() => {
      showToast(copiedMsg, 'success');
    }).catch(() => {
      fallbackCopyText(fullText);
    });
  } else {
    fallbackCopyText(fullText);
  }
}

function fallbackCopyText(text) {
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = uiLang === 'ja';
  const ta = document.createElement('textarea');
  ta.value = text;
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand('copy');
    showToast(isJa ? '文書全文をクリップボードにコピーしました' : 'Copied full text to clipboard', 'success');
  } catch (e) {
    showToast(isJa ? 'コピーに失敗しました' : 'Failed to copy text', 'error');
  }
  document.body.removeChild(ta);
}

function closeDocumentFullPreviewModal() {
  const modal = document.getElementById('documentFullPreviewModal');
  if (modal) modal.classList.add('hidden');
}

async function startReadingFromDocPreview(episodeNum = 1) {
  closeDocumentFullPreviewModal();
  if (currentPreviewNovelData) {
    if (!state.currentNovel || state.currentNovel.ncode !== currentPreviewNovelData.ncode) {
      displayNovelTOC(currentPreviewNovelData);
    }
    await startReadingEpisode(episodeNum);
  }
}

