const _AOZORA_WORK_I18N_LOOKUP = (() => {
  const map = {};
  if (typeof AOZORA_WORK_I18N === 'object' && AOZORA_WORK_I18N) {
    for (const [key, val] of Object.entries(AOZORA_WORK_I18N)) {
      if (!val) continue;
      map[String(key).trim().toLowerCase()] = val;
      if (val.ncode) map[String(val.ncode).trim().toLowerCase()] = val;
      if (val.shortKey) map[String(val.shortKey).trim().toLowerCase()] = val;
      if (val.titleJa) map[String(val.titleJa).trim().toLowerCase()] = val;
    }
  }
  return map;
})();

function matchAozoraWorkById(w, queryId) {
  if (!w || !queryId) return false;
  const q = String(queryId).trim().toLowerCase();
  const wId = String(w.id || '').trim().toLowerCase();
  const wNcode = String(w.ncode || '').trim().toLowerCase();
  if (wId === q || wNcode === q) return true;
  const qNumMatch = q.match(/^aozora_(?:\d+_)?0*(\d+)$/);
  if (qNumMatch) {
    const qNum = qNumMatch[1];
    const wIdNum = wId.match(/^aozora_(?:\d+_)?0*(\d+)$/)?.[1];
    const wNcodeNum = wNcode.match(/^aozora_(?:\d+_)?0*(\d+)$/)?.[1];
    if (wIdNum === qNum || wNcodeNum === qNum) return true;
  }
  const i18nEntry = _AOZORA_WORK_I18N_LOOKUP[q];
  if (i18nEntry) {
    const entryNcode = String(i18nEntry.ncode || '').trim().toLowerCase();
    const entryShort = String(i18nEntry.shortKey || '').trim().toLowerCase();
    const entryTitle = String(i18nEntry.titleJa || '').trim();
    if (entryNcode && (wId === entryNcode || wNcode === entryNcode)) return true;
    if (entryShort && (wId === entryShort || wNcode === entryShort)) return true;
    if (entryTitle && w.title === entryTitle) return true;
  }
  return false;
}

function findAozoraWorkI18nEntry(workOrId) {
  if (!workOrId || typeof _AOZORA_WORK_I18N_LOOKUP === 'undefined' || !_AOZORA_WORK_I18N_LOOKUP) return null;
  if (typeof workOrId === 'string') {
    const key = workOrId.trim().toLowerCase();
    if (_AOZORA_WORK_I18N_LOOKUP[key]) return _AOZORA_WORK_I18N_LOOKUP[key];
    const m = key.match(/^aozora_\d+_0*(\d+)$/);
    if (m && _AOZORA_WORK_I18N_LOOKUP[`aozora_${m[1]}`]) {
      return _AOZORA_WORK_I18N_LOOKUP[`aozora_${m[1]}`];
    }
    return null;
  }
  const candidates = [
    workOrId.id,
    workOrId.ncode,
    workOrId.novel_id,
    workOrId._orig_title,
    workOrId.title
  ];
  for (const c of candidates) {
    if (!c) continue;
    const key = String(c).trim().toLowerCase();
    if (_AOZORA_WORK_I18N_LOOKUP[key]) return _AOZORA_WORK_I18N_LOOKUP[key];
    // aozora_000879_000127 -> aozora_127 のような末尾番号フォールバック
    const m = key.match(/^aozora_\d+_0*(\d+)$/);
    if (m && _AOZORA_WORK_I18N_LOOKUP[`aozora_${m[1]}`]) {
      return _AOZORA_WORK_I18N_LOOKUP[`aozora_${m[1]}`];
    }
  }
  return null;
}

