function getLocalizedAozoraAuthor(jpAuthor, langCode) {
  const lang = langCode || (typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja');
  const norm = String(jpAuthor || '').trim();
  const entry = AOZORA_AUTHOR_I18N[norm];
  if (!entry) return norm;
  if (lang === 'ja') return entry.ja || norm;
  const loc = entry[lang] || entry.en || norm;
  return loc === norm ? norm : `${loc} (${entry.ja || norm})`;
}

function getLocalizedAozoraAuthorButtonLabel(jpAuthor, langCode) {
  const lang = langCode || (typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja');
  const norm = String(jpAuthor || '').trim();
  const entry = AOZORA_AUTHOR_I18N[norm];
  if (!entry) return norm;
  if (lang === 'ja') return entry.ja || norm;
  return entry[lang] || entry.en || norm;
}

function resolveJapaneseAuthorFromMultilingualQuery(rawQuery) {
  const q = String(rawQuery || '').trim().toLowerCase();
  if (!q || q.length < 2) return null;
  for (const [jpName, meta] of Object.entries(AOZORA_AUTHOR_I18N)) {
    const jpLower = jpName.toLowerCase();
    if (jpLower === q || jpLower.includes(q)) return jpName;
    if (Array.isArray(meta.aliases)) {
      const isAsciiQ = /^[a-z\s.\-]+$/i.test(q);
      if (isAsciiQ && q.length < 4) continue;
      if (meta.aliases.some(a => {
        const al = a.toLowerCase();
        return al === q || (q.length >= 4 && al.includes(q));
      })) {
        return jpName;
      }
    }
  }
  return null;
}

