async function requestGtxTranslateSingle(text, sourceLang = 'auto', targetLang = 'ja') {
  const clean = String(text || '').trim();
  if (!clean) return null;
  const gtxEndpoint = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=${encodeURIComponent(sourceLang)}&tl=${encodeURIComponent(targetLang)}&dt=t`;
  const bodyStr = `q=${encodeURIComponent(clean)}`;

  const useAndroidNative = (typeof isAndroidApp !== 'undefined' ? (isAndroidApp || isAndroidAppNow()) : false) && window.AndroidBridge;
  try {
    let res;
    if (useAndroidNative) {
      res = await nativeFetch(gtxEndpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
        body: bodyStr,
        timeoutMs: 4000
      });
    } else {
      const controller = (typeof AbortController !== 'undefined') ? new AbortController() : null;
      const timer = controller ? setTimeout(() => controller.abort(), 3500) : null;
      try {
        res = await fetch(gtxEndpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
          body: bodyStr,
          signal: controller?.signal
        });
      } finally {
        if (timer) clearTimeout(timer);
      }
    }
    if (res && res.ok) {
      const data = await res.json();
      if (Array.isArray(data) && Array.isArray(data[0])) {
        const translated = data[0].map(part => (Array.isArray(part) ? (part[0] || '') : '')).join('');
        const detectedLang = data[2] || sourceLang;
        return { text: translated.trim(), detectedLang };
      }
    }
  } catch (e) {
    // 失敗時はフォールバック
  }
  return null;
}

/**
 * 日本語以外のクエリを自動判別し、日本語の青空文庫検索キーワードへ変換する
 */
async function resolveJapaneseQueryFromMultilingualQueryAsync(rawQuery) {
  const q = String(rawQuery || '').trim();
  if (!q) return { jpKeyword: '', detectedLang: 'ja', isTranslated: false, origKeyword: '' };

  // 1. すでに日本語（ひらがな・カタカナを含む）ならそのまま日本語として処理
  const hasKana = /[\u3040-\u309F\u30A0-\u30FF]/.test(q);
  if (hasKana) {
    return { jpKeyword: q, detectedLang: 'ja', isTranslated: false, origKeyword: q };
  }

  const qLower = q.toLowerCase();
  const cacheKey = `q::${qLower}`;
  if (_searchQueryTranslationCache[cacheKey]) {
    return _searchQueryTranslationCache[cacheKey];
  }

  // 2. 漢字のみで構成されるクエリで、既存の日本語作品名・作家名にそのままヒットする（または日本語UIである）場合は誤翻訳を防止
  const isKanjiOnly = /^[\u4E00-\u9FFF\u3000-\u303F\uFF00-\uFFEF\s　]+$/.test(q);
  if (isKanjiOnly) {
    // 明示的な中国語簡体字辞書に完全一致する場合のみ変換（例: 罗生门 -> 羅生門）
    for (const item of MULTILINGUAL_SEARCH_LEXICON) {
      if (item.lang === 'zh' && item.re.test(q) && item.jp !== q) {
        const res = { jpKeyword: item.jp, detectedLang: 'zh', isTranslated: true, origKeyword: q };
        _searchQueryTranslationCache[cacheKey] = res;
        return res;
      }
    }
    const res = { jpKeyword: q, detectedLang: 'ja', isTranslated: false, origKeyword: q };
    _searchQueryTranslationCache[cacheKey] = res;
    return res;
  }

  // 3. 作家名辞書
  const mappedAuthor = (typeof resolveJapaneseAuthorFromMultilingualQuery === 'function')
    ? resolveJapaneseAuthorFromMultilingualQuery(q)
    : null;
  if (mappedAuthor) {
    const isSame = mappedAuthor.toLowerCase() === qLower;
    const res = { jpKeyword: mappedAuthor, detectedLang: isSame ? 'ja' : 'en', isTranslated: !isSame, origKeyword: q };
    _searchQueryTranslationCache[cacheKey] = res;
    return res;
  }

  // 4. 作品名辞書
  if (typeof _AOZORA_WORK_I18N_LOOKUP !== 'undefined' && _AOZORA_WORK_I18N_LOOKUP) {
    const entry = _AOZORA_WORK_I18N_LOOKUP[qLower];
    if (entry && entry.titleJa) {
      const isSame = entry.titleJa.toLowerCase() === qLower;
      const res = { jpKeyword: entry.titleJa, detectedLang: isSame ? 'ja' : 'en', isTranslated: !isSame, origKeyword: q };
      _searchQueryTranslationCache[cacheKey] = res;
      return res;
    }
  }

  // 5. 静的文学・一般語彙辞書
  for (const item of MULTILINGUAL_SEARCH_LEXICON) {
    if (item.re.test(q)) {
      const res = { jpKeyword: item.jp, detectedLang: item.lang || 'en', isTranslated: item.jp.toLowerCase() !== qLower, origKeyword: q };
      _searchQueryTranslationCache[cacheKey] = res;
      return res;
    }
  }

  // 6. オンライン高速GTX翻訳 (auto -> ja)
  try {
    const gtxRes = await requestGtxTranslateSingle(q, 'auto', 'ja');
    if (gtxRes && gtxRes.text && gtxRes.text.toLowerCase() !== qLower) {
      const res = {
        jpKeyword: gtxRes.text,
        detectedLang: gtxRes.detectedLang || 'en',
        isTranslated: true,
        origKeyword: q
      };
      _searchQueryTranslationCache[cacheKey] = res;
      return res;
    }
  } catch (e) {}

  // 翻訳不能時は元キーワードを使用
  const fallback = { jpKeyword: q, detectedLang: 'ja', isTranslated: false, origKeyword: q };
  _searchQueryTranslationCache[cacheKey] = fallback;
  return fallback;
}

function getLocalizedAozoraWork(work, langCode) {
  const lang = langCode || (typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja');
  const entry = findAozoraWorkI18nEntry(work);
  const wI18n = entry ? (entry[lang] || (lang !== 'ja' ? entry.en : null)) : null;
  const masterList = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS))
    ? window.AOZORA_MASTER_WORKS
    : (typeof AOZORA_MASTER_WORKS !== 'undefined' ? AOZORA_MASTER_WORKS : []);
  const workIdLower = String(work?.id || work?.ncode || '').trim().toLowerCase();
  const masterWork = workIdLower
    ? masterList.find(m => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(m, workIdLower) : (String(m.id || m.ncode || '').toLowerCase() === workIdLower))
    : null;
  const canonicalJaTitle = entry?.titleJa || work?._orig_title || masterWork?.title || work?.title || '';
  const canonicalJaAuthor = work?._orig_author || masterWork?.author || work?.author || '';
  const canonicalJaSynopsis = work?._orig_story || masterWork?.synopsis || work?.synopsis || '';
  const displayAuthor = getLocalizedAozoraAuthor(canonicalJaAuthor, lang);
  const genreByLang = {
    zh: '日本文学名作',
    ko: '일본 명작 문학',
    es: 'Literatura Clásica',
    fr: 'Littérature Classique',
    pt: 'Literatura Clássica',
    en: 'Classic Literature'
  };
  const openingLabelByLang = {
    ja: '冒頭プレビュー:',
    en: 'Opening Preview:',
    zh: '正文开头预览:',
    ko: '본문 도입부 미리보기:',
    es: 'Vista previa del inicio:',
    fr: 'Extrait du début :',
    pt: 'Prévia do início:'
  };
  const openingLabel = openingLabelByLang[lang] || openingLabelByLang.en;
  const keywordsByLang = {
    ja: ['青空文庫', 'パブリックドメイン'],
    en: ['Aozora Bunko', 'Public Domain'],
    zh: ['青空文库', '公有领域'],
    ko: ['아오조라 문고', '퍼블릭 도메인'],
    es: ['Aozora Bunko', 'Dominio Público'],
    fr: ['Aozora Bunko', 'Domaine Public'],
    pt: ['Aozora Bunko', 'Domínio Público']
  };
  const displayKeywords = keywordsByLang[lang] || keywordsByLang.en;

  // 日本語原文の冒頭抽出
  let rawJaOpening = entry?.openingJa || work?.sample_text || masterWork?.sample_text || '';
  if (!rawJaOpening && (work?.text || masterWork?.text)) {
    const rawSource = work?.text || masterWork?.text || '';
    const cleanedObj = typeof resolveAozoraRubyAndNotesJs === 'function' ? resolveAozoraRubyAndNotesJs(rawSource) : rawSource;
    const cleaned = (cleanedObj && typeof cleanedObj === 'object') ? (cleanedObj.displayText || '') : String(cleanedObj || '');
    const lines = String(cleaned || '').split(/\r?\n/).map(l => l.trim()).filter(l => l && l !== canonicalJaTitle && l !== canonicalJaAuthor);
    rawJaOpening = lines.slice(0, 2).join(' ').slice(0, 140);
  }

  if (lang === 'ja' || !wI18n) {
    if (lang !== 'ja' && work) {
      const fallbackAuthor = getLocalizedAozoraAuthorButtonLabel(canonicalJaAuthor, lang);
      return {
        displayTitle: `${canonicalJaTitle}`,
        displayAuthor,
        displaySynopsis: canonicalJaSynopsis || `${fallbackAuthor}: "${canonicalJaTitle}"`,
        displayOpening: rawJaOpening,
        openingLabel,
        displayGenre: genreByLang[lang] || 'Classic Literature',
        displayKeywords,
        isTranslatedPreset: false
      };
    }
    const jaSuperOn = (lang === 'ja') && typeof isAozoraModernSuperTranslateEnabled === 'function' && isAozoraModernSuperTranslateEnabled();
    const jaOpening = (jaSuperOn && rawJaOpening && typeof translateSegmentToModernJapaneseOffline === 'function')
      ? translateSegmentToModernJapaneseOffline(rawJaOpening, '地の文')
      : rawJaOpening;
    return {
      displayTitle: canonicalJaTitle,
      displayAuthor: canonicalJaAuthor,
      displaySynopsis: canonicalJaSynopsis,
      displayOpening: jaOpening,
      openingLabel,
      displayGenre: masterWork?.genre || work?.genre || '名作文学',
      displayKeywords: keywordsByLang.ja,
      isTranslatedPreset: true
    };
  }
  return {
    displayTitle: wI18n.title || canonicalJaTitle,
    displayAuthor,
    displaySynopsis: wI18n.synopsis || canonicalJaSynopsis,
    displayOpening: wI18n.opening || wI18n.synopsis || '',
    openingLabel,
    displayGenre: genreByLang[lang] || 'Classic Literature',
    displayKeywords,
    isTranslatedPreset: true
  };
}

function matchesAozoraMultilingualSearch(work, rawKeyword) {
  const kw = String(rawKeyword || '').trim().toLowerCase();
  if (!kw || !work) return false;
  // 日本語（かな・漢字のみ）で入力された場合は日本語タイトル・著者名側で判定済のため多言語あらすじ等とは照合しない
  if (/^[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FFF\s　]+$/.test(kw)) {
    return false;
  }
  const isAsciiShort = /^[a-z\s]+$/i.test(kw) && kw.length < 3;
  if (isAsciiShort) return false;

  const wDict = findAozoraWorkI18nEntry(work);
  if (wDict) {
    for (const langCode of ['en', 'zh', 'ko', 'es', 'fr', 'pt']) {
      const langObj = wDict[langCode];
      if (!langObj) continue;
      // タイトルのみを対象とし、あらすじ・冒頭文での無関係な部分一致を排除
      if (langObj.title && langObj.title.toLowerCase().includes(kw)) return true;
    }
  }
  const authorMeta = AOZORA_AUTHOR_I18N[work.author] || AOZORA_AUTHOR_I18N[work.authorTag];
  if (authorMeta) {
    for (const val of Object.values(authorMeta)) {
      if (typeof val === 'string' && val.toLowerCase().includes(kw)) return true;
      if (Array.isArray(val) && val.some(a => a.toLowerCase().includes(kw))) return true;
    }
  }
  return false;
}

// 日本語UI時の「✨ 現代語超訳モード」ON/OFF状態
function isAozoraModernSuperTranslateEnabled() {
  return localStorage.getItem('narou_aozora_modern_super_translate') === 'true';
}

// 外国語UI時（または手動有効化時）の「🌐 自動AI翻訳＆朗読モード」ON/OFF状態
function isAutoEpisodeTranslateEnabled() {
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const saved = localStorage.getItem('narou_ai_auto_episode_translate');
  if (effectiveLang !== 'ja') {
    // 非日本語UI時はデフォルトON（明示的に 'false' にされた場合のみOFF）
    return saved !== 'false';
  }
  return saved === 'true' || isAozoraModernSuperTranslateEnabled();
}

async function applyAutoTranslationModeToActiveEpisode(enabled) {
  if (typeof state === 'undefined' || !Array.isArray(state.currentSegments) || state.currentSegments.length === 0) {
    return;
  }
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const wasPlaying = !!state.isPlaying;

  if (enabled) {
    const targetLang = effectiveLang === 'ja' ? (_selectedTargetTranslationLang || 'ja') : effectiveLang;
    _selectedTargetTranslationLang = targetLang;
    await executeAiEpisodeTranslation({
      isAuto: true,
      awaitFirstBatchOnly: true,
      resumeIfWasPlaying: wasPlaying
    });
  } else {
    _aiTranslationRunId++;
    _isAiTranslationRunning = false;
    const progBox = document.getElementById('aiTranslationProgressBox');
    const execBtn = document.getElementById('executeAiTranslateBtn');
    if (progBox) progBox.classList.add('hidden');
    if (execBtn) execBtn.disabled = false;

    if (wasPlaying && typeof pauseAudio === 'function') {
      pauseAudio();
    }
    state.currentTranslatedLang = null;
    if (typeof renderSegments === 'function') renderSegments();
    if (typeof updateMiniPlayer === 'function') updateMiniPlayer();
    if (typeof updateCarModeUI === 'function') updateCarModeUI();
    if (typeof updatePlayerStatusUI === 'function') updatePlayerStatusUI();
    if (typeof refreshAiTranslationModalGateUI === 'function') refreshAiTranslationModalGateUI();

    if (wasPlaying) {
      state.isPlaying = true;
      if (typeof updatePlayPauseIcons === 'function') updatePlayPauseIcons();
      if (typeof playSegment === 'function') {
        playSegment(Number(state.currentSegmentIndex) || 0);
      }
    }
  }
}

function onToggleAutoEpisodeTranslate(checked) {
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  localStorage.setItem('narou_ai_auto_episode_translate', checked ? 'true' : 'false');
  if (effectiveLang === 'ja') {
    localStorage.setItem('narou_aozora_modern_super_translate', checked ? 'true' : 'false');
  }
  updateAozoraReadingModeBanner();
  renderAozoraCatalog(currentAozoraAuthorFilter || 'all');
  if (typeof refreshSwitchStateIndicators === 'function') refreshSwitchStateIndicators();
  if (typeof showMiniToast === 'function' && typeof sst === 'function') {
    showMiniToast(sst(checked ? 'toast_auto_trans_on' : 'toast_auto_trans_off'));
  }
  // 朗読中・エピソード読込中に切り替えた場合は現在話へ即時反映（ONなら即時超訳/翻訳して朗読継続、OFFなら原文へ即時復帰して朗読継続）
  applyAutoTranslationModeToActiveEpisode(!!checked);
}

function toggleAozoraSmartReadingMode() {
  if (typeof vibrateFeedback === 'function') vibrateFeedback(10);
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  let nextState = false;
  if (effectiveLang === 'ja') {
    nextState = !isAozoraModernSuperTranslateEnabled();
    localStorage.setItem('narou_aozora_modern_super_translate', nextState ? 'true' : 'false');
    localStorage.setItem('narou_ai_auto_episode_translate', nextState ? 'true' : 'false');
    _selectedTargetTranslationLang = 'ja';
    if (typeof showToast === 'function') {
      showToast(
        nextState
          ? '✨ 現代語超訳モードをONにしました！青空文庫の古い表現を現代のわかりやすい言葉に超訳して朗読します'
          : '🇯🇵 原文朗読モードに戻しました（青空文庫の原文をそのまま朗読します）',
        'info'
      );
    }
  } else {
    nextState = !isAutoEpisodeTranslateEnabled();
    localStorage.setItem('narou_ai_auto_episode_translate', nextState ? 'true' : 'false');
    _selectedTargetTranslationLang = effectiveLang;
    const meta = SUPPORTED_MAJOR_LANGUAGES[effectiveLang] || SUPPORTED_MAJOR_LANGUAGES.en;
    if (typeof showToast === 'function') {
      showToast(
        nextState
          ? `${meta.flag} Auto AI Translation (${meta.nativeName}) enabled`
          : `${meta.flag} Auto AI Translation disabled (Original Japanese)`,
        'info'
      );
    }
  }
  updateAozoraReadingModeBanner();
  renderAozoraCatalog(currentAozoraAuthorFilter || 'all');
  if (typeof refreshSwitchStateIndicators === 'function') refreshSwitchStateIndicators();
  applyAutoTranslationModeToActiveEpisode(nextState);
}

function updateAozoraReadingModeBanner() {
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const uiStr = AOZORA_UI_STRINGS_I18N[effectiveLang] || AOZORA_UI_STRINGS_I18N.ja;
  const titleEl = document.getElementById('aozoraModeTitle');
  const descEl = document.getElementById('aozoraModeDesc');
  const badgeEl = document.getElementById('aozoraModeStatusBadge');
  const btnEl = document.getElementById('aozoraModeToggleBtn');
  const iconEl = document.getElementById('aozoraModeToggleIcon');
  const lblEl = document.getElementById('aozoraModeToggleLabel');
  const searchInput = document.getElementById('searchKeyword');
  const catTitle = document.getElementById('aozoraCatalogTitle');
  const catDesc = document.getElementById('aozoraCatalogDesc');

  if (searchInput && uiStr.search_placeholder) {
    searchInput.placeholder = uiStr.search_placeholder;
  }
  if (catTitle && uiStr.catalog_title) catTitle.textContent = uiStr.catalog_title;
  if (catDesc && uiStr.catalog_desc) catDesc.textContent = uiStr.catalog_desc;

  const isActive = effectiveLang === 'ja' ? isAozoraModernSuperTranslateEnabled() : isAutoEpisodeTranslateEnabled();

  if (titleEl) titleEl.textContent = effectiveLang === 'ja' ? uiStr.mode_title_ja : uiStr.mode_title;
  if (descEl) descEl.textContent = effectiveLang === 'ja' ? uiStr.mode_desc_ja : uiStr.mode_desc;

  if (badgeEl) {
    badgeEl.textContent = effectiveLang === 'ja'
      ? (isActive ? uiStr.mode_on_ja : uiStr.mode_off_ja)
      : (isActive ? uiStr.mode_on : uiStr.mode_off);
    badgeEl.className = isActive
      ? 'px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40'
      : 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-800 text-slate-300 border border-slate-700';
  }

  if (btnEl && iconEl && lblEl) {
    if (isActive) {
      btnEl.className = 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-amber-500 to-emerald-600 hover:from-amber-400 hover:to-emerald-500 text-white border border-amber-400/50 text-xs font-extrabold flex items-center space-x-1.5 shadow-md transition active:scale-95';
      iconEl.className = 'ph-fill ph-toggle-right text-base text-white';
      lblEl.textContent = effectiveLang === 'ja' ? uiStr.mode_btn_turn_off_ja : uiStr.mode_btn_turn_off;
    } else {
      btnEl.className = 'px-3.5 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-600 text-xs font-bold flex items-center space-x-1.5 transition active:scale-95';
      iconEl.className = 'ph-bold ph-toggle-left text-base text-slate-400';
      lblEl.textContent = effectiveLang === 'ja' ? uiStr.mode_btn_turn_on_ja : uiStr.mode_btn_turn_on;
    }
  }

  const autoChk = document.getElementById('aiTransAutoEpisodeToggle');
  if (autoChk) autoChk.checked = isActive;
}

// 選択されている国・言語で知名度の高い青空文庫登録作家ボタンを優先順でUIへ配置
function renderAozoraAuthorButtons() {
  const container = document.getElementById('aozoraAuthorBtnsContainer');
  if (!container) return;
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const uiStr = AOZORA_UI_STRINGS_I18N[effectiveLang] || AOZORA_UI_STRINGS_I18N.ja;

  const lblEl = document.getElementById('aozoraFamousAuthorsLabel');
  const hintEl = document.getElementById('aozoraAuthorPriorityHint');
  if (lblEl && uiStr.famous_authors_label) lblEl.textContent = uiStr.famous_authors_label;
  if (hintEl && uiStr.priority_hint) hintEl.textContent = uiStr.priority_hint;

  const authorsOrder = AOZORA_COUNTRY_FAMOUS_AUTHORS[effectiveLang] || AOZORA_COUNTRY_FAMOUS_AUTHORS.ja;
  const activeKey = currentAozoraAuthorFilter || 'all';

  const allBtnActive = activeKey === 'all';
  let html = `<button onclick="filterAozoraAuthor('all')" data-author-key="all" class="aozora-author-btn px-3 py-1 rounded-lg ${allBtnActive ? 'bg-emerald-600 text-white font-semibold' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'} text-xs shrink-0 transition">${escapeHtml(uiStr.all_authors)}</button>`;

  authorsOrder.forEach((jpAuthor) => {
    const isSelected = activeKey === jpAuthor;
    const displayLabel = getLocalizedAozoraAuthorButtonLabel(jpAuthor, effectiveLang);
    html += `<button onclick="filterAozoraAuthor('${jpAuthor}')" data-author-key="${escapeHtml(jpAuthor)}" class="aozora-author-btn px-3 py-1 rounded-lg ${isSelected ? 'bg-emerald-600 text-white font-semibold' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'} text-xs shrink-0 transition">${escapeHtml(displayLabel)}</button>`;
  });

  container.innerHTML = html;
}

function renderAozoraCatalog(authorFilter = 'all') {
  currentAozoraAuthorFilter = authorFilter;
  const catalogSec = document.getElementById('aozoraCatalogSection');
  const kwActive = typeof isKeywordSearchActive === 'function' && isKeywordSearchActive();
  if (catalogSec) {
    if (kwActive) {
      catalogSec.classList.add('hidden');
    } else {
      catalogSec.classList.remove('hidden');
    }
  }
  const grid = document.getElementById('aozoraCatalogGrid');
  if (!grid) return;

  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const uiStr = AOZORA_UI_STRINGS_I18N[effectiveLang] || AOZORA_UI_STRINGS_I18N.ja;
  const isJa = effectiveLang === 'ja';
  const superModeOn = isJa && isAozoraModernSuperTranslateEnabled();
  const foreignAutoOn = !isJa && isAutoEpisodeTranslateEnabled();

  const allMasterWorks = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS))
    ? window.AOZORA_MASTER_WORKS
    : (typeof AOZORA_MASTER_WORKS !== 'undefined' ? AOZORA_MASTER_WORKS : []);

  let filteredWorks = authorFilter === 'all'
    ? [...allMasterWorks]
    : allMasterWorks.filter(w =>
        w.authorTag === authorFilter ||
        w.author === authorFilter ||
        (w.author && w.author.includes(authorFilter)) ||
        (authorFilter === '芥川龍之介' && w.author === '芥川竜之介')
      );

  // 「すべて」選択時も、その国で有名な作家の作品を上位に優先表示
  if (authorFilter === 'all' && AOZORA_COUNTRY_FAMOUS_AUTHORS[effectiveLang]) {
    const orderList = AOZORA_COUNTRY_FAMOUS_AUTHORS[effectiveLang];
    filteredWorks.sort((a, b) => {
      const normA = a.author === '芥川竜之介' ? '芥川龍之介' : (a.authorTag || a.author || '');
      const normB = b.author === '芥川竜之介' ? '芥川龍之介' : (b.authorTag || b.author || '');
      const idxA = orderList.indexOf(normA);
      const idxB = orderList.indexOf(normB);
      const rankA = idxA === -1 ? 999 : idxA;
      const rankB = idxB === -1 ? 999 : idxB;
      return rankA - rankB;
    });
  }

  grid.innerHTML = filteredWorks.map(w => {
    const loc = getLocalizedAozoraWork(w, effectiveLang);
    const workId = w.id || w.ncode;
    const displayYear = isJa
      ? (w.year || 'パブリックドメイン')
      : String(w.year || uiStr.tag_public_domain || 'Public Domain').replace(/年$/, '');
    const primaryBtnLabel = isJa
      ? (superModeOn ? uiStr.btn_read_super : uiStr.btn_read)
      : (foreignAutoOn ? uiStr.btn_read : uiStr.btn_read_raw);
    const primaryBtnClass = superModeOn
      ? 'w-full h-11 bg-gradient-to-r from-amber-500 to-emerald-600 hover:from-amber-400 hover:to-emerald-500 text-white rounded-xl text-xs sm:text-sm font-extrabold shadow-lg shadow-emerald-600/30 flex items-center justify-center space-x-2 transition active:scale-[0.98]'
      : 'w-full h-11 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white rounded-xl text-xs sm:text-sm font-extrabold shadow-lg shadow-emerald-600/30 flex items-center justify-center space-x-2 transition active:scale-[0.98]';

    return `
    <div class="bg-slate-950/80 border border-slate-800 hover:border-emerald-500/50 rounded-2xl p-3.5 flex flex-col justify-between transition shadow-md group">
      <div onclick="openAozoraNovelToc('${workId}')" class="cursor-pointer">
        <div class="flex items-center justify-between mb-1.5">
          <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-900/60 text-emerald-300 border border-emerald-600/40 flex items-center space-x-1">
            <i class="ph-bold ph-bank"></i>
            <span>${escapeHtml(uiStr.badge_aozora)}</span>
          </span>
          <span class="text-[10px] font-mono text-slate-400">${escapeHtml(isJa ? (w.lengthText || '名作文学') : loc.displayGenre)}</span>
        </div>
        <h4 class="text-sm sm:text-base font-bold text-white group-hover:text-emerald-300 transition line-clamp-1">
          ${escapeHtml(loc.displayTitle)}
        </h4>
        <p class="text-xs text-slate-400 mt-0.5 font-medium">${escapeHtml(loc.displayAuthor)} <span class="text-[10px] text-slate-500">(${escapeHtml(displayYear)})</span></p>
        <p class="text-[11px] text-slate-300 mt-2 line-clamp-2 leading-relaxed">
          ${escapeHtml(loc.displaySynopsis)}
        </p>
        ${loc.displayOpening ? `
        <div class="mt-2 px-2.5 py-1.5 rounded-xl bg-slate-900/90 border border-emerald-500/20 text-[11px] text-emerald-100/90 leading-relaxed">
          <span class="text-[10px] font-bold text-emerald-400 mr-1"><i class="ph-fill ph-quotes mr-0.5"></i>${escapeHtml(loc.openingLabel)}</span>
          <span class="italic line-clamp-2" data-aozora-opening-preview="${escapeHtml(workId)}">${escapeHtml(loc.displayOpening)}</span>
        </div>` : ''}
      </div>

      <div class="mt-3 pt-2.5 border-t border-slate-800/80 space-y-2">
        <!-- 1段目: 最優先アクション「1タップで朗読」(迷わず押せるフル幅ボタン) -->
        <button onclick="quickReadAozoraNovel('${workId}')" class="${primaryBtnClass}">
          <i class="ph-fill ${superModeOn ? 'ph-magic-wand' : 'ph-play-circle'} text-lg"></i>
          <span>${escapeHtml(primaryBtnLabel)}</span>
        </button>

        <!-- 2段目: サブ操作 (目次・超訳・オフライン保存) -->
        <div class="flex items-center justify-between gap-1.5">
          <button onclick="openAozoraNovelToc('${workId}')" class="flex-1 h-8 px-2.5 bg-slate-800/90 hover:bg-slate-700 text-slate-200 rounded-xl text-xs font-semibold border border-slate-700 transition flex items-center justify-center space-x-1 active:scale-95" title="${escapeHtml(uiStr.btn_toc)}">
            <i class="ph ph-list-bullets text-sm text-slate-300"></i>
            <span>${escapeHtml(uiStr.btn_toc)}</span>
          </button>
          ${isJa ? `
          <button onclick="quickReadAozoraNovel('${workId}', { forceTargetLang: 'ja', forceSuperTranslate: true })" class="h-8 px-2.5 bg-amber-500/15 hover:bg-amber-500/25 text-amber-300 rounded-xl text-[11px] font-bold border border-amber-500/40 transition flex items-center space-x-1 active:scale-95 shrink-0" title="古い表現を現代のわかりやすい言葉に超訳して朗読">
            <i class="ph-fill ph-magic-wand text-xs"></i>
            <span>${escapeHtml(uiStr.btn_chip_super)}</span>
          </button>` : ''}
          <!-- オフライン保存ボタン -->
          <button onclick="downloadAozoraNovelDirect('${workId}', this)" class="h-8 px-2.5 bg-slate-800/90 hover:bg-slate-700 text-emerald-400 rounded-xl text-xs font-semibold border border-emerald-500/30 transition flex items-center space-x-1 active:scale-95 shrink-0" title="${escapeHtml(uiStr.btn_save)}">
            <i class="ph-bold ph-download-simple text-sm"></i>
            <span>${escapeHtml(uiStr.btn_save)}</span>
          </button>
        </div>
      </div>
    </div>
  `;
  }).join('');

  // 外国語UIでプリセット辞書に未登録の作品のみ非同期で冒頭プレビューを翻訳反映（プリセット作品と現代語超訳はgetLocalizedAozoraWorkで即時解決済）
  if (!isJa && typeof translatePreviewTextAsync === 'function') {
    filteredWorks.slice(0, 12).forEach(w => {
      const workId = w.id || w.ncode;
      const loc = getLocalizedAozoraWork(w, effectiveLang);
      if (!loc.displayOpening || loc.isTranslatedPreset) return;
      translatePreviewTextAsync(loc.displayOpening, effectiveLang).then(translated => {
        if (!translated) return;
        const el = grid.querySelector(`[data-aozora-opening-preview="${CSS.escape(String(workId))}"]`);
        if (el) el.textContent = translated;
      }).catch(() => {});
    });
  }
}

// 青空文庫作品のオフライン直接保存
async function downloadAozoraNovelDirect(workId, btnEl = null, options = {}) {
  const allMasterWorks = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS))
    ? window.AOZORA_MASTER_WORKS
    : (typeof AOZORA_MASTER_WORKS !== 'undefined' ? AOZORA_MASTER_WORKS : []);
  let work = allMasterWorks.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, workId) : (w.id === workId || w.ncode === workId));
  if (!work) {
    const idx = await loadAozoraIndexIfNeeded();
    work = idx?.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, workId) : (w.id === workId));
  }
  if (!work) return;

  const targetId = work.id || work.ncode;
  const skipGate = options.skipGate === true;
  if (!skipGate && !NovelDownloadGate.tryAcquire(targetId)) {
    return;
  }

  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = effectiveLang === 'ja';
  const savingLabel = isJa ? '保存中' : ({ en: 'Saving...', zh: '保存中...', ko: '저장 중...', es: 'Guardando...', fr: 'Enregistrement...', pt: 'Salvando...' }[effectiveLang] || 'Saving...');

  const originalHtml = btnEl ? btnEl.innerHTML : '';
  if (btnEl) {
    btnEl.disabled = true;
    btnEl.innerHTML = `<i class="ph ph-spinner animate-spin text-sm"></i><span class="text-[11px]">${escapeHtml(savingLabel)}</span>`;
  }

  try {
    if (!work.text || work.text.length < 50) {
      const epData = await getAozoraEpisodeContentClient(targetId, 1);
      if (epData && epData.raw_text) {
        work.text = epData.raw_text;
      }
    }

    const novelData = {
      ncode: targetId,
      title: work.title,
      author: work.author,
      synopsis: work.synopsis || `${work.author}による名作文学『${work.title}』。`,
      story: work.synopsis || `${work.author}による名作文学『${work.title}』。`,
      site: 'aozora',
      site_name: '青空文庫',
      genre_name: work.genre || '名作文学',
      is_public_domain: true,
      total_episodes: 1,
      episode_count: 1,
      episodes: [
        {
          episode_number: 1,
          title: work.firstEpisodeTitle || '全文朗読',
          date: work.year,
          url: `https://www.aozora.gr.jp/${work.id}`,
          raw_text: work.text
        }
      ]
    };

    const segments = splitNovelTextToSegments(work.text);
    const analysis = analyzeSegmentsLocally(segments, work.title);
    const characters = analysis.characters || [];
    const enrichedSegments = analysis.segments || segments;

    const mergedCastData = mergeNovelCastIncremental(
      work.id,
      null,
      characters,
      '青空文庫AI配役解析'
    );

    if (typeof NarouIDB !== 'undefined' && NarouIDB.saveNovel && NarouIDB.saveEpisode) {
      await NarouIDB.saveNovel(novelData, true);
      await NarouIDB.saveEpisode(work.id, 1, {
        episode_number: 1,
        title: work.firstEpisodeTitle || '全文朗読',
        url: `https://www.aozora.gr.jp/${work.id}`,
        raw_text: work.text,
        segments: enrichedSegments,
        characters: characters,
        cast: mergedCastData.cast,
        cast_profiles: mergedCastData.cast_profiles
      }, true);
    }

    const locSaved = getLocalizedAozoraWork(work, effectiveLang);
    if (btnEl) {
      const uiStr = AOZORA_UI_STRINGS_I18N[effectiveLang] || AOZORA_UI_STRINGS_I18N.ja;
      btnEl.className = 'h-8 px-2.5 bg-emerald-900/60 text-emerald-300 rounded-xl text-xs font-medium border border-emerald-500/40 transition flex items-center space-x-1';
      btnEl.innerHTML = `<i class="ph-bold ph-check text-sm"></i><span class="text-[11px]">${escapeHtml(uiStr.btn_saved)}</span>`;
    }
    const dispSavedTitle = locSaved.displayTitle || work.title;
    showMiniToast(isJa ? `✔ 『${dispSavedTitle}』をオフライン保存しました！` : `✔ Saved "${dispSavedTitle}" offline!`);
    if (typeof loadDownloadsData === 'function') {
      loadDownloadsData(true);
    }
  } catch (e) {
    console.error('downloadAozoraNovelDirect error:', e);
    showToast(isJa ? `保存に失敗しました: ${e.message}` : `Save failed: ${e.message}`, 'error');
    if (btnEl) {
      btnEl.innerHTML = originalHtml;
      btnEl.disabled = false;
    }
  } finally {
    if (!skipGate) NovelDownloadGate.release(work.id);
  }
}

function filterAozoraAuthor(authorName, options = {}) {
  vibrateFeedback(10);
  currentAozoraAuthorFilter = authorName;
  if (!options.preserveKeywordSearch) {
    const kwInput = document.getElementById('searchKeyword');
    if (kwInput && kwInput.value.trim()) {
      kwInput.value = '';
      const clearBtn = document.getElementById('clearSearchInputBtn');
      if (clearBtn) clearBtn.classList.add('hidden');
    }
    if (typeof setExclusiveKeywordSearchMode === 'function') {
      setExclusiveKeywordSearchMode(false);
    }
  }
  const btns = document.querySelectorAll('.aozora-author-btn');
  btns.forEach(b => {
    const key = b.getAttribute('data-author-key') || b.textContent.trim();
    if (key === authorName || (authorName === 'all' && key === 'all')) {
      b.className = 'aozora-author-btn px-3 py-1 rounded-lg bg-emerald-600 text-white font-semibold text-xs shrink-0 transition';
    } else {
      b.className = 'aozora-author-btn px-3 py-1 rounded-lg bg-slate-800 text-slate-300 hover:bg-slate-700 text-xs shrink-0 transition';
    }
  });
  renderAozoraCatalog(authorName);
}

/**
 * 朗読開始・次話移動時に、設定言語または現代語超訳モードに応じて自動でAI翻訳／超訳を実行する
 */
async function maybeAutoTranslateCurrentEpisode(options = {}) {
  if (!state.currentSegments || state.currentSegments.length === 0) return;

  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isAozora = state.currentNovel?.site === 'aozora' || String(state.currentNovel?.ncode || '').startsWith('aozora_');

  let targetLang = null;
  if (options && options.forceTargetLang) {
    targetLang = options.forceTargetLang;
  } else if (effectiveLang !== 'ja' && isAutoEpisodeTranslateEnabled()) {
    targetLang = effectiveLang;
  } else if (effectiveLang === 'ja' && (options?.forceSuperTranslate || (isAozora && isAozoraModernSuperTranslateEnabled()) || (localStorage.getItem('narou_ai_auto_episode_translate') === 'true' && _selectedTargetTranslationLang))) {
    targetLang = (effectiveLang === 'ja' && (options?.forceSuperTranslate || isAozoraModernSuperTranslateEnabled()))
      ? 'ja'
      : (_selectedTargetTranslationLang || 'ja');
  }

  if (!targetLang) {
    state.currentTranslatedLang = null;
    if (typeof refreshAiTranslationModalGateUI === 'function') {
      refreshAiTranslationModalGateUI();
    }
    return;
  }

  _selectedTargetTranslationLang = targetLang;
  await executeAiEpisodeTranslation({ isAuto: true, awaitFirstBatchOnly: true });
}

// 青空文庫作品を1タップで即座に朗読開始する（多言語自動翻訳＆現代語超訳モード連動）
async function quickReadAozoraNovel(workId, options = {}) {
  triggerHaptic('click');
  const allMasterWorks = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS))
    ? window.AOZORA_MASTER_WORKS
    : (typeof AOZORA_MASTER_WORKS !== 'undefined' ? AOZORA_MASTER_WORKS : []);
  let work = allMasterWorks.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, workId) : (w.id === workId || w.ncode === workId));
  if (!work) {
    const idx = await loadAozoraIndexIfNeeded();
    work = idx?.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, workId) : (w.id === workId));
  }
  if (!work) return;

  const targetId = work.id || work.ncode;
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = effectiveLang === 'ja';
  const locWork = getLocalizedAozoraWork(work, effectiveLang);
  const dispTitle = locWork.displayTitle || work.title;

  const qrI18nMap = {
    ja: {
      prepTitle: `『${dispTitle}』を準備中`,
      step1: '① 構造と文脈を解析中...',
      step1Fetch: '① 青空文庫より作品テキストを取得中...',
      step2Cached: '② 保存済みAI配役データを展開中...',
      step2Live: (p) => `② ${p} で登場人物・セリフを高精度解析中...`,
      step3: '③ 朗読・翻訳データを適用中...',
      footer: '青空文庫名作AI自動配役・超訳・多言語エンジン',
      cachedEngine: 'キャッシュ済AI解析',
      fastEngine: '高速ロジック解析',
      aiEngine: 'AI配役エンジン',
      fullRead: '全文朗読',
      classicBadge: '名作'
    },
    en: {
      prepTitle: `Preparing "${dispTitle}"...`,
      step1: '① Analyzing structure & context...',
      step1Fetch: '① Fetching classic text from Aozora Bunko...',
      step2Cached: '② Loading saved AI voice cast...',
      step2Live: (p) => `② Analyzing characters & dialogue with ${p}...`,
      step3: '③ Applying voice & translation data...',
      footer: 'Aozora Bunko AI Multi-Voice & Translation Engine',
      cachedEngine: 'Cached AI Cast',
      fastEngine: 'Fast Logic Cast',
      aiEngine: 'AI Cast Engine',
      fullRead: 'Full Text Reading',
      classicBadge: 'Classic'
    },
    zh: {
      prepTitle: `正在准备《${dispTitle}》...`,
      step1: '① 正在解析作品结构与语境...',
      step1Fetch: '① 正在从青空文库获取正文...',
      step2Cached: '② 正在加载已保存的AI配音数据...',
      step2Live: (p) => `② 正在使用 ${p} 解析角色与台词...`,
      step3: '③ 正在应用朗读与翻译数据...',
      footer: '青空文库名作 AI自动配音与多语言翻译引擎',
      cachedEngine: '已缓存AI解析',
      fastEngine: '高速逻辑解析',
      aiEngine: 'AI配音引擎',
      fullRead: '全文朗读',
      classicBadge: '名作'
    },
    ko: {
      prepTitle: `『${dispTitle}』 준비 중...`,
      step1: '① 작품 구조 및 문맥 분석 중...',
      step1Fetch: '① 아오조라 문고에서 본문 가져오는 중...',
      step2Cached: '② 저장된 AI 배역 데이터 불러오는 중...',
      step2Live: (p) => `② ${p}로 등장인물·대사 정밀 분석 중...`,
      step3: '③ 낭독 및 번역 데이터 적용 중...',
      footer: '아오조라 문고 명작 AI 자동 배역·다국어 번역 엔진',
      cachedEngine: '캐시된 AI 분석',
      fastEngine: '고속 로직 분석',
      aiEngine: 'AI 배역 엔진',
      fullRead: '전문 낭독',
      classicBadge: '명작'
    },
    es: {
      prepTitle: `Preparando "${dispTitle}"...`,
      step1: '① Analizando estructura y contexto...',
      step1Fetch: '① Obteniendo texto de Aozora Bunko...',
      step2Cached: '② Cargando reparto de voces IA guardado...',
      step2Live: (p) => `② Analizando personajes y diálogos con ${p}...`,
      step3: '③ Aplicando datos de voz y traducción...',
      footer: 'Motor IA Multivoz y Traducción Aozora Bunko',
      cachedEngine: 'IA en caché',
      fastEngine: 'Análisis rápido',
      aiEngine: 'Motor IA',
      fullRead: 'Lectura completa',
      classicBadge: 'Clásico'
    },
    fr: {
      prepTitle: `Préparation de « ${dispTitle} »...`,
      step1: '① Analyse de la structure et du contexte...',
      step1Fetch: '① Récupération du texte depuis Aozora Bunko...',
      step2Cached: '② Chargement de la distribution vocale IA...',
      step2Live: (p) => `② Analyse des personnages et dialogues avec ${p}...`,
      step3: '③ Application des données vocales et de traduction...',
      footer: 'Moteur IA Multivoix & Traduction Aozora Bunko',
      cachedEngine: 'IA en cache',
      fastEngine: 'Analyse rapide',
      aiEngine: 'Moteur IA',
      fullRead: 'Lecture intégrale',
      classicBadge: 'Classique'
    },
    pt: {
      prepTitle: `Preparando "${dispTitle}"...`,
      step1: '① Analisando estrutura e contexto...',
      step1Fetch: '① Obtendo texto da Aozora Bunko...',
      step2Cached: '② Carregando elenco de vozes IA salvo...',
      step2Live: (p) => `② Analisando personagens e diálogos com ${p}...`,
      step3: '③ Aplicando dados de voz e tradução...',
      footer: 'Motor IA Multivoz e Tradução Aozora Bunko',
      cachedEngine: 'IA em cache',
      fastEngine: 'Análise rápida',
      aiEngine: 'Motor IA',
      fullRead: 'Leitura completa',
      classicBadge: 'Clássico'
    }
  };
  const qrStr = qrI18nMap[effectiveLang] || qrI18nMap.en;

  // 再生中オーディオの停止
  pauseAudio();

  // 1. 即座に朗読タブへ切り替え（フリーズ感を完全に排除）
  switchTab('player');

  // プレイヤーUIのタイトル等を即座に先行反映
  const playerTitle = document.getElementById('playerNovelTitle');
  const playerSubtitle = document.getElementById('playerSubtitle');
  const playerEpBadge = document.getElementById('playerEpisodeBadge');
  if (playerTitle) playerTitle.textContent = dispTitle;
  if (playerSubtitle) playerSubtitle.textContent = isJa ? (work.firstEpisodeTitle || '全文朗読') : qrStr.fullRead;
  if (playerEpBadge) playerEpBadge.textContent = qrStr.classicBadge;

  updateElementSiteBadge('tocSiteBadge', 'tocSiteBadgeText', 'aozora');
  updateElementSiteBadge('playerSiteBadge', 'playerSiteBadgeText', 'aozora');
  updateElementSiteBadge('modalDetailSiteBadge', '', 'aozora');

  // 2. ステップ1: 構造・文脈解析中インジケーターを描画
  if (segmentsContainer) {
    segmentsContainer.innerHTML = `
      <div class="py-14 px-4 flex flex-col items-center justify-center space-y-4 text-center animate-fadeIn">
        <div class="w-14 h-14 rounded-2xl bg-indigo-500/15 border border-indigo-500/30 flex items-center justify-center text-indigo-400 text-2xl shadow-xl shadow-indigo-500/10">
          <i class="ph-bold ph-sparkle animate-spin" style="animation-duration: 4s;"></i>
        </div>
        <div class="space-y-1">
          <h3 class="text-sm font-bold text-slate-100">${escapeHtml(qrStr.prepTitle)}</h3>
          <p id="quickReadStepText" class="text-xs text-indigo-300 font-medium">${escapeHtml(qrStr.step1)}</p>
        </div>
        <div class="w-48 bg-slate-900 rounded-full h-1.5 overflow-hidden border border-slate-800">
          <div id="quickReadProgressBar" class="h-full bg-gradient-to-r from-blue-500 to-indigo-500 transition-all duration-300 w-1/3"></div>
        </div>
        <span class="text-[10px] text-slate-500">${escapeHtml(qrStr.footer)}</span>
      </div>
    `;
  }

  // UI描画フレームを譲る
  await new Promise(r => setTimeout(r, 60));

  // エピソード遷移インタースティシャル広告の判定（画面切替・インジケーター描画後に行うことでタップ無反応を防止）
  if (typeof maybeShowEpisodeTransitionInterstitial === 'function') {
    try {
      await maybeShowEpisodeTransitionInterstitial();
    } catch (e) {
      console.warn('[AdMob] quickReadAozoraNovel transition check error:', e);
    }
  }

  // 本文が未取得の場合は取得
  const stepText = document.getElementById('quickReadStepText');
  const progBar = document.getElementById('quickReadProgressBar');

  if (!work.text || work.text.length < 50) {
    if (stepText) stepText.textContent = qrStr.step1Fetch;
    try {
      const epData = await getAozoraEpisodeContentClient(targetId, 1);
      if (epData && epData.raw_text && (!work.text || work.text.length < 50)) {
        work.text = epData.raw_text;
      }
    } catch (e) {
      console.warn('[Aozora] quickRead text fetch warning:', e);
    }
  }

  const splitEps = splitAozoraWorkIntoEpisodesClient(
    work.text || '',
    work.title,
    work.firstEpisodeTitle || '全文朗読',
    work.year || 'パブリックドメイン',
    work.html_url || work.card_url || `https://www.aozora.gr.jp/${targetId}`
  );
  const firstEpObj = splitEps[0] || {
    episode_number: 1,
    title: work.firstEpisodeTitle || '全文朗読',
    date: work.year || 'パブリックドメイン',
    url: work.html_url || work.card_url || `https://www.aozora.gr.jp/${targetId}`,
    raw_text: work.text || ''
  };
  if (playerSubtitle) playerSubtitle.textContent = isJa ? firstEpObj.title : qrStr.fullRead;

  // 作品オブジェクトを構築（日本語の正規メタデータを保持し、言語切替時にも getLocalizedAozoraWork で双方向復元可能にする）
  const novelData = {
    ncode: targetId,
    title: work.title,
    _orig_title: work.title,
    author: work.author,
    _orig_author: work.author,
    synopsis: work.synopsis || `${work.author}による名作文学『${work.title}』。`,
    _orig_story: work.synopsis || `${work.author}による名作文学『${work.title}』。`,
    story: work.synopsis || `${work.author}による名作文学『${work.title}』。`,
    site: 'aozora',
    site_name: '青空文庫',
    genre_name: work.genre || '名作文学',
    is_public_domain: true,
    _clean_rev: AOZORA_CLEAN_SEGMENT_REV,
    total_episodes: splitEps.length,
    episode_count: splitEps.length,
    episodes: splitEps.map(ep => ({
      episode_number: ep.episode_number,
      title: ep.title,
      date: ep.date,
      url: ep.url,
      raw_text: ep.raw_text
    }))
  };

  state.currentNovel = novelData;
  state.currentEpisodeNum = 1;

  // 既存キャッシュ（解析済みセグメント・配役）の確認（_clean_rev 一致時のみ使用）
  let cachedEpisode = null;
  if (typeof NarouIDB !== 'undefined' && NarouIDB.getEpisode) {
    try {
      cachedEpisode = await NarouIDB.getEpisode(targetId.toLowerCase(), 1);
    } catch (e) {}
  }

  let finalSegments = [];
  let characters = [];
  let engineLabel = null;

  if (cachedEpisode && cachedEpisode._clean_rev === AOZORA_CLEAN_SEGMENT_REV && Array.isArray(cachedEpisode.segments) && cachedEpisode.segments.length > 0) {
    finalSegments = cachedEpisode.segments;
    characters = cachedEpisode.characters || [];
    engineLabel = qrStr.cachedEngine;
    if (stepText) stepText.textContent = qrStr.step2Cached;
    if (progBar) progBar.style.width = '75%';
    await new Promise(r => setTimeout(r, 40));
  } else {
    const rawText = firstEpObj.raw_text || work.text || work.sample_text || `${work.title}\n\n${work.author}`;
    const segments = splitNovelTextToSegments(rawText);

    const settings = getSettingsFromStorage() || {};
    const currentProvider = getActiveCastLlmProvider(settings) || 'gemini';
    const providerLabel = currentProvider === 'gemini' ? 'Google Gemini'
      : currentProvider === 'openai' ? 'OpenAI'
      : currentProvider === 'claude' ? 'Claude'
      : currentProvider === 'local_llm' ? 'Local LLM'
      : qrStr.aiEngine;

    if (stepText) stepText.textContent = qrStr.step2Live(providerLabel);
    if (progBar) progBar.style.width = '65%';

    let analyzeData = null;
    try {
      const analyzeRes = await apiFetch('/api/analyze/episode', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          segments,
          novel_title: work.title,
          force_refresh: false
        })
      });
      if (analyzeRes.ok) {
        analyzeData = await analyzeRes.json();
      }
    } catch (e) {
      console.warn('[Aozora] 1-tap read AI analysis request error, falling back:', e);
    }

    finalSegments = (analyzeData && Array.isArray(analyzeData.segments) && analyzeData.segments.length > 0)
      ? analyzeData.segments
      : segments;
    characters = (analyzeData && Array.isArray(analyzeData.characters))
      ? analyzeData.characters
      : [];
    engineLabel = analyzeData?._engine || providerLabel;

    if (characters.length === 0) {
      const localResult = analyzeSegmentsLocally(finalSegments, work.title);
      finalSegments = localResult.segments;
      characters = localResult.characters || [];
      if (!engineLabel) engineLabel = qrStr.fastEngine;
    }
  }

  state.currentSegments = typeof normalizeAndMergeBrokenSegments === 'function'
    ? normalizeAndMergeBrokenSegments(finalSegments)
    : finalSegments;
  state.currentSegmentIndex = 0;

  const mergedCastData = mergeNovelCastIncremental(
    targetId,
    null,
    characters,
    `青空文庫 1タップ朗読 (${engineLabel})`
  );
  state.currentCharacters = mergedCastData.characters;
  state.currentCast = mergedCastData.cast;
  state.currentCastProfiles = mergedCastData.cast_profiles;

  if (typeof NarouIDB !== 'undefined' && NarouIDB.saveEpisode) {
    try {
      await NarouIDB.saveEpisode(targetId.toLowerCase(), 1, {
        ...novelData.episodes[0],
        segments: state.currentSegments,
        characters: state.currentCharacters,
        cast: state.currentCast,
        cast_profiles: state.currentCastProfiles,
        _clean_rev: AOZORA_CLEAN_SEGMENT_REV
      }, false);
    } catch (idbErr) {
      console.warn('[NarouIDB] saveEpisode cache update failed:', idbErr);
    }
  }

  if (stepText) stepText.textContent = qrStr.step3;
  if (progBar) progBar.style.width = '90%';
  await new Promise(r => setTimeout(r, 40));

  updatePlayerAiStatusBadge(engineLabel, state.currentCharacters.length);
  renderCastEditor();
  renderSegments();

  // 🌐 多言語UI時のAI自動翻訳 または 🇯🇵 日本語UI時の現代語超訳モードを自動実行
  await maybeAutoTranslateCurrentEpisode(options);

  highlightCurrentSegment(0);
  updatePlayerStatusUI();
  updatePlayButtonUI(false);

  // 自動音声生成（VOICEVOX設定ON時 & 日本語音声再生時）
  const autoGen = localStorage.getItem('narou_auto_generate_audio') !== 'false';
  const engine = getPreferredTtsEngine();
  if (autoGen && (!state.currentTranslatedLang || state.currentTranslatedLang === 'ja') && (engine === 'voicevox' || engine === 'hybrid_mix')) {
    setTimeout(() => {
      triggerBackgroundAudioGeneration(targetId, 1, 1);
    }, 500);
  }

  // 即座に再生開始
  if (!state.isPlaying) {
    playSegment(0);
  }
}

// 青空文庫作品を目次画面で開く
async function openAozoraNovelToc(workId) {
  const allMasterWorks = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS))
    ? window.AOZORA_MASTER_WORKS
    : (typeof AOZORA_MASTER_WORKS !== 'undefined' ? AOZORA_MASTER_WORKS : []);
  let work = allMasterWorks.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, workId) : (w.id === workId || w.ncode === workId));
  if (!work) {
    const idx = await loadAozoraIndexIfNeeded();
    work = idx?.find(w => typeof matchAozoraWorkById === 'function' ? matchAozoraWorkById(w, workId) : (w.id === workId));
  }
  if (!work) return;

  const targetId = work.id || work.ncode;
  const novelData = await getAozoraNovelIndexClient(targetId);
  displayNovelTOC(novelData);
}

// ==============================================
// 13-E. 初回起動時の利用規約同意モーダル制御
// ==============================================
function checkPolicyConsentOnStartup() {
  const agreed = localStorage.getItem('narou_policy_consent_v1');
  if (!agreed) {
    // 初回起動時: 対象言語を考慮し、スマートフォンの端末言語にUIと規約画面を合わせる
    const effectiveLang = detectDeviceMajorLanguage();
    applyAppUiLanguage(effectiveLang);

    // 🎬 ロゴスプラッシュ再生中の場合は、スプラッシュ終了後に開く
    if (typeof _studioLogoDismissed !== 'undefined' && !_studioLogoDismissed) {
      window._pendingPolicyConsentAfterSplash = true;
      return;
    }

    const modal = document.getElementById('policyConsentModal');
    if (modal) {
      modal.classList.remove('hidden');
    }
  }
}

function toggleConsentSubmitBtn(checked) {
  const btn = document.getElementById('policyConsentAcceptBtn');
  if (!btn) return;
  btn.disabled = !checked;
  if (checked) {
    btn.classList.remove('disabled:bg-slate-800', 'disabled:text-slate-500', 'cursor-not-allowed');
    btn.classList.add('bg-blue-600', 'hover:bg-blue-500', 'cursor-pointer');
  } else {
    btn.classList.add('disabled:bg-slate-800', 'disabled:text-slate-500', 'cursor-not-allowed');
    btn.classList.remove('bg-blue-600', 'hover:bg-blue-500', 'cursor-pointer');
  }
}

function acceptPolicyConsent() {
  localStorage.setItem('narou_policy_consent_v1', 'true');
  const modal = document.getElementById('policyConsentModal');
  if (modal) modal.classList.add('hidden');
  showToast(tUi('consent_toast_thank_you'), 'success');
  if (window._pendingApiKeyPromptAfterConsent) {
    window._pendingApiKeyPromptAfterConsent = false;
    setTimeout(() => {
      if (typeof openApiKeyTutorialModal === 'function' && !hasAnyConfiguredAiApiKey()) {
        openApiKeyTutorialModal('gemini', true);
      }
    }, 350);
  }
}

// ==============================================
// 13. なろう検索 & フィルター機能
// ==============================================
function toggleAdvancedFilter() {
  const panel = document.getElementById('advancedFilterPanel');
  const chevron = document.getElementById('filterChevron');
  if (!panel) return;

  if (panel.classList.contains('hidden')) {
    panel.classList.remove('hidden');
    if (chevron) chevron.style.transform = 'rotate(180deg)';
  } else {
    panel.classList.add('hidden');
    if (chevron) chevron.style.transform = 'rotate(0deg)';
  }
}

// ==============================================
// 13-A. 検索入力クリア・履歴・クイック探索 & キーワード検索時の排他的表示制御
// ==============================================
window.__isExclusiveKeywordSearchMode = false;

function isKeywordSearchActive() {
  const input = document.getElementById('searchKeyword');
  const hasKw = !!(input && input.value.trim().length > 0);
  if (!hasKw) return false;
  if (window.__isExclusiveKeywordSearchMode) return true;
  const resultsList = document.getElementById('novelResultsList');
  return !!(resultsList && !resultsList.classList.contains('hidden'));
}

/**
 * キーワード検索時の排他的表示モード切替
 * true: 検索結果以外の小説一覧（ランダム5作品・気分検索・名作カタログ・文豪クイック選択・初心者試聴カード）をすべて非表示にし、検索結果のみを排他的に表示
 * false: 通常の一覧表示へ復帰
 */
function setExclusiveKeywordSearchMode(isExclusive) {
  window.__isExclusiveKeywordSearchMode = !!isExclusive;
  const sectionIdsToHideOnSearch = [
    'moodSearchSection',
    'randomNovelsSection',
    'aozoraCatalogSection',
    'aozoraFamousAuthorsBlock',
    'beginnerQuickStartCard'
  ];
  sectionIdsToHideOnSearch.forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    if (isExclusive) {
      el.classList.add('hidden');
    } else {
      el.classList.remove('hidden');
    }
  });

  if (isExclusive) {
    // 気分検索の展開結果も閉じる
    if (typeof clearMoodFilter === 'function') {
      clearMoodFilter();
    }
  } else {
    const resultsList = document.getElementById('novelResultsList');
    if (resultsList) {
      resultsList.classList.add('hidden');
      resultsList.innerHTML = '';
    }
    const searchMeta = document.getElementById('searchMeta');
    if (searchMeta) searchMeta.classList.add('hidden');
    const paginationControls = document.getElementById('paginationControls');
    if (paginationControls) paginationControls.classList.add('hidden');
    const loadingEl = document.getElementById('searchLoading');
    if (loadingEl) loadingEl.classList.add('hidden');
  }
}
window.isKeywordSearchActive = isKeywordSearchActive;
window.setExclusiveKeywordSearchMode = setExclusiveKeywordSearchMode;

function onSearchKeywordInput(val) {
  const clearBtn = document.getElementById('clearSearchInputBtn');
  if (clearBtn) {
    if (val && val.trim().length > 0) {
      clearBtn.classList.remove('hidden');
    } else {
      clearBtn.classList.add('hidden');
      restoreAozoraCatalogIfEmpty();
    }
  }
}

function clearSearchInput() {
  const input = document.getElementById('searchKeyword');
  if (input) {
    input.value = '';
    input.focus();
  }
  const clearBtn = document.getElementById('clearSearchInputBtn');
  if (clearBtn) clearBtn.classList.add('hidden');
  restoreAozoraCatalogIfEmpty();
  persistLastSearchState(null);
}

function restoreAozoraCatalogIfEmpty() {
  const input = document.getElementById('searchKeyword');
  const val = input ? input.value.trim() : '';
  if (!val) {
    setExclusiveKeywordSearchMode(false);
  }
}
window.restoreAozoraCatalogIfEmpty = restoreAozoraCatalogIfEmpty;

function saveRecentSearch(kw) {
  if (!kw || typeof kw !== 'string') return;
  const clean = kw.trim();
  if (!clean || clean.length < 2) return;
  try {
    let searches = JSON.parse(localStorage.getItem('narou_recent_searches') || '[]');
    searches = searches.filter(s => s.toLowerCase() !== clean.toLowerCase());
    searches.unshift(clean);
    if (searches.length > 8) searches = searches.slice(0, 8);
    localStorage.setItem('narou_recent_searches', JSON.stringify(searches));
    renderRecentSearches();
  } catch (e) {}
}

function renderRecentSearches() {
  const container = document.getElementById('recentSearchHistoryContainer');
  const chipsContainer = document.getElementById('recentSearchChips');
  if (!container || !chipsContainer) return;

  try {
    const searches = JSON.parse(localStorage.getItem('narou_recent_searches') || '[]');
    if (!searches || searches.length === 0) {
      container.classList.add('hidden');
      chipsContainer.innerHTML = '';
      return;
    }

    container.classList.remove('hidden');
    chipsContainer.innerHTML = searches.map((kw, idx) => `
      <div class="recent-search-item inline-flex items-center space-x-1 px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300 text-xs hover:bg-slate-700 transition">
        <span onclick="applyRecentSearch('${escapeHtml(kw)}')" class="cursor-pointer font-medium">${escapeHtml(kw)}</span>
        <button onclick="removeRecentSearch(${idx}); event.stopPropagation();" class="text-slate-500 hover:text-red-400 text-[10px] ml-1 p-0.5">✕</button>
      </div>
    `).join('');
  } catch (e) {}
}

function applyRecentSearch(kw) {
  vibrateFeedback(10);
  const input = document.getElementById('searchKeyword');
  if (input) {
    input.value = kw;
    onSearchKeywordInput(kw);
  }
  executeSearch(1);
}

function removeRecentSearch(index) {
  try {
    let searches = JSON.parse(localStorage.getItem('narou_recent_searches') || '[]');
    searches.splice(index, 1);
    localStorage.setItem('narou_recent_searches', JSON.stringify(searches));
    renderRecentSearches();
  } catch (e) {}
}

function clearRecentSearches() {
  try {
    localStorage.removeItem('narou_recent_searches');
    renderRecentSearches();
  } catch (e) {}
}

const LAST_SEARCH_STORAGE_KEY = 'narou_last_search_state_v1';

function collectSearchConditions() {
  const advPanel = document.getElementById('advancedFilterPanel');
  return {
    site: state.selectedSearchSite || 'narou',
    keyword: document.getElementById('searchKeyword')?.value || '',
    page: state.searchPage || 1,
    advancedOpen: !!(advPanel && !advPanel.classList.contains('hidden')),
    aozoraAuthorFilter: currentAozoraAuthorFilter || 'all',
    filters: {
      order: document.getElementById('filterOrder')?.value || 'hyoka',
      biggenre: document.getElementById('filterBigGenre')?.value || '',
      genre: document.getElementById('filterGenre')?.value || '',
      novel_type: document.getElementById('filterType')?.value || '',
      minlen: document.getElementById('filterMinLen')?.value || '',
      maxlen: document.getElementById('filterMaxLen')?.value || '',
      notword: document.getElementById('filterNotWord')?.value || '',
      isr15: !!document.getElementById('chkR15')?.checked,
      istensei: !!document.getElementById('chkTensei')?.checked,
      istenni: !!document.getElementById('chkTenni')?.checked,
      iszankoku: !!document.getElementById('chkZankoku')?.checked,
      isbl: !!document.getElementById('chkBL')?.checked,
      isgl: !!document.getElementById('chkGL')?.checked
    }
  };
}

function applySearchConditions(cond) {
  if (!cond) return;
  let site = cond.site || 'narou';
  if (site === 'auto' || !SITE_DEFINITIONS[site]) site = 'narou';
  if (typeof selectSearchSite === 'function') {
    selectSearchSite(site);
  } else {
    state.selectedSearchSite = site;
  }

  const kw = document.getElementById('searchKeyword');
  if (kw) {
    kw.value = cond.keyword || '';
    onSearchKeywordInput(kw.value);
  }

  const f = cond.filters || {};
  const setVal = (id, value) => {
    const el = document.getElementById(id);
    if (el && value != null) el.value = value;
  };
  const setChk = (id, checked) => {
    const el = document.getElementById(id);
    if (el) el.checked = !!checked;
  };
  setVal('filterOrder', f.order || 'hyoka');
  setVal('filterBigGenre', f.biggenre || '');
  setVal('filterGenre', f.genre || '');
  setVal('filterType', f.novel_type || '');
  setVal('filterMinLen', f.minlen || '');
  setVal('filterMaxLen', f.maxlen || '');
  setVal('filterNotWord', f.notword || '');
  setChk('chkR15', f.isr15);
  setChk('chkTensei', f.istensei);
  setChk('chkTenni', f.istenni);
  setChk('chkZankoku', f.iszankoku);
  setChk('chkBL', f.isbl);
  setChk('chkGL', f.isgl);

  if (site === 'aozora' && cond.aozoraAuthorFilter) {
    currentAozoraAuthorFilter = cond.aozoraAuthorFilter;
    if (typeof filterAozoraAuthor === 'function') {
      filterAozoraAuthor(cond.aozoraAuthorFilter, { preserveKeywordSearch: !!(cond.keyword && String(cond.keyword).trim()) });
    }
  }

  if (cond.advancedOpen && site === 'narou') {
    const panel = document.getElementById('advancedFilterPanel');
    const chevron = document.getElementById('filterChevron');
    if (panel) panel.classList.remove('hidden');
    if (chevron) chevron.style.transform = 'rotate(180deg)';
  }

  state.searchPage = cond.page || 1;
}

function slimNovelsForSearchCache(novels) {
  return (novels || []).slice(0, 20).map((n) => ({
    ncode: n.ncode,
    title: n._orig_title || n.title,
    _orig_title: n._orig_title || n.title,
    author: n._orig_author || n.author,
    _orig_author: n._orig_author || n.author,
    story: String(n._orig_story || n.story || n.synopsis || '').slice(0, 400),
    _orig_story: String(n._orig_story || n.story || n.synopsis || '').slice(0, 400),
    synopsis: String(n._orig_story || n.synopsis || n.story || '').slice(0, 400),
    opening: String(n._orig_opening || n.opening || '').slice(0, 300),
    _orig_opening: String(n._orig_opening || n.opening || '').slice(0, 300),
    opening_label: n.opening_label || '',
    genre_name: n.genre_name,
    status_text: n.status_text,
    keywords: Array.isArray(n.keywords) ? n.keywords.slice(0, 8) : [],
    general_all_no: n.general_all_no,
    total_episodes: n.total_episodes,
    length: n.length,
    global_point: n.global_point,
    fav_count: n.fav_count,
    site: n.site,
    site_name: n.site_name
  }));
}

function persistLastSearchState(resultsData = null) {
  try {
    const prevRaw = localStorage.getItem(LAST_SEARCH_STORAGE_KEY);
    let prev = null;
    try { prev = prevRaw ? JSON.parse(prevRaw) : null; } catch (_) { prev = null; }

    const payload = {
      ...collectSearchConditions(),
      results: resultsData
        ? {
            total_count: resultsData.total_count || 0,
            novels: slimNovelsForSearchCache(resultsData.novels)
          }
        : (prev?.results || null),
      savedAt: Date.now()
    };
    localStorage.setItem(LAST_SEARCH_STORAGE_KEY, JSON.stringify(payload));
  } catch (e) {
    console.warn('[Search] 条件の保存に失敗:', e);
  }
}

function restoreLastSearchState() {
  try {
    const raw = localStorage.getItem(LAST_SEARCH_STORAGE_KEY);
    if (!raw) return false;
    const data = JSON.parse(raw);
    if (!data || typeof data !== 'object') return false;

    applySearchConditions(data);

    const hasSavedKeyword = !!(data.keyword && String(data.keyword).trim());
    if (hasSavedKeyword && data.results && Array.isArray(data.results.novels)) {
      state.searchPage = data.page || 1;
      setExclusiveKeywordSearchMode(true);
      renderSearchResults(data.results);
      return true;
    }

    if (!hasSavedKeyword) {
      setExclusiveKeywordSearchMode(false);
    }

    // 条件のみ復元（結果なし）でもUIは前回どおりにする
    persistLastSearchState(null);
    return true;
  } catch (e) {
    console.warn('[Search] 条件の復元に失敗:', e);
    return false;
  }
}

function applyQuickDiscovery(type) {
  vibrateFeedback(15);
  const keywordInput = document.getElementById('searchKeyword');
  if (keywordInput) {
    keywordInput.value = '';
    onSearchKeywordInput('');
  }

  if (type === 'aozora') {
    selectSearchSite('aozora');
    const aozoraSec = document.getElementById('aozoraCatalogSection');
    if (aozoraSec) aozoraSec.scrollIntoView({ behavior: 'smooth', block: 'start' });
    return;
  }

  // なろうサイトへ切り替え
  if (state.selectedSearchSite !== 'narou') {
    selectSearchSite('narou');
  }

  const orderSelect = document.getElementById('filterOrder');
  const typeSelect = document.getElementById('filterType');
  const genreSelect = document.getElementById('filterGenre');
  const bigGenreSelect = document.getElementById('filterBigGenre');

  if (orderSelect) orderSelect.value = 'hyoka';
  if (typeSelect) typeSelect.value = '';
  if (genreSelect) genreSelect.value = '';
  if (bigGenreSelect) bigGenreSelect.value = '';

  if (type === 'hyoka') {
    if (orderSelect) orderSelect.value = 'hyoka';
  } else if (type === 'daily') {
    if (orderSelect) orderSelect.value = 'daily_point';
  } else if (type === 'weekly') {
    if (orderSelect) orderSelect.value = 'weekly_point';
  } else if (type === 'completed') {
    if (typeSelect) typeSelect.value = 'er';
  } else if (type === 'isekai') {
    if (genreSelect) genreSelect.value = '201'; // ハイファンタジー
  } else if (type === 'gendai') {
    if (genreSelect) genreSelect.value = '202'; // ローファンタジー
  }

  executeSearch(1);
}

function applyTrendTag(tag) {
  vibrateFeedback(10);
  if (tag === '太宰治' || tag === '夏目漱石') {
    if (state.selectedSearchSite === 'aozora') {
      filterAozoraAuthor(tag);
      return;
    }
  }
  
  if (state.selectedSearchSite === 'aozora') {
    selectSearchSite('narou');
  }

  const keywordInput = document.getElementById('searchKeyword');
  if (keywordInput) {
    keywordInput.value = tag;
    onSearchKeywordInput(tag);
  }
  executeSearch(1);
}

// グローバル公開
window.onSearchKeywordInput = onSearchKeywordInput;
window.clearSearchInput = clearSearchInput;
window.saveRecentSearch = saveRecentSearch;
window.renderRecentSearches = renderRecentSearches;
window.applyRecentSearch = applyRecentSearch;
window.removeRecentSearch = removeRecentSearch;
window.clearRecentSearches = clearRecentSearches;
window.applyQuickDiscovery = applyQuickDiscovery;
window.applyTrendTag = applyTrendTag;
window.restoreLastSearchState = restoreLastSearchState;
window.persistLastSearchState = persistLastSearchState;

async function executeSearch(page = 1) {
  state.searchPage = page;
  const keywordInput = document.getElementById('searchKeyword');
  const rawKeyword = keywordInput ? keywordInput.value.trim() : '';
  const loadingEl = document.getElementById('searchLoading');
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';

  // URL直接入力による検索・読込は廃止（ライセンス遵守）
  if (looksLikeNovelPageUrl(rawKeyword)) {
    const urlWarnMsg = effectiveLang === 'ja'
      ? '著作権および各小説サイトの利用規約を遵守するため、外部Web小説サイトの直接読み込みは停止いたしました。青空文庫または「文書流し込み」をご利用ください。'
      : 'Direct loading of external web novel URLs is disabled for copyright compliance. Please use Aozora Bunko or Document Import.';
    showToast(urlWarnMsg, 'warning');
    if (loadingEl) loadingEl.classList.add('hidden');
    return;
  }

  if (rawKeyword) {
    saveRecentSearch(rawKeyword);
  }

  const resultsList = document.getElementById('novelResultsList');
  const searchMeta = document.getElementById('searchMeta');
  const paginationControls = document.getElementById('paginationControls');

  // キーワードが空のまま青空文庫で検索ボタンを押した場合は、通常カタログ表示に戻して終了（重複一覧を出さない）
  if (!rawKeyword && state.selectedSearchSite !== 'document') {
    if (loadingEl) loadingEl.classList.add('hidden');
    setExclusiveKeywordSearchMode(false);
    renderAozoraCatalog(currentAozoraAuthorFilter || 'all');
    return;
  }

  // キーワード検索時は排他的表示モードを有効化（ランダム5作品・気分検索・名作カタログ・文豪タグ等を非表示）
  if (rawKeyword) {
    setExclusiveKeywordSearchMode(true);
  } else {
    setExclusiveKeywordSearchMode(false);
  }

  if (loadingEl) loadingEl.classList.remove('hidden');
  if (resultsList) resultsList.innerHTML = '';
  if (searchMeta) searchMeta.classList.add('hidden');
  if (paginationControls) paginationControls.classList.add('hidden');

  // 1. ローカル文書モードの検索
  if (state.selectedSearchSite === 'document') {
    try {
      const res = await apiFetch(`/api/novels/search?provider=document&word=${encodeURIComponent(rawKeyword)}&page=${page}&limit=20`);
      if (res.ok) {
        const data = await res.json();
        if (loadingEl) loadingEl.classList.add('hidden');
        renderSearchResults(data);
        return;
      }
    } catch (e) {
      console.warn('[Search] Document search error:', e);
    }
    if (loadingEl) loadingEl.classList.add('hidden');
    renderSearchResults({ novels: [], total_count: 0 });
    return;
  }

  // 2. 青空文庫モードの検索（多言語クエリ自動検出＆日本語翻訳検索）
  let queryInfo = { jpKeyword: rawKeyword, detectedLang: 'ja', isTranslated: false, origKeyword: rawKeyword };
  if (typeof resolveJapaneseQueryFromMultilingualQueryAsync === 'function' && rawKeyword) {
    queryInfo = await resolveJapaneseQueryFromMultilingualQueryAsync(rawKeyword);
  }
  window.__lastSearchQueryInfo = queryInfo;

  const effectiveSearchWord = queryInfo.isTranslated ? queryInfo.jpKeyword : rawKeyword;
  const serverKeyword = effectiveSearchWord;

  // ローカル多言語カタログから該当作品を抽出（作品名・作家名のみを対象に排他的マッチング）
  const masterList = (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS) && window.AOZORA_MASTER_WORKS.length > 0)
    ? window.AOZORA_MASTER_WORKS
    : (typeof AOZORA_MASTER_WORKS !== 'undefined' && Array.isArray(AOZORA_MASTER_WORKS) ? AOZORA_MASTER_WORKS : AOZORA_FALLBACK_WORKS);

  const toHiraExec = (s) => String(s || '').replace(/[\u30a1-\u30f6]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0x60));
  const matchesTokensStrict = (titleStr, authorStr, queryStr) => {
    if (!queryStr) return false;
    const tokens = queryStr.toLowerCase().split(/[\s　]+/).filter(Boolean);
    if (tokens.length === 0) return false;
    const tLow = String(titleStr || '').toLowerCase();
    const aLow = String(authorStr || '').toLowerCase();
    const tHira = toHiraExec(tLow.replace(/[\s　]+/g, ''));
    const aHira = toHiraExec(aLow.replace(/[\s　]+/g, ''));
    return tokens.every(tok => {
      const tokHira = toHiraExec(tok);
      return tLow.includes(tok) || aLow.includes(tok) || tHira.includes(tokHira) || aHira.includes(tokHira);
    });
  };

  let localMultiMatched = [];
  if (rawKeyword && Array.isArray(masterList)) {
    const kw = rawKeyword.toLowerCase();
    const jpKw = (queryInfo.jpKeyword || '').toLowerCase();
    localMultiMatched = masterList.filter(w => {
      if (!w) return false;
      const multiMatch = (typeof matchesAozoraMultilingualSearch === 'function') ? matchesAozoraMultilingualSearch(w, kw) : false;
      const directMatch = matchesTokensStrict(w.title, w.author, kw) || (jpKw && matchesTokensStrict(w.title, w.author, jpKw));
      return directMatch || multiMatch;
    });
  }

  try {
    // サーバーまたはクライアントの青空文庫検索APIを試行
    const res = await apiFetch(`/api/aozora/search?keyword=${encodeURIComponent(serverKeyword)}&page=${page}&limit=20`);
    if (res && res.ok) {
      const data = await res.json();
      const works = data.works || data.novels || [];
      const seenIds = new Set();
      const mergedWorks = [];

      // 多言語・プリセットマッチした代表作を先頭にマージ（1ページ目のみ）
      if (page === 1) {
        localMultiMatched.forEach(lw => {
          const lid = lw.id || lw.ncode;
          if (lid && !seenIds.has(lid)) {
            seenIds.add(lid);
            mergedWorks.push(lw);
          }
        });
      }
      works.forEach(w => {
        const wid = w.ncode || w.novel_id || w.id;
        if (wid && !seenIds.has(wid)) {
          seenIds.add(wid);
          mergedWorks.push(w);
        }
      });

      const novelResults = mergedWorks.map(w => {
        const loc = (typeof getLocalizedAozoraWork === 'function') ? getLocalizedAozoraWork(w, effectiveLang) : null;
        return {
          ncode: w.ncode || w.novel_id || w.id,
          novel_id: w.ncode || w.novel_id || w.id,
          title: loc ? loc.displayTitle : (w.title || '無題'),
          _orig_title: w._orig_title || w.title || '無題',
          author: loc ? loc.displayAuthor : (w.author || '作者不詳'),
          _orig_author: w._orig_author || w.author || '作者不詳',
          story: loc ? loc.displaySynopsis : (w.synopsis || ''),
          _orig_story: w._orig_story || w.synopsis || '',
          synopsis: loc ? loc.displaySynopsis : (w.synopsis || ''),
          opening: (loc && loc.displayOpening) || w.opening || '',
          _orig_opening: w._orig_opening || w.sample_text || w.opening || '',
          opening_label: (loc && loc.openingLabel) || '',
          quotes: w.quotes || [],
          characters: w.characters || [],
          matchSnippet: w.matchSnippet || '',
          genre_name: loc ? loc.displayGenre : (w.genre || '日本文学'),
          status_text: effectiveLang === 'ja' ? '名作文学' : 'Classic',
          keywords: (loc && loc.displayKeywords) ? [...loc.displayKeywords, loc.displayAuthor] : ['青空文庫', 'パブリックドメイン', w.author || '日本文学'],
          general_all_no: 1,
          total_episodes: 1,
          length: parseInt(String(w.lengthText || '').replace(/[^0-9]/g, '')) || 5000,
          global_point: 99999,
          fav_count: 8888,
          site: 'aozora',
          site_name: effectiveLang === 'ja' ? '青空文庫' : 'Aozora Bunko'
        };
      });
      if (loadingEl) loadingEl.classList.add('hidden');
      renderSearchResults({ novels: novelResults, total_count: Math.max(data.total_count || 0, novelResults.length) });
      return;
    }
  } catch (e) {
    console.warn('[Search] Aozora search error, falling back to local index/catalog:', e);
  }

  // フォールバック: ローカル全作品インデックスおよび名作文学カタログから直接検索（作品名・作家名による排他的マッチング）
  let fallbackResults = [];
  try {
    const allIdx = await loadAozoraIndexIfNeeded();
    if (rawKeyword && Array.isArray(allIdx) && allIdx.length > 0) {
      const kw = rawKeyword.toLowerCase();
      const jpKw = (queryInfo.jpKeyword || '').toLowerCase();
      const summariesDict = (typeof window !== 'undefined' && window.AOZORA_SUMMARIES_DICT) ? window.AOZORA_SUMMARIES_DICT : null;

      const matchedIdx = allIdx.filter(item => {
        return matchesTokensStrict(item.title, item.author, kw) || (jpKw && matchesTokensStrict(item.title, item.author, jpKw));
      });
      if (matchedIdx.length > 0) {
        fallbackResults = matchedIdx.slice(0, 40).map(w => {
          const sumMeta = summariesDict ? (summariesDict[w.title] || summariesDict[w.title.replace(/[\s　]+/g, '')]) : null;
          return {
            ncode: w.ncode || w.id,
            novel_id: w.ncode || w.id,
            title: w.title || '無題',
            _orig_title: w.title || '無題',
            author: w.author || '作者不詳',
            _orig_author: w.author || '作者不詳',
            story: sumMeta ? sumMeta.synopsis : (w.synopsis || ''),
            _orig_story: sumMeta ? sumMeta.synopsis : (w.synopsis || ''),
            synopsis: sumMeta ? sumMeta.synopsis : (w.synopsis || ''),
            opening: sumMeta ? sumMeta.opening : (w.opening || ''),
            _orig_opening: sumMeta ? sumMeta.opening : (w.opening || ''),
            opening_label: '',
            quotes: sumMeta ? sumMeta.quotes : (w.quotes || []),
            characters: sumMeta ? sumMeta.characters : (w.characters || []),
            matchSnippet: w.matchSnippet || '',
            genre_name: (sumMeta && sumMeta.category) || w.genre || '青空文庫',
            status_text: effectiveLang === 'ja' ? '名作文学' : 'Classic',
            keywords: ['青空文庫', 'パブリックドメイン', w.author].filter(Boolean),
            general_all_no: 1,
            total_episodes: 1,
            length: 5000,
            global_point: 99999,
            fav_count: 8888,
            site: 'aozora',
            site_name: effectiveLang === 'ja' ? '青空文庫' : 'Aozora Bunko'
          };
        });
      }
    }
  } catch (err) {}

  if (fallbackResults.length === 0) {
    let filtered = rawKeyword ? localMultiMatched : masterList;
    fallbackResults = (filtered || []).map(w => {
      const loc = (typeof getLocalizedAozoraWork === 'function') ? getLocalizedAozoraWork(w, effectiveLang) : null;
      const dispYear = effectiveLang === 'ja' ? (w.year || '') : String(w.year || '').replace(/年$/, '');
      return {
        ncode: w.id || w.ncode,
        novel_id: w.id || w.ncode,
        title: loc ? loc.displayTitle : (w.title || '無題'),
        _orig_title: w.title || '無題',
        author: loc ? loc.displayAuthor : (w.author || '作者不詳'),
        _orig_author: w.author || '作者不詳',
        story: loc ? loc.displaySynopsis : (w.synopsis || ''),
        _orig_story: w.synopsis || '',
        synopsis: loc ? loc.displaySynopsis : (w.synopsis || ''),
        opening: (loc && loc.displayOpening) || w.opening || '',
        _orig_opening: w.sample_text || w.opening || '',
        opening_label: (loc && loc.openingLabel) || '',
        quotes: w.quotes || [],
        characters: w.characters || [],
        matchSnippet: w.matchSnippet || '',
        genre_name: loc ? loc.displayGenre : (w.genre || '青空文庫名作'),
        status_text: effectiveLang === 'ja' ? '短編・名作' : 'Classic',
        keywords: (loc && loc.displayKeywords) ? [...loc.displayKeywords, loc.displayAuthor, dispYear].filter(Boolean) : ['青空文庫', 'パブリックドメイン', w.author, w.year].filter(Boolean),
        general_all_no: 1,
        total_episodes: 1,
        length: parseInt(String(w.lengthText || '').replace(/[^0-9]/g, '')) || 5000,
        global_point: 99999,
        fav_count: 8888,
        site: 'aozora',
        site_name: effectiveLang === 'ja' ? '青空文庫' : 'Aozora Bunko'
      };
    });
  }

  if (loadingEl) loadingEl.classList.add('hidden');
  renderSearchResults({ novels: fallbackResults, total_count: fallbackResults.length });
}

function renderSearchResults(data) {
  const listEl = document.getElementById('novelResultsList');
  if (!listEl) return;
  listEl.classList.remove('hidden');
  listEl.innerHTML = '';

  const rawKeyword = (document.getElementById('searchKeyword')?.value || '').trim();
  if (rawKeyword && state.selectedSearchSite !== 'document') {
    setExclusiveKeywordSearchMode(true);
  }

  const queryInfo = window.__lastSearchQueryInfo || { detectedLang: 'ja', isTranslated: false, jpKeyword: rawKeyword };
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  // 結果を表示・翻訳すべき言語（外国語入力ならその言語、または外国語UIならそのUI言語）
  const targetOutputLang = (queryInfo.isTranslated && queryInfo.detectedLang && queryInfo.detectedLang !== 'ja')
    ? queryInfo.detectedLang
    : (effectiveLang !== 'ja' ? effectiveLang : 'ja');
  const isJa = targetOutputLang === 'ja';
  const superModeOn = isJa && typeof isAozoraModernSuperTranslateEnabled === 'function' && isAozoraModernSuperTranslateEnabled();
  const uiStr = AOZORA_UI_STRINGS_I18N[effectiveLang] || AOZORA_UI_STRINGS_I18N.ja;

  const total = data.total_count || 0;
  const totalCountEl = document.getElementById('totalCount');
  const currentPageNumEl = document.getElementById('currentPageNum');
  const searchMeta = document.getElementById('searchMeta');

  if (totalCountEl) totalCountEl.textContent = total.toLocaleString();
  if (currentPageNumEl) currentPageNumEl.textContent = state.searchPage;
  if (searchMeta) {
    searchMeta.classList.remove('hidden');
    // 多言語自動翻訳バッジの動的生成
    let metaNotice = '';
    if (queryInfo.isTranslated && queryInfo.jpKeyword && queryInfo.jpKeyword.toLowerCase() !== rawKeyword.toLowerCase()) {
      if (effectiveLang === 'ja') {
        metaNotice = `<span class="ml-2 px-2 py-0.5 rounded-full bg-blue-900/60 text-blue-300 text-[10px] font-semibold border border-blue-500/30">🌐 「${escapeHtml(rawKeyword)}」を「${escapeHtml(queryInfo.jpKeyword)}」に自動翻訳して検索</span>`;
      } else {
        metaNotice = `<span class="ml-2 px-2 py-0.5 rounded-full bg-blue-900/60 text-blue-300 text-[10px] font-semibold border border-blue-500/30">🌐 Translated "${escapeHtml(rawKeyword)}" → "${escapeHtml(queryInfo.jpKeyword)}"</span>`;
      }
    }
    const clearLabel = effectiveLang === 'ja' ? '✕ 検索をクリアして一覧へ戻る' : '✕ Clear search & back to catalog';
    const countContainer = searchMeta.querySelector('div:first-child');
    if (countContainer) {
      const kwBadge = rawKeyword
        ? `<span class="ml-1.5 text-slate-300 font-semibold">「${escapeHtml(rawKeyword)}」</span>`
        : '';
      countContainer.innerHTML = `検索結果${kwBadge}: <span id="totalCount" class="font-bold text-blue-400">${total.toLocaleString()}</span> 件${metaNotice}`;
    }
    const pagInfo = document.getElementById('paginationInfo');
    if (pagInfo && rawKeyword) {
      pagInfo.innerHTML = `<div class="flex items-center space-x-2.5"><span>ページ <span id="currentPageNum">${state.searchPage}</span></span><button type="button" onclick="clearSearchInput()" class="px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-emerald-300 border border-emerald-500/40 text-[11px] font-bold transition active:scale-95">${escapeHtml(clearLabel)}</button></div>`;
    }
  }

  // 検索条件＋結果を永続化（再起動後に復元）
  persistLastSearchState(data);

  if (!data.novels || data.novels.length === 0) {
    window.__lastSearchResultsMap = {};
    const inputVal = (document.getElementById('searchKeyword')?.value || '').trim();
    const emptyMsg = isJa
      ? (inputVal
          ? `「${inputVal}」に一致する青空文庫作品は見つかりませんでした。\n※作品名（例: 走れメロス, 羅生門, こころ, 山月記, 銀河鉄道の夜）や文豪名（例: 太宰治, 芥川龍之介, 夏目漱石, 宮沢賢治）で検索してください。\n※お手持ちの小説・文章を聴く場合は、上の「自分の文章・ファイル読込」をご利用ください。`
          : '青空文庫の作品名や作家名を入力して検索してください。')
      : ({ en: 'No matching works found. Please search by classic title or author (e.g. Dazai, Akutagawa, Soseki).', zh: '未找到符合条件的作品，请尝试使用经典作品名或作家名（如太宰治、芥川龙之介）搜索。', ko: '조건에 맞는 작품을 찾을 수 없습니다. 작가명 또는 작품명으로 검색해 보세요.', es: 'No se encontraron obras coincidentes.', fr: 'Aucune œuvre correspondante trouvée.', pt: 'Nenhuma obra correspondente encontrada.' }[effectiveLang] || 'No matching works found.');
    listEl.innerHTML = `
      <div class="bg-slate-900 border border-slate-800 rounded-2xl p-6 sm:p-8 text-center text-slate-300 space-y-2">
        <i class="ph ph-magnifying-glass text-3xl text-emerald-400 inline-block mb-1"></i>
        <p class="text-xs sm:text-sm font-medium whitespace-pre-line leading-relaxed">${escapeHtml(emptyMsg)}</p>
      </div>
    `;
    return;
  }

  const blockedIds = (typeof getBlockedNovelIds === 'function') ? getBlockedNovelIds() : new Set();
  const visibleNovels = data.novels.filter((n) => !blockedIds.has(String(n.ncode || '').toLowerCase()));
  if (visibleNovels.length === 0) {
    window.__lastSearchResultsMap = {};
    const blockedEmptyMsg = isJa
      ? '表示できる作品がありません（ブロック中の作品のみの可能性があります）。'
      : 'No works available to display.';
    listEl.innerHTML = `
      <div class="bg-slate-900 border border-slate-800 rounded-2xl p-8 text-center text-slate-400">
        <p class="text-sm">${escapeHtml(blockedEmptyMsg)}</p>
      </div>
    `;
    return;
  }

  const detailBtnLabelByLang = { ja: '詳細', en: 'Preview', zh: '详情', ko: '상세', es: 'Detalle', fr: 'Détails', pt: 'Detalhes' };
  const reportBtnLabelByLang = { ja: '通報', en: 'Report', zh: '举报', ko: '신고', es: 'Reportar', fr: 'Signaler', pt: 'Denunciar' };
  const authorPrefixByLang = { ja: '作者:', en: 'Author:', zh: '作者:', ko: '작가:', es: 'Autor:', fr: 'Auteur :', pt: 'Autor:' };
  const classicStatusByLang = { ja: '短編・名作', en: 'Classic', zh: '经典名作', ko: '명작 문학', es: 'Clásico', fr: 'Classique', pt: 'Clássico' };

  visibleNovels.forEach(novel => {
    // 元の日本語フィールドを非破壊で保持
    if (!novel._orig_title) novel._orig_title = novel.title || '';
    if (!novel._orig_author) novel._orig_author = novel.author || '';
    if (!novel._orig_story) novel._orig_story = novel.story || novel.synopsis || '';
    if (!novel._orig_opening && novel.opening) novel._orig_opening = novel.opening;

    const loc = (typeof getLocalizedAozoraWork === 'function') ? getLocalizedAozoraWork(novel, effectiveLang) : null;
    const dispTitle = (loc && (isJa || loc.isTranslatedPreset)) ? (loc.displayTitle || novel._orig_title) : novel._orig_title;
    const dispAuthor = loc ? (loc.displayAuthor || novel._orig_author) : novel._orig_author;
    const dispSynopsis = (loc && (isJa || loc.isTranslatedPreset)) ? (loc.displaySynopsis || novel._orig_story) : novel._orig_story;
    const dispOpening = (loc && loc.displayOpening) ? loc.displayOpening : (novel._orig_opening || novel.opening || '');
    const openingLabel = (loc && loc.openingLabel) || (isJa ? '冒頭プレビュー:' : 'Opening Preview:');
    const dispGenre = loc ? loc.displayGenre : (novel.genre_name || (isJa ? '小説' : 'Literature'));
    const dispStatus = isJa ? (novel.status_text || '短編・名作') : (classicStatusByLang[effectiveLang] || 'Classic');
    const dispKeywords = (loc && loc.displayKeywords)
      ? [...loc.displayKeywords, dispAuthor]
      : (novel.keywords || []);

    const card = document.createElement('div');
    card.className = 'bg-slate-900 border border-slate-800 hover:border-slate-700 rounded-2xl p-4 sm:p-5 transition shadow-lg flex flex-col justify-between';
    const normNcode = String(novel.ncode || '').toLowerCase();
    card.setAttribute('data-novel-card', normNcode);

    const keywordsHtml = dispKeywords.filter(Boolean).slice(0, 5).map(k => `
      <span class="px-2 py-0.5 rounded-md bg-slate-800 text-[10px] text-slate-300">#${escapeHtml(isJa ? k : String(k).replace(/年$/, ''))}</span>
    `).join('');

    const siteKey = novel.site || detectSiteFromUrlOrNcode(novel.ncode);
    const siteBadgeHtml = getSiteBadgeHtml(siteKey);
    const epUnit = isJa ? '話' : ' ep';
    const charUnit = isJa ? '字' : ' chars';

    card.innerHTML = `
      <div onclick="openWebPreviewModal('${novel.ncode}', '${escapeHtml(dispTitle)}', window.__lastSearchResultsMap && window.__lastSearchResultsMap['${novel.ncode}'])" class="cursor-pointer">
        <div class="flex flex-wrap items-center gap-1.5 mb-2">
          ${siteBadgeHtml}
          <span class="px-2 py-0.5 rounded text-[10px] font-semibold ${novel.status_text === '完結済' ? 'bg-emerald-900/60 text-emerald-300' : novel.status_text === '短編' ? 'bg-amber-900/60 text-amber-300' : 'bg-blue-900/60 text-blue-300'}">
            ${escapeHtml(dispStatus)}
          </span>
          <span class="px-2 py-0.5 rounded text-[10px] bg-slate-800 text-slate-300 font-medium">
            ${escapeHtml(dispGenre)}
          </span>
          <span class="text-[11px] text-slate-400 ml-auto font-mono">
            ${novel.general_all_no ? `${novel.general_all_no}${epUnit}` : ''} (${(novel.length || 0).toLocaleString()}${charUnit})
          </span>
        </div>

        <h3 class="text-base sm:text-lg font-bold text-slate-100 hover:text-blue-400 transition leading-snug" data-search-card-title="${escapeHtml(normNcode)}">
          ${escapeHtml(dispTitle)}
        </h3>
        <p class="text-xs text-slate-400 mt-1">${escapeHtml(authorPrefixByLang[effectiveLang] || 'Author:')} <span class="text-slate-300 font-medium" data-search-card-author="${escapeHtml(normNcode)}">${escapeHtml(dispAuthor)}</span></p>

        <p class="text-xs text-slate-300 mt-2 line-clamp-3 leading-relaxed" data-search-card-synopsis="${escapeHtml(normNcode)}">
          ${escapeHtml(dispSynopsis)}
        </p>

        ${novel.matchSnippet ? `
          <div class="mt-2 px-2.5 py-1.5 rounded-xl bg-amber-950/70 border border-amber-500/30 text-[11px] text-amber-200 leading-relaxed shadow-sm">
            <span class="text-[10px] font-bold text-amber-400 mr-1"><i class="ph-bold ph-text-align-left mr-0.5"></i>本文抜粋:</span>
            <span class="line-clamp-2">${escapeHtml(novel.matchSnippet)}</span>
          </div>
        ` : ''}

        ${(novel.quotes && novel.quotes.length > 0) ? `
          <div class="mt-1.5 px-2.5 py-1 rounded-lg bg-indigo-950/50 border border-indigo-500/20 text-[10.5px] text-indigo-200 flex items-center gap-1">
            <span class="text-[10px] font-bold text-indigo-400 shrink-0"><i class="ph-fill ph-chat-circle-quote mr-0.5"></i>名言:</span>
            <span class="italic truncate">「${escapeHtml(novel.quotes[0])}」</span>
          </div>
        ` : ''}

        ${(novel.characters && novel.characters.length > 0) ? `
          <div class="mt-1.5 text-[10.5px] text-slate-400 flex items-center gap-1 truncate">
            <span class="text-[10px] font-bold text-slate-500 shrink-0"><i class="ph-bold ph-users mr-0.5"></i>登場人物:</span>
            <span class="text-slate-300 truncate">${escapeHtml(novel.characters.join('、'))}</span>
          </div>
        ` : ''}

        <div class="mt-2 px-2.5 py-1.5 rounded-xl bg-slate-950/80 border border-emerald-500/20 text-[11px] text-emerald-100/90 leading-relaxed ${dispOpening ? '' : 'hidden'}" data-search-card-opening-box="${escapeHtml(normNcode)}">
          <span class="text-[10px] font-bold text-emerald-400 mr-1"><i class="ph-fill ph-quotes mr-0.5"></i>${escapeHtml(openingLabel)}</span>
          <span class="italic line-clamp-2" data-search-card-opening="${escapeHtml(normNcode)}">${escapeHtml(dispOpening)}</span>
        </div>

        <div class="flex flex-wrap gap-1 mt-2.5">
          ${keywordsHtml}
        </div>
      </div>

      <div class="mt-4 pt-3 border-t border-slate-800/80 space-y-2" onclick="event.stopPropagation()">
        <!-- 1段目: 最優先アクション「1タップで朗読」(大型フル幅ボタン) -->
        <button onclick="quickStartReading('${novel.ncode}', 1)" class="w-full h-11 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 active:from-blue-700 active:to-indigo-700 text-white rounded-xl text-xs sm:text-sm font-extrabold shadow-lg shadow-blue-600/30 transition flex items-center justify-center space-x-2 active:scale-[0.98]">
          <i class="ph-fill ph-play-circle text-lg"></i>
          <span>${escapeHtml(isJa ? '1タップで朗読をはじめる' : uiStr.btn_read)}</span>
        </button>

        <!-- 2段目: サブ操作 (目次 / 保存 / 詳細 / 通報) -->
        <div class="flex items-center justify-between gap-1.5" data-dl-actions-row>
          <div class="flex items-center gap-1.5 flex-1 min-w-0">
            <button onclick="loadNovel('${novel.ncode}')" class="flex-1 h-9 px-3 bg-slate-800 hover:bg-slate-700 text-slate-100 rounded-xl text-xs font-bold border border-slate-700 transition flex items-center justify-center space-x-1 active:scale-95">
              <i class="ph ph-list-bullets text-sm text-slate-300"></i>
              <span>${escapeHtml(uiStr.btn_toc)}</span>
            </button>
            <button data-dl-ncode="${normNcode}" onclick="downloadNovelDirect('${novel.ncode}', this)" class="h-9 px-3 bg-slate-800 hover:bg-slate-700 text-emerald-400 rounded-xl text-xs font-semibold border border-emerald-500/30 transition flex items-center space-x-1 active:scale-95 shrink-0" title="${escapeHtml(uiStr.btn_save)}">
              <i class="ph-bold ph-download-simple text-sm"></i>
              <span>${escapeHtml(uiStr.btn_save)}</span>
            </button>
            <button onclick="openWebPreviewModal('${novel.ncode}', '${escapeHtml(dispTitle)}', window.__lastSearchResultsMap && window.__lastSearchResultsMap['${novel.ncode}'])" class="h-9 px-2.5 bg-slate-800 hover:bg-slate-700 text-blue-300 rounded-xl text-xs font-medium border border-slate-700 transition flex items-center space-x-1 active:scale-95 shrink-0" title="${escapeHtml(detailBtnLabelByLang[effectiveLang] || 'Preview')}">
              <i class="ph ph-info text-sm"></i>
              <span>${escapeHtml(detailBtnLabelByLang[effectiveLang] || 'Preview')}</span>
            </button>
          </div>
          <button type="button" onclick='openUgcReportModal(${JSON.stringify({ ncode: String(novel.ncode), title: dispTitle || "", author: dispAuthor || "" })})' class="h-9 px-2.5 bg-slate-900 hover:bg-slate-800 text-slate-400 hover:text-rose-300 rounded-xl text-[11px] font-medium border border-slate-800 transition flex items-center space-x-1 active:scale-95 shrink-0" title="${escapeHtml(reportBtnLabelByLang[effectiveLang] || 'Report')}">
            <i class="ph ph-flag text-xs"></i>
            <span>${escapeHtml(reportBtnLabelByLang[effectiveLang] || 'Report')}</span>
          </button>
        </div>
      </div>
    `;
    listEl.appendChild(card);

    // 外国語入力時または外国語UI時に未翻訳の検索結果カード（上位15件まで）を入力言語／UI言語へ非同期翻訳反映
    const cardIdx = visibleNovels.indexOf(novel);
    const shouldTranslateCard = (targetOutputLang !== 'ja');
    if (shouldTranslateCard && cardIdx >= 0 && cardIdx < 15 && typeof translatePreviewTextAsync === 'function') {
      const hasJa = (s) => /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF]/.test(String(s || ''));
      const isPresetTranslated = !!(loc && loc.isTranslatedPreset);
      if (!isPresetTranslated && hasJa(novel._orig_title)) {
        translatePreviewTextAsync(novel._orig_title, targetOutputLang).then(trTitle => {
          if (!trTitle) return;
          const formattedTitle = `${trTitle} (${novel._orig_title})`;
          const tEl = card.querySelector(`[data-search-card-title="${CSS.escape(normNcode)}"]`);
          if (tEl) tEl.textContent = formattedTitle;
        }).catch(() => {});
      }
      if (!AOZORA_AUTHOR_I18N[novel._orig_author] && hasJa(novel._orig_author)) {
        translatePreviewTextAsync(novel._orig_author, targetOutputLang).then(trAuthor => {
          if (!trAuthor) return;
          const aEl = card.querySelector(`[data-search-card-author="${CSS.escape(normNcode)}"]`);
          if (aEl) aEl.textContent = `${trAuthor} (${novel._orig_author})`;
        }).catch(() => {});
      }
      if (!isPresetTranslated && hasJa(dispSynopsis)) {
        translatePreviewTextAsync(dispSynopsis, targetOutputLang).then(trSyn => {
          if (!trSyn) return;
          const sEl = card.querySelector(`[data-search-card-synopsis="${CSS.escape(normNcode)}"]`);
          if (sEl) sEl.textContent = trSyn;
        }).catch(() => {});
      }
      if (dispOpening && !isPresetTranslated && hasJa(dispOpening)) {
        translatePreviewTextAsync(dispOpening, targetOutputLang).then(trOp => {
          if (!trOp) return;
          const oEl = card.querySelector(`[data-search-card-opening="${CSS.escape(normNcode)}"]`);
          if (oEl) oEl.textContent = trOp;
        }).catch(() => {});
      }
    }
  });

  const paginationControls = document.getElementById('paginationControls');
  const prevBtn = document.getElementById('prevPageBtn');
  const nextBtn = document.getElementById('nextPageBtn');

  if (paginationControls) paginationControls.classList.remove('hidden');
  if (prevBtn) prevBtn.disabled = state.searchPage <= 1;
  if (nextBtn) nextBtn.disabled = data.novels.length < 20;

  // 検索結果をキャッシュ
  window.__lastSearchResultsMap = {};
  visibleNovels.forEach(n => { window.__lastSearchResultsMap[n.ncode] = n; });
}

function changeSearchPage(delta) {
  const newPage = state.searchPage + delta;
  if (newPage < 1) return;
  state.searchPage = newPage;
  executeSearch(newPage);
}
window.changePage = changeSearchPage;

// ==============================================
// 14. ネイティブ小説詳細 & 試し読みボトムシート (脱iframe)
// ==============================================
let modalCurrentNcode = '';
let modalSampleLoadedNcode = '';

