// 配役決定前にインターネット（Gemini知識推論 / Wikipedia）から登場人物リストを検索
async function searchNovelCharactersOnlineJs(novelTitle, author = '') {
  if (!novelTitle) return null;
  const cleanTitle = novelTitle.replace(/【[^】]+】|\[[^\]]+\]|（[^）]+）|\([^)]+\)/g, '').replace(/(?:〜|～|―|-).*$/g, '').trim();

  // 1. バックエンド API 経由で検索試行
  try {
    const res = await apiFetch('/api/narou/novel/search-characters', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        novel_title: cleanTitle || novelTitle,
        author: author || '',
        api_key: getSettingsFromStorage()?.gemini_api_key || ''
      })
    });
    if (res.ok) {
      const data = await res.json();
      if (data.success && data.characters && data.characters.length > 1) {
        return data;
      }
    }
  } catch (e) {
    console.warn('[OnlineCharSearch] Backend search error:', e);
  }

  // 2. スタンドアロン/Android クライアントサイド直接フォールバック (Wikipedia MediaWiki API)
  try {
    const queries = [`${cleanTitle}の登場人物`, `${cleanTitle} 登場人物`, cleanTitle];
    let pageTitle = null;

    for (const q of queries) {
      const searchUrl = `https://ja.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(q)}&format=json&origin=*`;
      const sRes = await fetch(searchUrl);
      if (sRes.ok) {
        const sData = await sRes.json();
        const results = sData?.query?.search || [];
        if (results.length > 0) {
          for (const r of results) {
            if (r.title.includes('登場人物') || r.title.includes('キャラクター')) {
              pageTitle = r.title;
              break;
            }
          }
          if (!pageTitle) {
            for (const r of results) {
              if (!r.title.includes(' (アニメ)') && !r.title.includes(' (漫画)')) {
                pageTitle = r.title;
                break;
              }
            }
          }
          if (!pageTitle) pageTitle = results[0]?.title;
          if (pageTitle) break;
        }
      }
    }

    if (pageTitle) {
      const secUrl = `https://ja.wikipedia.org/w/api.php?action=parse&page=${encodeURIComponent(pageTitle)}&prop=sections&format=json&origin=*`;
      const secRes = await fetch(secUrl);
      const charSections = [];
      if (secRes.ok) {
        const secData = await secRes.json();
        const sections = secData?.parse?.sections || [];
        for (const s of sections) {
          const line = s.line || '';
          if (/登場人物|主要人物|キャラクター|主人公|メイン/.test(line)) {
            charSections.push(s.index);
          }
        }
      }

      const wikitexts = [];
      if (charSections.length > 0) {
        for (const sIdx of charSections.slice(0, 4)) {
          const tUrl = `https://ja.wikipedia.org/w/api.php?action=parse&page=${encodeURIComponent(pageTitle)}&section=${sIdx}&prop=wikitext&format=json&origin=*`;
          const tRes = await fetch(tUrl);
          if (tRes.ok) {
            const tData = await tRes.json();
            wikitexts.push(tData?.parse?.wikitext?.['*'] || '');
          }
        }
      } else {
        const tUrl = `https://ja.wikipedia.org/w/api.php?action=parse&page=${encodeURIComponent(pageTitle)}&prop=wikitext&format=json&origin=*`;
        const tRes = await fetch(tUrl);
        if (tRes.ok) {
          const tData = await tRes.json();
          wikitexts.push(tData?.parse?.wikitext?.['*'] || '');
        }
      }

      const fullWiki = wikitexts.join('\n');
      const seen = new Set();
      const wikiChars = [];

      const lines = fullWiki.split('\n');
      for (const line of lines) {
        let rawName = '', desc = '';
        const mDef = line.match(/^;\s*([^:：\n]+)(?:[:：]\s*(.+))?$/);
        const mHead = line.match(/^={3,5}\s*([^=\n]+?)\s*={3,5}$/);
        const mBullet = line.match(/^\*\s*'''([^'\n]+)'''(?:[:：\s]*(.+))?$/);

        if (mDef) {
          rawName = mDef[1];
          desc = mDef[2] || '';
        } else if (mHead) {
          rawName = mHead[1];
        } else if (mBullet) {
          rawName = mBullet[1];
          desc = mBullet[2] || '';
        }

        if (rawName) {
          let cn = rawName.replace(/\[\[(?:[^|\]]*\|)?([^\]]+)\]\]/g, '$1')
                          .replace(/\{\{[^}]+\}\}/g, '')
                          .replace(/（[^）]+）|\([^)]+\)|【[^】]+】|［[^］]+］/g, '')
                          .replace(/\[\[[^\]]*/g, '')
                          .replace(/\}\}.*/g, '')
                          .replace(/^[ \t\r\n;*:・'\"\[\]{}()]+|[ \t\r\n;*:・'\"\[\]{}()]+$/g, '');
          if (cn.includes('・')) {
            const parts = cn.split('・').filter(p => p.length >= 2);
            if (parts.length > 0) cn = parts[parts.length - 1];
          }
          if (cn.includes('/')) cn = cn.split('/')[0].trim();

          if (cn.length >= 2 && cn.length <= 12 && !seen.has(cn)) {
            if (!/声 -|CV|キャスト|概要|用語|組織|魔法|スキル|世界観|あらすじ|主題歌|スタッフ|テレビアニメ|漫画|Web小説|陣営|登場人物/.test(cn)) {
              if (!CLIENT_IGNORE_SPEAKER_WORDS.has(cn)) {
                seen.add(cn);
                let gender = 'unknown';
                const knownGenders = {
                  'スバル': 'male', 'ナツキ': 'male', 'パック': 'male', 'ロム爺': 'male', 'ラインハルト': 'male', 'ユリウス': 'male', 'フェリス': 'male', 'オットー': 'male', 'ガーフィール': 'male', 'ロズワール': 'male', 'アル': 'male',
                  'エミリア': 'female', 'レム': 'female', 'ラム': 'female', 'ベアトリス': 'female', 'フェルト': 'female', 'クルシュ': 'female', 'プリシラ': 'female', 'アナスタシア': 'female', 'エキドナ': 'female', 'エルザ': 'female', 'ペトラ': 'female',
                  'リムル': 'male', 'ヴェルドラ': 'male', 'ベニマル': 'male', 'ソウエイ': 'male', 'ハクロウ': 'male', 'リグルド': 'male', 'ガビル': 'male', 'ゲルド': 'male', 'ディアブロ': 'male', 'ギィ': 'male',
                  'シズ': 'female', 'シュナ': 'female', 'シオン': 'female', 'ミリム': 'female', 'ラミリス': 'female', 'トレイニー': 'female', 'ヒナタ': 'female',
                  'ムコウダ': 'male', 'フェル': 'male', 'ドラ': 'male', 'ゴン爺': 'male', 'エルランド': 'male',
                  'スイ': 'female', 'ニンリル': 'female', 'キシャール': 'female', 'ルサールカ': 'female', 'アグニ': 'male', 'ヘファイストス': 'male'
                };
                if (knownGenders[cn]) {
                  gender = knownGenders[cn];
                } else if (/主人公|少年|青年|男性|男|彼|息子|兄|弟|父|おじさん|爺|王|皇帝|魔王/.test(desc)) {
                  gender = 'male';
                } else if (/ヒロイン|少女|女性|女|彼女|娘|姉|妹|母|お姉さん|令嬢|姫|メイド|巫女|女王|聖女/.test(desc)) {
                  gender = 'female';
                }

                wikiChars.push({
                  name: cn,
                  gender: gender,
                  voice_type: gender === 'female' ? 'female_young' : (gender === 'male' ? 'male_young' : 'female_young'),
                  role: /主人公/.test(desc) || ['スバル', 'リムル', 'ムコウダ'].includes(cn) ? 'protagonist' : ((/ヒロイン/.test(desc) || ['エミリア', 'レム', 'シズ'].includes(cn)) ? 'heroine' : 'companion'),
                  description: desc ? desc.slice(0, 100) : '公式登場人物'
                });
              }
            }
          }
        }
      }

      if (wikiChars.length > 0) {
        return {
          success: true,
          novel_title: novelTitle,
          source: `Wikipedia百科事典 (${pageTitle})`,
          characters: [
            { name: 'ナレーション', gender: 'female', voice_type: 'neutral_narration', description: '地の文' },
            ...wikiChars.slice(0, 20)
          ]
        };
      }
    }
  } catch (e) {
    console.warn('[OnlineCharSearch] Wikipedia direct fetch error:', e);
  }

  return null;
}

// ==============================================
// 複数話AIスキャンによる小説全体配役決定システム (1〜1000話)
// ==============================================
async function loadNovelFullCast(ncode, forceRefresh = false, showModal = false) {
  if (!ncode) return;
  const ncodeLower = ncode.toLowerCase();
  const scanLimit = getSettingScanEpisodes();

  const settings = getSettingsFromStorage() || {};
  const provider = getActiveCastLlmProvider(settings);
  let engineLabel = 'アプリ内包 ロジック解析';
  if (provider === 'gemini') engineLabel = `Google Gemini (${settings.gemini_model || 'gemini-3.8-flash'})`;
  else if (provider === 'openai') engineLabel = `OpenAI (${resolveOpenaiModel(settings)})`;
  else if (provider === 'claude') engineLabel = `Claude (${resolveClaudeModel(settings)})`;
  else if (provider === 'local_llm') engineLabel = `Local LLM (${sanitizeCommercialLocalLlmModel(settings.local_llm_model || 'phi4-mini')})`;
  else if (provider === 'rules') engineLabel = 'ルールベース解析エンジン';
  else if (provider === 'embedded_llm') engineLabel = 'アプリ内包 ロジック解析';

  const badge = document.getElementById('castScanStatusBadge');
  const reanalyzeBtnText = document.getElementById('castReanalyzeBtnText');
  const uiLangForCast = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  if (reanalyzeBtnText) reanalyzeBtnText.textContent = uiLangForCast === 'ja' ? 'AI解析中...' : 'Analyzing...';

  try {
    const cacheKey = `narou_novel_cast_${ncodeLower}`;
    if (!forceRefresh) {
      try {
        const cachedJson = localStorage.getItem(cacheKey);
        if (cachedJson) {
          const cachedData = JSON.parse(cachedJson);
          if (cachedData.characters && cachedData.characters.length > 0 && (cachedData.scanned_episodes || 0) >= scanLimit) {
            applyNovelCastData(cachedData);
            return;
          }
        }
      } catch (e) {}
    }

    let totalEps = state.currentNovel?.total_episodes || state.currentNovel?.episode_count || state.currentNovel?.episodes?.length || 0;
    if (totalEps <= 1 || forceRefresh) {
      try {
        const novRes = await apiFetch(`/api/narou/novel/${encodeURIComponent(ncodeLower)}`);
        if (novRes.ok) {
          const novData = await novRes.json();
          if (state.currentNovel) {
            state.currentNovel.total_episodes = novData.total_episodes || (novData.episodes || []).length || 1;
            state.currentNovel.episodes = novData.episodes || state.currentNovel.episodes;
          }
          totalEps = novData.total_episodes || (novData.episodes || []).length || 1;
        }
      } catch (e) {
        console.warn('Failed to refresh novel metadata during cast load:', e);
      }
    }

    const actualScan = totalEps > 0 ? Math.min(scanLimit, totalEps) : scanLimit;

    if (showModal || forceRefresh) {
      openAiAnalyzeProgressModal(`小説全体のAI配役再解析 (${actualScan}話スキャン)`, engineLabel, actualScan);
    }

    // 0. 配役決定の最優先ステップ: インターネット（Gemini / Wikipedia）から公式登場人物一覧を検索
    let onlineCharsResult = null;
    try {
      if (showModal || forceRefresh) {
        updateAiAnalyzeProgress(0, actualScan, 0, 'インターネットから公式登場人物リストを検索中...');
      }
      onlineCharsResult = await searchNovelCharactersOnlineJs(state.currentNovel?.title, state.currentNovel?.author);
      if (onlineCharsResult && onlineCharsResult.characters && onlineCharsResult.characters.length > 1) {
        console.log(`[OnlineCast] Found online characters from ${onlineCharsResult.source}:`, onlineCharsResult.characters);
        engineLabel = `公式ネット情報 (${onlineCharsResult.source})`;
      }
    } catch (onlineErr) {
      console.warn('[OnlineCast] Online character search error:', onlineErr);
    }

    const allCharsMap = {};
    allCharsMap['ナレーション'] = {
      name: 'ナレーション',
      gender: 'female',
      voice_type: 'neutral_narration',
      description: '地の文'
    };

    // オンライン検索結果が存在する場合は、あらかじめ公式キャラ一覧をマスター登録
    if (onlineCharsResult && onlineCharsResult.characters) {
      onlineCharsResult.characters.forEach(oc => {
        if (oc.name && oc.name !== 'ナレーション') {
          allCharsMap[oc.name] = {
            name: oc.name,
            gender: oc.gender || 'unknown',
            voice_type: oc.voice_type || (oc.gender === 'female' ? 'female_young' : 'male_young'),
            description: oc.description || '公式登場人物',
            appearances: 5,
            dialogue_count: 5,
            is_official: true
          };
        }
      });
    }

    let globalProtagonist = null;
    let hadFallback = false;
    let fallbackMessage = '';
    // フルキャストはローカル軽量スキャン（話×フルLLMを廃止）
    engineLabel = 'ローカル軽量配役スキャン';

    // 高速並行バッチスキャン (5話ずつ取得・ローカル解析して進捗表示)
    const batchSize = 5;
    const EARLY_CAST_TARGET = 12;
    for (let epStart = 1; epStart <= actualScan; epStart += batchSize) {
      if (aiAnalyzeCancelFlag) {
        console.log('[FullCast] AI analysis cancelled by user');
        break;
      }

      const epEnd = Math.min(epStart + batchSize - 1, actualScan);
      if (badge) {
        badge.textContent = uiLangForCast === 'ja'
          ? `AIスキャン中 ${epStart}〜${epEnd}/${actualScan}話...`
          : `Scanning Ep. ${epStart}-${epEnd}/${actualScan}...`;
        badge.classList.remove('hidden');
      }
      if (reanalyzeBtnText) {
        reanalyzeBtnText.textContent = uiLangForCast === 'ja'
          ? `AI解析中 (${epEnd}/${actualScan}話)`
          : `Analyzing (${epEnd}/${actualScan})`;
      }

      if (showModal || forceRefresh) {
        const currentCount = Object.keys(allCharsMap).length - 1;
        updateAiAnalyzeProgress(epEnd, actualScan, currentCount, `第 ${epStart}〜${epEnd} / ${actualScan} 話をAI解析中...`);
      }

      const epPromises = [];
      for (let ep = epStart; ep <= epEnd; ep++) {
        epPromises.push(
          (async (currentEp) => {
            try {
              const epRes = await apiFetch(`/api/narou/episode/${encodeURIComponent(ncodeLower)}/${currentEp}`);
              if (epRes.ok) {
                const epData = await epRes.json();
                // 配役スキャンは全文フル解析不要。先頭セグメントのみローカル推定で十分（CPU/待ち時間最適化）
                const segments = (epData.segments || []).slice(0, 80);
                if (!segments.length) return { characters: [], segments: [] };
                const analysis = analyzeSegmentsLocally(segments, state.currentNovel?.title || '');
                return {
                  characters: analysis.characters || [],
                  segments: analysis.segments || []
                };
              }
            } catch (epErr) {
              console.warn(`[LocalCast] Ep ${currentEp} fetch/analysis skipped:`, epErr);
            }
            return { characters: [], segments: [] };
          })(ep)
        );
      }

      const batchResults = await Promise.all(epPromises);
      
      // 全バッチ結果から主人公名を特定
      batchResults.forEach(res => {
        (res.characters || []).forEach(c => {
          if (c && c.name && (c.description || '').includes('主人公') && !isGenericRoleName(c.name)) {
            const cn = cleanExtractedNameJs(c.name);
            if (cn && !CLIENT_IGNORE_SPEAKER_WORDS.has(cn)) globalProtagonist = cn;
          }
        });
      });

      // 未特定の場合はセリフ頻度と名乗りから主人公を推定
      if (!globalProtagonist) {
        batchResults.forEach(res => {
          (res.segments || []).forEach(seg => {
            const t = seg.display_text || '';
            const m = t.match(/(?:俺|オレ|僕|ボク|私|わたし)の名前は\s*([一-龠ぁ-んァ-ヶー]{1,8})/) ||
                      t.match(/(?:俺|オレ|僕|ボク|私|わたし)[、,\s]+([一-龠]{2,6}|[ァ-ヶー]{2,8})/);
            if (m) {
              const cand = cleanExtractedNameJs(m[1]);
              if (cand && !CLIENT_IGNORE_SPEAKER_WORDS.has(cand)) globalProtagonist = cand;
            }
          });
        });
      }

      batchResults.forEach(res => {
        (res.characters || []).forEach(c => {
          if (c && c.name && c.name !== 'ナレーション' && c.name !== 'システム') {
            const canonicalName = canonicalizeCharacterName(c.name, globalProtagonist);
            if (canonicalName && !CLIENT_IGNORE_SPEAKER_WORDS.has(canonicalName) && !isGenericRoleName(canonicalName)) {
              if (!allCharsMap[canonicalName]) {
                allCharsMap[canonicalName] = { ...c, name: canonicalName, appearances: 1, dialogue_count: 0 };
              } else {
                allCharsMap[canonicalName].appearances = (allCharsMap[canonicalName].appearances || 1) + 1;
              }
            }
          }
        });

        (res.segments || []).forEach(seg => {
          if (seg.type === 'dialogue' && seg.speaker && seg.speaker !== 'ナレーション' && seg.speaker !== 'システム') {
            const canonicalName = canonicalizeCharacterName(seg.speaker, globalProtagonist);
            if (canonicalName && !CLIENT_IGNORE_SPEAKER_WORDS.has(canonicalName) && !isGenericRoleName(canonicalName)) {
              if (!allCharsMap[canonicalName]) {
                allCharsMap[canonicalName] = {
                  name: canonicalName,
                  gender: seg.gender || '不明',
                  voice_type: seg.voice_type || 'male_young',
                  appearances: 1,
                  dialogue_count: 1
                };
              } else {
                allCharsMap[canonicalName].dialogue_count = (allCharsMap[canonicalName].dialogue_count || 0) + 1;
              }
            }
          }
        });
      });

      // 十分キャラが揃ったら早期終了（フィルタ後相当のカウントで判定）
      const earlyMinCount = actualScan >= 10 ? 2 : 1;
      const uniqueCastCount = Object.entries(allCharsMap).filter(([n, c]) => {
        if (n === 'ナレーション') return false;
        if (isGenericRoleName(n) || CLIENT_IGNORE_SPEAKER_WORDS.has(n)) return false;
        return ((c.dialogue_count || 0) + (c.appearances || 0)) >= earlyMinCount;
      }).length;
      if (uniqueCastCount >= EARLY_CAST_TARGET && epEnd >= Math.min(10, actualScan)) {
        console.log(`[FullCast] Early stop at ep ${epEnd}: ${uniqueCastCount} qualified characters found`);
        break;
      }
    }

    // 登場頻度（セリフ数・登場話数）による名寄せと重要人物フィルタリング
    // セリフが2回以上（または総話数が少ない場合は1回以上）のキャラクターのみを採用
    const minDialogueCount = actualScan >= 10 ? 2 : 1;
    const filteredEntries = Object.entries(allCharsMap)
      .filter(([name, c]) => {
        if (name === 'ナレーション') return true;
        if (isGenericRoleName(name) || CLIENT_IGNORE_SPEAKER_WORDS.has(name)) return false;
        const count = (c.dialogue_count || 0) + (c.appearances || 0);
        return count >= minDialogueCount;
      })
      .sort((a, b) => {
        if (a[0] === 'ナレーション') return -1;
        if (b[0] === 'ナレーション') return 1;
        const scoreA = (a[1].dialogue_count || 0) * 3 + (a[1].appearances || 0);
        const scoreB = (b[1].dialogue_count || 0) * 3 + (b[1].appearances || 0);
        return scoreB - scoreA;
      });

    // 最大主要キャラクター20名に絞り込み
    const charactersList = filteredEntries.slice(0, 20).map(([_, c]) => ({
      name: c.name,
      gender: c.gender || '不明',
      voice_type: c.voice_type || 'male_young',
      description: c.name === 'ナレーション' ? '地の文' : `登場人物 (セリフ ${c.dialogue_count || c.appearances || 1}件)`
    }));

    // もしナレーション以外が0名なら代表モブを追加
    if (charactersList.length <= 1) {
      charactersList.push({
        name: '登場人物',
        gender: '男性',
        voice_type: 'male_young',
        description: '会話キャラ'
      });
    }

    const castMap = {};
    const castProfiles = {};
    const defaultVoice = state.availableVoices[0]?.id || 'ja-JP-NanamiNeural';

    charactersList.forEach(c => {
      castMap[c.name] = (state.currentCast && state.currentCast[c.name]) ? state.currentCast[c.name] : defaultVoice;
      castProfiles[c.name] = getCharacterVoiceProfile(c.name, c.gender, c.voice_type);
    });

    const fullCastData = {
      ncode: ncodeLower,
      scanned_episodes: actualScan,
      characters: charactersList,
      cast: castMap,
      cast_profiles: castProfiles,
      ai_engine: engineLabel
    };

    try {
      localStorage.setItem(cacheKey, JSON.stringify(fullCastData));
    } catch (e) {}

    applyNovelCastData(fullCastData);

    if (showModal || forceRefresh) {
      finishAiAnalyzeProgress({
        success: true,
        engineName: engineLabel,
        scannedEpisodes: actualScan,
        characters: charactersList,
        fallback: hadFallback,
        fallbackMessage: fallbackMessage
      });
    }

    updatePlayerAiStatusBadge(engineLabel, charactersList.length);
    showToast(`AI再解析完了: ${engineLabel} で ${actualScan}話中 ${charactersList.length}名の登場人物を検出しました`, 'success');
    return;
  } catch (err) {
    console.warn('[FullCast] Failed to load novel cast:', err);
    if (showModal || forceRefresh) {
      finishAiAnalyzeProgress({
        success: false,
        engineName: engineLabel,
        scannedEpisodes: 0,
        characters: [],
        error: `解析中にエラーが発生しました: ${err.message || err}`
      });
    }
    showToast(`AI解析エラー: ${err.message || err}`, 'error');
  } finally {
    if (reanalyzeBtnText) reanalyzeBtnText.textContent = typeof tUi === 'function' ? tUi('cast_ai_reset_btn') : '全体AI再解析';
  }
}

// 小説の続き（追加エピソード）ダウンロード時・追加スキャン時のインクリメンタル配役マージエンジン
function mergeNovelCastIncremental(ncode, existingData, newCandidates, sourceInfo = '追加ダウンロード解析') {
  const ncodeLower = (ncode || '').toLowerCase();
  const existing = existingData || (() => {
    try {
      const s = localStorage.getItem(`narou_novel_cast_${ncodeLower}`);
      return s ? JSON.parse(s) : null;
    } catch (e) { return null; }
  })() || { characters: [], cast: {}, cast_profiles: {}, scanned_episodes: 0 };

  const mergedCharacters = [...(existing.characters || [])];
  const mergedCast = { ...(existing.cast || {}) };
  const mergedProfiles = { ...(existing.cast_profiles || {}) };
  const existingNames = new Set(mergedCharacters.map(c => c.name));

  const availableVoices = state.availableVoices || [];
  const defaultVoice = availableVoices[0]?.id || 'ja-JP-NanamiNeural';

  // 使用済みボイスのカウント（新キャラへの重複回避・分散割当用）
  const usedVoiceCounts = {};
  Object.values(mergedCast).forEach(vId => {
    usedVoiceCounts[vId] = (usedVoiceCounts[vId] || 0) + 1;
  });

  let newlyAddedCount = 0;

  (newCandidates || []).forEach(newChar => {
    if (!newChar || !newChar.name) return;
    const name = newChar.name.trim();
    if (!name || name === 'ナレーション' || name === 'システム') return;

    if (!existingNames.has(name)) {
      // 新規登場キャラクターの判定と登録
      existingNames.add(name);
      newlyAddedCount++;

      // 性別判定（unknownを完全排除 & '女性'/'男性' を 'female'/'male' に正規化）
      let gender = newChar.gender;
      if (gender === '女性' || gender === '女' || gender === 'f' || gender === 'F') gender = 'female';
      else if (gender === '男性' || gender === '男' || gender === 'm' || gender === 'M') gender = 'male';
      if (!gender || (gender !== 'female' && gender !== 'male')) {
        gender = inferGenderAdvancedJs(name, newChar.cv || '', newChar.description || newChar.tone || '');
      }

      const isFem = gender === 'female' || gender === '女性';
      const voiceType = newChar.voice_type || (isFem ? 'female_young' : 'male_young');
      const charObj = {
        name: name,
        cv: newChar.cv || '',
        gender: gender,
        voice_type: voiceType,
        pitch_ratio: newChar.pitch_ratio || (isFem ? 1.15 : 0.95),
        rate_ratio: newChar.rate_ratio || 1.0,
        echo: !!newChar.echo,
        tone: newChar.tone || '新登場キャラクター',
        role: newChar.role || 'sub',
        description: newChar.description || '追加エピソードで初登場'
      };
      mergedCharacters.push(charObj);

      // プロファイルの生成
      const profile = getCharacterVoiceProfile(name, gender, voiceType);
      mergedProfiles[name] = profile;

      // ボイスの割り当て（公式推奨 or 既存キャラと被りにくい最適ボイス）
      if (newChar.recommended_voice) {
        mergedCast[name] = newChar.recommended_voice;
      } else if (profile.voiceId) {
        mergedCast[name] = profile.voiceId;
      } else {
        // 重複の少ないボイスを選択
        const matchingPool = availableVoices.filter(v => 
          isFem ? (v.gender === 'female' || (!v.name.includes('jad') && !v.name.includes('jab') && !v.name.includes('Male')))
                : (v.gender === 'male' || v.name.includes('jad') || v.name.includes('jab') || v.name.includes('Male'))
        );
        const pool = matchingPool.length > 0 ? matchingPool : availableVoices;
        if (pool.length > 0) {
          const sortedByUsage = [...pool].sort((a, b) => (usedVoiceCounts[a.id] || 0) - (usedVoiceCounts[b.id] || 0));
          const chosen = sortedByUsage[0]?.id || defaultVoice;
          mergedCast[name] = chosen;
          usedVoiceCounts[chosen] = (usedVoiceCounts[chosen] || 0) + 1;
        } else {
          mergedCast[name] = defaultVoice;
        }
      }
    } else {
      // 既存キャラクターの場合: 声(cast)は絶対に変更・上書きせず、CVや説明文のみ補完
      const existingChar = mergedCharacters.find(c => c.name === name);
      if (existingChar) {
        if (!existingChar.cv && newChar.cv) existingChar.cv = newChar.cv;
        if ((!existingChar.description || existingChar.description === '公式登場人物') && newChar.description) {
          existingChar.description = newChar.description;
        }
      }
    }
  });

  const finalData = {
    ncode: ncodeLower,
    scanned_episodes: Math.max(existing.scanned_episodes || 0, existingData?.scanned_episodes || 0),
    characters: mergedCharacters,
    cast: mergedCast,
    cast_profiles: mergedProfiles,
    ai_engine: existing.ai_engine || sourceInfo,
    last_updated: new Date().toISOString()
  };

  // 永続化保存
  try {
    localStorage.setItem(`narou_novel_cast_${ncodeLower}`, JSON.stringify(finalData));
  } catch (e) {}

  // 現在の小説と一致する場合はステートにも即座にマージ反映
  if (state.currentNovel?.ncode?.toLowerCase() === ncodeLower) {
    applyNovelCastData(finalData);
  }

  if (newlyAddedCount > 0) {
    console.log(`[CastMerge] Added ${newlyAddedCount} new characters to '${ncode}' without altering existing voice assignments.`);
  }

  return finalData;
}

function applyNovelCastData(data) {
  if (!data) return;
  state.currentNovelCharacters = data.characters || [];
  state.currentNovelCast = data.cast || {};

  if (state.currentNovelCharacters.length > 0) {
    state.currentCharacters = state.currentNovelCharacters;
    state.currentCast = { ...state.currentCast, ...state.currentNovelCast };
    if (!state.currentCastProfiles) state.currentCastProfiles = {};
    state.currentCharacters.forEach(c => {
      state.currentCastProfiles[c.name] = getCharacterVoiceProfile(c.name, c.gender, c.voice_type);
    });
    renderCastEditor();
  }

  const badge = document.getElementById('castScanStatusBadge');
  if (badge) {
    const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
    const scanCount = data.scanned_episodes || getSettingScanEpisodes();
    const charCount = state.currentCharacters.length;
    if (uiLang === 'ja') {
      const engine = data.ai_engine ? `${data.ai_engine} / ` : '';
      badge.textContent = `${engine}${scanCount}話スキャン済 (${charCount}名)`;
    } else {
      badge.textContent = `Scanned ${scanCount} ep. (${charCount} chars)`;
    }
    badge.classList.remove('hidden');
  }
}

async function reanalyzeNovelFullCast() {
  if (!state.currentNovel?.ncode) {
    showToast('小説が選択されていません', 'info');
    return;
  }
  await loadNovelFullCast(state.currentNovel.ncode, true, true);
}

// ==============================================
// 18. ユーザースクロール検知 & 自動スクロール復帰
// ==============================================
let isUserScrolling = false;
let _isUserTouchingReader = false;
let _readerTouchStartX = 0;
let _readerTouchStartY = 0;
let _readerTouchMoved = false;
let _lastReaderScrollOrDragAt = 0;

function setupUserScrollDetection() {
  const middlePane = document.getElementById('playerMiddlePane');
  const onTouchStart = (e) => {
    if (!e.touches || e.touches.length === 0) return;
    _isUserTouchingReader = true;
    _readerTouchMoved = false;
    _readerTouchStartX = e.touches[0].clientX;
    _readerTouchStartY = e.touches[0].clientY;
  };
  const onTouchMove = (e) => {
    if (e.touches && e.touches.length > 0) {
      const dx = Math.abs(e.touches[0].clientX - _readerTouchStartX);
      const dy = Math.abs(e.touches[0].clientY - _readerTouchStartY);
      if (dx > 5 || dy > 5) {
        _readerTouchMoved = true;
        _lastReaderScrollOrDragAt = Date.now();
        handleUserScroll();
      }
    } else {
      handleUserScroll();
    }
  };
  const onTouchEndOrCancel = () => {
    const wasMoving = _readerTouchMoved;
    _isUserTouchingReader = false;
    if (wasMoving) {
      _lastReaderScrollOrDragAt = Date.now();
      setTimeout(() => {
        _readerTouchMoved = false;
      }, 240);
    } else {
      _readerTouchMoved = false;
    }
    if (typeof handlePlayerScrollCompact === 'function') {
      handlePlayerScrollCompact();
    }
  };

  if (middlePane) {
    middlePane.addEventListener('touchstart', onTouchStart, { passive: true });
    middlePane.addEventListener('touchmove', onTouchMove, { passive: true });
    middlePane.addEventListener('touchend', onTouchEndOrCancel, { passive: true });
    middlePane.addEventListener('touchcancel', onTouchEndOrCancel, { passive: true });
    middlePane.addEventListener('wheel', () => {
      _lastReaderScrollOrDragAt = Date.now();
      handleUserScroll();
    }, { passive: true });
    middlePane.addEventListener('scroll', () => {
      if (_isUserTouchingReader || _readerTouchMoved) {
        _lastReaderScrollOrDragAt = Date.now();
        handleUserScroll();
      }
    }, { passive: true });
  } else {
    window.addEventListener('touchstart', (e) => {
      if (e.target && e.target.closest && e.target.closest('#playerMiddlePane')) onTouchStart(e);
    }, { passive: true });
    window.addEventListener('touchmove', (e) => {
      if (e.target && e.target.closest && e.target.closest('#playerMiddlePane')) onTouchMove(e);
    }, { passive: true });
    window.addEventListener('touchend', onTouchEndOrCancel, { passive: true });
    window.addEventListener('touchcancel', onTouchEndOrCancel, { passive: true });
  }
}

function handleUserScroll() {
  if (!state.isPlaying && !state.autoScroll) return;
  if (!isUserScrolling) {
    isUserScrolling = true;
    const resumeBtn = document.getElementById('resumeAutoScrollBtn');
    if (resumeBtn) {
      resumeBtn.classList.remove('hidden');
      resumeBtn.classList.add('flex');
    }
  }
}

function resumeAutoScroll() {
  triggerHaptic('click');
  isUserScrolling = false;
  _isUserTouchingReader = false;
  _readerTouchMoved = false;
  state.autoScroll = true;
  const btn = document.getElementById('autoScrollBtn');
  const btnText = document.getElementById('autoScrollBtnText');
  if (btn) btn.className = 'px-2.5 py-1.5 rounded-xl bg-blue-600/20 text-blue-300 border border-blue-500/40 text-[11px] font-medium flex items-center space-x-1 transition active:scale-95';
  if (btnText) btnText.textContent = '追従ON';
  
  const resumeBtn = document.getElementById('resumeAutoScrollBtn');
  if (resumeBtn) {
    resumeBtn.classList.add('hidden');
    resumeBtn.classList.remove('flex');
  }

  highlightCurrentSegment(state.currentSegmentIndex);
  showMiniToast('朗読位置へスクロールしました');
}

// 互換性エイリアス
const resumeAutoScrollTracking = resumeAutoScroll;

// ==============================================
// 18-B. 韻律エンジン (話者属性 × 場面 × 感情 × 文末表現 / 多言語対応)
//   pitchDelta: VOICEVOX pitchScale 単位の加算補正 (±0.08程度)
//   rate      : キャラ基本テンポへの乗数
//   intonation: 抑揚スケール (1.0=標準)
// ==============================================
const PROSODY_SCENE_LEXICON = [
  { mood: 'tense', re: /剣|刃|血|斬|戦|敵|襲|爆|銃|砲|怒鳴|殺|追っ|追わ|逃げ|急い|駆け|走っ|雷|嵐|炎|燃え|崩れ|悲鳴|叫び|掴み|摑み|睨|\b(?:sword|blade|blood|slash|battle|fight|enemy|attack|explod\w*|explosion|gun|cannon|roar|kill|chase|flee|escape|rush|run|thunder|storm|flame|fire|burn|collaps\w*|scream|shout|grab|glare|espada|sangre|batalla|enemigo|ataque|fuego|grito|sang|bataille|ennemi|attaque|feu|cri|sangue|batalha|inimigo|fogo|chama|gritar|correr|fugir)\b|épée|剑|刀|血|斩|战|敌|袭|爆|杀|逃|雷|风暴|火焰|尖叫|검|피|전투|적|습격|폭발|살해|도망|폭풍|비명/gi },
  { mood: 'quiet', re: /静か|静まり|夜|闇|暗|沈黙|ひそ|囁|ささや|霧|月明|星空|雨|薄暗|ひっそり|寝静|黙|\b(?:quiet|silent|silence|night|dark|darkness|whisper|murmur|fog|mist|moonlight|starlight|rain|dim|hush|stillness|silencio|tranquilo|noche|oscuridad|susurro|niebla|lluvia|calme|nuit|murmure|brouillard|pluie|silêncio|noite|escuridão|sussurro|névoa|chuva)\b|obscurité|安静|寂静|夜|黑暗|沉默|低语|雾|月光|星空|雨|조용|정적|밤|어둠|침묵|속삭|안개|달빛|빗소리/gi },
  { mood: 'sad',   re: /涙|泣|悲し|葬|死|別れ|孤独|寂し|哀|嘆|うなだれ|俯|うつむ|飢|貧|途方|\b(?:tear|cry|wept|weep|sob|sad|sorrow|grief|funeral|death|die|farewell|goodbye|lonely|alone|sigh|despair|mourn|llorar|triste|muerte|soledad|larme|pleurer|mort|adieu|solitude|chorar|morte|solidão|adeus|desespero)\b|lágrima|adiós|desesperación|désespoir|泪|哭|悲伤|死|别离|孤独|寂寞|叹息|绝望|눈물|울음|슬픔|죽음|이별|고독|외로움|절망/gi },
  { mood: 'joy',   re: /笑|嬉|楽し|祝|宴|陽気|花|歓|喜|にこ|弾ん|賑|\b(?:smile|laugh|giggle|chuckle|happy|joy|glad|celebrat\w*|feast|banquet|cheer|bright|flower|delight|merry|lively|sonrisa|feliz|fiesta|celebrar|sourire|rire|heureux|joie|sorriso|sorrir|rir|festa|alegria)\b|reír|alegría|fête|célébrer|笑|高兴|开心|快乐|庆祝|宴会|欢喜|灿烂|웃음|기쁨|즐거움|축하|연회|행복|미소/gi },
  { mood: 'eerie', re: /不気味|怪|幽|亡霊|屍|死骸|鴉|からす|蝋燭|腐|異様|ぞっ|ぞく|薄気味|蝙蝠|荒れ果て|朽ち|\b(?:eerie|creepy|ghost|phantom|specter|corpse|cadaver|crow|raven|candle|rot|decay|bizarre|shiver|shudder|chilling|ruin|haunt|curse|espeluznante|fantasma|cuervo|podrido|ruina|sinistre|cadavre|corbeau|pourri|frisson|ruine|assustador|corvo|apodrecido|arrepio|ruína)\b|cadáver|escalofrío|fantôme|诡异|怪|幽灵|亡灵|尸体|乌鸦|腐烂|发抖|废墟|기괴|유령|망령|시체|까마귀|부패|소름|폐허/gi }
];
const PROSODY_SCENE_PARAMS = {
  tense: { pd: 0.020, rate: 1.06, inton: 1.15 },
  quiet: { pd: -0.015, rate: 0.94, inton: 0.90 },
  sad:   { pd: -0.025, rate: 0.92, inton: 0.88 },
  joy:   { pd: 0.025, rate: 1.04, inton: 1.20 },
  eerie: { pd: -0.030, rate: 0.90, inton: 0.95 }
};
const PROSODY_EMOTION_PARAMS = {
  angry:   { pd: 0.020, rate: 1.09, inton: 1.32 },
  shout:   { pd: 0.055, rate: 1.14, inton: 1.40 },
  excited: { pd: 0.035, rate: 1.07, inton: 1.26 },
  happy:   { pd: 0.032, rate: 1.04, inton: 1.25 },
  whisper: { pd: -0.030, rate: 0.90, inton: 0.72 },
  sad:     { pd: -0.040, rate: 0.90, inton: 0.80 }
};

function prosodyDetectScene(segments, index) {
  const scores = {};
  const from = Math.max(0, index - 4);
  const to = Math.min(segments.length - 1, index + 3);
  const activeLang = state.currentTranslatedLang || '';
  for (let i = from; i <= to; i++) {
    const s = segments[i];
    if (!s) continue;
    const t = s.display_text || s.text || '';
    const transT = (activeLang && s.translated_text && s.translated_lang === activeLang && s.translated_text !== t)
      ? String(s.translated_text)
      : '';
    if (!t && !transT) continue;
    const w = (s.type === 'narration' ? 1.0 : 0.6) * (1 - Math.abs(i - index) * 0.12);
    for (const { mood, re } of PROSODY_SCENE_LEXICON) {
      const m1 = t ? t.match(re) : null;
      const m2 = transT ? transT.match(re) : null;
      const count = Math.max(m1 ? m1.length : 0, m2 ? m2.length : 0);
      if (count > 0) scores[mood] = (scores[mood] || 0) + count * w;
    }
  }
  let best = null;
  let bestScore = 0;
  for (const [mood, sc] of Object.entries(scores)) {
    if (sc > bestScore) { best = mood; bestScore = sc; }
  }
  if (!best || bestScore < 1.2) return { mood: null, strength: 0 };
  return { mood: best, strength: Math.min(1, bestScore / 3) };
}

function prosodyInferEmotion(seg, text) {
  const activeLang = state.currentTranslatedLang || '';
  const transText = (seg && activeLang && seg.translated_text && seg.translated_lang === activeLang)
    ? String(seg.translated_text)
    : '';
  const combined = transText ? `${text} ${transText}` : text;
  if (seg && (seg.subtype === 'monologue' || (text.startsWith('（') && text.endsWith('）')) || (text.startsWith('(') && text.endsWith(')')))) {
    return 'whisper';
  }
  let e = seg.emotion && seg.emotion !== 'normal' ? seg.emotion : null;
  // ルールベース解析は「？」だけでも excited にするため、疑問文は文末ピッチ上昇で別扱いにする
  if (e === 'excited' && /[？?]/.test(combined) && !/[！!]/.test(combined)) e = null;
  if (e) return e;
  if (/[！!]{2,}|うおお|ぎゃあ|きゃあ|くらえ|死ね|助け|逃げろ|\b(?:scream\w*|shriek\w*|roar\w*|die!|help!|run!)\b/i.test(combined)) return 'shout';
  if (/てめえ|ふざけるな|許さ|殺す|くそ|ちくしょう|黙れ|貴様|\b(?:damn|bastard|idiot|shut up|kill you|unforgivable|how dare|curse you|get lost|maldita|idiota|merde|maldição|droga|cale-se)\b|te mataré|imbécile|混蛋|该死|可恶|杀了你|滚|젠장|죽여|닥쳐/i.test(combined)) return 'angry';
  if (/悲し|泣|涙|うぅ|ううっ|ごめん|すまな|さよなら|死にたく|寂し|つらい|辛い|苦し|もう駄目|おしまい|\b(?:sorry|forgive me|goodbye|farewell|sobs?|crying|tears|lonely|painful|hopeless|it's over|lo siento|triste|llorar|larmes|pleurer|adieu|desculpe|sinto muito|chorar|adeus|solidão)\b|lágrimas|adiós|désolé|对不起|难过|流泪|哭|再见|悲伤|미안|슬프|눈물|울었|안녕/i.test(combined)) return 'sad';
  if (/[！!]/.test(combined)) return 'excited';
  if (/ありがとう|嬉し|うれし|よかった|やった|わーい|楽し|あはは|ふふ|えへへ|\b(?:thank you|thanks|glad|happy|yay|hurray|wonderful|awesome|haha|hehe|giggle|gracias|feliz|alegre|genial|jaja|merci|heureux|content|super|obrigado|obrigada|ótimo|maravilhoso|kkk)\b|谢谢|太好了|开心|高兴|哈哈|고마워|감사|기뻐|다행|하하/i.test(combined)) return 'happy';
  const trimmed = (transText || text).trim();
  if (((/(……|…|\.{3,})$/.test(trimmed)) && trimmed.length < 45) || /\b(?:whisper\w*|murmur\w*|sigh\w*|shh|hush|susurr\w*|chuchot\w*|sussurr\w*)\b|低声|小声|叹气|속삭|한숨/i.test(combined)) return 'whisper';
  return 'normal';
}

// 年齢・性別に応じた感情表現の振れ幅 (子供は大きく、老人・落ち着いた人物は控えめ)
function prosodyExpressiveness(seg, profile) {
  const vt = String(seg.voice_type || (profile && profile.voice_type) || '');
  if (/system/.test(vt)) return 0.6;
  if (/child/.test(vt)) return 1.3;
  if (/elder|old/.test(vt)) return 0.75;
  if (/mature|calm/.test(vt)) return 0.85;
  if (/female/.test(vt) || seg.gender === '女性' || seg.gender === 'female') return 1.1;
  return 1.0;
}

function computeSegmentProsody(segments, index, profile) {
  const seg = (segments && segments[index]) || {};
  const prof = profile || {};
  const basePitch = prof.pitch || 1.0;
  const baseRate = prof.rateMultiplier || 1.0;
  const text = String(seg.display_text || seg.text || '');
  const isNarr = seg.type === 'narration' || seg.voice_type === 'neutral_narration';

  let pd = 0;
  let rm = 1;
  let im = 1;
  const expr = isNarr ? 0.7 : prosodyExpressiveness(seg, prof);

  // 1. セリフの感情
  let emotion = 'normal';
  if (!isNarr) {
    emotion = prosodyInferEmotion(seg, text);
    const ep = PROSODY_EMOTION_PARAMS[emotion];
    if (ep) {
      pd += ep.pd;
      rm *= ep.rate;
      im *= ep.inton;
    }
  }

  // 2. 物語の場面（前後の地の文・セリフの語彙から雰囲気を推定）
  const scene = prosodyDetectScene(segments || [], index);
  if (scene.mood) {
    const sp = PROSODY_SCENE_PARAMS[scene.mood];
    const w = (isNarr ? 0.9 : 0.6) * scene.strength;
    pd += sp.pd * w;
    rm *= 1 + (sp.rate - 1) * w;
    im *= 1 + (sp.inton - 1) * w;
  }

  // 3. 文末表現（セリフのみ）: 疑問は文末上昇、「… / ...」は間を取り遅く（多言語引用符対応）
  if (!isNarr) {
    const activeTxt = (seg.translated_text && state.currentTranslatedLang && seg.translated_lang === state.currentTranslatedLang)
      ? String(seg.translated_text)
      : text;
    const tail = activeTxt.replace(/[」』）)\s"”'’»›]+$/, '');
    if (/[？?]$/.test(tail) || /^¿/.test(activeTxt.trim()) || (/(か|かい|のか|だろう)[。]?$/.test(tail) && !/[！!]$/.test(tail))) {
      pd += 0.015;
      im *= 1.15;
    } else if (/[！!]$/.test(tail) || /^¡/.test(activeTxt.trim())) {
      im *= 1.08;
    }
    if (/(……|…|\.{3,})/.test(tail)) rm *= 0.95;
    if (/(……|…|\.{3,})$/.test(tail)) rm *= 0.96;
  }

  // 4. 話者属性による振れ幅の調整
  pd *= expr;
  rm = 1 + (rm - 1) * expr;
  im = 1 + (im - 1) * expr;

  // 5. 🎭 作者意図 ＆ 場面調子ディレクター補正 (AI Director Expressive Tuning)
  let directorStage = null;
  let sentencePauseMs = 240;
  if (typeof isDirectorModeEnabled === 'function' && isDirectorModeEnabled()) {
    const novelTitle = state.currentNovel?.title || '';
    const author = state.currentNovel?.author || '';
    directorStage = evaluateDirectorStageForSegment(novelTitle, author, text, index, segments?.length || 1, scene.mood);
    if (directorStage && directorStage.prosody) {
      const dp = directorStage.prosody;
      pd += (dp.pitchBoost || 0);
      rm *= (dp.rateMult || 1.0);
      im *= (dp.intonMult || 1.0);
      sentencePauseMs = dp.pauseMs || 240;
    }
  }

  pd = Math.max(-0.09, Math.min(0.09, pd));
  rm = Math.max(0.70, Math.min(1.35, rm));
  im = Math.max(0.60, Math.min(1.65, im));

  return {
    pitch: basePitch,
    pitchDelta: Number(pd.toFixed(4)),
    rate: Number((baseRate * rm).toFixed(4)),
    intonation: Number(im.toFixed(4)),
    emotion,
    mood: scene.mood,
    directorStage,
    sentencePauseMs
  };
}

/**
 * 原文が外国語（英語小説・韓国語・中国語・スペイン語・フランス語・ポルトガル語等）かどうかを判定し、非日本語の場合のみ言語コードを返す。
 * 日本語小説内の英単語混じりで誤判定しないよう、エピソード全体でも仮名が含まれないことを確認する。
 */
function detectNativeForeignSegmentLang(spokenText, segments) {
  if (!spokenText) return null;
  if (/[\u3040-\u30ff]/.test(spokenText)) return null; // ひらがな・カタカナがあれば日本語
  const sampleSegs = Array.isArray(segments) ? segments.slice(0, 12) : [];
  const kanaCount = sampleSegs.filter(s => /[\u3040-\u30ff]/.test(String(s?.display_text || s?.text || ''))).length;
  if (sampleSegs.length > 0 && kanaCount > sampleSegs.length * 0.2) return null;

  if (/[\uac00-\ud7af]/.test(spokenText)) return 'ko';
  if (/[\u4e00-\u9fff]/.test(spokenText)) return 'zh';
  if (/[a-zA-Z]{2,}/.test(spokenText)) {
    if (/[ãõ]/i.test(spokenText) || (/\b(?:não|você|está|estão|então|coração|olá|obrigado|obrigada|disse)\b/i.test(spokenText) && /\b(?:que|de|em|um|uma|para|com|por|mais|mas)\b/i.test(spokenText))) return 'pt';
    if (/[¿¡ñ]/i.test(spokenText) || (/\b(?:el|los|las|una|pero|porque|hola|gracias|señor|dijo)\b/i.test(spokenText) && /\b(?:que|de|en|por|con|para|no|es|está)\b/i.test(spokenText))) return 'es';
    if (/[œæèëîïùû]/i.test(spokenText) || (/\b(?:le|les|une|des|est|sont|dans|avec|pour|mais|bonjour|merci|monsieur)\b/i.test(spokenText) && /\b(?:que|de|en|pas|ne|sur|dans|il|elle)\b/i.test(spokenText))) return 'fr';
    return 'en';
  }
  return null;
}

// ==============================================
// 19. セグメント再生制御 (playSegment / playNextSegment)
// ==============================================
let _activePlaySeq = 0;

function playSegment(index) {
  if (window._sentencePauseTimer) {
    clearTimeout(window._sentencePauseTimer);
    window._sentencePauseTimer = null;
  }
  const playSeq = ++_activePlaySeq;

  if (typeof previewAudio !== 'undefined' && previewAudio) {
    try {
      previewAudio.pause();
      previewAudio.removeAttribute('src');
      previewAudio.load();
    } catch (e) {}
    previewAudio = null;
  }

  const totalSegs = state.currentSegments.length;
  if (totalSegs === 0) {
    pauseAudio();
    return;
  }
  if (index < 0 || index >= totalSegs) {
    if (index >= totalSegs && state.currentNovel) {
      if (typeof recordEpisodeCompletion === 'function') {
        recordEpisodeCompletion();
      }
      // スリープタイマー「この話の終わりまで」が有効な場合は次話へ進まず自動停止
      if (window._sleepTimerEndOfEpisode) {
        if (typeof setSleepTimer === 'function') setSleepTimer(0, true);
        pauseAudio();
        showToast('🌙 スリープタイマーにより、この話の終わりで朗読を停止しました', 'info');
        return;
      }
      // 次話への自動連続再生がOFFの場合も停止
      if (typeof isAutoNextEpisodeEnabled === 'function' && !isAutoNextEpisodeEnabled()) {
        pauseAudio();
        showToast('この話の朗読が完了しました（自動次話再生: OFF）', 'info');
        return;
      }
      const totalEps = state.currentNovel.total_episodes || state.currentNovel.episode_count || state.currentNovel.episodes?.length || 1;
      if (state.currentEpisodeNum < totalEps) {
        startReadingEpisode(state.currentEpisodeNum + 1, null, false, true);
      } else {
        pauseAudio();
        // 作品全話読了時: 自然な節目として全画面広告判定（読了後の達成感ブレイク）
        if (typeof maybeShowEpisodeTransitionInterstitial === 'function') {
          setTimeout(() => {
            maybeShowEpisodeTransitionInterstitial();
          }, 800);
        }
      }
    }
    return;
  }

  state.currentSegmentIndex = index;
  state.isPlaying = true;

  // エピソード終盤（残り3文以下）に到達したら、次話遷移用インタースティシャル広告を事前プリロード（ロード待ちゼロ化）
  if (totalSegs > 3 && index >= totalSegs - 3) {
    if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.preloadInterstitialAd === 'function') {
      try { window.AndroidBridge.preloadInterstitialAd(); } catch (e) {}
    }
  }

  // 再生中も BG キャッシュは継続（Kotlin 側で PLAYBACK ≫ BACKGROUND 優先度）。
  // オーケストレータは再生中スロットルで回す（即キャンセルしない）。
  if (typeof BackgroundAudioCacheOrchestrator !== 'undefined') {
    BackgroundAudioCacheOrchestrator.onPlaybackStateChanged();
  }

  highlightCurrentSegment(index);
  updatePlayerStatusUI();

  const seg = state.currentSegments[index];
  const activeTransLang = state.currentTranslatedLang || '';
  const hasTranslation = !!(activeTransLang && seg.translated_text && seg.translated_lang === activeTransLang);
  const spokenText = hasTranslation
    ? (activeTransLang === 'ja' ? cleanTtsTextJs(String(seg.translated_text)) : String(seg.translated_text).trim())
    : cleanTtsTextJs(seg.tts_text || seg.display_text);

  if (!spokenText || !/[\u3040-\u30ff\u3400-\u9fff\uf900-\ufaff\uac00-\ud7afa-zA-Z0-9０-９]/.test(spokenText)) {
    const silentPauseMs = (seg && seg.type === 'dialogue') ? 320 : 40;
    setTimeout(() => {
      if (_activePlaySeq === playSeq && state.isPlaying && state.currentSegmentIndex === index) {
        playNextSegment();
      }
    }, silentPauseMs);
    return;
  }

  // 500+ 音声プロファイルからキャラクター固有の音響パラメータを取得
  const voiceProfile = getCharacterVoiceProfile(seg.speaker, seg.gender, seg.voice_type);
  const assignedVoice = resolveSpeakVoiceToken(seg, voiceProfile);

  // 話者属性(年齢/性別)・場面(地の文の雰囲気)・感情・文末表現から韻律を決定
  const prosody = computeSegmentProsody(state.currentSegments, index, voiceProfile);
  const charPitch = prosody.pitch;
  const charRate = Math.min(2.0, Math.max(0.35, (state.playbackSpeed || 0.8) * prosody.rate));
  // 標準TTS/外国語TTS向けの表現力ピッチ (VOICEVOX pitchDelta に加え抑揚倍率の偏差もピッチ変化へ反映)
  const intonPitchBoost = (prosody.intonation - 1.0) * 0.12;
  const expressiveForeignPitch = Math.min(2.0, Math.max(0.5, Number((charPitch + prosody.pitchDelta * 3.5 + intonPitchBoost).toFixed(3))));

  // 🎭 作者意図 ＆ 場面調子 UI更新 & ポーズ時間保持
  if (typeof updateDirectorTuningUI === 'function') {
    updateDirectorTuningUI(index, prosody.directorStage);
  }
  window._currentDirectorPauseMs = prosody.sentencePauseMs || 220;

  // エコー・残響効果の判定 (プロファイル指定、セグメント指定、または神/念話/心話/エコー/天啓キーワード)
  const hasEcho = !!(voiceProfile.echo || seg.echo || (seg.speaker && (seg.speaker.includes('神') || seg.speaker.includes('女神') || seg.speaker.includes('念話') || seg.speaker.includes('心話') || seg.speaker.includes('エコー') || seg.speaker.includes('天啓'))));

  // 🌐 多言語AI翻訳モード中 (ja以外の外国語翻訳時) または原文が外国語の作品は各国語ネイティブTTSで抑揚付き読み上げ
  const foreignLang = (hasTranslation && activeTransLang !== 'ja')
    ? activeTransLang
    : (!hasTranslation ? detectNativeForeignSegmentLang(spokenText, state.currentSegments) : null);
  if (foreignLang && foreignLang !== 'ja') {
    const bcp47Map = { en: 'en-US', zh: 'zh-CN', ko: 'ko-KR', es: 'es-ES', fr: 'fr-FR', pt: 'pt-BR', ja: 'ja-JP' };
    const targetBcp47 = bcp47Map[foreignLang] || 'en-US';
    if (audio && !audio.paused) {
      try { audio.pause(); } catch (e) {}
    }
    if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.speakTranslatedText === 'function') {
      window.AndroidBridge.speakTranslatedText(spokenText, foreignLang, expressiveForeignPitch, charRate, String(seg.id));
      if (window.AndroidBridge.updateMediaNotification) {
        const spk = seg.translated_speaker || seg.speaker || '';
        window.AndroidBridge.updateMediaNotification(state.currentNovel?.title || 'AI Novel Reader', `${spk}: ${spokenText}`, true);
      }
      return;
    } else if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utter = new SpeechSynthesisUtterance(spokenText);
      utter.lang = targetBcp47;
      try {
        const voices = window.speechSynthesis.getVoices() || [];
        const langVoices = voices.filter(v => String(v.lang || '').toLowerCase().startsWith(foreignLang));
        if (langVoices.length > 0) {
          const wantFemale = seg.gender === '女性' || /female|child_girl/i.test(String(seg.voice_type || '')) || expressiveForeignPitch >= 1.05;
          const matchedVoice = langVoices.find(v => {
            const n = String(v.name || '').toLowerCase();
            return wantFemale ? /female|woman|zira|aria|jenny|samantha|victoria|xiaoxiao|huihui|heami|sunhi|helena|sabina|pauline|hortense|julie|amelie|maria|francisca|luciana|fernanda/i.test(n)
                              : /male|man|david|mark|guy|daniel|alex|yunxi|kangkang|injoon|pablo|jorge|thomas|paul|antonio|daniel|felipe/i.test(n);
          }) || langVoices[0];
          if (matchedVoice) utter.voice = matchedVoice;
        }
      } catch (_) {}
      utter.rate = charRate;
      utter.pitch = expressiveForeignPitch;
      utter.onend = () => {
        if (_activePlaySeq !== playSeq || !state.isPlaying || state.currentSegmentIndex !== index) return;
        const pause = window._currentDirectorPauseMs || 200;
        if (pause > 40) {
          window._sentencePauseTimer = setTimeout(() => {
            if (_activePlaySeq === playSeq && state.isPlaying && state.currentSegmentIndex === index) playNextSegment();
          }, pause);
        } else {
          playNextSegment();
        }
      };
      utter.onerror = (ev) => {
        if (ev && (ev.error === 'canceled' || ev.error === 'interrupted')) return;
        if (_activePlaySeq === playSeq && state.isPlaying && state.currentSegmentIndex === index) playNextSegment();
      };
      window.speechSynthesis.speak(utter);
      return;
    }
  }

  // 1. Android Native App の場合
  if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.speakText === 'function') {
    if (audio && !audio.paused) {
      try { audio.pause(); } catch (e) {}
    }
    if ('speechSynthesis' in window) {
      try { window.speechSynthesis.cancel(); } catch (e) {}
    }
    if (typeof window.AndroidBridge.speakTextExpressive === 'function') {
      window.AndroidBridge.speakTextExpressive(spokenText, assignedVoice, charPitch, prosody.pitchDelta, charRate, prosody.intonation, String(seg.id), hasEcho);
    } else {
      window.AndroidBridge.speakText(spokenText, assignedVoice, charPitch + prosody.pitchDelta * 3, charRate, String(seg.id), hasEcho);
    }
    if (window.AndroidBridge.updateMediaNotification) {
      window.AndroidBridge.updateMediaNotification(state.currentNovel?.title || '小説朗読', `${seg.speaker}: ${seg.display_text}`, true);
    }
    preloadNextSegments(index);
    return;
  }

  // 2. サーバー接続または合成済みURLがある場合
  if (seg.audio_url && audio) {
    if ('speechSynthesis' in window) {
      try { window.speechSynthesis.cancel(); } catch (e) {}
    }
    audio.src = seg.audio_url;
    audio.playbackRate = charRate;
    audio.play().then(() => {
      if (_activePlaySeq !== playSeq) return;
      updateMediaSessionPositionState();
      preloadNextSegments(index);
    }).catch(e => {
      if (e && e.name === 'AbortError') return;
      console.warn('Audio play error:', e);
      if (_activePlaySeq === playSeq && state.isPlaying && state.currentSegmentIndex === index) {
        setTimeout(() => {
          if (_activePlaySeq === playSeq && state.isPlaying && state.currentSegmentIndex === index) {
            playNextSegment();
          }
        }, 300);
      }
    });
  } else if ('speechSynthesis' in window) {
    // 3. ブラウザ単体 / iPhone (iOS Web Speech API マルチ声優オート配役)
    if (audio && !audio.paused) {
      try { audio.pause(); } catch (e) {}
    }
    try {
      window.speechSynthesis.cancel();
      if (window.speechSynthesis.paused) window.speechSynthesis.resume();
    } catch (_) {}
    const utter = new SpeechSynthesisUtterance(spokenText);
    utter.lang = 'ja-JP';
    let charPitchOffset = 0;
    try {
      const voices = window.speechSynthesis.getVoices() || [];
      const jaVoices = voices.filter(v => /^ja([-_]|$)/i.test(String(v.lang || '')));
      if (jaVoices.length > 0) {
        const spkName = String(seg.speaker || 'ナレーター');
        const genderStr = String(seg.gender || voiceProfile?.gender || '').toLowerCase();
        const vTypeStr = String(seg.voice_type || voiceProfile?.category || assignedVoice || '').toLowerCase();
        const isMale = genderStr === '男性' || genderStr === 'male' || /male_young|male_elder|child_boy|keita|daichi|otoya|hattori|ichiro/.test(vTypeStr);
        const isFemale = !isMale && (genderStr === '女性' || genderStr === 'female' || /female|child_girl|nanami|aoi|shiori|kyoko|o-ren/.test(vTypeStr));
        const femalePool = jaVoices.filter(v => /kyoko|o-ren|nanami|haruka|sayaka|ayumi|female|woman|siri.*female/i.test(v.name));
        const malePool = jaVoices.filter(v => /otoya|hattori|keita|ichiro|takumi|male|man|siri.*male/i.test(v.name));
        let spkHash = 0;
        for (let i = 0; i < spkName.length; i++) spkHash = ((spkHash << 5) - spkHash + spkName.charCodeAt(i)) | 0;
        spkHash = Math.abs(spkHash);
        let chosenVoice = null;
        if (isMale && malePool.length > 0) {
          chosenVoice = malePool[spkHash % malePool.length];
        } else if (isFemale && femalePool.length > 0) {
          chosenVoice = femalePool[spkHash % femalePool.length];
        } else if (isMale && jaVoices.length > 1) {
          chosenVoice = jaVoices[spkHash % jaVoices.length];
          charPitchOffset = -0.18;
        } else if (femalePool.length > 0) {
          chosenVoice = femalePool[0];
        } else {
          chosenVoice = jaVoices[0];
        }
        if (chosenVoice) utter.voice = chosenVoice;
        if (spkName !== 'ナレーター' && spkName !== '地の文') {
          const offsets = [-0.08, 0.0, 0.08, 0.14, -0.14];
          charPitchOffset += offsets[spkHash % offsets.length];
        }
      }
    } catch (_) {}
    utter.rate = charRate;
    utter.pitch = Math.min(2, Math.max(0.5, charPitch + charPitchOffset + prosody.pitchDelta * 3));

    utter.onend = () => {
      if (_activePlaySeq !== playSeq || !state.isPlaying || state.currentSegmentIndex !== index) return;
      const pause = (prosody && prosody.sentencePauseMs) || window._currentDirectorPauseMs || 200;
      if (pause > 40) {
        window._sentencePauseTimer = setTimeout(() => {
          if (_activePlaySeq === playSeq && state.isPlaying && state.currentSegmentIndex === index) playNextSegment();
        }, pause);
      } else {
        playNextSegment();
      }
    };
    utter.onerror = (ev) => {
      if (ev && (ev.error === 'canceled' || ev.error === 'interrupted')) return;
      if (_activePlaySeq === playSeq && state.isPlaying && state.currentSegmentIndex === index) playNextSegment();
    };
    window.speechSynthesis.speak(utter);
  }
}

function playNextSegment() {
  if (window._sentencePauseTimer) {
    clearTimeout(window._sentencePauseTimer);
    window._sentencePauseTimer = null;
  }
  const expectedSeq = _activePlaySeq;
  let nextIdx = state.currentSegmentIndex + 1;
  // セリフのみ朗読（地の文スキップ）モードが有効な場合、次のdialogueセグメントを探す
  if (typeof isDialogueOnlyMode === 'function' && isDialogueOnlyMode() && Array.isArray(state.currentSegments)) {
    while (nextIdx < state.currentSegments.length && state.currentSegments[nextIdx]?.type !== 'dialogue') {
      nextIdx++;
    }
  }
  const pauseMs = typeof getSentencePauseMs === 'function' ? getSentencePauseMs() : 0;
  if (pauseMs > 0 && state.isPlaying && nextIdx < state.currentSegments.length) {
    window._sentencePauseTimer = setTimeout(() => {
      window._sentencePauseTimer = null;
      if (_activePlaySeq === expectedSeq && state.isPlaying) {
        playSegment(nextIdx);
      }
    }, pauseMs);
  } else {
    playSegment(nextIdx);
  }
}

function togglePlayPause() {
  vibrateFeedback();
  if (!canPlayAudio()) {
    showMiniToast('朗読可能な作品またはエピソードを選択してください');
    return;
  }
  if (state.isPlaying) {
    pauseAudio();
  } else {
    if (isAndroidApp) {
      playSegment(state.currentSegmentIndex);
    } else if (audio && audio.src && audio.paused && audio.currentTime > 0 && !audio.ended) {
      audio.play().then(() => {
        state.isPlaying = true;
        updatePlayButtonUI(true);
      }).catch(() => {
        playSegment(state.currentSegmentIndex);
      });
    } else if (state.currentSegments.length > 0) {
      playSegment(state.currentSegmentIndex);
    }
  }
}

function pauseAudio() {
  _activePlaySeq++;
  if (window._sentencePauseTimer) {
    clearTimeout(window._sentencePauseTimer);
    window._sentencePauseTimer = null;
  }
  if ((isAndroidApp || isAndroidAppNow()) && window.AndroidBridge && typeof window.AndroidBridge.stopTts === 'function') {
    try {
      window.AndroidBridge.stopTts();
      if (window.AndroidBridge.updateMediaNotification) {
        window.AndroidBridge.updateMediaNotification(state.currentNovel?.title || '小説朗読', '一時停止中', false);
      }
    } catch (e) {}
  }
  if ('speechSynthesis' in window) {
    try { window.speechSynthesis.cancel(); } catch (e) {}
  }
  if (audio) {
    audio.pause();
  }
  state.isPlaying = false;
  updatePlayButtonUI(false);
  if ('mediaSession' in navigator) {
    navigator.mediaSession.playbackState = 'paused';
  }
  if (typeof BackgroundAudioCacheOrchestrator !== 'undefined') {
    BackgroundAudioCacheOrchestrator.onPlaybackStateChanged();
  }
}

function jumpSegment(delta) {
  if (!canPlayAudio()) return;
  if (window._sentencePauseTimer) {
    clearTimeout(window._sentencePauseTimer);
    window._sentencePauseTimer = null;
  }
  vibrateFeedback();
  playSegment(state.currentSegmentIndex + delta);
}

function navigateEpisode(delta) {
  if (!canPlayAudio()) return;
  vibrateFeedback();
  const target = state.currentEpisodeNum + delta;
  const total = state.currentNovel?.total_episodes || state.currentNovel?.episode_count || state.currentNovel?.episodes?.length || 1;
  if (target >= 1 && target <= total) {
    startReadingEpisode(target);
  }
}

function seekByProgressBar(event) {
  if (!canPlayAudio()) return;
  const rect = event.currentTarget.getBoundingClientRect();
  const clickX = event.clientX - rect.left;
  const ratio = Math.max(0, Math.min(1, clickX / rect.width));
  const targetIndex = Math.floor(ratio * state.currentSegments.length);
  playSegment(targetIndex);
}

function onPlayerSeekSliderInput(val) {
  if (!canPlayAudio()) return;
  isPlayerSeeking = true;
  const percent = parseInt(val, 10) || 0;
  const percentEl = document.getElementById('playerSeekPercentText');
  const segCounterEl = document.getElementById('currentSegIndex');
  const timeProgressEl = document.getElementById('playerTimeProgressText');

  if (percentEl) percentEl.textContent = `${percent}%`;

  const totalSegs = state.currentSegments?.length || 0;
  if (totalSegs > 0) {
    const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
    const targetIdx = Math.max(0, Math.min(totalSegs - 1, Math.round((percent / 100) * (totalSegs - 1))));
    if (segCounterEl) segCounterEl.textContent = `${targetIdx + 1} / ${totalSegs}${uiLang === 'ja' ? ' 文' : ''}`;
    if (timeProgressEl) {
      const avgSecPerSeg = 4.0;
      const curSec = Math.round(targetIdx * avgSecPerSeg);
      const totalSec = Math.round(totalSegs * avgSecPerSeg);
      const fmt = s => `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
      timeProgressEl.textContent = `${fmt(curSec)} / ${fmt(totalSec)}`;
    }
  }
}

function onPlayerSeekSliderChange(val) {
  if (!canPlayAudio()) {
    isPlayerSeeking = false;
    return;
  }
  isPlayerSeeking = false;
  triggerHaptic('click');
  const percent = parseInt(val, 10) || 0;
  const totalSegs = state.currentSegments?.length || 0;
  if (totalSegs === 0) return;

  const targetIdx = Math.max(0, Math.min(totalSegs - 1, Math.round((percent / 100) * (totalSegs - 1))));
  state.currentSegmentIndex = targetIdx;
  playSegment(targetIdx);
}

function carModeSeekPercentToIndex(percent) {
  const totalSegs = state.currentSegments?.length || 0;
  if (totalSegs <= 0) return 0;
  if (totalSegs === 1) return 0;
  return Math.max(0, Math.min(totalSegs - 1, Math.round((percent / 100) * (totalSegs - 1))));
}

function onCarModeSeekSliderInput(val) {
  if (!canPlayAudio()) return;
  isCarModeSeeking = true;
  const percent = parseInt(val, 10) || 0;
  const totalSegs = state.currentSegments?.length || 0;
  const targetIdx = carModeSeekPercentToIndex(percent);
  const progressEl = document.getElementById('carModeProgress');
  const percentEl = document.getElementById('carModeSeekPercent');
  const textEl = document.getElementById('carModeCurrentText');
  const speakerEl = document.getElementById('carModeSpeaker');
  const hintEl = document.getElementById('carModeSeekHint');
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';

  if (percentEl) percentEl.textContent = `${percent}%`;
  if (progressEl) {
    progressEl.textContent = totalSegs > 0 ? `${targetIdx + 1} / ${totalSegs}` : '0 / 0';
  }
  if (hintEl) {
    if (uiLang === 'ja') {
      hintEl.textContent = totalSegs > 0 ? `第 ${targetIdx + 1} 文へ移動` : 'ドラッグで文位置を移動';
    } else {
      hintEl.textContent = totalSegs > 0 ? `Line ${targetIdx + 1}` : '';
    }
  }

  const previewSeg = state.currentSegments[targetIdx];
  if (previewSeg) {
    const segText = (state.currentTranslatedLang && previewSeg.translated_text)
      ? previewSeg.translated_text
      : (previewSeg.display_text || '...');
    if (textEl) textEl.textContent = segText;
    if (speakerEl) {
      const rawSpeaker = previewSeg.speaker || 'ナレーション';
      if (uiLang === 'ja') {
        speakerEl.textContent = rawSpeaker;
      } else {
        speakerEl.textContent = previewSeg.translated_speaker
          || (typeof translateSpeakerOnDevice === 'function' ? translateSpeakerOnDevice(rawSpeaker, uiLang) : null)
          || (rawSpeaker === 'ナレーション' ? tUi('cast_narration_label') : rawSpeaker);
      }
    }
  }
}

function onCarModeSeekSliderChange(val) {
  if (!canPlayAudio()) {
    isCarModeSeeking = false;
    return;
  }
  isCarModeSeeking = false;
  vibrateFeedback(10);
  triggerHaptic('tick');
  const percent = parseInt(val, 10) || 0;
  const totalSegs = state.currentSegments?.length || 0;
  if (totalSegs === 0) return;

  const targetIdx = carModeSeekPercentToIndex(percent);
  state.currentSegmentIndex = targetIdx;
  playSegment(targetIdx);
  updateCarModeUI();
}

function changeSpeed(speedVal) {
  const parsed = parseFloat(speedVal);
  state.playbackSpeed = (!isNaN(parsed) && parsed >= 0.4 && parsed <= 2.5) ? parsed : 0.8;
  if (audio) {
    audio.playbackRate = state.playbackSpeed;
  }
  const speedTextEl = document.getElementById('playbackSpeedText');
  if (speedTextEl) speedTextEl.textContent = `${state.playbackSpeed}x`;
  const floatSpeedTextEl = document.getElementById('floatPlaybackSpeedText');
  if (floatSpeedTextEl) floatSpeedTextEl.textContent = `${state.playbackSpeed}x`;
  const speedSelect = document.getElementById('playbackSpeedSelect');
  if (speedSelect) speedSelect.value = String(state.playbackSpeed);
  try {
    localStorage.setItem('narou_reader_playback_speed', String(state.playbackSpeed));
  } catch (e) {}
  updateMediaSessionPositionState();
}

// ==============================================
// 20. Media Session API 実装 (完全版)
// ==============================================
function setupMediaSession() {
  if (!('mediaSession' in navigator)) return;

  navigator.mediaSession.setActionHandler('play', () => togglePlayPause());
  navigator.mediaSession.setActionHandler('pause', () => togglePlayPause());

  navigator.mediaSession.setActionHandler('previoustrack', () => {
    if (state.currentSegmentIndex === 0 && state.currentEpisodeNum > 1) {
      navigateEpisode(-1);
    } else {
      jumpSegment(-1);
    }
  });

  navigator.mediaSession.setActionHandler('nexttrack', () => {
    if (state.currentSegmentIndex >= state.currentSegments.length - 1) {
      navigateEpisode(1);
    } else {
      jumpSegment(1);
    }
  });

  navigator.mediaSession.setActionHandler('seekbackward', () => jumpSegment(-1));
  navigator.mediaSession.setActionHandler('seekforward', () => jumpSegment(1));

  navigator.mediaSession.setActionHandler('seekto', (details) => {
    if (details.seekTime && audio && audio.duration) {
      audio.currentTime = details.seekTime;
      updateMediaSessionPositionState();
    }
  });

  navigator.mediaSession.setActionHandler('stop', () => pauseAudio());
}

function updateMediaSessionMetadata() {
  if (!('mediaSession' in navigator) || !state.currentNovel) return;

  const seg = state.currentSegments[state.currentSegmentIndex];
  const origin = window.location.origin;
  const icon192 = new URL('/static/icons/icon-192.png', origin).href;
  const icon512 = new URL('/static/icons/icon-512.png', origin).href;

  navigator.mediaSession.metadata = new MediaMetadata({
    title: seg?.display_text ? `${seg.display_text}` : state.currentNovel.title,
    artist: `${state.currentNovel.title} - 第${state.currentEpisodeNum}話 (${state.currentSegmentIndex + 1}/${state.currentSegments.length})`,
    album: `青空・文書AI朗読 [${seg?.speaker || 'ナレーション'}]`,
    artwork: [
      { src: icon192, sizes: '192x192', type: 'image/png' },
      { src: icon512, sizes: '512x512', type: 'image/png' },
    ]
  });

  navigator.mediaSession.playbackState = state.isPlaying ? 'playing' : 'paused';
  updateMediaSessionPositionState();
}

function updateMediaSessionPositionState() {
  if (!('mediaSession' in navigator) || !('setPositionState' in navigator.mediaSession) || !audio) return;
  if (!isNaN(audio.duration) && audio.duration > 0) {
    try {
      navigator.mediaSession.setPositionState({
        duration: audio.duration,
        playbackRate: audio.playbackRate || 1.0,
        position: Math.min(audio.currentTime || 0, audio.duration),
      });
    } catch (e) {}
  }
}

// ==============================================
// 21. 音声プレビュー & 配役エディタ (Cast Editor)
// ==============================================
let previewAudio = null;

async function previewVoice(voiceId) {
  vibrateFeedback();
  if (previewAudio) {
    previewAudio.pause();
    previewAudio = null;
  }
  try {
    const res = await apiFetch('/api/narou/episode/prepare', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ncode: 'preview',
        episode_num: 1,
        custom_cast: { '試聴': voiceId },
        pre_analyzed_segments: [
          { id: 1, type: 'dialogue', speaker: '試聴', display_text: 'これは音声のサンプルです。よろしくお願いします。' }
        ]
      })
    });
    const data = await res.json();
    if (data.segments?.[0]?.audio_url) {
      previewAudio = new Audio(data.segments[0].audio_url);
      previewAudio.play();
    }
  } catch (e) {
    alert('試聴の再生に失敗しました: ' + e.message);
  }
}

// ==============================================
// 14. 登場人物ボイス割り当て & ビジュアル配役エディタ
// ==============================================

let activeVoicePickerCharName = '';
let activeVoicePickerCharIndex = 0;
let activeVoicePickerCategory = 'all';
let activeVoicePickerQuery = '';

function renderCastEditor() {
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const titleBadge = document.getElementById('castNovelTitleBadge');
  if (titleBadge) {
    if (state.currentNovel?.title) {
      const locWork = typeof getLocalizedAozoraWork === 'function'
        ? getLocalizedAozoraWork({ ncode: state.currentNovel.ncode, title: state.currentNovel.title, author: state.currentNovel.author || '' }, uiLang)
        : null;
      const dispTitle = (locWork && locWork.displayTitle) || state.currentNovel.title;
      titleBadge.textContent = dispTitle;
      titleBadge.title = dispTitle;
    } else {
      titleBadge.textContent = tUi('carmode_no_title');
    }
  }

  const container = document.getElementById('castList');
  if (!container) return;
  container.innerHTML = '';

  let chars = state.currentCharacters;
  if (!chars || chars.length === 0) {
    const uniqueSpeakers = new Set();
    state.currentSegments.forEach(s => {
      if (s.speaker) uniqueSpeakers.add(s.speaker);
    });
    if (uniqueSpeakers.size > 0) {
      chars = Array.from(uniqueSpeakers).map(name => ({
        name,
        gender: name.includes('男') ? '男性' : (name.includes('女') || name.includes('ヒロイン') ? '女性' : '不明'),
        description: name === 'ナレーション' ? tUi('cast_narration_label') : 'Character'
      }));
    } else {
      chars = [{ name: 'ナレーション', gender: '不明', description: tUi('cast_narration_label') }];
    }
  }

  const castUiMap = {
    ja: { voiceSection: '割り当てボイス & 感情スタイル', pitch: 'ピッチ (音高)', speed: '話速 (テンポ)', echo: 'エコー', preview: '試聴', change: '配役変更', female: '女性', male: '男性', unknown: '不明', character: '登場人物', lines: '件' },
    en: { voiceSection: 'Assigned Voice & Style', pitch: 'Pitch', speed: 'Speed', echo: 'Echo', preview: 'Preview', change: 'Change', female: 'Female', male: 'Male', unknown: 'Neutral', character: 'Character', lines: 'lines' },
    zh: { voiceSection: '分配角色音色与风格', pitch: '音调', speed: '语速', echo: '回声', preview: '试听', change: '更换', female: '女性', male: '男性', unknown: '中性', character: '角色', lines: '句' },
    ko: { voiceSection: '할당 보이스 & 감정 스타일', pitch: '피치', speed: '속도', echo: '에코', preview: '미리듣기', change: '변경', female: '여성', male: '남성', unknown: '미상', character: '등장인물', lines: '문장' },
    es: { voiceSection: 'Voz y Estilo Asignados', pitch: 'Tono', speed: 'Velocidad', echo: 'Eco', preview: 'Probar', change: 'Cambiar', female: 'Mujer', male: 'Hombre', unknown: 'Neutro', character: 'Personaje', lines: 'líneas' },
    fr: { voiceSection: 'Voix & Style Attribués', pitch: 'Hauteur', speed: 'Vitesse', echo: 'Écho', preview: 'Écouter', change: 'Changer', female: 'Femme', male: 'Homme', unknown: 'Neutre', character: 'Personnage', lines: 'lignes' },
    pt: { voiceSection: 'Voz e Estilo Atribuídos', pitch: 'Tom', speed: 'Velocidade', echo: 'Eco', preview: 'Ouvir', change: 'Alterar', female: 'Feminino', male: 'Masculino', unknown: 'Neutro', character: 'Personagem', lines: 'falas' }
  };
  const cLabels = castUiMap[uiLang] || castUiMap.en;
  const voiceSectionTitle = cLabels.voiceSection;
  const tapToChangeLbl = tUi('player_tap_to_change_voice');
  const pitchLbl = cLabels.pitch;
  const speedLbl = cLabels.speed;
  const echoLbl = cLabels.echo;
  const previewLbl = cLabels.preview;
  const changeBtnLbl = cLabels.change;

  chars.forEach((char, idx) => {
    const profile = getCharacterVoiceProfile(char.name, char.gender, char.voice_type);

    const card = document.createElement('div');
    card.className = 'bg-slate-950/90 border border-slate-800 rounded-2xl p-4 flex flex-col justify-between shadow-md space-y-3';

    const cvBadgeHtml = (char.cv || profile.cv) ? `<span class="text-[10px] px-2 py-0.5 rounded-full bg-pink-950/60 border border-pink-500/30 text-pink-300 font-medium flex items-center gap-1"><i class="ph-bold ph-microphone"></i>CV: ${escapeHtml(char.cv || profile.cv)}</span>` : '';

    const speakerDisplayName = profile.speakerName || profile.name || 'VOICEVOX';
    const styleDisplayName = profile.styleName || (uiLang === 'ja' ? 'ノーマル' : 'Normal');
    const spDict = (uiLang !== 'ja' && typeof ON_DEVICE_SPEAKER_DICT !== 'undefined' && ON_DEVICE_SPEAKER_DICT[char.name]);
    const localizedCharName = (spDict && (spDict[uiLang] || spDict.en))
      || (char.name === 'ナレーション' && uiLang !== 'ja' ? tUi('cast_narration_label') : (uiLang !== 'ja' && typeof translateSpeakerOnDevice === 'function' ? translateSpeakerOnDevice(char.name, uiLang) : char.name));

    let rawDesc = char.description || '';
    if (uiLang !== 'ja') {
      if (rawDesc === '地の文' || char.name === 'ナレーション') {
        rawDesc = tUi('cast_narration_label');
      } else {
        const mLines = rawDesc.match(/セリフ\s*(\d+)\s*件/);
        if (mLines) {
          rawDesc = `${cLabels.character} (${mLines[1]} ${cLabels.lines})`;
        } else if (/登場人物|会話キャラ|追加エピソード/.test(rawDesc)) {
          rawDesc = cLabels.character;
        }
      }
    }

    const rawGender = String(char.gender || profile.gender || '').toLowerCase();
    let localizedGender = char.gender || profile.gender || '';
    if (uiLang !== 'ja') {
      if (rawGender === '女性' || rawGender === 'female') localizedGender = cLabels.female;
      else if (rawGender === '男性' || rawGender === 'male') localizedGender = cLabels.male;
      else localizedGender = cLabels.unknown;
    }

    card.innerHTML = `
      <div>
        <!-- キャラクター基本情報 -->
        <div class="flex items-center justify-between mb-1.5 flex-wrap gap-1.5">
          <div class="flex items-center space-x-2.5">
            <div class="w-8 h-8 rounded-xl flex items-center justify-center text-white font-bold text-xs shadow-sm shrink-0" style="background-color: ${profile.color || '#3b82f6'};">
              ${escapeHtml((localizedCharName || 'C').charAt(0))}
            </div>
            <div>
              <h4 class="text-sm font-bold text-slate-100">${escapeHtml(localizedCharName)}</h4>
              <p class="text-[10px] text-slate-400 truncate max-w-[150px]">${escapeHtml(rawDesc)}</p>
            </div>
          </div>
          <div class="flex items-center space-x-1.5">
            ${cvBadgeHtml}
            <span class="text-[10px] px-2 py-0.5 rounded-full bg-slate-800 text-slate-300 font-medium">${escapeHtml(localizedGender)}</span>
          </div>
        </div>
      </div>

      <!-- ボイス選択ボタン（タップで専用ボイスピッカーを開く） -->
      <div class="space-y-2 pt-2 border-t border-slate-900">
        <label class="text-[10px] text-emerald-400 font-bold flex items-center justify-between">
          <span class="flex items-center gap-1"><i class="ph-fill ph-waveform"></i> ${escapeHtml(voiceSectionTitle)}</span>
          <span class="text-[9px] text-slate-500">${escapeHtml(tapToChangeLbl)}</span>
        </label>

        <button type="button" onclick="openVoicePickerModal('${escapeHtml(char.name)}', ${idx})" class="w-full text-left bg-slate-900/90 hover:bg-slate-800/90 border border-slate-700 hover:border-emerald-500/50 rounded-xl p-2.5 flex items-center justify-between transition group active:scale-[0.99] shadow-sm">
          <div class="flex items-center space-x-2.5 min-w-0">
            <div class="w-8 h-8 rounded-lg flex items-center justify-center text-white font-bold text-xs shadow shrink-0" style="background-color: ${profile.color || '#3b82f6'};">
              ${escapeHtml(speakerDisplayName.charAt(0))}
            </div>
            <div class="min-w-0">
              <div class="flex items-center space-x-1.5">
                <span class="text-xs font-bold text-slate-100 truncate" id="vp-badge-${idx}">${escapeHtml(speakerDisplayName)}</span>
                <span class="px-1.5 py-0.5 rounded text-[10px] font-semibold bg-emerald-500/20 text-emerald-300" id="vp-style-badge-${idx}">${escapeHtml(styleDisplayName)}</span>
              </div>
              <p class="text-[10px] text-slate-400 truncate">${escapeHtml(profile.categoryName || profile.gender || '')} ${profile.echo ? `・${escapeHtml(echoLbl)} ON` : ''}</p>
            </div>
          </div>
          <div class="flex items-center space-x-1 shrink-0 text-emerald-400 font-semibold text-xs group-hover:translate-x-0.5 transition">
            <span>${escapeHtml(changeBtnLbl)}</span>
            <i class="ph-bold ph-caret-right"></i>
          </div>
        </button>

        <!-- ピッチ & 話速 微調整スライダー -->
        <div class="grid grid-cols-2 gap-2 text-[10px] text-slate-400 pt-1">
          <div class="bg-slate-900/60 p-2 rounded-xl border border-slate-800/80">
            <div class="flex justify-between font-medium"><span>${escapeHtml(pitchLbl)}</span><span class="text-emerald-400 font-bold" id="pitch-val-${idx}">${profile.pitch}</span></div>
            <input type="range" id="pitch-slider-${idx}" min="0.5" max="1.8" step="0.02" value="${profile.pitch}" oninput="onPitchSliderChange('${escapeHtml(char.name)}', ${idx}, this.value)" class="w-full accent-emerald-500 h-1 mt-1 bg-slate-800 rounded cursor-pointer">
          </div>
          <div class="bg-slate-900/60 p-2 rounded-xl border border-slate-800/80">
            <div class="flex justify-between font-medium"><span>${escapeHtml(speedLbl)}</span><span class="text-emerald-400 font-bold" id="rate-val-${idx}">${profile.rateMultiplier}x</span></div>
            <input type="range" id="rate-slider-${idx}" min="0.7" max="1.4" step="0.02" value="${profile.rateMultiplier}" oninput="onRateSliderChange('${escapeHtml(char.name)}', ${idx}, this.value)" class="w-full accent-emerald-500 h-1 mt-1 bg-slate-800 rounded cursor-pointer">
          </div>
        </div>

        <!-- エコー & 試聴 アクション -->
        <div class="pt-1 flex items-center justify-between">
          <label class="flex items-center space-x-1.5 text-[11px] text-slate-300 cursor-pointer select-none">
            <input type="checkbox" id="echo-toggle-${idx}" ${profile.echo ? 'checked' : ''} onchange="onEchoToggleChange('${escapeHtml(char.name)}', ${idx}, this.checked)" class="rounded accent-cyan-500 w-3.5 h-3.5">
            <span class="text-cyan-400 font-medium flex items-center gap-1">
              <i class="ph-fill ph-waves"></i> ${escapeHtml(echoLbl)}
            </span>
          </label>
          <div class="flex items-center space-x-2">
            <button onclick="previewVoiceProfileFromCard('${escapeHtml(char.name)}', ${idx})" class="px-3 py-1.5 bg-blue-600/20 hover:bg-blue-600/30 text-blue-400 rounded-xl border border-blue-500/30 text-xs font-semibold flex items-center space-x-1.5 transition active:scale-95 shadow-sm">
              <i class="ph-fill ph-speaker-high"></i>
              <span>${escapeHtml(previewLbl)}</span>
            </button>
          </div>
        </div>
      </div>
    `;

    container.appendChild(card);
  });
}

// ==============================================
// 専用ボイスピッカー モーダルシート コントローラー
// ==============================================

function openVoicePickerModal(charName, idx) {
  vibrateFeedback(8);
  activeVoicePickerCharName = charName;
  activeVoicePickerCharIndex = idx;
  activeVoicePickerQuery = '';
  activeVoicePickerCategory = 'all';

  const nameEl = document.getElementById('vpTargetCharName');
  if (nameEl) nameEl.textContent = `【${charName}】`;

  const searchInput = document.getElementById('vpSearchInput');
  if (searchInput) searchInput.value = '';
  const clearBtn = document.getElementById('vpSearchClearBtn');
  if (clearBtn) clearBtn.classList.add('hidden');

  setVoicePickerCategoryFilter('all');
  updateVoicePickerCurrentLabel();
  renderVoicePickerCards();

  const modal = document.getElementById('voicePickerModal');
  if (modal) {
    lockBodyScroll();
    modal.classList.remove('hidden');
  }
}

function closeVoicePickerModal() {
  const modal = document.getElementById('voicePickerModal');
  if (modal) modal.classList.add('hidden');
  unlockBodyScroll();
}

function updateVoicePickerCurrentLabel() {
  const label = document.getElementById('vpCurrentSelectionText');
  if (!label) return;
  const profile = getCharacterVoiceProfile(activeVoicePickerCharName);
  label.textContent = `${profile.speakerName || profile.name} (${profile.styleName || 'ノーマル'})`;
}

function setVoicePickerCategoryFilter(cat) {
  activeVoicePickerCategory = cat;
  document.querySelectorAll('.vp-cat-btn').forEach(btn => {
    btn.className = 'vp-cat-btn px-2.5 py-1 rounded-full text-[11px] font-semibold shrink-0 bg-slate-800 text-slate-300 hover:bg-slate-700 transition';
  });
  const activeBtn = document.getElementById(`vpCat-${cat}`);
  if (activeBtn) {
    activeBtn.className = 'vp-cat-btn px-2.5 py-1 rounded-full text-[11px] font-semibold shrink-0 bg-emerald-500 text-slate-950 shadow-sm transition';
  }
  renderVoicePickerCards();
}

function onVoicePickerSearchInput(val) {
  activeVoicePickerQuery = (val || '').trim().toLowerCase();
  const clearBtn = document.getElementById('vpSearchClearBtn');
  if (clearBtn) {
    if (activeVoicePickerQuery) clearBtn.classList.remove('hidden');
    else clearBtn.classList.add('hidden');
  }
  renderVoicePickerCards();
}

function clearVoicePickerSearch() {
  const input = document.getElementById('vpSearchInput');
  if (input) input.value = '';
  onVoicePickerSearchInput('');
}

function renderVoicePickerCards() {
  const container = document.getElementById('vpCardsContainer');
  if (!container) return;
  container.innerHTML = '';

  const currentProfile = getCharacterVoiceProfile(activeVoicePickerCharName);
  const currentVpId = currentProfile.id || currentProfile.voicevoxId;

  // カテゴリ判定フィルター
  const femaleCats = ['zundamon', 'metan', 'tsumugi', 'hau', 'ritsu', 'himari', 'sora', 'mochiko', 'no7', 'nurse_robot', 'miko', 'hanamaru', 'nekotsukai', 'chugoku_usagi'];
  const maleCats = ['takehiro', 'kotaro', 'ryusei', 'mesuo'];
  const mascotCats = ['zundamon', 'kotaro', 'miko', 'hanamaru', 'nekotsukai', 'chugoku_usagi'];
  const systemCats = ['system_divine', 'no7', 'nurse_robot', 'other_characters'];

  let matchedProfiles = VOICE_PROFILES_CATALOG.filter(vp => {
    // 0. Androidスタンドアロン時は同梱VVMスタイルまたは標準TTSのみ表示（クレジットと実音声の完全一致を保証）
    if (isAndroidApp && !vp.isNativeTts && vp.styleId != null && !VOICEVOX_BUNDLED_STYLE_IDS.has(vp.styleId)) {
      return false;
    }

    // 1. カテゴリタブ判定
    if (activeVoicePickerCategory === 'native' && vp.category !== 'native_tts') return false;
    if (activeVoicePickerCategory === 'female' && !femaleCats.includes(vp.category)) return false;
    if (activeVoicePickerCategory === 'male' && !maleCats.includes(vp.category)) return false;
    if (activeVoicePickerCategory === 'mascot' && !mascotCats.includes(vp.category)) return false;
    if (activeVoicePickerCategory === 'system' && !systemCats.includes(vp.category)) return false;

    // 2. 検索キーワード判定
    if (activeVoicePickerQuery) {
      const targetStr = `${vp.name} ${vp.speakerName} ${vp.styleName} ${vp.categoryName} ${vp.gender}`.toLowerCase();
      if (!targetStr.includes(activeVoicePickerQuery)) return false;
    }
    return true;
  });

  if (matchedProfiles.length === 0) {
    container.innerHTML = `
      <div class="py-12 text-center text-slate-400 space-y-2">
        <i class="ph-bold ph-magnifying-glass text-3xl text-slate-600"></i>
        <p class="text-xs">該当するボイス・スタイルが見つかりませんでした。</p>
      </div>
    `;
    return;
  }

  // キャラクターごとにグループ化
  const groupedBySpeaker = {};
  matchedProfiles.forEach(vp => {
    const speakerKey = vp.speakerName || vp.categoryName || vp.name;
    if (!groupedBySpeaker[speakerKey]) {
      groupedBySpeaker[speakerKey] = [];
    }
    groupedBySpeaker[speakerKey].push(vp);
  });

  Object.keys(groupedBySpeaker).forEach(speakerKey => {
    const profiles = groupedBySpeaker[speakerKey];
    const first = profiles[0];
    const charColor = first.color || '#3b82f6';

    const card = document.createElement('div');
    card.className = 'bg-slate-950/80 border border-slate-800/90 rounded-2xl p-3.5 space-y-2.5 shadow-sm';

    // キャラクターヘッダー
    const isSelectedChar = profiles.some(p => p.id === currentVpId || p.voicevoxId === currentProfile.voicevoxId);
    card.innerHTML = `
      <div class="flex items-center justify-between pb-2 border-b border-slate-900">
        <div class="flex items-center space-x-2.5">
          <div class="w-8 h-8 rounded-xl flex items-center justify-center text-white font-bold text-xs shadow-sm" style="background-color: ${charColor};">
            ${escapeHtml(speakerKey.charAt(0))}
          </div>
          <div>
            <div class="flex items-center space-x-2">
              <h4 class="text-xs sm:text-sm font-bold text-slate-100">${escapeHtml(speakerKey)}</h4>
              <span class="text-[9px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-300">${escapeHtml(first.gender || '女性')}</span>
            </div>
            <p class="text-[10px] text-slate-400">${escapeHtml(first.categoryName || '')}</p>
          </div>
        </div>
        ${isSelectedChar ? '<span class="text-[10px] px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 font-bold border border-emerald-500/30">現在選択中</span>' : ''}
      </div>

      <!-- 感情スタイル一覧（ピルボタングリッド） -->
      <div class="grid grid-cols-2 sm:grid-cols-3 gap-2 pt-0.5">
        ${profiles.map(p => {
          const isCurrent = (p.id === currentVpId || p.voicevoxId === currentProfile.voicevoxId || p.id === currentProfile.id);
          const activeStyleClass = isCurrent
            ? 'bg-emerald-500/20 border-emerald-500 text-emerald-300 font-bold shadow-sm shadow-emerald-500/20 ring-1 ring-emerald-500/50'
            : 'bg-slate-900/90 border-slate-700/80 text-slate-300 hover:bg-slate-800 hover:border-slate-600';

          return `
            <div class="flex items-center rounded-xl border ${activeStyleClass} p-1.5 transition active:scale-95 cursor-pointer" onclick="selectVoiceProfileFromPicker('${p.id}')">
              <div class="flex-1 min-w-0 pr-1">
                <div class="flex items-center space-x-1">
                  ${isCurrent ? '<i class="ph-bold ph-check text-emerald-400 text-xs"></i>' : ''}
                  <span class="text-xs truncate">${escapeHtml(p.styleName || 'ノーマル')}</span>
                </div>
              </div>
              <button type="button" onclick="event.stopPropagation(); previewVoiceProfileFromPicker('${p.id}', '${escapeHtml(p.styleName)}', '${escapeHtml(p.speakerName)}')" class="w-6 h-6 rounded-lg bg-slate-800/80 hover:bg-blue-600 hover:text-white text-slate-400 flex items-center justify-center transition shrink-0" title="スタイル試聴">
                <i class="ph-fill ph-speaker-high text-[11px]"></i>
              </button>
            </div>
          `;
        }).join('')}
      </div>
    `;

    container.appendChild(card);
  });
}

let _castAutoPersistTimer = null;

function persistAndApplyCastChangeImmediately(charName, options = {}) {
  if (!charName) return;
  const debounceMs = typeof options.debounceMs === 'number' ? options.debounceMs : 0;
  if (!state.currentCastProfiles) state.currentCastProfiles = {};
  if (!state.currentCast) state.currentCast = {};

  const prof = state.currentCastProfiles[charName] || getCharacterVoiceProfile(charName);
  const voiceToken = prof?.voicevoxId || prof?.voiceId || prof?.id || state.currentCast[charName] || '';
  if (voiceToken) {
    state.currentCast[charName] = voiceToken;
    if (state.currentNovelCast) {
      state.currentNovelCast[charName] = voiceToken;
    }
  }

  // 現在再生対象エピソードのセグメント音声IDにも即座に反映
  if (Array.isArray(state.currentSegments) && voiceToken) {
    state.currentSegments.forEach((seg) => {
      const sp = seg?.speaker || (seg?.type === 'narration' ? 'ナレーション' : '登場人物');
      if (sp === charName) {
        seg.voice = voiceToken;
        seg.voiceId = voiceToken;
        seg.voice_id = voiceToken;
      }
    });
  }

  const doPersist = async () => {
    const ncodeLower = state.currentNovel?.ncode ? String(state.currentNovel.ncode).toLowerCase() : '';
    if (!ncodeLower) return;

    try {
      const cacheKey = `narou_novel_cast_${ncodeLower}`;
      const existingRaw = localStorage.getItem(cacheKey);
      const existing = existingRaw ? JSON.parse(existingRaw) : {};
      const updatedCastData = {
        ...existing,
        ncode: ncodeLower,
        scanned_episodes: existing.scanned_episodes || getSettingScanEpisodes(),
        characters: state.currentCharacters?.length ? state.currentCharacters : (existing.characters || []),
        cast: { ...(existing.cast || {}), ...(state.currentCast || {}) },
        cast_profiles: { ...(existing.cast_profiles || {}), ...(state.currentCastProfiles || {}) },
        last_updated: new Date().toISOString()
      };
      localStorage.setItem(cacheKey, JSON.stringify(updatedCastData));
    } catch (e) {
      console.warn('[CastAutoSave] localStorage persist warning:', e);
    }

    if (state.currentEpisodeNum && typeof NarouIDB !== 'undefined' && NarouIDB.getEpisode && NarouIDB.saveEpisode) {
      try {
        const ep = await NarouIDB.getEpisode(ncodeLower, state.currentEpisodeNum);
        if (ep) {
          ep.cast = { ...(ep.cast || {}), ...(state.currentCast || {}) };
          ep.cast_profiles = { ...(ep.cast_profiles || {}), ...(state.currentCastProfiles || {}) };
          if (Array.isArray(ep.segments) && voiceToken) {
            ep.segments.forEach((seg) => {
              const sp = seg?.speaker || (seg?.type === 'narration' ? 'ナレーション' : '登場人物');
              if (sp === charName) {
                seg.voice = voiceToken;
                seg.voiceId = voiceToken;
                seg.voice_id = voiceToken;
              }
            });
          }
          await NarouIDB.saveEpisode(ncodeLower, state.currentEpisodeNum, ep);
        }
      } catch (e) {
        console.warn('[CastAutoSave] IndexedDB saveEpisode warning:', e);
      }
    }
  };

  if (debounceMs > 0) {
    if (_castAutoPersistTimer) clearTimeout(_castAutoPersistTimer);
    _castAutoPersistTimer = setTimeout(() => {
      _castAutoPersistTimer = null;
      doPersist();
    }, debounceMs);
  } else {
    doPersist();
  }
}

function selectVoiceProfileFromPicker(vpId) {
  vibrateFeedback(12);
  const selectedVp = VOICE_PROFILES_CATALOG.find(v => v.id === vpId);
  if (!selectedVp) return;

  const profileCopy = { ...selectedVp };
  if (profileCopy.styleId != null) {
    const ci = getOfficialVoicevoxCreditInfo(profileCopy.styleId);
    profileCopy.styleId = ci.styleId;
    profileCopy.voicevoxId = `voicevox_${ci.styleId}`;
    profileCopy.speakerName = ci.speakerName;
    profileCopy.creditText = ci.credit;
  }

  if (!state.currentCastProfiles) state.currentCastProfiles = {};
  state.currentCastProfiles[activeVoicePickerCharName] = profileCopy;
  persistAndApplyCastChangeImmediately(activeVoicePickerCharName, { debounceMs: 0 });

  // カード側の表示更新
  const idx = activeVoicePickerCharIndex;
  const badge = document.getElementById(`vp-badge-${idx}`);
  if (badge) badge.textContent = profileCopy.speakerName || profileCopy.name;
  const styleBadge = document.getElementById(`vp-style-badge-${idx}`);
  if (styleBadge) styleBadge.textContent = profileCopy.styleName || 'ノーマル';

  const pSlider = document.getElementById(`pitch-slider-${idx}`);
  if (pSlider) pSlider.value = profileCopy.pitch;
  const pVal = document.getElementById(`pitch-val-${idx}`);
  if (pVal) pVal.textContent = profileCopy.pitch;
  const rSlider = document.getElementById(`rate-slider-${idx}`);
  if (rSlider) rSlider.value = profileCopy.rateMultiplier;
  const rVal = document.getElementById(`rate-val-${idx}`);
  if (rVal) rVal.textContent = `${profileCopy.rateMultiplier}x`;
  const echoToggle = document.getElementById(`echo-toggle-${idx}`);
  if (echoToggle) echoToggle.checked = !!profileCopy.echo;

  updateVoicePickerCurrentLabel();
  renderVoicePickerCards();
  showToast(`🎉 【${activeVoicePickerCharName}】の声を「${profileCopy.speakerName} (${profileCopy.styleName})」に即時反映・自動保存しました`, 'success');
}

function previewVoiceProfileFromPicker(vpId, styleName, speakerName) {
  vibrateFeedback(10);
  const vp = VOICE_PROFILES_CATALOG.find(v => v.id === vpId);
  if (!vp) return;

  const sampleText = `${speakerName}の${styleName}スタイルです。よろしくお願いします！`;
  const pitch = vp.pitch || 1.0;
  const rate = vp.rateMultiplier || 1.0;

  if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.speakText === 'function') {
    const assignedVoice = vp.voicevoxId || vp.id || '';
    window.AndroidBridge.speakText(sampleText, assignedVoice, pitch, rate, 'preview_voice', !!vp.echo);
    return;
  }

  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
    const utter = new SpeechSynthesisUtterance(sampleText);
    utter.lang = 'ja-JP';
    utter.pitch = pitch;
    utter.rate = rate;
    window.speechSynthesis.speak(utter);
  }
}

function onEchoToggleChange(charName, idx, isChecked) {
  vibrateFeedback(8);
  const profile = getCharacterVoiceProfile(charName);
  profile.echo = isChecked;
  if (!state.currentCastProfiles) state.currentCastProfiles = {};
  state.currentCastProfiles[charName] = profile;
  persistAndApplyCastChangeImmediately(charName, { debounceMs: 50 });
}

function onPitchSliderChange(charName, idx, val) {
  const p = parseFloat(val);
  const pVal = document.getElementById(`pitch-val-${idx}`);
  if (pVal) pVal.textContent = p.toFixed(2);
  const profile = getCharacterVoiceProfile(charName);
  profile.pitch = p;
  if (!state.currentCastProfiles) state.currentCastProfiles = {};
  state.currentCastProfiles[charName] = profile;
  persistAndApplyCastChangeImmediately(charName, { debounceMs: 250 });
}

function onRateSliderChange(charName, idx, val) {
  const r = parseFloat(val);
  const rVal = document.getElementById(`rate-val-${idx}`);
  if (rVal) rVal.textContent = `${r.toFixed(2)}x`;
  const profile = getCharacterVoiceProfile(charName);
  profile.rateMultiplier = r;
  if (!state.currentCastProfiles) state.currentCastProfiles = {};
  state.currentCastProfiles[charName] = profile;
  persistAndApplyCastChangeImmediately(charName, { debounceMs: 250 });
}

function previewVoiceProfileFromCard(charName, idx) {
  vibrateFeedback();
  const profile = getCharacterVoiceProfile(charName);
  const sampleText = profile.echo ? `${charName}。世界の理を告げる者なり……。` : `${charName}です。声のバリエーションはいかがでしょうか？よろしくお願いします。`;
  const pitch = profile.pitch || 1.0;
  const rate = profile.rateMultiplier || 1.0;

  if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.speakText === 'function') {
    const assignedVoice = profile.voicevoxId || profile.id || profile.voiceId || '';
    window.AndroidBridge.speakText(sampleText, assignedVoice, pitch, rate, 'preview_voice', !!profile.echo);
    return;
  }

  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
    const utter = new SpeechSynthesisUtterance(sampleText);
    utter.lang = 'ja-JP';
    utter.pitch = pitch;
    utter.rate = rate;
    window.speechSynthesis.speak(utter);
  }
}

async function applyCustomCastAndRegenerate() {
  showToast('登場人物の配役設定を更新しました', 'success');
  if (state.currentNovel && state.currentEpisodeNum) {
    await startReadingEpisode(state.currentEpisodeNum, state.currentCast, true);
  }
}

