function openVoicevoxCreditModal() {
  const modal = document.getElementById('voicevoxCreditModal');
  if (!modal) return;

  // 1. 現在の作品で使用されているVOICEVOXキャラクターのクレジットを自動抽出
  updateCurrentCastCreditsUI();

  // 2. キャラクター一覧の描画
  renderVoicevoxCreditsList();

  modal.classList.remove('hidden');
}

function closeVoicevoxCreditModal() {
  const modal = document.getElementById('voicevoxCreditModal');
  if (modal) modal.classList.add('hidden');
}

function updateCurrentCastCreditsUI() {
  const box = document.getElementById('currentCastCreditsBox');
  if (!box) return;

  const usedCredits = new Set();

  // 1. 現在のエピソードのセグメント話者から実際に発声されるプロファイルの公式クレジットを収集
  if (Array.isArray(state.segments) && state.segments.length > 0) {
    state.segments.forEach(seg => {
      const sp = seg?.speaker || 'ナレーション';
      const prof = getCharacterVoiceProfile(sp);
      if (prof && !prof.isNativeTts) {
        const ci = getOfficialVoicevoxCreditInfo(prof);
        if (ci && ci.credit) usedCredits.add(ci.credit);
      }
    });
  }

  // 2. currentCastProfiles からも収集
  if (state.currentCastProfiles && typeof state.currentCastProfiles === 'object') {
    Object.values(state.currentCastProfiles).forEach(prof => {
      if (prof && !prof.isNativeTts) {
        const ci = getOfficialVoicevoxCreditInfo(prof);
        if (ci && ci.credit) usedCredits.add(ci.credit);
      }
    });
  }

  // 3. currentCast マップからも収集
  const castMap = state.currentCast || {};
  Object.values(castMap).forEach(voiceId => {
    if (typeof voiceId === 'string' && voiceId.startsWith('voicevox_')) {
      const ci = getOfficialVoicevoxCreditInfo(voiceId);
      if (ci && ci.credit) usedCredits.add(ci.credit);
    }
  });

  if (usedCredits.size > 0) {
    const lines = Array.from(usedCredits);
    lines.push('VOICEVOX公式サイト: https://voicevox.hiroshiba.jp/');
    box.textContent = lines.join('\n');
  } else {
    // 作品未選択時はアプリ同梱モデルの全9キャラクター公式クレジットを表示
    const bundledCredits = VOICEVOX_CHARACTERS_DATABASE.filter(c => c.bundled).map(c => c.credit);
    bundledCredits.push('VOICEVOX公式サイト: https://voicevox.hiroshiba.jp/');
    box.textContent = bundledCredits.join('\n');
  }
}

function copyCurrentCastVoicevoxCredits() {
  const box = document.getElementById('currentCastCreditsBox');
  if (box && box.textContent) {
    copyTextToClipboard(box.textContent.trim(), '現在の作品のクレジットをコピーしました！');
  }
}

function copyGenericVoicevoxTemplate() {
  const text = '音声：VOICEVOX\nVOICEVOX公式サイト：https://voicevox.hiroshiba.jp/';
  copyTextToClipboard(text, '汎用クレジットテンプレートをコピーしました！');
}

function copyCharacterCredit(creditText) {
  copyTextToClipboard(creditText, `「${creditText}」をコピーしました！`);
}

function copyTextToClipboard(text, successMsg = 'クリップボードにコピーしました！') {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      showMiniToast(successMsg);
    }).catch(() => {
      prompt('以下のテキストをコピーしてください:', text);
    });
  } else {
    prompt('以下のテキストをコピーしてください:', text);
  }
}

function showMiniToast(msg) {
  const existing = document.getElementById('appMiniToast');
  if (existing) existing.remove();

  const toast = document.createElement('div');
  toast.id = 'appMiniToast';
  // 下部ナビゲーションやミニプレイヤーに被らないよう bottom-20 に配置
  toast.className = 'fixed bottom-20 right-4 z-[9999] bg-emerald-600 text-white px-3.5 py-2 rounded-xl text-xs font-semibold shadow-2xl flex items-center space-x-2 animate-fadeIn';

  toast.innerHTML = `<i class="ph-bold ph-check-circle text-base"></i><span>${escapeHtml(msg)}</span>`;
  document.body.appendChild(toast);

  setTimeout(() => {
    toast.classList.add('opacity-0', 'transition-opacity', 'duration-300');
    setTimeout(() => toast.remove(), 300);
  }, 2200);
}

function renderVoicevoxCreditsList(filterQuery = '') {
  const container = document.getElementById('vvCharacterCreditsList');
  if (!container) return;

  const query = filterQuery.toLowerCase().trim();
  const matchedList = VOICEVOX_CHARACTERS_DATABASE.filter(c => {
    return !query || c.name.toLowerCase().includes(query) || c.credit.toLowerCase().includes(query);
  });

  if (matchedList.length === 0) {
    container.innerHTML = '<div class="text-center py-4 text-slate-500 text-xs">一致するキャラクターが見つかりませんでした</div>';
    return;
  }

  container.innerHTML = matchedList.map(c => `
    <div class="flex flex-col sm:flex-row sm:items-center justify-between p-2.5 rounded-lg bg-slate-950/60 border ${c.bundled ? 'border-emerald-700/50' : 'border-slate-800/80'} hover:border-slate-700 transition text-xs gap-1.5">
      <div class="min-w-0 space-y-0.5">
        <div class="flex items-center space-x-2 min-w-0 flex-wrap gap-y-1">
          <span class="w-1.5 h-1.5 rounded-full ${c.bundled ? 'bg-emerald-400' : 'bg-slate-500'} shrink-0"></span>
          <span class="font-bold text-slate-200 truncate">${escapeHtml(c.name)}</span>
          ${c.bundled ? `<span class="px-1.5 py-0.5 rounded bg-emerald-950 text-emerald-300 border border-emerald-700/50 text-[9px] font-mono">同梱 (${escapeHtml(c.vvm)})</span>` : ''}
          <span class="font-mono text-[11px] text-emerald-300/90 truncate">${escapeHtml(c.credit)}</span>
        </div>
        ${c.note ? `<p class="text-[10px] text-slate-400 pl-3.5">${escapeHtml(c.note)}</p>` : ''}
      </div>
      <div class="flex items-center space-x-1.5 shrink-0 self-end sm:self-center">
        <button onclick="copyCharacterCredit('${escapeHtml(c.credit)}')" class="px-2.5 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded text-[11px] font-medium flex items-center space-x-1 transition border border-slate-700" title="クレジットをコピー">
          <i class="ph ph-copy"></i>
          <span>コピー</span>
        </button>
        <a href="${c.policyUrl}" target="_blank" rel="noopener noreferrer" class="px-2 py-1 bg-slate-800 hover:bg-slate-700 text-blue-400 rounded text-[11px] transition border border-slate-700 inline-flex items-center space-x-1" title="キャラクター利用規約を開く">
          <span>規約</span>
          <i class="ph ph-arrow-square-out text-xs"></i>
        </a>
      </div>
    </div>
  `).join('');
}

function filterVoicevoxCredits() {
  const input = document.getElementById('vvCreditSearchInput');
  const query = input ? input.value : '';
  renderVoicevoxCreditsList(query);
}

// ==============================================
// 21. Android Google AdMob 広告マネタイズ連携
// ==============================================

/** 新規取得30話ごとに全画面広告（ダウンロード区切り） */
const DOWNLOAD_INTERSTITIAL_EVERY = 30;
/** 広告表示中にダウンロードを止める最大時間（動画が長くても15秒で再開） */
const DOWNLOAD_INTERSTITIAL_MAX_BLOCK_MS = 15_000;
let _downloadInterstitialNewCount = 0;
let _interstitialCloseWaiters = [];
let _interstitialDidShow = false;

window.onAndroidInterstitialShown = function() {
  _interstitialDidShow = true;
};

window.onAndroidInterstitialClosed = function() {
  const waiters = _interstitialCloseWaiters.splice(0, _interstitialCloseWaiters.length);
  waiters.forEach((fn) => {
    try { fn(); } catch (e) {}
  });
};

function waitForAndroidInterstitialClosed(timeoutMs = DOWNLOAD_INTERSTITIAL_MAX_BLOCK_MS) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = () => {
      if (settled) return;
      settled = true;
      resolve();
    };
    _interstitialCloseWaiters.push(finish);
    setTimeout(finish, timeoutMs);
  });
}

/**
 * ダウンロード中の30話区切りで全画面広告を表示し、閉じるまで（最大15秒）取得ループを一時停止する。
 * 未準備・表示失敗時はカウンターを戻し、次話で再試行する（機会損失防止）。
 */
async function maybeShowDownloadInterstitialAdBreak(progressCtx = null) {
  if (!(typeof isAndroidApp !== 'undefined' && isAndroidApp && window.AndroidBridge)) return false;
  if (typeof window.AndroidBridge.tryShowDownloadInterstitialAd !== 'function'
    && typeof window.AndroidBridge.showInterstitialAd !== 'function') {
    return false;
  }

  _downloadInterstitialNewCount++;

  // 到達数話前からプリロード（30話ちょうどでロード待ちにならないようにする）
  if (_downloadInterstitialNewCount === DOWNLOAD_INTERSTITIAL_EVERY - 5
    || _downloadInterstitialNewCount === DOWNLOAD_INTERSTITIAL_EVERY - 1) {
    if (typeof window.AndroidBridge.preloadInterstitialAd === 'function') {
      try { window.AndroidBridge.preloadInterstitialAd(); } catch (e) {}
    }
  }

  if (_downloadInterstitialNewCount < DOWNLOAD_INTERSTITIAL_EVERY) return false;

  if (typeof window.AndroidBridge.preloadInterstitialAd === 'function') {
    try { window.AndroidBridge.preloadInterstitialAd(); } catch (e) {}
  }

  // 最大約12秒待ちで広告ロード（初回・在庫薄時の余裕）
  for (let i = 0; i < 24; i++) {
    const ready = typeof window.AndroidBridge.isInterstitialAdReady === 'function'
      && window.AndroidBridge.isInterstitialAdReady();
    if (ready) break;
    if (i === 0 || i === 12) {
      try { window.AndroidBridge.preloadInterstitialAd?.(); } catch (e) {}
    }
    await new Promise((r) => setTimeout(r, 500));
  }

  const ready = typeof window.AndroidBridge.isInterstitialAdReady === 'function'
    && window.AndroidBridge.isInterstitialAdReady();
  if (!ready) {
    console.warn('[DownloadAd] Interstitial not ready after wait; retry next episode');
    // 次話で即再試行（カウンターを消費しない）
    _downloadInterstitialNewCount = DOWNLOAD_INTERSTITIAL_EVERY - 1;
    return false;
  }

  if (progressCtx && typeof reportNovelDownloadProgress === 'function') {
    reportNovelDownloadProgress({
      ...progressCtx,
      statusText: '全画面広告表示中（最大15秒でダウンロード再開）…',
      phase: 'running'
    });
  } else if (typeof showMiniToast === 'function') {
    showMiniToast('30話取得区切り：広告表示（最大15秒）…');
  }

  const closed = waitForAndroidInterstitialClosed(DOWNLOAD_INTERSTITIAL_MAX_BLOCK_MS);
  let shown = false;
  _interstitialDidShow = false;
  try {
    if (typeof window.AndroidBridge.tryShowDownloadInterstitialAd === 'function') {
      shown = !!window.AndroidBridge.tryShowDownloadInterstitialAd();
    } else {
      shown = !!window.AndroidBridge.showInterstitialAd();
    }
  } catch (e) {
    console.warn('[DownloadAd] show failed:', e);
    window.onAndroidInterstitialClosed();
    _downloadInterstitialNewCount = DOWNLOAD_INTERSTITIAL_EVERY - 1;
    return false;
  }

  if (!shown) {
    console.warn('[DownloadAd] show returned false (interval or not ready); retry next episode');
    window.onAndroidInterstitialClosed();
    _downloadInterstitialNewCount = DOWNLOAD_INTERSTITIAL_EVERY - 1;
    return false;
  }

  await closed;

  // show() は成功しても onAdFailedToShow になり得る → 実表示時のみカウント消費
  if (!_interstitialDidShow) {
    console.warn('[DownloadAd] scheduled show but ad did not appear; retry next episode');
    _downloadInterstitialNewCount = DOWNLOAD_INTERSTITIAL_EVERY - 1;
    return false;
  }

  _downloadInterstitialNewCount = 0;
  return true;
}

/** 30話バッチ完了時（continueDownloadNovel 等）に1回表示 */
async function showDownloadBatchInterstitialAd(downloadedCount = 0) {
  if (downloadedCount < 1) return false;
  // カウンターを満タンにして共通ロジックへ
  _downloadInterstitialNewCount = DOWNLOAD_INTERSTITIAL_EVERY - 1;
  return maybeShowDownloadInterstitialAdBreak({
    statusText: '30話バッチ完了：広告表示中…',
    counterText: `${downloadedCount}話完了`,
    phase: 'running'
  });
}

/**
 * エピソード遷移時・読了時の全画面広告配信最適化 (Monetization & UX Engine)
 * - ポリシー遵守: 画面表示中 (foreground) の自然な区切りのみ配信
 * - バックグラウンド再生中・画面オフ時は絶対スキップ (ポリシー違反・無効インプレッション防止)
 * - プレミアム購入済みユーザーはスキップ
 * - 広告表示中は朗読を一時停止し、クローズを待機してから次話をスムーズに開始
 */
async function maybeShowEpisodeTransitionInterstitial() {
  if (!isAndroidAppNow() || !window.AndroidBridge) return false;
  
  // 1. 画面がフォアグラウンド（表示中）でない場合は絶対に表示しない
  const isForeground = document.visibilityState === 'visible' && !document.hidden;
  if (!isForeground) {
    console.log('[AdMob] Interstitial skipped: app is not in foreground.');
    return false;
  }

  // 2. プレミアム購入ユーザー判定
  if (typeof isPremiumPurchased === 'function' && isPremiumPurchased()) {
    return false;
  }
  if (typeof window.AndroidBridge.isPremiumBgPurchased === 'function' && window.AndroidBridge.isPremiumBgPurchased()) {
    return false;
  }

  // 3. 広告ブリッジの呼び出し（コールバック取りこぼし防止のため先に待機Promiseを登録）
  const closed = waitForAndroidInterstitialClosed(12000);
  let shown = false;
  try {
    if (typeof window.AndroidBridge.tryShowEpisodeTransitionInterstitial === 'function') {
      shown = !!window.AndroidBridge.tryShowEpisodeTransitionInterstitial(isForeground);
    } else if (typeof window.AndroidBridge.onEpisodeTransition === 'function') {
      shown = !!window.AndroidBridge.onEpisodeTransition();
    }
  } catch (e) {
    console.warn('[AdMob] Episode transition interstitial check failed:', e);
    if (typeof window.onAndroidInterstitialClosed === 'function') window.onAndroidInterstitialClosed();
    return false;
  }

  if (!shown) {
    if (typeof window.onAndroidInterstitialClosed === 'function') window.onAndroidInterstitialClosed();
    return false;
  }

  console.log('[AdMob] Interstitial ad showing. Waiting for user dismiss...');
  pauseAudio();
  await closed;
  console.log('[AdMob] Interstitial ad dismissed. Resuming playback sequence.');
  return true;
}

function triggerWatchRewardedAd() {
  // §26 triggerWatchRewardAd に一本化（旧 bonus_credit 経路の残骸）
  if (typeof triggerWatchRewardAd === 'function') {
    triggerWatchRewardAd();
    return;
  }
  if (window.AndroidBridge && typeof window.AndroidBridge.showRewardedAd === 'function') {
    window.AndroidBridge.showRewardedAd(typeof REWARD_TYPE_BG_PLAYBACK !== 'undefined' ? REWARD_TYPE_BG_PLAYBACK : 'bg_playback_3h');
  } else {
    alert('現在この端末では動画リワード広告の再生に対応していません。');
  }
}

// ==============================================
// 22. ダウンロード済みデータ & ストレージ管理 (Downloads Manager)
// ==============================================

let loadedDownloadedNovelsList = [];

async function loadDownloadsData(force = false) {
  const container = document.getElementById('downloadsNovelList');
  if (!container) return;

  if (force || loadedDownloadedNovelsList.length === 0) {
    container.innerHTML = `
      <div class="py-16 text-center text-slate-500 text-xs">
        <div class="inline-block w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin mb-2"></div>
        <p>${escapeHtml(tUi('trans_gate_checking'))}</p>
      </div>
    `;
  }

  try {
    // 1. 保存済み小説一覧とストレージサマリーを並行取得
    const [novelsRes, summaryRes] = await Promise.all([
      apiFetch('/api/downloads/novels'),
      apiFetch('/api/downloads/summary')
    ]);

    const novelsData = await novelsRes.json();
    const summaryData = await summaryRes.json();

    if (novelsData.success && Array.isArray(novelsData.novels)) {
      loadedDownloadedNovelsList = novelsData.novels;
      renderDownloadedNovels(loadedDownloadedNovelsList);

      // バッジ更新
      const badgeHeader = document.getElementById('downloadsBadge');
      const badgeList = document.getElementById('downloadsListBadge');
      if (badgeHeader) {
        badgeHeader.textContent = loadedDownloadedNovelsList.length;
        badgeHeader.classList.toggle('hidden', loadedDownloadedNovelsList.length === 0);
      }
      if (badgeList) {
        badgeList.textContent = `${loadedDownloadedNovelsList.length}`;
      }
    }

    if (summaryData.success && summaryData.summary) {
      updateStorageSummaryUI(summaryData.summary);
    }
  } catch (err) {
    console.error('[DownloadManager] Error loading downloads data:', err);
    if (container) {
      container.innerHTML = `
        <div class="p-6 bg-slate-900 border border-red-500/30 rounded-xl text-center space-y-2">
          <i class="ph ph-warning text-2xl text-red-400"></i>
          <p class="text-xs text-red-300">${escapeHtml(err.message)}</p>
          <button onclick="loadDownloadsData(true)" class="mt-2 px-3 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs rounded-lg border border-slate-700">${escapeHtml(tUi('dl_refresh_btn'))}</button>
        </div>
      `;
    }
  }
}

function updateStorageSummaryUI(summary) {
  if (typeof state !== 'undefined') state._lastStorageSummary = summary;
  const usageText = document.getElementById('storageUsageText');
  const progressBar = document.getElementById('storageProgressBar');
  const statNovelCount = document.getElementById('statNovelCount');
  const statEpisodeCount = document.getElementById('statEpisodeCount');
  const statNovelSize = document.getElementById('statNovelSize');
  const statAudioSize = document.getElementById('statAudioSize');
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';

  if (usageText) {
    usageText.textContent = `${summary.total_used_mb} MB / ${summary.max_cache_size_mb} MB (${summary.usage_percent}%)`;
  }
  if (progressBar) {
    progressBar.style.width = `${Math.min(100, summary.usage_percent)}%`;
    if (summary.usage_percent > 85) {
      progressBar.className = 'bg-gradient-to-r from-rose-500 to-amber-500 h-full rounded-full transition-all duration-500';
    } else if (summary.usage_percent > 60) {
      progressBar.className = 'bg-gradient-to-r from-amber-500 to-yellow-400 h-full rounded-full transition-all duration-500';
    } else {
      progressBar.className = 'bg-gradient-to-r from-emerald-500 to-teal-400 h-full rounded-full transition-all duration-500';
    }
  }
  if (statNovelCount) statNovelCount.textContent = uiLang === 'ja' ? `${summary.downloaded_novels_count} 作品` : `${summary.downloaded_novels_count}`;
  if (statEpisodeCount) statEpisodeCount.textContent = tUi('toc_total_episodes', { count: summary.total_downloaded_episodes });
  if (statNovelSize) statNovelSize.textContent = `${summary.novel_text_size_mb} MB`;
  if (statAudioSize) statAudioSize.textContent = `${(summary.audio_size_mb + (summary.combined_audio_size_mb || 0)).toFixed(1)} MB`;
}

function renderDownloadedNovels(novels) {
  const container = document.getElementById('downloadsNovelList');
  if (!container) return;
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';

  if (!novels || novels.length === 0) {
    container.innerHTML = `
      <div class="py-16 text-center space-y-3 bg-slate-900/60 border border-slate-800/80 rounded-2xl p-6">
        <div class="w-14 h-14 mx-auto rounded-2xl bg-slate-800/80 flex items-center justify-center text-2xl text-slate-500">
          <i class="ph ph-folder-dashed"></i>
        </div>
        <div>
          <h4 class="text-sm font-bold text-slate-300">${escapeHtml(tUi('dl_title'))}</h4>
          <p class="text-xs text-slate-400 mt-1 max-w-sm mx-auto leading-relaxed">
            ${escapeHtml(tUi('dl_empty_msg'))}
          </p>
        </div>
        <button onclick="switchTab('search')" class="mt-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-xs font-semibold shadow-lg shadow-blue-600/30 transition inline-flex items-center space-x-1.5">
          <i class="ph ph-magnifying-glass"></i>
          <span>${escapeHtml(tUi('tab_search'))}</span>
        </button>
      </div>
    `;
    return;
  }

  container.innerHTML = novels.map(novel => {
    const downloadedCount = novel.downloaded_episodes_count ?? novel.downloaded_count ?? novel.saved_episodes_count ?? 0;
    const totalEpisodes = novel.total_episodes || (downloadedCount > 0 ? downloadedCount : 1);
    const isComplete = novel.is_complete || (downloadedCount >= totalEpisodes && totalEpisodes > 0);
    const progressPercent = novel.progress_percent ?? (totalEpisodes > 0 ? Math.min(100, Math.round((downloadedCount / totalEpisodes) * 100)) : 100);
    const sizeMb = novel.size_mb ?? (downloadedCount * 0.05).toFixed(1);

    const locWork = typeof getLocalizedAozoraWork === 'function'
      ? getLocalizedAozoraWork({ ncode: novel.ncode, title: novel.title, author: novel.author || '', synopsis: novel.synopsis || '' }, uiLang)
      : null;
    const dispTitle = (locWork && locWork.displayTitle) || novel.title;
    const dispAuthor = (locWork && locWork.displayAuthor) || novel.author || '';
    const dispSynopsis = (locWork && locWork.displaySynopsis) || novel.synopsis || '';

    const badgeHtml = isComplete
      ? `<span class="px-2 py-0.5 bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 rounded-full text-[10px] font-bold flex items-center space-x-1"><i class="ph-bold ph-check"></i><span>${escapeHtml(tUi('toc_all_saved_badge', { total: totalEpisodes }))}</span></span>`
      : `<span class="px-2 py-0.5 bg-blue-500/20 text-blue-300 border border-blue-500/40 rounded-full text-[10px] font-bold flex items-center space-x-1"><i class="ph ph-download-simple"></i><span>${downloadedCount}/${totalEpisodes} (${progressPercent}%)</span></span>`;

    const txtBadge = novel.has_full_txt
      ? `<a href="/api/narou/download/export-txt/${novel.ncode}" target="_blank" class="px-2 py-0.5 bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 rounded-md text-[10px] flex items-center space-x-1"><i class="ph ph-file-text text-blue-400"></i><span>TXT</span></a>`
      : '';

    let progressMap = {};
    try {
      progressMap = JSON.parse(localStorage.getItem('narou_novel_progress_map') || '{}');
    } catch (e) {}
    const readProgress = progressMap[novel.ncode];
    let readBadgeHtml = '';
    if (readProgress && readProgress.episodeNum) {
      const epStr = uiLang === 'ja' ? `第${readProgress.episodeNum}話 ${readProgress.progress}%` : `Ep.${readProgress.episodeNum} (${readProgress.progress}%)`;
      readBadgeHtml = `<span class="px-2 py-0.5 bg-amber-500/20 text-amber-300 border border-amber-500/40 rounded-full text-[10px] font-bold flex items-center space-x-1"><i class="ph-bold ph-headphones"></i><span>${escapeHtml(epStr)}</span></span>`;
    }

    const continueBtn = !isComplete
      ? `<button onclick="continueDownloadNovel('${novel.ncode}', ${downloadedCount + 1})" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-emerald-400 hover:text-emerald-300 rounded-xl text-xs font-medium border border-emerald-500/30 transition flex items-center space-x-1"><i class="ph-bold ph-plus"></i><span>+DL</span></button>`
      : '';

    const bcp47 = (SUPPORTED_MAJOR_LANGUAGES[uiLang] && SUPPORTED_MAJOR_LANGUAGES[uiLang].bcp47) || 'en-US';
    const formattedDate = novel.last_updated
      ? new Date(novel.last_updated * 1000).toLocaleDateString(bcp47, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
      : (novel.saved_at ? new Date(novel.saved_at).toLocaleDateString(bcp47, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '---');

    return `
      <div class="p-4 bg-slate-900 hover:bg-slate-900/90 border border-slate-800/90 rounded-2xl transition space-y-3 shadow-lg">
        <div class="flex flex-col sm:flex-row sm:items-start justify-between gap-2">
          <div class="space-y-1 min-w-0 flex-1">
            <div class="flex flex-wrap items-center gap-1.5">
              ${readBadgeHtml}
              ${badgeHtml}
              <span class="px-1.5 py-0.5 bg-slate-800 text-slate-400 rounded text-[10px] font-mono uppercase">${escapeHtml(novel.ncode)}</span>
              ${txtBadge}
              <span class="text-[10px] text-slate-500 ml-auto sm:ml-0">${formattedDate}</span>
            </div>
            <h4 data-dl-title-ncode="${escapeHtml(novel.ncode)}" class="text-sm sm:text-base font-bold text-slate-100 hover:text-blue-400 cursor-pointer transition line-clamp-1" onclick="openDownloadedNovelToc('${novel.ncode}')">
              ${escapeHtml(dispTitle)}
            </h4>
            <p data-dl-author-ncode="${escapeHtml(novel.ncode)}" class="text-xs text-slate-400">${escapeHtml(dispAuthor)}</p>
          </div>
          <div class="text-right sm:shrink-0 flex sm:flex-col items-center sm:items-end justify-between text-[11px] text-slate-400">
            <span class="font-mono text-slate-300 font-medium">${sizeMb} MB</span>
            <span class="text-[10px] text-slate-500">${escapeHtml(tUi('dl_saved_episodes', { saved: downloadedCount, total: totalEpisodes }))}</span>
          </div>
        </div>

        ${dispSynopsis ? `<p data-dl-synopsis-ncode="${escapeHtml(novel.ncode)}" class="text-xs text-slate-400 line-clamp-2 leading-relaxed bg-slate-950/40 p-2 rounded-xl border border-slate-800/40">${escapeHtml(dispSynopsis)}</p>` : ''}
        ${(locWork && locWork.displayOpening) ? `<p class="text-[11px] text-emerald-200/90 italic line-clamp-2 leading-relaxed bg-slate-950/70 px-2.5 py-1.5 rounded-xl border border-emerald-500/20"><span class="font-bold not-italic text-emerald-400 mr-1">${escapeHtml(locWork.openingLabel)}</span>${escapeHtml(locWork.displayOpening)}</p>` : ''}

        <!-- アクションボタンバー（初心者向け階層レイアウト：最上段に大きく再生ボタン、下段にサブ操作） -->
        <div class="pt-2 border-t border-slate-800/60 space-y-2">
          <button onclick="startReadingDownloadedNovel('${novel.ncode}')" class="w-full py-2.5 px-4 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white rounded-xl text-xs sm:text-sm font-bold shadow-md shadow-blue-900/30 flex items-center justify-center space-x-2 transition active:scale-[0.99]">
            <i class="ph-fill ph-play-circle text-base"></i>
            <span>${readProgress && readProgress.episodeNum ? (uiLang === 'ja' ? `第${readProgress.episodeNum}話の続きから朗読 (${readProgress.progress}%)` : `${escapeHtml(tUi('dl_read_btn'))} (Ep.${readProgress.episodeNum})`) : escapeHtml(tUi('dl_read_btn'))}</span>
          </button>

          <div class="flex flex-wrap items-center justify-between gap-1.5">
            <div class="flex flex-wrap items-center gap-1.5">
              <button onclick="openDownloadedNovelToc('${novel.ncode}')" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-xl text-xs font-medium border border-slate-700 transition flex items-center space-x-1 active:scale-95">
                <i class="ph ph-list-bullets"></i>
                <span>${escapeHtml(tUi('tab_toc'))}</span>
              </button>
              <button onclick="openNovelAiReanalyzeModal('${novel.ncode}', '${escapeHtml(dispTitle)}', 1)" class="px-3 py-1.5 bg-indigo-600/20 hover:bg-indigo-600/40 text-indigo-300 hover:text-white border border-indigo-500/30 rounded-xl text-xs font-semibold transition flex items-center space-x-1 active:scale-95">
                <i class="ph-bold ph-user-sound text-indigo-400"></i>
                <span>${escapeHtml(tUi('tab_cast'))}</span>
              </button>
              <button onclick="triggerBackgroundAudioGeneration('${novel.ncode}', 1, ${downloadedCount})" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-purple-300 hover:text-purple-200 rounded-xl text-xs font-medium border border-purple-500/30 transition flex items-center space-x-1 active:scale-95">
                <i class="ph-bold ph-waveform"></i>
                <span>${escapeHtml(tUi('dl_voice_create_btn'))}</span>
              </button>
              ${continueBtn}
            </div>

            <button onclick="deleteDownloadedNovelConfirm('${novel.ncode}', '${escapeHtml(dispTitle)}')" class="px-2.5 py-1.5 bg-slate-800/80 hover:bg-rose-950/60 text-slate-400 hover:text-rose-400 border border-slate-700/80 hover:border-rose-500/40 rounded-xl text-xs transition flex items-center space-x-1" title="${escapeHtml(tUi('dl_delete_btn'))}">
              <i class="ph ph-trash text-sm"></i>
              <span class="text-[11px]">${escapeHtml(tUi('dl_delete_btn'))}</span>
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');

  // 非プリセット作品のタイトル・あらすじも外国語UI時は非同期で自動翻訳して反映
  if (uiLang !== 'ja' && typeof translatePreviewTextAsync === 'function') {
    novels.forEach((novel) => {
      const i18nHit = typeof findAozoraWorkI18nEntry === 'function' ? findAozoraWorkI18nEntry(novel) : null;
      if (i18nHit) return;
      if (novel.title && /[\u3040-\u30ff\u4e00-\u9faf]/.test(novel.title)) {
        translatePreviewTextAsync(novel.title, uiLang).then((tr) => {
          if (!tr || getEffectiveAppUiLanguage() !== uiLang) return;
          const el = container.querySelector(`[data-dl-title-ncode="${CSS.escape(String(novel.ncode))}"]`);
          if (el) el.textContent = tr;
        }).catch(() => {});
      }
      if (novel.synopsis && /[\u3040-\u30ff\u4e00-\u9faf]/.test(novel.synopsis)) {
        translatePreviewTextAsync(novel.synopsis.slice(0, 240), uiLang).then((tr) => {
          if (!tr || getEffectiveAppUiLanguage() !== uiLang) return;
          const el = container.querySelector(`[data-dl-synopsis-ncode="${CSS.escape(String(novel.ncode))}"]`);
          if (el) el.textContent = tr;
        }).catch(() => {});
      }
    });
  }
}

function filterDownloadedNovels() {
  const input = document.getElementById('downloadsFilterInput');
  const query = input ? input.value.toLowerCase().trim() : '';

  if (!query) {
    renderDownloadedNovels(loadedDownloadedNovelsList);
    return;
  }

  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const filtered = loadedDownloadedNovelsList.filter(n => {
    const locWork = typeof getLocalizedAozoraWork === 'function'
      ? getLocalizedAozoraWork({ ncode: n.ncode, title: n.title, author: n.author || '', synopsis: n.synopsis || '' }, uiLang)
      : null;
    return (
      (n.title && n.title.toLowerCase().includes(query)) ||
      (n.author && n.author.toLowerCase().includes(query)) ||
      (n.ncode && n.ncode.toLowerCase().includes(query)) ||
      (n.synopsis && n.synopsis.toLowerCase().includes(query)) ||
      (locWork?.displayTitle && locWork.displayTitle.toLowerCase().includes(query)) ||
      (locWork?.displayAuthor && locWork.displayAuthor.toLowerCase().includes(query)) ||
      (locWork?.displaySynopsis && locWork.displaySynopsis.toLowerCase().includes(query))
    );
  });

  renderDownloadedNovels(filtered);
}

async function startReadingDownloadedNovel(ncode) {
  if (!ncode) return;
  try {
    const raw = decodeURIComponent(String(ncode)).toLowerCase();
    pauseAudio();
    cancelBackgroundAudioGenerationJobs({ clearQueue: false });
    showMiniToast(`『${raw.toUpperCase()}』を開いています...`);

    // オフライン優先: 端末内保存データを先に使う（ネット取得で別作品状態が残る事故を防ぐ）
    let novelData = null;
    if (typeof NarouIDB !== 'undefined' && NarouIDB.getNovel) {
      novelData = await NarouIDB.getNovel(raw);
    }
    if (!novelData) {
      const res = await apiFetch(`/api/narou/novel/${encodeURIComponent(raw)}`);
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.error || err.detail || '作品情報の取得に失敗しました');
      }
      novelData = await res.json();
    }
    if (!novelData.ncode) novelData.ncode = raw;
    displayNovelTOC(novelData);

    if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.setCurrentPlaybackContext === 'function') {
      try {
        window.AndroidBridge.setCurrentPlaybackContext(raw, 1);
      } catch (e) {}
    }

    const lastState = JSON.parse(localStorage.getItem('narou_last_read') || 'null');
    const lastNcode = lastState?.ncode ? String(lastState.ncode).toLowerCase() : '';
    const startEp = (lastNcode === raw && lastState.episodeNum)
      ? lastState.episodeNum
      : 1;
    switchTab('player');
    await startReadingEpisode(startEp, null, false, true);
  } catch (e) {
    alert(`作品の読み込みに失敗しました: ${e.message}`);
  }
}

async function openDownloadedNovelToc(ncode) {
  if (!ncode) return;
  try {
    showMiniToast(`『${ncode.toUpperCase()}』の目次を開いています...`);
    const res = await apiFetch(`/api/narou/novel/${encodeURIComponent(ncode)}`);
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error || err.detail || '作品情報の取得に失敗しました');
    }
    const novelData = await res.json();
    displayNovelTOC(novelData);
    switchTab('toc');
  } catch (e) {
    alert(`目次の読み込みに失敗しました: ${e.message}`);
  }
}

async function continueDownloadNovel(ncode, startEp = 1) {
  if (!ncode) return;
  if (!NovelDownloadGate.tryAcquire(ncode)) return;
  showMiniToast(`『${ncode.toUpperCase()}』の第${startEp}話以降を安全に取得中...`);

  try {
    const res = await apiFetch(`/api/narou/download/${encodeURIComponent(ncode)}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ start_episode: startEp, max_episodes: 30, max_bytes: 5242880 })
    });
    const data = await res.json();

    if (data.success) {
      const mb = (data.bytes_downloaded / (1024 * 1024)).toFixed(2);
      const msg = data.message || `✔ 第${data.start_episode}話〜第${data.end_episode}話のダウンロードが完了しました！`;
      alert(`${msg}\n（取得サイズ: ${mb} MB / 保存話数: 第${data.start_episode}話〜第${data.end_episode}話）`);
      await loadDownloadsData(true);
    } else {
      alert('ダウンロードに失敗しました: ' + (data.error || '不明なエラー'));
    }
  } catch (e) {
    alert('通信エラー: ' + e.message);
  } finally {
    NovelDownloadGate.release(ncode);
  }
}

async function deleteDownloadedNovelConfirm(ncode, title) {
  const confirmed = confirm(`『${title || ncode}』のローカル保存データを削除しますか？\n\n※エピソード本文、目次、全文テキスト、音声キャッシュ、解析データが完全に消去されます。`);
  if (!confirmed) return;

  try {
    const res = await apiFetch(`/api/downloads/novels/${encodeURIComponent(ncode)}`, {
      method: 'DELETE'
    });
    const data = await res.json();

    if (data.success) {
      showMiniToast(`✔ 『${title || ncode}』のデータを削除しました（${data.freed_mb} MB解放）`);
      await loadDownloadsData(true);
    } else {
      alert('削除に失敗しました: ' + (data.error || '不明なエラー'));
    }
  } catch (e) {
    alert('削除通信エラー: ' + e.message);
  }
}

