function setReaderTheme(themeName) {
  triggerHaptic('tick');
  document.body.classList.remove('theme-dark', 'theme-oled', 'theme-paper', 'theme-sepia');
  document.body.classList.add(`theme-${themeName}`);
  state.readerTheme = themeName;
  localStorage.setItem('narou_reader_theme', themeName);
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const themeLabels = uiLang === 'ja'
    ? { dark: 'ダーク', oled: 'OLED漆黒', paper: 'ペーパーホワイト', sepia: '暖色セピア' }
    : { dark: 'Dark', oled: 'OLED Black', paper: 'Paper White', sepia: 'Warm Sepia' };
  showMiniToast(`${uiLang === 'ja' ? 'テーマ' : 'Theme'}: ${themeLabels[themeName] || themeName}`);
}

function setReaderFont(fontClass) {
  triggerHaptic('tick');
  state.readerFontClass = fontClass;
  localStorage.setItem('narou_reader_font_class', fontClass);
  applyReaderTypography();
}



function toggleVerticalMode() {
  triggerHaptic('click');
  const container = document.getElementById('segmentsContainer');
  const btnText = document.getElementById('verticalModeText');
  if (!container) return;

  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isVertical = container.classList.toggle('vertical-reader');
  if (btnText) {
    btnText.textContent = uiLang === 'ja'
      ? (isVertical ? '横書きに戻す' : '縦書きにする')
      : (isVertical ? 'Horizontal Text' : 'Vertical Text');
  }
  localStorage.setItem('narou_reader_vertical', isVertical ? '1' : '0');
  showMiniToast(uiLang === 'ja'
    ? (isVertical ? '縦書き表示に切り替えました' : '横書き表示に切り替えました')
    : (isVertical ? 'Switched to Vertical Text' : 'Switched to Horizontal Text'));
}

function toggleAutoScroll() {
  triggerHaptic('click');
  state.autoScroll = !state.autoScroll;
  const btn = document.getElementById('autoScrollBtn');
  const btnText = document.getElementById('autoScrollBtnText');
  if (state.autoScroll) {
    if (btn) btn.className = 'px-2.5 py-1.5 rounded-xl bg-blue-600/20 text-blue-300 border border-blue-500/40 text-[11px] font-medium flex items-center space-x-1 transition active:scale-95';
    if (btnText) btnText.textContent = tUi('player_auto_scroll');
    highlightCurrentSegment(state.currentSegmentIndex);
  } else {
    if (btn) btn.className = 'px-2.5 py-1.5 rounded-xl bg-slate-800 text-slate-400 border border-slate-700 text-[11px] font-medium flex items-center space-x-1 transition active:scale-95';
    if (btnText) btnText.textContent = tUi('player_auto_scroll');
  }
}



// =============================================================================
// 17. FTUE (初回ガイド) & Hero レジューム & 読書統計 (ストリーク・時間)
// =============================================================================
function initFTUEAndHero() {
  // FTUE 判定
  const ftueDismissed = localStorage.getItem('narou_ftue_dismissed');
  const ftueCard = document.getElementById('ftueIntroCard');
  if (ftueCard && !ftueDismissed) {
    ftueCard.classList.remove('hidden');
  }

  // Hero レジュームカードの更新
  updateHeroResumeCard();

  // 読書ストリーク & 累計朗読時間の更新
  updateUserStatsUI();

  // バックグラウンド再生の解放状態UI更新
  updateBgPlaybackUI();
}

function dismissFTUE() {
  triggerHaptic('click');
  localStorage.setItem('narou_ftue_dismissed', '1');
  const ftueCard = document.getElementById('ftueIntroCard');
  if (ftueCard) {
    ftueCard.classList.add('hidden');
  }
}

function updateHeroResumeCard() {
  const lastState = JSON.parse(localStorage.getItem('narou_last_read') || 'null');
  const heroCard = document.getElementById('heroResumeCard');
  const beginnerResumeBtn = document.getElementById('beginnerResumeListeningBtn');
  const beginnerResumeText = document.getElementById('beginnerResumeListeningText');

  if (lastState && lastState.ncode && lastState.novelTitle) {
    if (heroCard) heroCard.classList.remove('hidden');
    if (beginnerResumeBtn) {
      beginnerResumeBtn.classList.remove('hidden');
      beginnerResumeBtn.classList.add('flex');
    }
    const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
    const locResume = typeof getLocalizedAozoraWork === 'function'
      ? getLocalizedAozoraWork({ id: lastState.ncode, ncode: lastState.ncode, title: lastState.novelTitle }, uiLang)
      : null;
    const dispResumeTitle = (locResume && locResume.displayTitle) || lastState.novelTitle;
    if (beginnerResumeText) {
      beginnerResumeText.textContent = uiLang === 'ja'
        ? `続きを聴く: ${dispResumeTitle}`
        : `${tUi('beginner_resume_btn')}: ${dispResumeTitle}`;
    }

    const titleEl = document.getElementById('resumeNovelTitle');
    const epTitleEl = document.getElementById('resumeEpisodeTitle');
    const progressPill = document.getElementById('resumeProgressPill');
    const segCounterEl = document.getElementById('heroResumeSegCounter');
    const percentEl = document.getElementById('heroResumePercentText');
    const sliderEl = document.getElementById('heroResumeSlider');

    const progress = lastState.progress || 0;
    const currentSeg = (lastState.segmentIndex || 0) + 1;
    const totalSegs = lastState.totalSegments || (state.currentSegments?.length || 0);

    if (titleEl) {
      const cacheKey = `${uiLang}::${lastState.ncode}::${lastState.novelTitle}`;
      const cachedTr = window.__heroResumeTitleCache && window.__heroResumeTitleCache[cacheKey];
      const finalTitle = cachedTr || dispResumeTitle;
      titleEl.textContent = finalTitle;
      if (cachedTr && beginnerResumeText) {
        beginnerResumeText.textContent = `${tUi('beginner_resume_btn')}: ${cachedTr}`;
      }
      if (!cachedTr && uiLang !== 'ja' && !(locResume && locResume.isTranslatedPreset) && /[\u3040-\u30ff\u4e00-\u9faf]/.test(lastState.novelTitle) && typeof translatePreviewTextAsync === 'function') {
        translatePreviewTextAsync(lastState.novelTitle, uiLang).then((tr) => {
          if (tr && getEffectiveAppUiLanguage() === uiLang) {
            if (!window.__heroResumeTitleCache) window.__heroResumeTitleCache = {};
            window.__heroResumeTitleCache[cacheKey] = tr;
            if (titleEl) titleEl.textContent = tr;
            if (beginnerResumeText) beginnerResumeText.textContent = `${tUi('beginner_resume_btn')}: ${tr}`;
          }
        }).catch(() => {});
      }
    }
    if (epTitleEl) {
      epTitleEl.textContent = uiLang === 'ja'
        ? (lastState.episodeTitle || `第 ${lastState.episodeNum} 話`)
        : `Ep. ${lastState.episodeNum}`;
    }
    if (progressPill) {
      progressPill.textContent = uiLang === 'ja'
        ? `第${lastState.episodeNum}話 ${progress}%`
        : `Ep. ${lastState.episodeNum} · ${progress}%`;
    }
    if (segCounterEl) {
      segCounterEl.textContent = uiLang === 'ja'
        ? (totalSegs > 0 ? `再生位置: ${currentSeg} / ${totalSegs} 文` : `再生位置: ${progress}%`)
        : (totalSegs > 0 ? `Position: ${currentSeg} / ${totalSegs}` : `Progress: ${progress}%`);
    }
    if (percentEl) percentEl.textContent = `${progress}%`;
    if (sliderEl) sliderEl.value = progress;
  } else {
    if (heroCard) heroCard.classList.add('hidden');
    if (beginnerResumeBtn) {
      beginnerResumeBtn.classList.add('hidden');
      beginnerResumeBtn.classList.remove('flex');
    }
  }
}

function togglePlayerMoreToolsDrawer(forceOpen) {
  const drawer = document.getElementById('playerMoreToolsDrawer');
  const btn = document.getElementById('playerMoreToolsToggleBtn');
  if (!drawer) return;
  const isCurrentlyHidden = drawer.classList.contains('hidden');
  const nextOpen = typeof forceOpen === 'boolean' ? forceOpen : isCurrentlyHidden;
  drawer.classList.toggle('hidden', !nextOpen);
  if (btn) {
    btn.classList.toggle('bg-blue-600/30', nextOpen);
    btn.classList.toggle('border-blue-500/50', nextOpen);
    btn.classList.toggle('text-blue-200', nextOpen);
  }
}
window.togglePlayerMoreToolsDrawer = togglePlayerMoreToolsDrawer;

function onHeroResumeSliderInput(val) {
  const percent = parseInt(val, 10) || 0;
  const percentEl = document.getElementById('heroResumePercentText');
  const progressPill = document.getElementById('resumeProgressPill');
  const segCounterEl = document.getElementById('heroResumeSegCounter');

  if (percentEl) percentEl.textContent = `${percent}%`;

  const lastState = JSON.parse(localStorage.getItem('narou_last_read') || 'null');
  if (lastState) {
    if (progressPill) progressPill.textContent = `第${lastState.episodeNum}話 ${percent}%`;
    const totalSegs = lastState.totalSegments || 100;
    const targetSeg = Math.max(1, Math.min(totalSegs, Math.round((percent / 100) * totalSegs)));
    if (segCounterEl) segCounterEl.textContent = `再生位置: ${targetSeg} / ${totalSegs} 文`;
  }
}

async function onHeroResumeSliderChange(val) {
  vibrateFeedback(10);
  const percent = parseInt(val, 10) || 0;
  const lastState = JSON.parse(localStorage.getItem('narou_last_read') || 'null');
  if (!lastState || !lastState.ncode) return;

  showMiniToast(`再生位置を ${percent}% に移動して朗読を開始します`);
  await loadNovelByQuery(lastState.ncode);

  if (lastState.episodeNum) {
    await startReadingEpisode(lastState.episodeNum, null, false, false);
    const totalSegs = state.currentSegments?.length || 1;
    const targetSegIndex = Math.max(0, Math.min(totalSegs - 1, Math.round((percent / 100) * (totalSegs - 1))));
    state.currentSegmentIndex = targetSegIndex;
    playSegment(targetSegIndex);
  }
}

function saveReadingProgress(ncode, novelTitle, episodeNum, episodeTitle, segmentIndex, totalSegments) {
  const progress = totalSegments > 0 ? Math.round(((segmentIndex + 1) / totalSegments) * 100) : 0;
  const stateObj = {
    ncode,
    novelTitle,
    episodeNum,
    episodeTitle,
    segmentIndex,
    totalSegments,
    progress,
    updatedAt: Date.now()
  };
  localStorage.setItem('narou_last_read', JSON.stringify(stateObj));
  try {
    const map = JSON.parse(localStorage.getItem('narou_novel_progress_map') || '{}');
    map[ncode] = stateObj;
    localStorage.setItem('narou_novel_progress_map', JSON.stringify(map));
  } catch (e) {}
  updateHeroResumeCard();
}


async function resumeLastListening() {
  triggerHaptic('click');
  const lastState = JSON.parse(localStorage.getItem('narou_last_read') || 'null');
  if (!lastState || !lastState.ncode) return;

  showMiniToast(`『${lastState.novelTitle || lastState.ncode}』の続きを読み込み中...`);
  await loadNovelByQuery(lastState.ncode);

  if (lastState.episodeNum) {
    await startReadingEpisode(lastState.episodeNum, null, false, true);
    if (lastState.segmentIndex > 0 && lastState.segmentIndex < state.currentSegments.length) {
      state.currentSegmentIndex = lastState.segmentIndex;
      playSegment(lastState.segmentIndex);
    }
  }
}
window.resumeLastRead = resumeLastListening;

function updateUserStatsUI() {
  // ストリーク計算
  const todayStr = new Date().toISOString().slice(0, 10);
  const lastDate = localStorage.getItem('narou_last_active_date');
  let streak = parseInt(localStorage.getItem('narou_streak_days') || '1', 10);

  if (lastDate && lastDate !== todayStr) {
    const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
    if (lastDate === yesterday) {
      streak += 1;
    } else {
      streak = 1;
    }
    localStorage.setItem('narou_streak_days', streak.toString());
  }
  localStorage.setItem('narou_last_active_date', todayStr);

  const streakElem = document.getElementById('streakDaysVal');
  if (streakElem) streakElem.textContent = streak;

  // 累計時間 (分)
  const totalMins = parseInt(localStorage.getItem('narou_total_listen_minutes') || '0', 10);
  const timeElem = document.getElementById('listenTimeVal');
  if (timeElem) timeElem.textContent = totalMins;

  // 読了エピソード数
  const completedCount = parseInt(localStorage.getItem('narou_completed_episodes_count') || '0', 10);
  const compElem = document.getElementById('completedEpisodesVal');
  if (compElem) compElem.textContent = completedCount;
}

// 再生中に定期的に朗読時間を加算 & BG再生タイマー表示更新（1分ごと）
setInterval(() => {
  if (state.isPlaying) {
    let currentMins = parseInt(localStorage.getItem('narou_total_listen_minutes') || '0', 10);
    currentMins += 1;
    localStorage.setItem('narou_total_listen_minutes', currentMins.toString());
    const timeElem = document.getElementById('listenTimeVal');
    if (timeElem) timeElem.textContent = currentMins;
  }
  updateBgPlaybackUI();
}, 60000);

// =============================================================================
// 18. Google Play ストア評価プロンプト (読了トリガー & 頻出抑制)
// =============================================================================
let selectedRatingStars = 5;

// エピソード読了時の処理（全セグメント再生完了時）
function recordEpisodeCompletion() {
  let comp = parseInt(localStorage.getItem('narou_completed_episodes_count') || '0', 10) + 1;
  localStorage.setItem('narou_completed_episodes_count', comp.toString());
  const compElem = document.getElementById('completedEpisodesVal');
  if (compElem) compElem.textContent = comp;
  checkPlayStorePromptCondition(comp);

  if (typeof getReadingStreakData === 'function' && typeof saveReadingStreakData === 'function') {
    const data = getReadingStreakData();
    data.totalEpisodesRead = (data.totalEpisodesRead || 0) + 1;
    saveReadingStreakData(data);
    if (typeof checkAndUpdateDailyStreak === 'function') checkAndUpdateDailyStreak();
  }
}

function checkPlayStorePromptCondition(completedEpisodes = null) {
  // 1. Android アプリ環境のみ対象（デスクトップ版・Web版では表示しない）
  if (!isAndroidApp && (!window.AndroidBridge || typeof window.AndroidBridge.speakText !== 'function')) {
    return;
  }

  // 2. 既に評価済み または 永久非表示フラグの確認
  const promptShown = localStorage.getItem('narou_play_store_prompt_shown');
  if (promptShown === '1') return;

  const neverShow = localStorage.getItem('narou_rating_never_show');
  if (neverShow === '1') return;

  // 3. 「後で」押下回数の確認（2回以上「後で」が選ばれたら二度と出さない）
  const dismissCount = parseInt(localStorage.getItem('narou_rating_dismiss_count') || '0', 10);
  if (dismissCount >= 2) {
    localStorage.setItem('narou_play_store_prompt_shown', '1');
    return;
  }

  // 4. クールダウン期間の確認（次回判定まで最低14日間は再表示しない）
  const dismissedUntil = parseInt(localStorage.getItem('narou_rating_dismissed_until') || '0', 10);
  if (dismissedUntil && Date.now() < dismissedUntil) {
    return;
  }

  // 5. 読了条件の確認（最低5話以上読了 かつ 累計朗読時間15分以上）
  const comp = completedEpisodes !== null 
    ? completedEpisodes 
    : parseInt(localStorage.getItem('narou_completed_episodes_count') || '0', 10);
  const totalMins = parseInt(localStorage.getItem('narou_total_listen_minutes') || '0', 10);

  if (comp >= 5 && totalMins >= 15) {
    setTimeout(() => {
      const modal = document.getElementById('playStoreRatingModal');
      if (modal) {
        modal.classList.remove('hidden');
        selectRatingStar(5);
      }
    }, 1200);
  }
}

function selectRatingStar(stars) {
  triggerHaptic('click');
  selectedRatingStars = stars;
  const buttons = document.querySelectorAll('.star-btn');
  buttons.forEach((btn, idx) => {
    if (idx < stars) {
      btn.className = 'star-btn p-1 text-2xl text-amber-400 hover:text-amber-300 transition';
    } else {
      btn.className = 'star-btn p-1 text-2xl text-slate-600 hover:text-amber-400 transition';
    }
  });

  const posBtn = document.getElementById('ratingPositiveBtn');
  const feedbackSec = document.getElementById('ratingFeedbackSection');

  if (stars === 5) {
    posBtn?.classList.remove('hidden');
    feedbackSec?.classList.add('hidden');
  } else {
    posBtn?.classList.add('hidden');
    feedbackSec?.classList.remove('hidden');
  }
}

function openPlayStorePage() {
  triggerHaptic('heavy');
  localStorage.setItem('narou_play_store_prompt_shown', '1');
  dismissRatingModal(false);
  const playStoreUrl = 'market://details?id=com.surei.naroureader';
  const webFallback = 'https://play.google.com/store/apps/details?id=com.surei.naroureader';
  try {
    window.location.href = playStoreUrl;
  } catch (e) {
    window.open(webFallback, '_blank');
  }
}

function submitFeedbackAndDismiss() {
  triggerHaptic('click');
  localStorage.setItem('narou_play_store_prompt_shown', '1');
  const text = document.getElementById('ratingFeedbackText')?.value || '';
  dismissRatingModal(false);
  showMiniToast('貴重なご意見ありがとうございます！');
}

function dismissRatingModal(isLater = false, neverAgain = false) {
  triggerHaptic('tick');
  const modal = document.getElementById('playStoreRatingModal');
  if (modal) modal.classList.add('hidden');

  if (neverAgain) {
    localStorage.setItem('narou_play_store_prompt_shown', '1');
    localStorage.setItem('narou_rating_never_show', '1');
    showMiniToast('案内を非表示に設定しました');
    return;
  }

  if (isLater) {
    let dismissCount = parseInt(localStorage.getItem('narou_rating_dismiss_count') || '0', 10) + 1;
    localStorage.setItem('narou_rating_dismiss_count', dismissCount.toString());

    if (dismissCount >= 2) {
      // 2回「後で」が選ばれた場合は永久非表示
      localStorage.setItem('narou_play_store_prompt_shown', '1');
    } else {
      // 1回目の「後で」は14日間のクールダウン期間を設定
      const cooldownMs = 14 * 24 * 60 * 60 * 1000;
      localStorage.setItem('narou_rating_dismissed_until', (Date.now() + cooldownMs).toString());
    }
  } else {
    localStorage.setItem('narou_play_store_prompt_shown', '1');
  }
}

// =============================================================================
// 19. Google AdMob 広告連携 & リワード特典 (バックグラウンド再生 3時間解放)
// =============================================================================
function isBackgroundPlaybackAllowed() {
  if (!isAndroidApp) return true;
  if (typeof isBackgroundPassActive === 'function') {
    return isBackgroundPassActive();
  }
  try {
    const expiry = Number(localStorage.getItem('narou_bg_playback_expiry') || 0);
    return Date.now() < expiry;
  } catch (e) {
    return false;
  }
}

function getBgPlaybackRemainingMinutes() {
  try {
    const expiry = Number(localStorage.getItem('narou_bg_playback_expiry') || 0);
    const diffMs = expiry - Date.now();
    return diffMs > 0 ? Math.ceil(diffMs / 60000) : 0;
  } catch (e) {
    return 0;
  }
}

function formatRemainingTime(mins) {
  if (mins <= 0) return '0分';
  const hours = Math.floor(mins / 60);
  const remainingMins = mins % 60;
  if (hours > 0) {
    return remainingMins > 0 ? `${hours}時間${remainingMins}分` : `${hours}時間`;
  }
  return `${mins}分`;
}

function applyBackgroundPlaybackReward() {
  // §26 unlockBackgroundPass への薄い互換エイリアス
  if (typeof unlockBackgroundPass === 'function') {
    unlockBackgroundPass(0.25, 15);
  }
}

function updateBgPlaybackUI() {
  if (typeof updateBackgroundPassUI === 'function') {
    updateBackgroundPassUI();
  }
}

function handleAppBackground() {
  try {
    if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.isFullscreenAdShowing === 'function') {
      if (window.AndroidBridge.isFullscreenAdShowing()) {
        console.log('[NarouAIReader] Skipping BG restriction (fullscreen ad showing)');
        return;
      }
    }
  } catch (e) {}
  const isPlaying = state.isPlaying || (typeof tts !== 'undefined' && tts.isSpeaking);
  if (isPlaying && !isBackgroundPlaybackAllowed()) {
    console.log('[NarouAIReader] Background playback restricted by policy. Pausing audio.');
    pauseAudio();
    state.pausedDueToBackground = true;
    if (typeof showMiniToast === 'function') {
      showMiniToast('バックグラウンド再生はリワード広告で15分間解放できます');
    }
  }
}

function handleAppForeground() {
  updateBgPlaybackUI();
  if (state.pausedDueToBackground) {
    state.pausedDueToBackground = false;
    showBgPlaybackModalPrompt();
  }
  // 未完了の事前生成キューがあれば再開（再生中は内部で待機）
  scheduleAudioGenQueueResume(1200);
}

function showBgPlaybackModalPrompt() {
  const existing = document.getElementById('bgPlaybackPromptModal');
  if (existing) existing.remove();

  const modalHtml = `
    <div id="bgPlaybackPromptModal" class="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
      <div class="bg-slate-900 border border-slate-700/80 rounded-2xl max-w-sm w-full p-6 text-center space-y-4 shadow-2xl animate-fade-in">
        <div class="w-12 h-12 mx-auto rounded-2xl bg-amber-500/20 text-amber-400 flex items-center justify-center text-2xl border border-amber-500/30">
          <i class="ph-bold ph-headphones"></i>
        </div>
        <div class="space-y-1">
          <h3 class="text-base font-bold text-slate-100">バックグラウンド再生について</h3>
          <p class="text-xs text-slate-400 leading-relaxed">
            画面OFF時や他アプリ使用中のバックグラウンド朗読は、<strong>リワード広告を1回視聴すると【15分間】自由に解放</strong>されます！
          </p>
        </div>
        <div class="flex flex-col gap-2 pt-2">
          <button onclick="document.getElementById('bgPlaybackPromptModal').remove(); watchRewardAdForBackgroundPlayback();" class="w-full py-2.5 bg-gradient-to-r from-amber-500 to-yellow-500 hover:from-amber-400 hover:to-yellow-400 text-slate-950 font-bold rounded-xl text-xs flex items-center justify-center space-x-1.5 shadow-lg shadow-amber-500/20 transition active:scale-95">
            <i class="ph-bold ph-play-circle text-base"></i>
            <span>動画広告を見て15分間解放する</span>
          </button>
          <button onclick="document.getElementById('bgPlaybackPromptModal').remove();" class="w-full py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-xs transition">
            閉じる
          </button>
        </div>
      </div>
    </div>
  `;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
}

window.onAppBackground = handleAppBackground;
window.onAppForeground = handleAppForeground;

document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    handleAppBackground();
  } else {
    handleAppForeground();
  }
});

// 広告の表示を常時にし収益を最大化
// =============================================================================
// 20. デスクトップ版 キーボードショートカット & デュアルペイン
// =============================================================================
function initDesktopFeatures() {
  // 画面幅が広い場合はデスクトップデュアルペインを有効化
  if (window.innerWidth >= 1024) {
    document.body.classList.add('desktop-dual-pane');
  }

  window.addEventListener('resize', () => {
    if (window.innerWidth >= 1024) {
      document.body.classList.add('desktop-dual-pane');
    } else {
      document.body.classList.remove('desktop-dual-pane');
    }
  });

  // キーボードショートカット
  window.addEventListener('keydown', (e) => {
    // 入力欄にフォーカスがある場合は無効化
    if (['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName)) {
      return;
    }

    switch (e.code) {
      case 'Space':
        e.preventDefault();
        togglePlayPause();
        break;
      case 'KeyJ': // 次の文
        e.preventDefault();
        jumpSegment(1);
        break;
      case 'KeyK': // 前の文
        e.preventDefault();
        jumpSegment(-1);
        break;
      case 'KeyL': // 次の話
        e.preventDefault();
        navigateEpisode(1);
        break;
      case 'KeyH': // 前の話
        e.preventDefault();
        navigateEpisode(-1);
        break;
      case 'KeyM': // ミュート
        const audio = document.getElementById('audioPlayer');
        if (audio) audio.muted = !audio.muted;
        break;
      case 'KeyF': // フルスクリーン / 縦書き
        toggleVerticalMode();
        break;
      case 'Digit1':
        changeSpeed(1.0);
        break;
      case 'Digit2':
        changeSpeed(1.25);
        break;
      case 'Digit3':
        changeSpeed(1.5);
        break;
      case 'Digit4':
        changeSpeed(2.0);
        break;
    }
  });
}

function renderDesktopSidePane() {
  const container = document.getElementById('desktopQuickEpisodeList');
  if (!container || !state.currentNovel || !state.currentNovel.episodes) return;

  container.innerHTML = state.currentNovel.episodes.map(ep => `
    <button onclick="startReadingEpisode(${ep.episode_number || ep.number || 1})" class="w-full text-left p-2 rounded-lg transition text-xs flex items-center justify-between ${(ep.episode_number || ep.number || 1) === state.currentEpisodeNum ? 'bg-blue-600 text-white font-bold' : 'hover:bg-slate-800 text-slate-300'}">
      <span class="truncate pr-2">${ep.episode_number || ep.number || 1}. ${ep.title}</span>
      <i class="ph ph-play text-[10px] shrink-0"></i>
    </button>
  `).join('');
}

// =============================================================================
// 21. 高度なマルチタッチ・ジェスチャーシステム (Multi-Touch & Gesture Controls)
// =============================================================================
function initTouchGestures() {
  const readerArea = document.getElementById('tab-player');
  const segmentsContainer = document.getElementById('segmentsContainer');
  if (!readerArea) return;

  let touchStartX = 0;
  let touchStartY = 0;
  let touchStartTime = 0;
  let lastTapTime = 0;
  let lastTapX = 0;
  let lastTapY = 0;
  let initialPinchDistance = null;
  let initialFontSize = 16;
  let pinchIndicatorTimer = null;
  let longPressTimer = null;

  // ピンチイン/アウトによるフォントサイズ調整インジケーター
  function showFontSizeIndicator(sizePx) {
    let indicator = document.getElementById('gestureFontSizeIndicator');
    if (!indicator) {
      indicator = document.createElement('div');
      indicator.id = 'gestureFontSizeIndicator';
      indicator.className = 'fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 px-4 py-2 bg-slate-900/95 border border-blue-500/50 text-blue-300 font-bold rounded-2xl shadow-2xl text-xs pointer-events-none transition-opacity duration-200 backdrop-blur-md flex items-center space-x-2';
      document.body.appendChild(indicator);
    }
    indicator.innerHTML = `<i class="ph-bold ph-text-aa text-lg"></i><span>文字サイズ: ${sizePx}px</span>`;
    indicator.style.opacity = '1';

    clearTimeout(pinchIndicatorTimer);
    pinchIndicatorTimer = setTimeout(() => {
      if (indicator) indicator.style.opacity = '0';
    }, 1200);
  }

  // スキップ演出リップル
  function showSkipRipple(isForward, count = 3) {
    const ripple = document.createElement('div');
    ripple.className = `fixed top-1/2 ${isForward ? 'right-6' : 'left-6'} -translate-y-1/2 z-50 px-4 py-3 bg-blue-600/90 text-white font-bold rounded-2xl shadow-2xl text-xs flex items-center space-x-1.5 animate-scaleUp pointer-events-none backdrop-blur-md`;
    ripple.innerHTML = isForward ? `<span>+${count}文</span><i class="ph-bold ph-fast-forward text-base"></i>` : `<i class="ph-bold ph-rewind text-base"></i><span>-${count}文</span>`;
    document.body.appendChild(ripple);
    setTimeout(() => ripple.remove(), 600);
  }

  readerArea.addEventListener('touchstart', (e) => {
    const touches = e.touches;

    // 1. 2本指タップ判定
    if (touches.length === 2) {
      // ピンチ開始距離の記録
      const dx = touches[0].clientX - touches[1].clientX;
      const dy = touches[0].clientY - touches[1].clientY;
      initialPinchDistance = Math.hypot(dx, dy);
      
      const currentStyle = segmentsContainer ? window.getComputedStyle(segmentsContainer).fontSize : '16px';
      initialFontSize = parseInt(currentStyle, 10) || 16;
      return;
    }

    if (touches.length === 1) {
      touchStartX = touches[0].screenX;
      touchStartY = touches[0].screenY;
      touchStartTime = Date.now();
      clearTimeout(longPressTimer);
    }
  }, { passive: true });

  readerArea.addEventListener('touchmove', (e) => {
    if (e.touches.length === 1) {
      const moveX = Math.abs(e.touches[0].screenX - touchStartX);
      const moveY = Math.abs(e.touches[0].screenY - touchStartY);
      if (moveX > 5 || moveY > 5) {
        clearTimeout(longPressTimer);
      }
    } else {
      clearTimeout(longPressTimer);
    }

    // 2本指ピンチ操作中
    if (e.touches.length === 2 && initialPinchDistance !== null && segmentsContainer) {
      const dx = e.touches[0].clientX - e.touches[1].clientX;
      const dy = e.touches[0].clientY - e.touches[1].clientY;
      const currentDistance = Math.hypot(dx, dy);
      const scale = currentDistance / initialPinchDistance;

      let newSize = Math.round(initialFontSize * scale);
      newSize = Math.max(12, Math.min(28, newSize)); // 12px〜28pxの範囲制限

      segmentsContainer.style.fontSize = `${newSize}px`;
      localStorage.setItem('narou_custom_font_size', `${newSize}px`);
      showFontSizeIndicator(newSize);
    }
  }, { passive: true });

  readerArea.addEventListener('touchend', (e) => {
    clearTimeout(longPressTimer);
    const now = Date.now();

    // 2本指タップ完了（ピンチ距離変化が小さかった場合 -> 再生/一時停止トグル）
    if (e.changedTouches.length === 2 && initialPinchDistance !== null) {
      initialPinchDistance = null;
      return;
    }

    if (e.changedTouches.length === 0) return;
    const endX = e.changedTouches[0].screenX;
    const endY = e.changedTouches[0].screenY;
    const diffX = endX - touchStartX;
    const diffY = endY - touchStartY;
    const duration = now - touchStartTime;

    // ① 水平スワイプ判定（話数送り）
    if (duration < 500 && Math.abs(diffX) > 75 && Math.abs(diffX) > Math.abs(diffY) * 1.6) {
      if (diffX < 0) {
        // 左スワイプ -> 次のエピソード
        triggerHaptic('double');
        showMiniToast('👉 次のエピソードへ移動します');
        navigateEpisode(1);
      } else {
        // 右スワイプ -> 前のエピソード
        triggerHaptic('double');
        showMiniToast('👈 前のエピソードへ移動します');
        navigateEpisode(-1);
      }
      return;
    }

    // ② 画面左右ダブルタップ判定（+3文スキップ / -3文巻き戻し）
    const isDoubleTap = (now - lastTapTime < 300) && (Math.hypot(endX - lastTapX, endY - lastTapY) < 40);
    if (isDoubleTap && Math.abs(diffX) < 15 && Math.abs(diffY) < 15) {
      const screenWidth = window.innerWidth;
      const tapX = e.changedTouches[0].clientX;

      if (tapX > screenWidth * 0.6) {
        // 画面右側ダブルタップ: +3文スキップ
        triggerHaptic('double');
        showSkipRipple(true, 3);
        jumpSegment(3);
      } else if (tapX < screenWidth * 0.4) {
        // 画面左側ダブルタップ: -3文巻き戻し
        triggerHaptic('double');
        showSkipRipple(false, 3);
        jumpSegment(-3);
      } else {
        // 画面中央ダブルタップ: 再生/一時停止
        triggerHaptic('click');
        togglePlayPause();
      }
      lastTapTime = 0;
      return;
    }

    lastTapTime = now;
    lastTapX = endX;
    lastTapY = endY;
  }, { passive: true });
}

// =============================================================================
// 22. Android 通知バー & Bluetooth操作受信コールバック (window.onAndroidMediaAction)
// =============================================================================
let pausedByTransientFocusLoss = false;

window.onAndroidMediaAction = function(action) {
  console.log('[NarouAIReader] Media action from Android notification/BT:', action);
  switch (action) {
    case 'PLAY':
      pausedByTransientFocusLoss = false;
      if (!state.isPlaying) togglePlayPause();
      break;
    case 'PAUSE':
      if (state.isPlaying) {
        pausedByTransientFocusLoss = true;
        togglePlayPause();
      }
      break;
    case 'NEXT': {
      // Bluetooth / 車載コントローラーの専用「次へ」ボタン
      const btMode = (state.settings && state.settings.bluetooth_skip_behavior) || localStorage.getItem('narou_bt_skip_behavior') || 'episode';
      if (btMode === 'episode') {
        triggerHaptic('double');
        showMiniToast('⏩ 次のエピソードへ移動します');
        navigateEpisode(1);
      } else if (btMode === 'skip3') {
        triggerHaptic('double');
        showMiniToast('⏭️ +3文スキップ');
        jumpSegment(3);
      } else {
        triggerHaptic('tick');
        jumpSegment(1);
      }
      break;
    }
    case 'PREV': {
      // Bluetooth / 車載コントローラーの専用「前へ」ボタン
      const btMode = (state.settings && state.settings.bluetooth_skip_behavior) || localStorage.getItem('narou_bt_skip_behavior') || 'episode';
      if (btMode === 'episode') {
        triggerHaptic('double');
        showMiniToast('⏪ 前のエピソードへ移動します');
        navigateEpisode(-1);
      } else if (btMode === 'skip3') {
        triggerHaptic('double');
        showMiniToast('⏮️ -3文スキップ');
        jumpSegment(-3);
      } else {
        triggerHaptic('tick');
        jumpSegment(-1);
      }
      break;
    }
    case 'NEXT_EPISODE':
      // 次のエピソードへスキップ
      triggerHaptic('double');
      showMiniToast('⏩ 次のエピソードへ移動します');
      navigateEpisode(1);
      break;
    case 'PREV_EPISODE':
      // 前のエピソードへスキップ
      triggerHaptic('double');
      showMiniToast('⏪ 前のエピソードへ移動します');
      navigateEpisode(-1);
      break;
    case 'FAST_FORWARD_3':
      triggerHaptic('double');
      jumpSegment(3);
      break;
    case 'REWIND_3':
      triggerHaptic('double');
      jumpSegment(-3);
      break;
    case 'STOP':
      pausedByTransientFocusLoss = false;
      state.isPlaying = false;
      if (typeof pauseAudio === 'function') {
        try { pauseAudio(); } catch (e) {}
      }
      try {
        if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.stopTts === 'function') {
          window.AndroidBridge.stopTts();
        }
      } catch (e) {}
      break;
    case 'DUCK':
      const audioDuck = document.getElementById('audioPlayer');
      if (audioDuck) audioDuck.volume = 0.2;
      break;
    case 'RESUME':
      const audioRes = document.getElementById('audioPlayer');
      if (audioRes) audioRes.volume = 1.0;
      if (pausedByTransientFocusLoss && !state.isPlaying) {
        pausedByTransientFocusLoss = false;
        togglePlayPause();
      }
      break;
  }
};
// =============================================================================
// 22-A. 🚗 カーモード（ドライブモード）制御
// =============================================================================
function enterCarMode() {
  state.isCarMode = true;
  triggerHaptic('heavy');

  // カーモードオーバーレイ表示
  const overlay = document.getElementById('carModeOverlay');
  if (overlay) overlay.classList.remove('hidden');

  // 通常UIを隠す
  const header = document.querySelector('header');
  const bottomNav = document.getElementById('bottomNavBar');
  const miniPlayer = document.getElementById('miniPlayerBar');
  const floatingPlayer = document.getElementById('floatingPlayerBar');
  if (header) header.classList.add('hidden');
  if (bottomNav) bottomNav.classList.add('hidden');
  if (miniPlayer) miniPlayer.classList.add('hidden');
  if (floatingPlayer) floatingPlayer.classList.add('hidden');

  // BT skip を自動で episode モードに切替（元の値を保存）
  state._prevBtSkipBehavior = localStorage.getItem('narou_bt_skip_behavior') || 'episode';
  localStorage.setItem('narou_bt_skip_behavior', 'episode');

  updateCarModeUI();
  showMiniToast('🚗 カーモードを起動しました');
  console.log('[NarouAIReader] Car Mode: ACTIVATED');

  // カーモード状態を保存
  try { localStorage.setItem('narou_car_mode_active', 'true'); } catch(e) {}
}

function exitCarMode() {
  state.isCarMode = false;
  triggerHaptic('click');

  // カーモードオーバーレイ非表示
  const overlay = document.getElementById('carModeOverlay');
  if (overlay) overlay.classList.add('hidden');

  // 通常UIを復帰
  const header = document.querySelector('header');
  const bottomNav = document.getElementById('bottomNavBar');
  if (header) header.classList.remove('hidden');
  if (bottomNav) bottomNav.classList.remove('hidden');

  // BT skip を元の設定に復元
  if (state._prevBtSkipBehavior) {
    localStorage.setItem('narou_bt_skip_behavior', state._prevBtSkipBehavior);
    delete state._prevBtSkipBehavior;
  }

  showMiniToast('カーモードを終了しました');
  console.log('[NarouAIReader] Car Mode: DEACTIVATED');

  // カーモード状態をクリア
  try { localStorage.removeItem('narou_car_mode_active'); } catch(e) {}

  // 現在のタブに合わせてUI復帰
  switchTab(state.currentTab || 'player');
}

function updateCarModeUI() {
  if (!state.isCarMode) return;

  const titleEl = document.getElementById('carModeTitle');
  const episodeEl = document.getElementById('carModeEpisode');
  const textEl = document.getElementById('carModeCurrentText');
  const speakerEl = document.getElementById('carModeSpeaker');
  const progressEl = document.getElementById('carModeProgress');
  const seekSlider = document.getElementById('carModeSeekSlider');
  const seekPercentEl = document.getElementById('carModeSeekPercent');
  const seekHintEl = document.getElementById('carModeSeekHint');
  const playIcon = document.getElementById('carModePlayIcon');
  const playable = canPlayAudio();
  const totalSegs = state.currentSegments?.length || 0;
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const locWork = (state.currentNovel && typeof getLocalizedAozoraWork === 'function')
    ? getLocalizedAozoraWork({ ncode: state.currentNovel.ncode, title: state.currentNovel.title, author: state.currentNovel.author || '' }, uiLang)
    : null;

  if (titleEl) titleEl.textContent = (locWork && locWork.displayTitle) || state.currentNovel?.title || tUi('carmode_no_title');
  if (episodeEl) episodeEl.textContent = uiLang === 'ja' ? `第${state.currentEpisodeNum}話` : `Ep. ${state.currentEpisodeNum}`;

  const currentSeg = (state.currentSegments && state.currentSegments.length > 0)
    ? state.currentSegments[state.currentSegmentIndex]
    : null;
  if (currentSeg) {
    const activeTransLang = state.currentTranslatedLang || '';
    const hasTranslation = !!(activeTransLang && currentSeg.translated_text && currentSeg.translated_lang === activeTransLang);
    if (textEl) textEl.textContent = (hasTranslation ? currentSeg.translated_text : currentSeg.display_text) || '...';
    if (speakerEl) {
      const rawSpeaker = currentSeg.speaker || 'ナレーション';
      if (uiLang === 'ja') {
        speakerEl.textContent = rawSpeaker;
      } else {
        speakerEl.textContent = (hasTranslation && currentSeg.translated_speaker)
          ? currentSeg.translated_speaker
          : (typeof translateSpeakerOnDevice === 'function' ? translateSpeakerOnDevice(rawSpeaker, uiLang) : (rawSpeaker === 'ナレーション' ? tUi('cast_narration_label') : rawSpeaker));
      }
    }
  } else {
    if (textEl) textEl.textContent = tUi('carmode_ready');
    if (speakerEl) speakerEl.textContent = tUi('cast_narration_label');
  }

  if (progressEl) {
    progressEl.textContent = totalSegs > 0
      ? `${state.currentSegmentIndex + 1} / ${totalSegs}`
      : '0 / 0';
  }

  const pct = totalSegs > 0
    ? Math.round(((state.currentSegmentIndex + 1) / totalSegs) * 100)
    : 0;
  if (!isCarModeSeeking) {
    if (seekSlider) {
      seekSlider.value = String(pct);
      seekSlider.disabled = !playable || totalSegs === 0;
    }
    if (seekPercentEl) seekPercentEl.textContent = `${pct}%`;
    if (seekHintEl) seekHintEl.textContent = uiLang === 'ja' ? 'ドラッグで文位置を移動' : '';
  }

  if (playIcon) {
    playIcon.className = state.isPlaying
      ? 'ph-fill ph-pause text-6xl'
      : 'ph-fill ph-play text-6xl ml-1';
  }
}

// Bluetooth A2DP 接続/切断コールバック（Android native から呼び出される）
window.onBluetoothA2dpConnected = function() {
  console.log('[NarouAIReader] Bluetooth A2DP connected');
  const autoStart = localStorage.getItem('narou_car_mode_auto_start') === 'true';
  if (autoStart && !state.isCarMode) {
    showMiniToast('🚗 Bluetooth接続を検知 — カーモード自動起動');
    setTimeout(() => enterCarMode(), 500);
  }
};

window.onBluetoothA2dpDisconnected = function() {
  console.log('[NarouAIReader] Bluetooth A2DP disconnected');
  if (state.isCarMode) {
    showMiniToast('Bluetooth切断 — カーモードを終了します');
    setTimeout(() => exitCarMode(), 300);
  }
};

// =============================================================================
// 23. 初期化ライフサイクルフック
// =============================================================================
document.addEventListener('DOMContentLoaded', () => {
  // 保存されたテーマとフォントの復元
  const savedTheme = localStorage.getItem('narou_reader_theme') || 'paper';
  setReaderTheme(savedTheme);

  const savedFont = localStorage.getItem('narou_reader_font_class') || 'font-shippori';
  setReaderFont(savedFont);

  const savedVertical = localStorage.getItem('narou_reader_vertical') === '1';
  if (savedVertical) {
    const container = document.getElementById('segmentsContainer');
    if (container) container.classList.add('vertical-reader');
  }

  applyReaderTypography();

  // 初期化モジュール呼び出し
  initFTUEAndHero();
  initDesktopFeatures();
  initTouchGestures();
  NarouIDB.init();
  updateBgPlaybackUI();
  checkPolicyConsentOnStartup();
  renderRecentSearches();
  // 探すタブ: 前回の検索条件と結果を復元
  restoreLastSearchState();
  selectSearchSite(state.selectedSearchSite || 'aozora');

  // カーモード: Bluetooth A2DP 接続チェック（自動起動）
  if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.isBluetoothA2dpConnected === 'function') {
    try {
      const btConnected = window.AndroidBridge.isBluetoothA2dpConnected();
      const autoStart = localStorage.getItem('narou_car_mode_auto_start') === 'true';
      if (btConnected && autoStart) {
        setTimeout(() => enterCarMode(), 1000);
      }
    } catch(e) { console.warn('[NarouAIReader] BT A2DP check failed:', e); }
  }
});

