let legalPolicyLoaded = false;
let legalPolicyData = null;

async function openAppPolicyModal() {
  const modal = document.getElementById('appPolicyModal');
  if (!modal) return;
  modal.classList.remove('hidden');
  if (!legalPolicyLoaded) {
    await loadLegalPolicyContent();
  }
}

function closeAppPolicyModal() {
  const modal = document.getElementById('appPolicyModal');
  if (modal) modal.classList.add('hidden');
}

function switchPolicyTab(tabName) {
  const tabs = ['disclaimer', 'terms', 'privacy', 'copyright', 'aozora', 'platforms', 'takedown'];
  tabs.forEach(t => {
    const btn = document.getElementById(`polTabBtn-${t}`);
    const content = document.getElementById(`polTabContent-${t}`);
    if (t === tabName) {
      if (btn) {
        btn.classList.remove('text-slate-400', 'hover:text-slate-200', 'hover:bg-slate-800', 'text-rose-400');
        if (t === 'takedown') {
          btn.classList.add('bg-rose-600', 'text-white', 'shadow');
        } else {
          btn.classList.add('bg-blue-600', 'text-white', 'shadow');
        }
      }
      if (content) content.classList.remove('hidden');
    } else {
      if (btn) {
        btn.classList.remove('bg-blue-600', 'bg-rose-600', 'text-white', 'shadow');
        if (t === 'takedown') {
          btn.classList.add('text-rose-400', 'hover:text-rose-200', 'hover:bg-rose-950/30');
        } else {
          btn.classList.add('text-slate-400', 'hover:text-slate-200', 'hover:bg-slate-800');
        }
      }
      if (content) content.classList.add('hidden');
    }
  });
}

