async function loadLegalPolicyContent() {
  try {
    let disclaimerRes = {}, termsRes = {}, privacyRes = {}, copyrightRes = {}, platformsRes = null;
    if (!isAndroidApp) {
      [disclaimerRes, termsRes, privacyRes, copyrightRes, platformsRes] = await Promise.all([
        fetch('/api/legal/disclaimer').then(r => r.ok ? r.json() : {}).catch(() => ({})),
        fetch('/api/legal/terms').then(r => r.ok ? r.json() : {}).catch(() => ({})),
        fetch('/api/legal/privacy').then(r => r.ok ? r.json() : {}).catch(() => ({})),
        fetch('/api/legal/copyright').then(r => r.ok ? r.json() : {}).catch(() => ({})),
        fetch('/api/legal/platforms').then(r => r.ok ? r.json() : null).catch(() => null)
      ]);
    }

    const discEl = document.getElementById('policyDisclaimerText');
    if (discEl) {
      discEl.textContent = disclaimerRes.disclaimer || OFFLINE_LEGAL_FALLBACKS.disclaimer;
    }

    const termsEl = document.getElementById('policyTermsText');
    if (termsEl) {
      termsEl.textContent = termsRes.terms_of_service || OFFLINE_LEGAL_FALLBACKS.terms_of_service;
    }

    const privacyEl = document.getElementById('policyPrivacyText');
    if (privacyEl && privacyRes.privacy_policy) {
      privacyEl.textContent = privacyRes.privacy_policy;
    }

    const copyEl = document.getElementById('policyCopyrightText');
    if (copyEl) {
      copyEl.textContent = copyrightRes.copyright_notice || OFFLINE_LEGAL_FALLBACKS.copyright_notice;
    }

    const platData = (platformsRes && Object.keys(platformsRes).length > 0)
      ? platformsRes
      : OFFLINE_LEGAL_FALLBACKS.platforms;
    const platContainer = document.getElementById('policyPlatformsContainer');
    if (platContainer && platData) {
      platContainer.innerHTML = Object.entries(platData).map(([key, p]) => `
        <div class="p-3 bg-slate-950/70 border border-slate-800 rounded-xl space-y-2">
          <div class="flex items-center justify-between">
            <span class="font-bold text-white text-xs">${escapeHtml(p.name)}</span>
            <span class="text-[10px] px-2 py-0.5 rounded ${p.api_available ? 'bg-emerald-950 text-emerald-300 border border-emerald-800' : 'bg-slate-800 text-slate-400'}">
              ${p.api_available ? '公式ライセンス準拠' : 'ローカル文書'}
            </span>
          </div>
          <ul class="list-disc list-inside text-[11px] text-slate-400 space-y-1">
            ${(p.terms_highlights || []).map(h => `<li>${escapeHtml(h)}</li>`).join('')}
          </ul>
        </div>
      `).join('');
    }

    legalPolicyLoaded = true;
  } catch (err) {
    console.error('Failed to load legal policy contents:', err);
  }
}

async function submitTakedownRequest(event) {
  event.preventDefault();
  const btn = document.getElementById('tdSubmitBtn');
  const msgBox = document.getElementById('takedownResultMsg');
  if (!btn) return;

  const payload = {
    reporter_name: document.getElementById('tdReporterName')?.value || '',
    reporter_email: document.getElementById('tdReporterEmail')?.value || '',
    is_rights_holder: document.getElementById('tdIsHolder')?.checked || false,
    work_title: document.getElementById('tdWorkTitle')?.value || '',
    author_name: document.getElementById('tdAuthorName')?.value || '',
    content_identifier: document.getElementById('tdContentId')?.value || '',
    reason_detail: document.getElementById('tdReasonDetail')?.value || ''
  };

  btn.disabled = true;
  btn.innerHTML = '<i class="ph ph-spinner animate-spin"></i><span>送信中...</span>';

  try {
    const res = await fetch('/api/legal/takedown/request', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    if (res.ok && data.success) {
      if (msgBox) {
        msgBox.className = 'p-3 rounded-xl text-xs bg-emerald-950/60 border border-emerald-500/50 text-emerald-200';
        msgBox.innerHTML = `<strong>✔ 送信完了 (${escapeHtml(data.ticket_id)})</strong><br>${escapeHtml(data.message)}<br>受付完了メールをご連絡先へ送信いたしました。`;
        msgBox.classList.remove('hidden');
      }
      document.getElementById('takedownForm')?.reset();
    } else {
      throw new Error(data.error || '送信に失敗しました');
    }
  } catch (err) {
    if (msgBox) {
      msgBox.className = 'p-3 rounded-xl text-xs bg-rose-950/60 border border-rose-500/50 text-rose-200';
      msgBox.textContent = `送信エラー: ${err.message}`;
      msgBox.classList.remove('hidden');
    }
  } finally {
    btn.disabled = false;
    btn.innerHTML = '<i class="ph-bold ph-paper-plane-tilt"></i><span>除外要請を送信</span>';
  }
}

// =============================================================================
// 23. 作品AI再解析 & 配役最適化 モーダル制御 (Home / Search / TOC からの直通)
// =============================================================================
let activeReanalyzeTarget = {
  ncode: null,
  novelTitle: null,
  episodeNum: 1
};

function openNovelAiReanalyzeModal(ncode = null, novelTitle = null, episodeNum = null) {
  triggerHaptic('click');
  const lastState = JSON.parse(localStorage.getItem('narou_last_read') || 'null');
  const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';

  const targetNcode = ncode || state.currentNovel?.ncode || lastState?.ncode || null;
  const rawTitle = novelTitle || state.currentNovel?.title || lastState?.novelTitle || (targetNcode ? `(${targetNcode})` : tUi('carmode_no_title'));
  const locWork = (targetNcode && typeof getLocalizedAozoraWork === 'function')
    ? getLocalizedAozoraWork({ id: targetNcode, ncode: targetNcode, title: rawTitle }, uiLang)
    : null;
  const targetTitle = (locWork && locWork.displayTitle) || rawTitle;
  const targetEpNum = episodeNum || state.currentEpisodeNum || lastState?.episodeNum || 1;

  if (!targetNcode) {
    showToast(tUi('carmode_no_title'), 'info');
    return;
  }

  activeReanalyzeTarget = {
    ncode: targetNcode,
    novelTitle: targetTitle,
    episodeNum: targetEpNum
  };

  const titleEl = document.getElementById('reanalyzeModalNovelTitle');
  if (titleEl) titleEl.textContent = targetTitle;

  const epBtnText = document.getElementById('reanalyzeEpisodeBtnText');
  if (epBtnText) epBtnText.textContent = uiLang === 'ja' ? `第${targetEpNum}話のみ再解析` : `Re-analyze Ep. ${targetEpNum} Only`;

  // 保存済みの配役情報をチェックして現在の登録状況を表示
  const savedCast = (() => {
    try {
      const s = localStorage.getItem(`narou_novel_cast_${targetNcode.toLowerCase()}`);
      return s ? JSON.parse(s) : null;
    } catch (e) { return null; }
  })();

  const statusEl = document.getElementById('reanalyzeModalStatusText');
  const scanBadgeEl = document.getElementById('reanalyzeModalScanBadge');
  if (savedCast && Array.isArray(savedCast.characters) && savedCast.characters.length > 0) {
    if (statusEl) {
      statusEl.textContent = uiLang === 'ja'
        ? `キャラクター ${savedCast.characters.length}名 登録済`
        : `${savedCast.characters.length} characters registered`;
    }
    if (scanBadgeEl) {
      scanBadgeEl.textContent = uiLang === 'ja'
        ? (savedCast.scanned_episodes ? `${savedCast.scanned_episodes}話スキャン済` : '配役保存済')
        : (savedCast.scanned_episodes ? `Scanned ${savedCast.scanned_episodes} ep.` : 'Cast saved');
      scanBadgeEl.className = 'text-[10px] px-2 py-0.5 rounded-full bg-emerald-950 border border-emerald-500/40 text-emerald-300 font-mono shrink-0';
    }
  } else {
    if (statusEl) {
      statusEl.textContent = uiLang === 'ja'
        ? 'キャラクター未登録（「AI再スキャン」で自動判定）'
        : 'No characters registered yet (Run AI Re-scan)';
    }
    if (scanBadgeEl) {
      scanBadgeEl.textContent = uiLang === 'ja' ? '未スキャン' : 'Not scanned';
      scanBadgeEl.className = 'text-[10px] px-2 py-0.5 rounded-full bg-blue-950 border border-blue-500/40 text-blue-300 font-mono shrink-0';
    }
  }

  // 現在のLLM設定を選択肢に反映
  const currentSettings = (typeof getSettingsFromStorage === 'function' ? getSettingsFromStorage() : null) || {};
  const currentProvider = getActiveCastLlmProvider(currentSettings);
  const selectEl = document.getElementById('reanalyzeModalLlmSelect');
  if (selectEl) {
    selectEl.value = currentProvider;
  }

  const modal = document.getElementById('novelAiReanalyzeModal');
  if (modal) {
    modal.classList.remove('hidden');
  }
}

function closeNovelAiReanalyzeModal() {
  triggerHaptic('tick');
  const modal = document.getElementById('novelAiReanalyzeModal');
  if (modal) modal.classList.add('hidden');
}

async function openCastEditorForTarget() {
  triggerHaptic('click');
  const { ncode, novelTitle } = activeReanalyzeTarget;
  closeNovelAiReanalyzeModal();

  if (!ncode) {
    showToast('作品が指定されていません', 'info');
    return;
  }

  // 小説データが未ロードなら取得
  if (!state.currentNovel || state.currentNovel.ncode?.toLowerCase() !== ncode.toLowerCase()) {
    showMiniToast(`『${novelTitle || ncode}』の配役データを準備中...`);
    try {
      await loadNovelByQuery(ncode);
    } catch (e) {
      console.warn('loadNovelByQuery fallback in openCastEditorForTarget:', e);
    }
  }

  // 保存済みの配役データがあれば確実にstateへ反映
  const savedCast = (() => {
    try {
      const s = localStorage.getItem(`narou_novel_cast_${ncode.toLowerCase()}`);
      return s ? JSON.parse(s) : null;
    } catch (e) { return null; }
  })();

  if (savedCast) {
    if (Array.isArray(savedCast.characters) && savedCast.characters.length > 0) {
      state.currentCharacters = savedCast.characters;
    }
    if (savedCast.cast) {
      state.currentCast = { ...(state.currentCast || {}), ...savedCast.cast };
    }
    if (savedCast.cast_profiles) {
      state.currentCastProfiles = { ...(state.currentCastProfiles || {}), ...savedCast.cast_profiles };
    }
  }

  switchTab('cast');
  renderCastEditor();
  showToast(`『${novelTitle || ncode}』の配役・音声エディタを開きました`, 'info');
}

function onReanalyzeModalLlmChange() {
  triggerHaptic('click');
  const selectEl = document.getElementById('reanalyzeModalLlmSelect');
  if (!selectEl) return;
  const newProvider = selectEl.value;

  const settings = (typeof getSettingsFromStorage === 'function' ? getSettingsFromStorage() : null) || {};
  settings.llm_provider = newProvider;
  localStorage.setItem('narou_app_settings', JSON.stringify(settings));

  // 設定タブのセレクトボックスとも同期
  const mainSettingSelect = document.getElementById('settingLlmProvider');
  if (mainSettingSelect) {
    mainSettingSelect.value = newProvider;
    if (typeof toggleLlmFields === 'function') toggleLlmFields();
  }

  const providerNames = {
    'embedded_llm': 'アプリ内包ロジック',
    'gemini': 'Google Gemini API',
    'openai': 'OpenAI API',
    'claude': 'Anthropic Claude API',
    'local_llm': '外部ローカルサーバー',
    'rules': 'ルールベース'
  };
  showMiniToast(`✔ AIエンジンを「${providerNames[newProvider] || newProvider}」に変更しました`);
  if (typeof updatePlayerAiStatusBadge === 'function') {
    updatePlayerAiStatusBadge();
  }
}

async function triggerReanalyzeFromModal(type) {
  triggerHaptic('double');
  const { ncode, novelTitle, episodeNum } = activeReanalyzeTarget;
  closeNovelAiReanalyzeModal();

  if (!ncode) {
    showToast('作品が指定されていません', 'error');
    return;
  }

  // 小説データが未ロードならまず取得
  if (!state.currentNovel || state.currentNovel.ncode?.toLowerCase() !== ncode.toLowerCase()) {
    showMiniToast(`『${novelTitle || ncode}』の目次を読み込み中...`);
    await loadNovelByQuery(ncode);
  }

  if (type === 'episode') {
    showToast(`第${episodeNum}話を最新AIで再解析中...`, 'info');
    await startReadingEpisode(episodeNum, null, true);
    switchTab('player');
  } else if (type === 'full_cast') {
    showToast(`『${novelTitle || ncode}』の複数話AIスキャンを開始します...`, 'info');
    await loadNovelFullCast(ncode, true, true);
  }
}

