      btnBuyPremium.className = 'w-full py-2.5 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold rounded-xl text-xs shadow-md shadow-blue-600/30 flex items-center justify-center space-x-1.5 transition active:scale-[0.98]';
