// --- 3. 読書ストリーク & 読書統計 (リテンション・DAU向上ゲーミフィケーション) ---
function getReadingStreakData() {
  try {
    const raw = localStorage.getItem(RETENTION_STORAGE_KEY_STREAK);
    if (raw) {
      return JSON.parse(raw);
    }
  } catch (e) {}
  return {
    streakDays: 1,
    lastReadDate: '',
    longestStreak: 1,
    todayReadSec: 0,
    totalReadSec: 0,
    totalEpisodesRead: 0,
    totalCharactersRead: 0
  };
}

function saveReadingStreakData(data) {
  try {
    localStorage.setItem(RETENTION_STORAGE_KEY_STREAK, JSON.stringify(data));
    updateStreakAndStatsUI();
  } catch (e) {}
}

function getTodayDateString() {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function checkAndUpdateDailyStreak() {
  const data = getReadingStreakData();
  const today = getTodayDateString();

  if (!data.lastReadDate) {
    data.lastReadDate = today;
    data.streakDays = 1;
    data.longestStreak = 1;
    data.todayReadSec = 0;
    saveReadingStreakData(data);
    return;
  }

  if (data.lastReadDate === today) {
    // 本日すでに読書済み
    return;
  }

  const lastDate = new Date(data.lastReadDate);
  const curDate = new Date(today);
  const diffDays = Math.round((curDate - lastDate) / (1000 * 60 * 60 * 24));

  if (diffDays === 1) {
    // 連続日
    data.streakDays += 1;
    if (data.streakDays > (data.longestStreak || 1)) {
      data.longestStreak = data.streakDays;
    }
    data.todayReadSec = 0;
    data.lastReadDate = today;

    // ストリーク達成ボーナス付与 (例: 3日、7日、30日)
    if (data.streakDays === 3 || data.streakDays === 7 || data.streakDays === 14 || data.streakDays === 30) {
      unlockBackgroundPass(1); // ボーナス+1時間
      showToast(`🔥 ${data.streakDays}日連続読書達成！ボーナスでバックグラウンド再生+1時間を獲得！`, 'success');
    }
  } else if (diffDays > 1) {
    // ストリーク途切れ
    data.streakDays = 1;
    data.todayReadSec = 0;
    data.lastReadDate = today;
  }

  saveReadingStreakData(data);
}

function recordReadingProgress(charCount = 0, durationSec = 1) {
  const data = getReadingStreakData();
  const today = getTodayDateString();

  if (data.lastReadDate !== today) {
    checkAndUpdateDailyStreak();
  }

  data.todayReadSec = (data.todayReadSec || 0) + durationSec;
  data.totalReadSec = (data.totalReadSec || 0) + durationSec;
  data.totalCharactersRead = (data.totalCharactersRead || 0) + charCount;

  saveReadingStreakData(data);
}

function updateStreakAndStatsUI() {
  const data = getReadingStreakData();

  const streakValEl = document.getElementById('streakDaysVal');
  if (streakValEl) {
    streakValEl.textContent = String(data.streakDays || 1);
  }

  const statListenEl = document.getElementById('statTotalListenTime');
  if (statListenEl) {
    const totalMinutes = Math.floor((data.totalReadSec || 0) / 60);
    if (totalMinutes >= 60) {
      const hours = (totalMinutes / 60).toFixed(1);
      statListenEl.innerHTML = `<span id="listenTimeVal">${hours}</span> 時間`;
    } else {
      statListenEl.innerHTML = `<span id="listenTimeVal">${totalMinutes}</span> 分`;
    }
  }

  const epValEl = document.getElementById('completedEpisodesVal');
  if (epValEl) {
    epValEl.textContent = String(data.totalEpisodesRead || 0);
  }
}

// --- 4. 初期化 & バックグラウンド監視ループ ---
let bgPassCheckInterval = null;
let readingProgressTimer = null;

function initMonetizationAndGamification() {
  checkAndUpdateDailyStreak();
  updateStreakAndStatsUI();
  updateBackgroundPassUI();
  updateAdMobBannerVisibility(false);

  // 定期的なパス残時間のUI更新 (1分ごと)
  if (bgPassCheckInterval) clearInterval(bgPassCheckInterval);
  bgPassCheckInterval = setInterval(() => {
    updateBackgroundPassUI();
  }, 60000);

  // 朗読中の読書時間加算タイマー (5秒ごと)
  if (readingProgressTimer) clearInterval(readingProgressTimer);
  readingProgressTimer = setInterval(() => {
    if (state.isPlaying) {
      const currentSeg = state.currentSegments[state.currentSegmentIndex];
      const charCount = currentSeg ? (currentSeg.display_text?.length || 0) : 0;
      recordReadingProgress(Math.round(charCount / 6), 5);
    }
  }, 5000);

  // Androidアプリ起動時のリワード・インタースティシャル広告事前読み込み
  if (isAndroidApp && window.AndroidBridge) {
    try {
      if (typeof window.AndroidBridge.preloadRewardedAd === 'function') {
        window.AndroidBridge.preloadRewardedAd();
      }
      if (typeof window.AndroidBridge.preloadInterstitialAd === 'function') {
        window.AndroidBridge.preloadInterstitialAd();
      }
    } catch (e) {}
  }
}

