function openOnlineManualModal(initialTab = 'basic') {
  const modal = document.getElementById('onlineManualModal');
  if (modal) {
    modal.classList.remove('hidden');
    switchManualTab(initialTab);
  }
}

function closeOnlineManualModal() {
  const modal = document.getElementById('onlineManualModal');
  if (modal) {
    modal.classList.add('hidden');
  }
}

function switchManualTab(tabKey) {
  const tabs = ['basic', 'ai', 'gestures', 'bluetooth', 'offline'];
  tabs.forEach(t => {
    const btn = document.getElementById(`manualTabBtn-${t}`);
    const pane = document.getElementById(`manualTabContent-${t}`);
    if (btn && pane) {
      if (t === tabKey) {
        btn.classList.add('font-bold', 'border-cyan-500', 'text-cyan-400');
        btn.classList.remove('font-medium', 'border-transparent', 'text-slate-400');
        pane.classList.remove('hidden');
      } else {
        btn.classList.remove('font-bold', 'border-cyan-500', 'text-cyan-400');
        btn.classList.add('font-medium', 'border-transparent', 'text-slate-400');
        pane.classList.add('hidden');
      }
    }
  });
}

