const UGC_REASON_LABELS = {
  r18_sexual: '性的・成人向け（R18）',
  violence_gore: '過度な暴力・グロテスク',
  hate_harassment: 'ヘイト・嫌がらせ',
  copyright: '著作権侵害の疑い',
  csam: '児童の性的搾取（CSAM）',
  other: 'その他'
};

function getBlockedNovelsMap() {
  try {
    return JSON.parse(localStorage.getItem(UGC_BLOCK_STORAGE_KEY) || '{}') || {};
  } catch (e) {
    return {};
  }
}

function saveBlockedNovelsMap(map) {
  try {
    localStorage.setItem(UGC_BLOCK_STORAGE_KEY, JSON.stringify(map || {}));
  } catch (e) {}
}

function getBlockedNovelIds() {
  return new Set(Object.keys(getBlockedNovelsMap()).map((k) => String(k).toLowerCase()));
}

function isNovelBlocked(ncode) {
  if (!ncode) return false;
  return getBlockedNovelIds().has(String(ncode).toLowerCase());
}

function blockNovelLocally(ncode, title = '', author = '', reason = '') {
  const id = String(ncode || '').toLowerCase().trim();
  if (!id) return false;
  const map = getBlockedNovelsMap();
  map[id] = {
    ncode: id,
    title: title || id,
    author: author || '',
    reason: reason || '',
    blockedAt: Date.now()
  };
  saveBlockedNovelsMap(map);

  if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.blockContent === 'function') {
    try {
      window.AndroidBridge.blockContent(id, 'novel', reason || '', title || id, author || '');
    } catch (e) {}
  }
  return true;
}

function unblockNovelLocally(ncode) {
  const id = String(ncode || '').toLowerCase().trim();
  if (!id) return false;
  const map = getBlockedNovelsMap();
  delete map[id];
  saveBlockedNovelsMap(map);
  if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.unblockContent === 'function') {
    try { window.AndroidBridge.unblockContent(id); } catch (e) {}
  }
  return true;
}

function renderBlockedNovelsList() {
  const el = document.getElementById('blockedNovelsList');
  if (!el) return;
  const map = getBlockedNovelsMap();
  const entries = Object.values(map).sort((a, b) => (b.blockedAt || 0) - (a.blockedAt || 0));
  if (!entries.length) {
    el.innerHTML = '<p class="text-slate-500">ブロック中の作品はありません</p>';
    return;
  }
  el.innerHTML = entries.map((item) => `
    <div class="flex items-center justify-between gap-2 p-2 rounded-lg bg-slate-950 border border-slate-800">
      <div class="min-w-0">
        <p class="text-slate-200 font-medium truncate">${escapeHtml(item.title || item.ncode)}</p>
        <p class="text-[10px] text-slate-500 font-mono truncate">${escapeHtml(String(item.ncode || '').toUpperCase())}</p>
      </div>
      <button type="button" onclick="unblockNovelLocally('${escapeHtml(item.ncode)}'); renderBlockedNovelsList(); showMiniToast && showMiniToast('ブロックを解除しました');" class="shrink-0 px-2 py-1 rounded-lg bg-slate-800 text-slate-300 text-[10px] border border-slate-700">解除</button>
    </div>
  `).join('');
}

function closeUgcReportModal() {
  const modal = document.getElementById('ugcReportModal');
  if (modal) modal.classList.add('hidden');
}

function openUgcReportModal(payload = {}) {
  const ncode = String(payload.ncode || '').trim();
  const title = payload.title || ncode || '（無題）';
  const author = payload.author || '';
  if (!ncode) {
    showToast('通報対象の作品が特定できません', 'error');
    return;
  }
  const modal = document.getElementById('ugcReportModal');
  if (!modal) return;
  document.getElementById('ugcReportNcode').value = ncode;
  document.getElementById('ugcReportAuthor').value = author;
  document.getElementById('ugcReportTitle').textContent = title;
  document.getElementById('ugcReportMeta').textContent = `ID: ${ncode.toUpperCase()}${author ? ` / 作者: ${author}` : ''}`;
  const comment = document.getElementById('ugcReportComment');
  if (comment) comment.value = '';
  const alsoBlock = document.getElementById('ugcAlsoBlock');
  if (alsoBlock) alsoBlock.checked = true;
  modal.classList.remove('hidden');
  vibrateFeedback(10);
}

function openUgcReportModalFromCurrentNovel() {
  const novel = state.currentNovel;
  if (!novel || !novel.ncode) {
    showToast('先に作品を開いてください', 'error');
    return;
  }
  openUgcReportModal({
    ncode: novel.ncode,
    title: novel.title || '',
    author: novel.author || ''
  });
}

function buildUgcReportMail(ncode, title, author, reasonKey, comment) {
  const reasonLabel = UGC_REASON_LABELS[reasonKey] || reasonKey;
  const subject = `【小説AI朗読 通報】${ncode.toUpperCase()} ${title}`.slice(0, 120);
  const body = [
    '小説AI朗読プレイヤーからの不適切コンテンツ通報です。',
    '',
    `作品ID: ${ncode}`,
    `タイトル: ${title}`,
    `作者: ${author || '（不明）'}`,
    `理由: ${reasonLabel} (${reasonKey})`,
    `補足: ${comment || '（なし）'}`,
    `送信日時: ${new Date().toISOString()}`,
    '',
    '※本メールはアプリの通報機能から作成されました。'
  ].join('\n');
  return { subject, body };
}

function submitUgcReport() {
  const ncode = document.getElementById('ugcReportNcode')?.value?.trim();
  const title = document.getElementById('ugcReportTitle')?.textContent?.trim() || ncode;
  const author = document.getElementById('ugcReportAuthor')?.value || '';
  const reasonKey = document.getElementById('ugcReportReason')?.value || 'other';
  const comment = document.getElementById('ugcReportComment')?.value?.trim() || '';
  const alsoBlock = !!document.getElementById('ugcAlsoBlock')?.checked;
  if (!ncode) {
    showToast('通報対象がありません', 'error');
    return;
  }

  const { subject, body } = buildUgcReportMail(ncode, title, author, reasonKey, comment);
  let mailed = false;

  if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.sendUgcReportEmail === 'function') {
    try {
      mailed = !!window.AndroidBridge.sendUgcReportEmail(UGC_REPORT_EMAIL, subject, body);
    } catch (e) {
      mailed = false;
    }
  }
  if (!mailed) {
    const href = `mailto:${encodeURIComponent(UGC_REPORT_EMAIL)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    try {
      window.location.href = href;
      mailed = true;
    } catch (e) {
      mailed = false;
    }
  }

  if (alsoBlock) {
    blockNovelLocally(ncode, title, author, reasonKey);
    renderBlockedNovelsList();
  }

  // Native にも通報ログ（端末内）を残す
  if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.reportContent === 'function') {
    try {
      window.AndroidBridge.reportContent(ncode, 'novel', reasonKey, comment, title, author);
    } catch (e) {}
  }

  closeUgcReportModal();
  if (mailed) {
    showToast(alsoBlock ? 'メール下書きを開きました（端末で非表示済み）' : 'メール下書きを開きました。送信してください。', 'success');
  } else {
    showToast(`メールを開けませんでした。窓口: ${UGC_REPORT_EMAIL}`, 'error');
  }
}

window.UGC_REPORT_EMAIL = UGC_REPORT_EMAIL;
window.getBlockedNovelIds = getBlockedNovelIds;
window.isNovelBlocked = isNovelBlocked;
window.blockNovelLocally = blockNovelLocally;
window.unblockNovelLocally = unblockNovelLocally;
window.renderBlockedNovelsList = renderBlockedNovelsList;
window.openUgcReportModal = openUgcReportModal;
window.openUgcReportModalFromCurrentNovel = openUgcReportModalFromCurrentNovel;
window.closeUgcReportModal = closeUgcReportModal;
window.submitUgcReport = submitUgcReport;

// アプリバージョン表示の更新（最上部＆下部）
function updateAppVersionBadges() {
  const verBadges = [
    document.getElementById('appVersionBadge'),
    document.getElementById('appVersionBadgeTop')
  ].filter(Boolean);
  const platBadges = [
    document.getElementById('appPlatformBadge'),
    document.getElementById('appPlatformBadgeTop')
  ].filter(Boolean);

  let verText = 'v1.4.0 (Build 11)';
  let platText = 'Android App';

  if (isAndroidApp && window.AndroidBridge && typeof window.AndroidBridge.getAppVersion === 'function') {
    const verName = window.AndroidBridge.getAppVersion();
    const verCode = (typeof window.AndroidBridge.getAppVersionCode === 'function') ? window.AndroidBridge.getAppVersionCode() : null;
    verText = verCode ? `v${verName} (Build ${verCode})` : `v${verName}`;
    platText = 'Android App';
  } else {
    verText = 'v1.4.0 (Build 11)';
    platText = isStandaloneMode ? 'Standalone' : 'Web/Desktop';
  }

  verBadges.forEach(badge => {
    badge.textContent = verText;
  });
  platBadges.forEach(badge => {
    badge.textContent = platText;
  });
}
window.updateAppVersionBadges = updateAppVersionBadges;

// 隠しタブ: バージョンバッジ連続タップで開発者・サポート情報を表示
let _versionTapCount = 0;
let _versionTapTimer = null;
function onAppVersionBadgeTap() {
  _versionTapCount++;
  if (_versionTapTimer) clearTimeout(_versionTapTimer);
  _versionTapTimer = setTimeout(() => {
    _versionTapCount = 0;
  }, 1800);

  if (_versionTapCount >= 5) {
    _versionTapCount = 0;
    const card = document.getElementById('hiddenSupportCard');
    if (card) {
      card.classList.remove('hidden');
      card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
    showToast('🛠️ 開発者・サポート情報（隠しタブ）を表示しました', 'info');
  } else if (_versionTapCount >= 3) {
    const remaining = 5 - _versionTapCount;
    showToast(`あと${remaining}回タップで開発者サポート情報を表示`, 'info');
  }
}

function copySupportEmail() {
  const email = window.UGC_REPORT_EMAIL || 'hosokawamamoru.mh@gmail.com';
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(email).then(() => {
      showToast('連絡先メールアドレスをコピーしました', 'success');
    }).catch(() => {
      showToast(`連絡先: ${email}`, 'info');
    });
  } else {
    showToast(`連絡先: ${email}`, 'info');
  }
}

window.onAppVersionBadgeTap = onAppVersionBadgeTap;
window.copySupportEmail = copySupportEmail;

