/**
 * いずれかのAI APIキー（Gemini / OpenAI / Claude）が設定されているか判定する
 */
function hasAnyConfiguredAiApiKey() {
  const stored = typeof getSettingsFromStorage === 'function' ? (getSettingsFromStorage() || {}) : {};
  const sysSettings = (!isAndroidApp && state.systemInfo?.settings) ? state.systemInfo.settings : {};

  const geminiKey = (
    document.getElementById('settingGeminiKey')?.value ||
    stored.gemini_api_key ||
    localStorage.getItem('narou_gemini_key') ||
    sysSettings.gemini_api_key ||
    ''
  ).trim();

  const openaiKey = (
    document.getElementById('settingOpenaiKey')?.value ||
    stored.openai_api_key ||
    localStorage.getItem('narou_openai_key') ||
    sysSettings.openai_api_key ||
    ''
  ).trim();

  const claudeKey = (
    document.getElementById('settingClaudeKey')?.value ||
    stored.claude_api_key ||
    localStorage.getItem('narou_claude_key') ||
    sysSettings.claude_api_key ||
    ''
  ).trim();

  return geminiKey.length >= 10 || openaiKey.length >= 10 || claudeKey.length >= 10;
}

/**
 * AIのAPIキーが何も設定されていない場合、起動2回に1回の頻度（1回目・3回目・5回目…）でAPIキー設定促進ダイアログを表示する
 */
function checkApiKeyPromptOnStartup() {
  if (window._hasCheckedApiKeyPromptThisLaunch) return;
  window._hasCheckedApiKeyPromptThisLaunch = true;

  if (hasAnyConfiguredAiApiKey()) {
    return;
  }

  const prevCount = parseInt(localStorage.getItem('narou_apikey_prompt_launch_counter') || '0', 10) || 0;
  const nextCount = prevCount + 1;
  try {
    localStorage.setItem('narou_apikey_prompt_launch_counter', String(nextCount));
  } catch (e) {}

  // 起動2回に1回（奇数回: 1回目, 3回目, 5回目...）の頻度で表示
  if (nextCount % 2 === 1) {
    const consentAgreed = localStorage.getItem('narou_policy_consent_v1');
    const consentModal = document.getElementById('policyConsentModal');
    const isConsentModalOpen = !consentAgreed || (consentModal && !consentModal.classList.contains('hidden'));

    if (isConsentModalOpen) {
      // 初回規約同意モーダル表示中は、同意ボタン押下直後に表示する
      window._pendingApiKeyPromptAfterConsent = true;
    } else {
      setTimeout(() => {
        if (!hasAnyConfiguredAiApiKey()) {
          openApiKeyTutorialModal('gemini', true);
        }
      }, 450);
    }
  }
}

function openApiKeyTutorialModal(initialProvider, isStartupPrompt = false) {
  const modal = document.getElementById('apiKeyTutorialModal');
  if (!modal) return;

  const startupBanner = document.getElementById('apiKeyStartupPromptBanner');
  if (startupBanner) {
    if (isStartupPrompt && !hasAnyConfiguredAiApiKey()) {
      const uiLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
      const t = API_KEY_STARTUP_PROMPT_I18N[uiLang] || API_KEY_STARTUP_PROMPT_I18N.ja;
      const titleEl = document.getElementById('apiKeyStartupPromptTitle');
      const badgeEl = document.getElementById('apiKeyStartupPromptBadge');
      const descEl = document.getElementById('apiKeyStartupPromptDesc');
      const openSetBtnEl = document.getElementById('apiKeyStartupOpenSettingsBtnText');
      const laterBtnEl = document.getElementById('apiKeyStartupLaterBtnText');

      if (titleEl) {
        titleEl.innerHTML = `<i class="ph-fill ph-bell-ringing text-amber-400 text-base"></i><span>${t.title}</span>`;
      }
      if (badgeEl) badgeEl.textContent = t.badge;
      if (descEl) descEl.innerHTML = t.desc;
      if (openSetBtnEl) openSetBtnEl.textContent = t.openSettingsBtn;
      if (laterBtnEl) laterBtnEl.textContent = t.laterBtn;
      startupBanner.classList.remove('hidden');
    } else {
      startupBanner.classList.add('hidden');
    }
  }

  const providerSel = document.getElementById('settingLlmProvider')?.value;
  const target = (initialProvider && ['gemini', 'openai', 'claude'].includes(initialProvider))
    ? initialProvider
    : (['gemini', 'openai', 'claude'].includes(providerSel) ? providerSel : 'gemini');
  modal.classList.remove('hidden');
  switchApiKeyTutorialTab(target);
}

function closeApiKeyTutorialModal() {
  const modal = document.getElementById('apiKeyTutorialModal');
  if (modal) modal.classList.add('hidden');
}

function switchApiKeyTutorialTab(provider) {
  _currentApiTutTab = ['gemini', 'openai', 'claude'].includes(provider) ? provider : 'gemini';
  const tabs = ['gemini', 'openai', 'claude'];
  tabs.forEach(p => {
    const btn = document.getElementById(`apiTutTab-${p}`);
    const pane = document.getElementById(`apiTutPane-${p}`);
    if (pane) pane.classList.toggle('hidden', p !== _currentApiTutTab);
    if (btn) {
      if (p === _currentApiTutTab) {
        const colorClass = p === 'gemini' ? 'border-blue-500 text-blue-400' : (p === 'openai' ? 'border-emerald-500 text-emerald-400' : 'border-violet-500 text-violet-400');
        btn.className = `py-2.5 px-2 font-bold border-b-2 ${colorClass} flex items-center justify-center space-x-1 transition`;
      } else {
        btn.className = 'py-2.5 px-2 font-medium border-b-2 border-transparent text-slate-400 hover:text-slate-200 flex items-center justify-center space-x-1 transition';
      }
    }
  });

  // 既存の保存済みキーを入力欄へ反映
  const input = document.getElementById('apiTutKeyInput');
  const step3Title = document.getElementById('apiTutStep3Title');
  const resBox = document.getElementById('apiTutTestResultBox');
  if (resBox) resBox.classList.add('hidden');

  if (input) {
    const stored = typeof getSettingsFromStorage === 'function' ? (getSettingsFromStorage() || {}) : {};
    let existing = '';
    if (_currentApiTutTab === 'gemini') {
      existing = document.getElementById('settingGeminiKey')?.value || stored.gemini_api_key || localStorage.getItem('narou_gemini_key') || '';
      input.placeholder = 'AIzaSy... から始まるGoogle Gemini APIキーを貼り付け';
      if (step3Title) step3Title.textContent = 'Gemini APIキーを貼り付けて接続テスト＆保存';
    } else if (_currentApiTutTab === 'openai') {
      existing = document.getElementById('settingOpenaiKey')?.value || stored.openai_api_key || localStorage.getItem('narou_openai_key') || '';
      input.placeholder = 'sk-... から始まるOpenAI APIキーを貼り付け';
      if (step3Title) step3Title.textContent = 'OpenAI APIキーを貼り付けて接続テスト＆保存';
    } else if (_currentApiTutTab === 'claude') {
      existing = document.getElementById('settingClaudeKey')?.value || stored.claude_api_key || localStorage.getItem('narou_claude_key') || '';
      input.placeholder = 'sk-ant-... から始まるClaude APIキーを貼り付け';
      if (step3Title) step3Title.textContent = 'Claude APIキーを貼り付けて接続テスト＆保存';
    }
    input.value = existing.trim();
    onApiTutKeyInputChange();
  }
}

function openExternalApiKeyPortal(url) {
  if (!url) return;
  try {
    if (window.AndroidBridge && typeof window.AndroidBridge.openExternalUrl === 'function') {
      window.AndroidBridge.openExternalUrl(url);
      return;
    }
  } catch (e) {}
  window.open(url, '_blank', 'noopener,noreferrer');
}

function toggleApiTutKeyVisibility() {
  const input = document.getElementById('apiTutKeyInput');
  const icon = document.getElementById('apiTutEyeIcon');
  if (!input) return;
  if (input.type === 'password') {
    input.type = 'text';
    if (icon) icon.className = 'ph-bold ph-eye-slash';
  } else {
    input.type = 'password';
    if (icon) icon.className = 'ph-bold ph-eye';
  }
}

function validateApiKeyFormat(provider, key) {
  const k = (key || '').trim();
  if (!k) return { valid: false, label: '未入力', color: 'bg-slate-800 text-slate-400' };
  if (provider === 'gemini') {
    if (/^AIza[0-9A-Za-z\-_]{30,45}$/.test(k)) {
      return { valid: true, label: '✓ Geminiキー形式OK', color: 'bg-emerald-950 text-emerald-300 border border-emerald-500/40' };
    }
    return { valid: false, label: '⚠️ AIzaSy...から始まる約39文字のキーを確認してください', color: 'bg-amber-950 text-amber-300 border border-amber-500/40' };
  }
  if (provider === 'openai') {
    if (/^sk-[0-9A-Za-z\-_]{20,}$/.test(k) && !k.startsWith('sk-ant-')) {
      return { valid: true, label: '✓ OpenAIキー形式OK', color: 'bg-emerald-950 text-emerald-300 border border-emerald-500/40' };
    }
    return { valid: false, label: '⚠️ sk-...から始まるOpenAIキーを確認してください', color: 'bg-amber-950 text-amber-300 border border-amber-500/40' };
  }
  if (provider === 'claude') {
    if (/^sk-ant-[0-9A-Za-z\-_]{20,}$/.test(k)) {
      return { valid: true, label: '✓ Claudeキー形式OK', color: 'bg-emerald-950 text-emerald-300 border border-emerald-500/40' };
    }
    return { valid: false, label: '⚠️ sk-ant-...から始まるClaudeキーを確認してください', color: 'bg-amber-950 text-amber-300 border border-amber-500/40' };
  }
  return { valid: true, label: '入力済', color: 'bg-blue-950 text-blue-300' };
}

function onApiTutKeyInputChange() {
  const input = document.getElementById('apiTutKeyInput');
  const badge = document.getElementById('apiTutFormatBadge');
  if (!input || !badge) return;
  const val = input.value.trim();

  // 万一別プロバイダのキーが貼られたら自動でタブを切り替える親切設計
  if (val.startsWith('AIza') && _currentApiTutTab !== 'gemini') {
    switchApiKeyTutorialTab('gemini');
    input.value = val;
  } else if (val.startsWith('sk-ant-') && _currentApiTutTab !== 'claude') {
    switchApiKeyTutorialTab('claude');
    input.value = val;
  } else if (val.startsWith('sk-') && !val.startsWith('sk-ant-') && _currentApiTutTab !== 'openai') {
    switchApiKeyTutorialTab('openai');
    input.value = val;
  }

  const check = validateApiKeyFormat(_currentApiTutTab, val);
  badge.textContent = check.label;
  badge.className = `text-[10px] font-mono px-2 py-0.5 rounded ${check.color}`;

  // 有効なAPIキー形式が入力されたら設定画面とストレージへ即時反映・自動保存
  if (val && check.valid) {
    const keyFieldMap = {
      gemini: 'settingGeminiKey',
      openai: 'settingOpenaiKey',
      claude: 'settingClaudeKey'
    };
    const targetFieldId = keyFieldMap[_currentApiTutTab];
    const targetEl = targetFieldId ? document.getElementById(targetFieldId) : null;
    if (targetEl && targetEl.value !== val) {
      targetEl.value = val;
    }
    const providerEl = document.getElementById('settingLlmProvider');
    if (providerEl && providerEl.value !== _currentApiTutTab) {
      providerEl.value = _currentApiTutTab;
      if (typeof toggleLlmFields === 'function') toggleLlmFields();
    }
    if (typeof scheduleImmediateSettingsSave === 'function') {
      scheduleImmediateSettingsSave({ debounceMs: 120 });
    }
  }
}

async function pasteToApiTutInput() {
  const input = document.getElementById('apiTutKeyInput');
  if (!input) return;
  try {
    if (navigator.clipboard && navigator.clipboard.readText) {
      const text = await navigator.clipboard.readText();
      if (text && text.trim()) {
        input.value = text.trim();
        onApiTutKeyInputChange();
        showToast('📋 クリップボードからAPIキーを貼り付け・即時保存しました', 'success');
        return;
      }
    }
  } catch (e) {}
  input.focus();
  showToast('入力欄を長押しして「貼り付け」を選択してください', 'info');
}

async function pasteApiKeyToInput(targetInputId) {
  const input = document.getElementById(targetInputId);
  if (!input) return;
  try {
    if (navigator.clipboard && navigator.clipboard.readText) {
      const text = await navigator.clipboard.readText();
      if (text && text.trim()) {
        input.value = text.trim();
        if (targetInputId === 'settingGeminiKey' && typeof onGeminiKeyInput === 'function') {
          onGeminiKeyInput();
        } else if (typeof scheduleImmediateSettingsSave === 'function') {
          scheduleImmediateSettingsSave({ debounceMs: 80 });
        }
        showToast('📋 APIキーを貼り付けて自動保存しました', 'success');
        return;
      }
    }
  } catch (e) {}
  input.focus();
  showToast('入力欄を長押しして「貼り付け」を選択してください', 'info');
}

async function testAndSaveApiKeyFromTutorial() {
  const input = document.getElementById('apiTutKeyInput');
  const resBox = document.getElementById('apiTutTestResultBox');
  const btn = document.getElementById('apiTutTestAndSaveBtn');
  if (!input || !resBox) return;

  const key = input.value.trim();
  if (!key) {
    resBox.className = 'p-2.5 rounded-lg bg-rose-950/70 border border-rose-500/40 text-rose-200 text-[11px]';
    resBox.textContent = '⚠️ APIキーが入力されていません。ステップ2でコピーしたキーを貼り付けてください。';
    resBox.classList.remove('hidden');
    return;
  }

  const originalBtnHtml = btn ? btn.innerHTML : '';
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="ph-bold ph-spinner animate-spin text-sm"></i><span>接続テスト中...</span>';
  }
  resBox.className = 'p-2.5 rounded-lg bg-blue-950/60 border border-blue-500/40 text-blue-200 text-[11px]';
  resBox.textContent = '🔄 AIサーバーへ疎通確認を行っています...';
  resBox.classList.remove('hidden');

  let testOk = false;
  let detailMsg = '';

  try {
    if (_currentApiTutTab === 'gemini') {
      const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${encodeURIComponent(key)}`);
      if (resp.ok) {
        const data = await resp.json();
        const count = Array.isArray(data.models) ? data.models.length : 0;
        testOk = true;
        detailMsg = `🎉 Google Gemini API との接続に成功しました！（利用可能モデル ${count}件を確認）`;
      } else {
        const errData = await resp.json().catch(() => ({}));
        detailMsg = `❌ Gemini API認証エラー (${resp.status}): ${errData.error?.message || 'キーが正しいか確認してください'}`;
      }
    } else if (_currentApiTutTab === 'openai') {
      const resp = await fetch('https://api.openai.com/v1/models', {
        headers: { 'Authorization': `Bearer ${key}` }
      });
      if (resp.ok) {
        testOk = true;
        detailMsg = '🎉 OpenAI API との接続に成功しました！';
      } else {
        const errData = await resp.json().catch(() => ({}));
        detailMsg = `❌ OpenAI API認証エラー (${resp.status}): ${errData.error?.message || 'キーまたはクレジット残高を確認してください'}`;
      }
    } else if (_currentApiTutTab === 'claude') {
      // Claudeはブラウザからの直接CORSが制限される場合があるため、フォーマット検証＋キー保存を行う
      const fmt = validateApiKeyFormat('claude', key);
      if (fmt.valid) {
        testOk = true;
        detailMsg = '✅ Anthropic Claude APIキーの形式を確認し、端末に安全に保存しました！';
      } else {
        detailMsg = '❌ Claude APIキーは「sk-ant-...」から始まる文字列を入力してください。';
      }
    }
  } catch (err) {
    const fmt = validateApiKeyFormat(_currentApiTutTab, key);
    if (fmt.valid) {
      testOk = true;
      detailMsg = '✅ APIキーの形式を確認し、端末に保存しました（オフラインまたはネットワーク制限下のため形式検証で保存）。';
    } else {
      detailMsg = `⚠️ 通信エラーまたはキー形式不正: ${err.message || err}`;
    }
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = originalBtnHtml;
    }
  }

  if (testOk) {
    const currentSettings = (typeof getSettingsFromStorage === 'function' ? getSettingsFromStorage() : null) || {};
    // 設定画面の入力欄・localStorage・narou_reader_settingsのすべてに即時反映してプロバイダを有効化
    if (_currentApiTutTab === 'gemini') {
      localStorage.setItem('narou_gemini_key', key);
      currentSettings.gemini_api_key = key;
      const el = document.getElementById('settingGeminiKey');
      if (el) el.value = key;
    } else if (_currentApiTutTab === 'openai') {
      localStorage.setItem('narou_openai_key', key);
      currentSettings.openai_api_key = key;
      const el = document.getElementById('settingOpenaiKey');
      if (el) el.value = key;
    } else if (_currentApiTutTab === 'claude') {
      localStorage.setItem('narou_claude_key', key);
      currentSettings.claude_api_key = key;
      const el = document.getElementById('settingClaudeKey');
      if (el) el.value = key;
    }
    currentSettings.llm_provider = _currentApiTutTab;
    currentSettings.llm_provider_manually_set = true;
    try {
      localStorage.setItem('narou_reader_settings', JSON.stringify(currentSettings));
    } catch (e) {}
    localStorage.setItem('narou_llm_provider', _currentApiTutTab);
    localStorage.setItem('narou_ai_provider', _currentApiTutTab);

    const provSel = document.getElementById('settingLlmProvider');
    if (provSel) {
      provSel.value = _currentApiTutTab;
      if (typeof toggleLlmFields === 'function') toggleLlmFields(false);
    }
    if (typeof updateLlmBadge === 'function') {
      updateLlmBadge(_currentApiTutTab);
    }
    if (_currentApiTutTab === 'gemini' && typeof fetchGeminiModelsList === 'function') {
      fetchGeminiModelsList(true);
    }
    const startupBanner = document.getElementById('apiKeyStartupPromptBanner');
    if (startupBanner) startupBanner.classList.add('hidden');

    resBox.className = 'p-2.5 rounded-lg bg-emerald-950/70 border border-emerald-500/40 text-emerald-200 text-[11px] font-medium';
    resBox.textContent = `${detailMsg} 話者推定エンジンを「${_currentApiTutTab.toUpperCase()}」に自動設定しました。`;
    showToast('✅ APIキーを保存・有効化しました！', 'success');
  } else {
    resBox.className = 'p-2.5 rounded-lg bg-rose-950/70 border border-rose-500/40 text-rose-200 text-[11px]';
    resBox.textContent = detailMsg;
  }
}

// ============================================================================
// 27. 🌙 スリープタイマー (おやすみ自動停止: 時間指定 & この話の終わりまで)
// ============================================================================
let _sleepTimerInterval = null;
let _sleepTimerTargetTimeMs = 0;
window._sleepTimerEndOfEpisode = false;

function openSleepTimerModal() {
  const modal = document.getElementById('sleepTimerModal');
  if (!modal) return;
  modal.classList.remove('hidden');
  updateSleepTimerUI();
}

function closeSleepTimerModal() {
  const modal = document.getElementById('sleepTimerModal');
  if (modal) modal.classList.add('hidden');
}

function setSleepTimer(minutesOrMode, silent) {
  if (_sleepTimerInterval) {
    clearInterval(_sleepTimerInterval);
    _sleepTimerInterval = null;
  }
  _sleepTimerTargetTimeMs = 0;
  window._sleepTimerEndOfEpisode = false;

  if (minutesOrMode === 'end_of_episode') {
    window._sleepTimerEndOfEpisode = true;
    if (!silent) showToast('🌙 スリープタイマー: この話の終わりで自動停止します', 'info');
    updateSleepTimerUI();
    closeSleepTimerModal();
    return;
  }

  const mins = Number(minutesOrMode) || 0;
  if (mins <= 0) {
    if (!silent) showToast('🌙 スリープタイマーを解除しました', 'info');
    updateSleepTimerUI();
    return;
  }

  _sleepTimerTargetTimeMs = Date.now() + mins * 60 * 1000;
  _sleepTimerInterval = setInterval(() => {
    const remainMs = _sleepTimerTargetTimeMs - Date.now();
    if (remainMs <= 0) {
      clearInterval(_sleepTimerInterval);
      _sleepTimerInterval = null;
      _sleepTimerTargetTimeMs = 0;
      pauseAudio();
      // 環境音BGMも再生中ならスリープ時に自動停止して睡眠を妨げない
      if (typeof setAmbientBgmMode === 'function' && _currentAmbientMode !== 'off') {
        setAmbientBgmMode('off', true);
      }
      updateSleepTimerUI();
      showToast('🌙 おやすみタイマーの時間になったため朗読を停止しました', 'info');
      return;
    }
    updateSleepTimerUI();
  }, 1000);

  if (!silent) showToast(`🌙 スリープタイマーを ${mins}分後 にセットしました`, 'success');
  updateSleepTimerUI();
  closeSleepTimerModal();
}

function updateSleepTimerUI() {
  const btn = document.getElementById('sleepTimerBtn');
  const badge = document.getElementById('sleepTimerBadge');
  const drawerBadge = document.getElementById('drawerSleepTimerBadge');
  const activeBanner = document.getElementById('sleepTimerActiveBanner');
  const modalCountdown = document.getElementById('sleepTimerModalCountdown');

  if (window._sleepTimerEndOfEpisode) {
    if (badge) badge.textContent = '話末停止';
    if (drawerBadge) {
      drawerBadge.textContent = '話末停止';
      drawerBadge.className = 'text-[10px] text-indigo-400 font-mono font-bold';
    }
    if (btn) btn.classList.add('active-pill');
    if (activeBanner) activeBanner.classList.remove('hidden');
    if (modalCountdown) modalCountdown.textContent = 'この話の終わりまで';
    return;
  }

  const remainMs = _sleepTimerTargetTimeMs - Date.now();
  if (_sleepTimerTargetTimeMs > 0 && remainMs > 0) {
    const totalSec = Math.ceil(remainMs / 1000);
    const m = String(Math.floor(totalSec / 60)).padStart(2, '0');
    const s = String(totalSec % 60).padStart(2, '0');
    if (badge) badge.textContent = `${m}:${s}`;
    if (drawerBadge) {
      drawerBadge.textContent = `${m}:${s} 残り`;
      drawerBadge.className = 'text-[10px] text-indigo-400 font-mono font-bold animate-pulse';
    }
    if (btn) btn.classList.add('active-pill');
    if (activeBanner) activeBanner.classList.remove('hidden');
    if (modalCountdown) modalCountdown.textContent = `${m}:${s}`;
  } else {
    if (badge) badge.textContent = 'タイマー';
    if (drawerBadge) {
      drawerBadge.textContent = 'オフ';
      drawerBadge.className = 'text-[10px] text-slate-400 font-mono';
    }
    if (btn) btn.classList.remove('active-pill');
    if (activeBanner) activeBanner.classList.add('hidden');
  }
}

function updateDrawerSleepTimerUI(mins) {
  triggerHaptic('click');
  updateSleepTimerUI();
}
window.updateDrawerSleepTimerUI = updateDrawerSleepTimerUI;

// ============================================================================
// 28. 🔖 しおり・お気に入り名言帳 (Bookmarks & Favorite Quotes)
// ============================================================================
const BOOKMARKS_STORAGE_KEY = 'narou_user_bookmarks_v1';

function getSavedBookmarks() {
  try {
    const raw = localStorage.getItem(BOOKMARKS_STORAGE_KEY);
    const list = raw ? JSON.parse(raw) : [];
    return Array.isArray(list) ? list : [];
  } catch (e) {
    return [];
  }
}

function saveBookmarksList(list) {
  try {
    localStorage.setItem(BOOKMARKS_STORAGE_KEY, JSON.stringify(list));
  } catch (e) {}
  updateBookmarksCountBadge();
}

function updateBookmarksCountBadge() {
  const list = getSavedBookmarks();
  const badge = document.getElementById('bookmarksCountBadge');
  if (!badge) return;
  if (list.length > 0) {
    badge.textContent = String(list.length);
    badge.classList.remove('hidden');
  } else {
    badge.classList.add('hidden');
  }
}

function isSegmentBookmarked(segIndex) {
  if (!state.currentNovel) return false;
  const ncode = String(state.currentNovel.ncode || '').toLowerCase();
  const ep = Number(state.currentEpisodeNum) || 1;
  return getSavedBookmarks().some(b => String(b.ncode || '').toLowerCase() === ncode && Number(b.episode) === ep && Number(b.segmentIndex) === Number(segIndex));
}

function toggleSegmentBookmark(segIndex, event) {
  if (event) event.stopPropagation();
  if (!state.currentNovel || !Array.isArray(state.currentSegments) || !state.currentSegments[segIndex]) {
    showToast('作品またはエピソードを開いた状態で実行してください', 'info');
    return;
  }
  const ncode = String(state.currentNovel.ncode || '').toLowerCase();
  const ep = Number(state.currentEpisodeNum) || 1;
  const seg = state.currentSegments[segIndex];
  let list = getSavedBookmarks();
  const existingIdx = list.findIndex(b => String(b.ncode || '').toLowerCase() === ncode && Number(b.episode) === ep && Number(b.segmentIndex) === Number(segIndex));

  if (existingIdx >= 0) {
    list.splice(existingIdx, 1);
    saveBookmarksList(list);
    showToast('🔖 しおりを解除しました', 'info');
  } else {
    list.unshift({
      id: `bm_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
      ncode,
      novelTitle: state.currentNovel.title || ncode,
      episode: ep,
      episodeTitle: document.getElementById('playerEpisodeTitle')?.textContent || `第${ep}話`,
      segmentIndex: Number(segIndex),
      speaker: seg.speaker || (seg.type === 'dialogue' ? '登場人物' : '地の文'),
      text: seg.display_text || '',
      note: '',
      createdAt: new Date().toISOString()
    });
    saveBookmarksList(list);
    showToast(`🔖 #${segIndex + 1} をしおり・名言帳に保存しました`, 'success');
  }
  if (typeof renderSegments === 'function') {
    const curIdx = state.currentSegmentIndex;
    renderSegments();
    highlightCurrentSegment(curIdx);
  }
  renderBookmarksModalList();
}

function quickSaveCurrentBookmark(fromModal) {
  if (!state.currentNovel || !Array.isArray(state.currentSegments) || state.currentSegments.length === 0) {
    showToast('朗読中のエピソードがある時にしおりを保存できます', 'info');
    return;
  }
  const idx = Math.max(0, Number(state.currentSegmentIndex) || 0);
  const ncode = String(state.currentNovel.ncode || '').toLowerCase();
  const ep = Number(state.currentEpisodeNum) || 1;
  const seg = state.currentSegments[idx];
  const list = getSavedBookmarks();
  const exists = list.some(b => String(b.ncode || '').toLowerCase() === ncode && Number(b.episode) === ep && Number(b.segmentIndex) === idx);
  if (exists) {
    showToast(`🔖 第${ep}話 #${idx + 1} はすでにしおり保存されています`, 'info');
    if (fromModal) renderBookmarksModalList();
    return;
  }
  list.unshift({
    id: `bm_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    ncode,
    novelTitle: state.currentNovel.title || ncode,
    episode: ep,
    episodeTitle: document.getElementById('playerEpisodeTitle')?.textContent || `第${ep}話`,
    segmentIndex: idx,
    speaker: seg?.speaker || '地の文',
    text: seg?.display_text || '',
    note: '',
    createdAt: new Date().toISOString()
  });
  saveBookmarksList(list);
  showToast(`🔖 第${ep}話 #${idx + 1} をしおりに保存しました`, 'success');
  if (typeof renderSegments === 'function') {
    renderSegments();
    highlightCurrentSegment(idx);
  }
  if (fromModal) renderBookmarksModalList();
}

function openBookmarksModal() {
  const modal = document.getElementById('bookmarksModal');
  if (!modal) return;
  modal.classList.remove('hidden');
  renderBookmarksModalList();
}

function closeBookmarksModal() {
  const modal = document.getElementById('bookmarksModal');
  if (modal) modal.classList.add('hidden');
}

function renderBookmarksModalList() {
  const container = document.getElementById('bookmarksListContainer');
  if (!container) return;
  const list = getSavedBookmarks();
  updateBookmarksCountBadge();

  if (list.length === 0) {
    container.innerHTML = '<p class="text-slate-500 text-center py-6">保存されたしおり・名言はまだありません。<br>朗読画面の「+しおり」または各セリフ右上の🔖から保存できます。</p>';
    return;
  }

  container.innerHTML = list.map(item => `
    <div class="p-3 rounded-xl bg-slate-950 border border-slate-800 space-y-1.5">
      <div class="flex items-center justify-between gap-2">
        <div class="min-w-0">
          <span class="text-[10px] font-bold text-amber-300 truncate block">${escapeHtml(item.novelTitle || item.ncode)}</span>
          <span class="text-[10px] text-slate-400 font-mono">${escapeHtml(item.episodeTitle || `第${item.episode}話`)} ・ #${Number(item.segmentIndex) + 1} (${escapeHtml(item.speaker || '地の文')})</span>
        </div>
        <div class="flex items-center gap-1 shrink-0">
          <button type="button" onclick="jumpToBookmarkItem('${item.id}')" class="px-2.5 py-1 rounded-lg bg-blue-600 hover:bg-blue-500 text-white text-[11px] font-bold flex items-center space-x-1 transition">
            <i class="ph-fill ph-play"></i>
            <span>再生</span>
          </button>
          <button type="button" onclick="deleteBookmarkItem('${item.id}')" class="p-1.5 rounded-lg bg-slate-800 hover:bg-rose-900/50 text-slate-400 hover:text-rose-300 transition" title="削除">
            <i class="ph-bold ph-trash"></i>
          </button>
        </div>
      </div>
      <p class="text-xs text-slate-200 leading-relaxed bg-slate-900/80 p-2 rounded-lg border border-slate-800/80">${escapeHtml(item.text)}</p>
    </div>
  `).join('');
}

async function jumpToBookmarkItem(id) {
  const item = getSavedBookmarks().find(b => b.id === id);
  if (!item) return;
  closeBookmarksModal();
  const curNcode = String(state.currentNovel?.ncode || '').toLowerCase();
  if (curNcode === String(item.ncode || '').toLowerCase() && Number(state.currentEpisodeNum) === Number(item.episode)) {
    switchTab('player');
    playSegment(Number(item.segmentIndex) || 0);
    return;
  }
  if (curNcode !== String(item.ncode || '').toLowerCase() && typeof selectNovel === 'function') {
    await selectNovel(item.ncode);
  }
  if (typeof startReadingEpisode === 'function') {
    await startReadingEpisode(Number(item.episode) || 1, Number(item.segmentIndex) || 0, false, true);
  }
}

function deleteBookmarkItem(id) {
  const list = getSavedBookmarks().filter(b => b.id !== id);
  saveBookmarksList(list);
  renderBookmarksModalList();
  if (typeof renderSegments === 'function' && state.currentSegments?.length) {
    const idx = state.currentSegmentIndex;
    renderSegments();
    highlightCurrentSegment(idx);
  }
}

function copyAllBookmarksText() {
  const list = getSavedBookmarks();
  if (list.length === 0) {
    showToast('コピーするしおりがありません', 'info');
    return;
  }
  const text = list.map(b => `【${b.novelTitle}】(${b.episodeTitle} #${Number(b.segmentIndex) + 1} / ${b.speaker})\n${b.text}`).join('\n\n');
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => showToast('📋 しおり・名言一覧をコピーしました', 'success'));
  }
}

// ============================================================================
// 29. 📖 カスタム読み辞書 (固有名詞・ルビ登録 & ファンタジープリセット)
// ============================================================================
const PRONUNCIATION_DICT_KEY = 'narou_custom_pronunciation_dict_v1';

function getPronunciationDict() {
  try {
    const raw = localStorage.getItem(PRONUNCIATION_DICT_KEY);
    const list = raw ? JSON.parse(raw) : [];
    return Array.isArray(list) ? list : [];
  } catch (e) {
    return [];
  }
}

function savePronunciationDict(list) {
  try {
    localStorage.setItem(PRONUNCIATION_DICT_KEY, JSON.stringify(list));
  } catch (e) {}
}

function applyCustomPronunciationDict(text) {
  if (!text) return '';
  const list = getPronunciationDict();
  if (list.length === 0) return text;
  let out = text;
  // 長い単語から優先的に置換して部分一致の誤爆を防ぐ
  const sorted = [...list].sort((a, b) => (b.surface?.length || 0) - (a.surface?.length || 0));
  for (const item of sorted) {
    if (item && item.surface && item.reading) {
      out = out.split(item.surface).join(item.reading);
    }
  }
  return out;
}

function openPronunciationDictModal() {
  const modal = document.getElementById('pronunciationDictModal');
  if (!modal) return;
  modal.classList.remove('hidden');
  renderPronunciationDictList();
}

function closePronunciationDictModal() {
  const modal = document.getElementById('pronunciationDictModal');
  if (modal) modal.classList.add('hidden');
}

function addPronunciationDictEntry() {
  const surfEl = document.getElementById('pronDictSurfaceInput');
  const readEl = document.getElementById('pronDictReadingInput');
  const surface = (surfEl?.value || '').trim();
  const reading = (readEl?.value || '').trim();
  if (!surface || !reading) {
    showToast('置換したい単語と読み仮名の両方を入力してください', 'info');
    return;
  }
  const list = getPronunciationDict().filter(x => x.surface !== surface);
  list.unshift({ surface, reading, updatedAt: Date.now() });
  savePronunciationDict(list);
  if (surfEl) surfEl.value = '';
  if (readEl) readEl.value = '';
  renderPronunciationDictList();
  showToast(`📖 読み辞書に「${surface} → ${reading}」を登録しました`, 'success');
}

function addFantasyPresetPronunciations() {
  const presets = [
    { surface: '聖剣エクスカリバー', reading: 'せいけんえくすかりばー' },
    { surface: '冒険者ギルド', reading: 'ぼうけんしゃぎるど' },
    { surface: '治癒魔法', reading: 'ちゆまほう' },
    { surface: '空間転移', reading: 'くうかんてんい' },
    { surface: '魔導師', reading: 'まどうし' },
    { surface: '鑑定眼', reading: 'かんていがん' },
    { surface: '状態異常', reading: 'じょうたいいじょう' },
    { surface: '固有スキル', reading: 'こゆうすきる' },
    { surface: '迷宮', reading: 'ダンジョン' },
    { surface: '好感度', reading: 'こうかんど' }
  ];
  const list = getPronunciationDict();
  let added = 0;
  for (const p of presets) {
    if (!list.some(x => x.surface === p.surface)) {
      list.push({ ...p, updatedAt: Date.now() });
      added++;
    }
  }
  savePronunciationDict(list);
  renderPronunciationDictList();
  showToast(`✨ 定番ファンタジー・難読語プリセット (${added}件) を追加しました`, 'success');
}

function deletePronunciationDictEntry(surface) {
  const list = getPronunciationDict().filter(x => x.surface !== surface);
  savePronunciationDict(list);
  renderPronunciationDictList();
}

function testSpeakPronunciationEntry(reading) {
  if (!reading) return;
  if (isAndroidAppNow() && window.AndroidBridge && typeof window.AndroidBridge.speakText === 'function') {
    window.AndroidBridge.speakText(reading, 'vv:3', 1.0, 1.0, 'dict_test', false);
  } else if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(reading);
    u.lang = 'ja-JP';
    window.speechSynthesis.speak(u);
  }
}

function renderPronunciationDictList() {
  const container = document.getElementById('pronunciationDictListContainer');
  const countEl = document.getElementById('pronunciationDictCountText');
  if (!container) return;
  const list = getPronunciationDict();
  if (countEl) countEl.textContent = `登録数: ${list.length}件`;

  if (list.length === 0) {
    container.innerHTML = '<p class="text-slate-500 text-center py-6">登録されている読み辞書エントリはありません</p>';
    return;
  }

  container.innerHTML = list.map((item, idx) => `
    <div class="p-2.5 rounded-xl bg-slate-950 border border-slate-800 flex items-center justify-between gap-2">
      <div class="min-w-0 flex items-center space-x-2">
        <span class="font-bold text-slate-100 truncate">${escapeHtml(item.surface)}</span>
        <i class="ph-bold ph-arrow-right text-slate-500 text-[10px]"></i>
        <span class="text-emerald-300 font-medium truncate">${escapeHtml(item.reading)}</span>
      </div>
      <div class="flex items-center space-x-1 shrink-0">
        <button type="button" onclick="testSpeakPronunciationEntry('${escapeHtml(item.reading)}')" class="px-2 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-cyan-300 text-[10px] font-bold" title="発音テスト">🔊 試聴</button>
        <button type="button" onclick="deletePronunciationDictEntry('${escapeHtml(item.surface)}')" class="p-1 rounded-lg bg-slate-800 hover:bg-rose-900/50 text-slate-400 hover:text-rose-300" title="削除">
          <i class="ph-bold ph-trash"></i>
        </button>
      </div>
    </div>
  `).join('');
}

// ============================================================================
// 30. 🌧️ 環境音BGMミキサー (通信ゼロ・Web Audio API プロシージャル生成)
// ============================================================================
let _ambientAudioCtx = null;
let _ambientSourceNode = null;
let _ambientGainNode = null;
let _ambientCrackleTimer = null;
let _currentAmbientMode = 'off';

function openAmbientBgmModal() {
  const modal = document.getElementById('ambientBgmModal');
  if (!modal) return;
  modal.classList.remove('hidden');
  updateAmbientBgmUI();
}

function closeAmbientBgmModal() {
  const modal = document.getElementById('ambientBgmModal');
  if (modal) modal.classList.add('hidden');
}

function stopAmbientAudioNodes() {
  if (_ambientCrackleTimer) {
    clearInterval(_ambientCrackleTimer);
    _ambientCrackleTimer = null;
  }
  if (_ambientSourceNode) {
    try { _ambientSourceNode.stop(); } catch (e) {}
    try { _ambientSourceNode.disconnect(); } catch (e) {}
    _ambientSourceNode = null;
  }
}

function setAmbientBgmMode(mode, silent) {
  _currentAmbientMode = mode || 'off';
  stopAmbientAudioNodes();

  if (_currentAmbientMode === 'off') {
    updateAmbientBgmUI();
    if (!silent) showToast('🔇 環境音BGMをオフにしました', 'info');
    return;
  }

  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!_ambientAudioCtx) _ambientAudioCtx = new AudioCtx();
    if (_ambientAudioCtx.state === 'suspended') _ambientAudioCtx.resume();

    // 4秒ループのブラウン/ピンクノイズバッファを生成
    const sampleRate = _ambientAudioCtx.sampleRate;
    const bufferSize = sampleRate * 4;
    const buffer = _ambientAudioCtx.createBuffer(1, bufferSize, sampleRate);
    const data = buffer.getChannelData(0);
    let lastOut = 0.0;
    for (let i = 0; i < bufferSize; i++) {
      const white = Math.random() * 2 - 1;
      data[i] = (lastOut + (0.02 * white)) / 1.02;
      lastOut = data[i];
      data[i] *= 3.2;
    }

    const noise = _ambientAudioCtx.createBufferSource();
    noise.buffer = buffer;
    noise.loop = true;

    const filter = _ambientAudioCtx.createBiquadFilter();
    if (_currentAmbientMode === 'rain') {
      filter.type = 'bandpass';
      filter.frequency.value = 950;
      filter.Q.value = 0.5;
    } else if (_currentAmbientMode === 'bonfire') {
      filter.type = 'lowpass';
      filter.frequency.value = 420;
    } else if (_currentAmbientMode === 'cafe') {
      filter.type = 'lowpass';
      filter.frequency.value = 320;
    } else {
      // wind
      filter.type = 'bandpass';
      filter.frequency.value = 380;
      filter.Q.value = 1.8;
    }

    if (!_ambientGainNode) {
      _ambientGainNode = _ambientAudioCtx.createGain();
      _ambientGainNode.connect(_ambientAudioCtx.destination);
    }
    const volSlider = document.getElementById('ambientBgmVolumeSlider');
    const volPct = Number(volSlider?.value || localStorage.getItem('narou_ambient_vol') || 20);
    _ambientGainNode.gain.value = Math.max(0.01, Math.min(0.7, volPct / 150));

    noise.connect(filter);
    filter.connect(_ambientGainNode);
    noise.start(0);
    _ambientSourceNode = noise;

    // 焚き火モードの場合はパチパチという微小なクラックル音を追加
    if (_currentAmbientMode === 'bonfire') {
      _ambientCrackleTimer = setInterval(() => {
        if (!_ambientAudioCtx || _currentAmbientMode !== 'bonfire') return;
        try {
          const osc = _ambientAudioCtx.createOscillator();
          const g = _ambientAudioCtx.createGain();
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(1200 + Math.random() * 1800, _ambientAudioCtx.currentTime);
          g.gain.setValueAtTime(0.015, _ambientAudioCtx.currentTime);
          g.gain.exponentialRampToValueAtTime(0.0001, _ambientAudioCtx.currentTime + 0.04);
          osc.connect(g);
          g.connect(_ambientGainNode);
          osc.start();
          osc.stop(_ambientAudioCtx.currentTime + 0.045);
        } catch (e) {}
      }, 450);
    }

    const labelMap = { rain: '🌧️ 雨音', bonfire: '🔥 焚き火', cafe: '☕ カフェ', wind: '🌲 夜風' };
    if (!silent) showToast(`${labelMap[_currentAmbientMode] || '環境音'} BGMを開始しました`, 'success');
  } catch (e) {
    console.warn('Ambient BGM error:', e);
  }
  updateAmbientBgmUI();
}

function onAmbientBgmVolumeChange(val) {
  const pct = Number(val) || 20;
  localStorage.setItem('narou_ambient_vol', String(pct));
  const lbl = document.getElementById('ambientBgmVolumeLabel');
  if (lbl) lbl.textContent = `${pct}%`;
  if (_ambientGainNode) {
    _ambientGainNode.gain.value = Math.max(0.01, Math.min(0.7, pct / 150));
  }
}

function updateAmbientBgmUI() {
  const modes = ['off', 'rain', 'bonfire', 'cafe', 'wind'];
  modes.forEach(m => {
    const btn = document.getElementById(`ambientBtn-${m}`);
    if (!btn) return;
    const icon = btn.querySelector('i');
    if (m === _currentAmbientMode) {
      btn.classList.add('is-selected');
      if (icon) icon.classList.remove('hidden');
    } else {
      btn.classList.remove('is-selected');
      if (icon) icon.classList.add('hidden');
    }
  });
  const topBtn = document.getElementById('ambientBgmBtn');
  const badge = document.getElementById('ambientBgmBadge');
  const shortMap = { off: '環境音', rain: '雨音ON', bonfire: '焚き火ON', cafe: 'カフェON', wind: '夜風ON' };
  if (badge) badge.textContent = shortMap[_currentAmbientMode] || '環境音';
  if (topBtn) topBtn.classList.toggle('active-pill', _currentAmbientMode !== 'off');
}

// ============================================================================
// 31. 🔍 エピソード内セリフ検索 & キャラクター絞り込みジャンプ
// ============================================================================
let _episodeSearchMatches = [];
let _episodeSearchCurrentPos = -1;

function toggleEpisodeSearchBar(forceState) {
  const bar = document.getElementById('playerInEpisodeSearchBar');
  const btn = document.getElementById('episodeSearchToggleBtn');
  if (!bar) return;
  const show = typeof forceState === 'boolean' ? forceState : bar.classList.contains('hidden');
  bar.classList.toggle('hidden', !show);
  if (btn) btn.classList.toggle('active-pill', show);
  if (show) {
    refreshEpisodeSpeakerFilterOptions();
    document.getElementById('episodeSearchInput')?.focus();
  } else {
    clearEpisodeSearchHighlights();
  }
}

function refreshEpisodeSpeakerFilterOptions() {
  const sel = document.getElementById('episodeSpeakerFilterSelect');
  if (!sel || !Array.isArray(state.currentSegments)) return;
  const currentVal = sel.value;
  const speakers = new Set();
  state.currentSegments.forEach(s => {
    if (s && s.speaker) speakers.add(s.speaker);
  });
  sel.innerHTML = '<option value="">全話者 (すべて)</option>' +
    Array.from(speakers).map(sp => `<option value="${escapeHtml(sp)}">${escapeHtml(sp)}</option>`).join('');
  if (speakers.has(currentVal)) sel.value = currentVal;
}

function clearEpisodeSearchHighlights() {
  document.querySelectorAll('.segment-search-match, .segment-search-match-current').forEach(el => {
    el.classList.remove('segment-search-match', 'segment-search-match-current');
  });
}

function clearEpisodeSearchInput() {
  const input = document.getElementById('episodeSearchInput');
  const sel = document.getElementById('episodeSpeakerFilterSelect');
  if (input) input.value = '';
  if (sel) sel.value = '';
  onEpisodeSearchInput();
}

function onEpisodeSearchInput() {
  clearEpisodeSearchHighlights();
  _episodeSearchMatches = [];
  _episodeSearchCurrentPos = -1;

  const q = (document.getElementById('episodeSearchInput')?.value || '').trim().toLowerCase();
  const sp = (document.getElementById('episodeSpeakerFilterSelect')?.value || '').trim();
  const statusEl = document.getElementById('episodeSearchStatusText');
  const countEl = document.getElementById('episodeSearchCountBadge');

  if (!q && !sp) {
    if (statusEl) statusEl.textContent = 'キーワードまたは話者を選択すると該当行へジャンプします';
    if (countEl) countEl.textContent = '';
    return;
  }

  if (Array.isArray(state.currentSegments)) {
    state.currentSegments.forEach((seg, idx) => {
      const textMatch = !q || String(seg.display_text || '').toLowerCase().includes(q) || String(seg.speaker || '').toLowerCase().includes(q);
      const speakerMatch = !sp || String(seg.speaker || '') === sp;
      if (textMatch && speakerMatch) {
        _episodeSearchMatches.push(idx);
        document.getElementById(`seg-${idx}`)?.classList.add('segment-search-match');
      }
    });
  }

  if (_episodeSearchMatches.length === 0) {
    if (statusEl) statusEl.textContent = '一致するセリフ・本文が見つかりませんでした';
    if (countEl) countEl.textContent = '0件';
    return;
  }

  _episodeSearchCurrentPos = 0;
  focusEpisodeSearchMatch();
}

function navigateEpisodeSearchMatch(delta) {
  if (_episodeSearchMatches.length === 0) return;
  _episodeSearchCurrentPos = (_episodeSearchCurrentPos + delta + _episodeSearchMatches.length) % _episodeSearchMatches.length;
  focusEpisodeSearchMatch();
}

function focusEpisodeSearchMatch() {
  document.querySelectorAll('.segment-search-match-current').forEach(el => el.classList.remove('segment-search-match-current'));
  const targetSegIdx = _episodeSearchMatches[_episodeSearchCurrentPos];
  const card = document.getElementById(`seg-${targetSegIdx}`);
  if (card) {
    card.classList.add('segment-search-match-current');
    card.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
  const statusEl = document.getElementById('episodeSearchStatusText');
  const countEl = document.getElementById('episodeSearchCountBadge');
  if (statusEl) statusEl.textContent = `一致: #${targetSegIdx + 1} 行目（タップでここから再生）`;
  if (countEl) countEl.textContent = `${_episodeSearchCurrentPos + 1} / ${_episodeSearchMatches.length}件`;
}

