function getSentencePauseMs() {
  return Math.max(0, Math.min(2000, Number(localStorage.getItem('narou_sentence_pause_ms') || 0)));
}

function onSentencePauseRangeChange(val) {
  const ms = Math.max(0, Math.min(2000, Number(val) || 0));
  localStorage.setItem('narou_sentence_pause_ms', String(ms));
  const lbl = document.getElementById('settingSentencePauseLabel');
  if (lbl) lbl.textContent = ms === 0 ? '0ms (標準)' : `${ms}ms`;
  updatePlayerStatusUI();
  setSettingsAutoSaveBadgeState('saved');
}

function isAutoNextEpisodeEnabled() {
  return localStorage.getItem('narou_auto_next_episode') !== 'false';
}

function onToggleAutoNextEpisode(checked) {
  localStorage.setItem('narou_auto_next_episode', checked ? 'true' : 'false');
  setSettingsAutoSaveBadgeState('saved');
}

function isDialogueOnlyMode() {
  return localStorage.getItem('narou_dialogue_only_mode') === 'true';
}

function syncDialogueOnlyUI() {
  const active = isDialogueOnlyMode();
  const chk = document.getElementById('settingDialogueOnlyMode');
  if (chk) chk.checked = active;
  const quickBtn = document.getElementById('dialogueOnlyQuickBtn');
  const quickTxt = document.getElementById('dialogueOnlyQuickText');
  if (quickTxt) quickTxt.textContent = active ? 'セリフのみ:ON' : 'セリフのみ:OFF';
  if (quickBtn) quickBtn.classList.toggle('active-pill', active);
}

function onToggleDialogueOnlySetting(checked) {
  localStorage.setItem('narou_dialogue_only_mode', checked ? 'true' : 'false');
  syncDialogueOnlyUI();
  setSettingsAutoSaveBadgeState('saved');
  showToast(checked ? '💬 セリフのみ朗読モードをONにしました（地の文を自動スキップ）' : '📖 通常朗読モード（地の文＋セリフ）に戻しました', 'info');
}

function toggleDialogueOnlyQuick() {
  onToggleDialogueOnlySetting(!isDialogueOnlyMode());
}

function exportAllAppDataBackup() {
  try {
    const backup = {
      version: '1.4.0',
      exportedAt: new Date().toISOString(),
      localStorageData: {}
    };
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && (k.startsWith('narou_') || k.startsWith('novel_'))) {
        backup.localStorageData[k] = localStorage.getItem(k);
      }
    }
    const jsonStr = JSON.stringify(backup, null, 2);
    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `novel_ai_reader_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('💾 設定・しおり・読み辞書・配役データのバックアップを保存しました', 'success');
  } catch (e) {
    showToast('バックアップ作成に失敗しました: ' + e.message, 'error');
  }
}

function triggerImportAppDataBackup() {
  document.getElementById('appBackupImportInput')?.click();
}

function handleImportAppDataBackupFile(event) {
  const file = event?.target?.files?.[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const parsed = JSON.parse(String(reader.result || '{}'));
      const data = parsed.localStorageData || parsed;
      let count = 0;
      for (const [k, v] of Object.entries(data)) {
        if (typeof v === 'string' && (k.startsWith('narou_') || k.startsWith('novel_'))) {
          localStorage.setItem(k, v);
          count++;
        }
      }
      initConvenienceFeaturesState();
      showToast(`✅ バックアップから ${count}件 の設定・辞書・しおりデータを復元しました！`, 'success');
    } catch (e) {
      showToast('バックアップファイルの読み込みに失敗しました', 'error');
    }
  };
  reader.readAsText(file);
}

function initConvenienceFeaturesState() {
  updateBookmarksCountBadge();
  syncDialogueOnlyUI();
  const pauseMs = getSentencePauseMs();
  const pauseInput = document.getElementById('settingSentencePauseMs');
  const pauseLbl = document.getElementById('settingSentencePauseLabel');
  if (pauseInput) pauseInput.value = String(pauseMs);
  if (pauseLbl) pauseLbl.textContent = pauseMs === 0 ? '0ms (標準)' : `${pauseMs}ms`;

  const autoNextChk = document.getElementById('settingAutoNextEpisode');
  if (autoNextChk) autoNextChk.checked = isAutoNextEpisodeEnabled();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initConvenienceFeaturesState);
} else {
  initConvenienceFeaturesState();
}

