function tUi(key, vars = {}) {
  const lang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const dict = APP_UI_I18N_DICT[lang] || APP_UI_I18N_DICT.en || APP_UI_I18N_DICT.ja;
  const fallbackDict = lang === 'ja' ? APP_UI_I18N_DICT.ja : (APP_UI_I18N_DICT.en || APP_UI_I18N_DICT.ja);
  let str = (dict && dict[key]) !== undefined ? dict[key] : (fallbackDict[key] || APP_UI_I18N_DICT.ja[key] || key);
  if (vars && typeof str === 'string') {
    Object.keys(vars).forEach((k) => {
      str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), String(vars[k]));
    });
  }
  return str;
}
window.tUi = tUi;

let _selectedTargetTranslationLang = 'en';
let _isAiTranslationRunning = false;
const _episodeTranslationMemoryCache = {};

/**
 * 起動端末のOS設定言語を検出して主要7ヶ国語 ('ja'|'en'|'zh'|'ko'|'es'|'fr'|'pt') に正規化する
 */
function detectDeviceMajorLanguage() {
  let rawLang = '';
  try {
    if (window.AndroidBridge && typeof window.AndroidBridge.getDeviceLanguage === 'function') {
      rawLang = String(window.AndroidBridge.getDeviceLanguage() || '').trim().toLowerCase();
    }
  } catch (e) {}
  if (!rawLang) {
    try {
      rawLang = String((navigator.languages && navigator.languages[0]) || navigator.language || 'ja').trim().toLowerCase();
    } catch (e) {
      rawLang = 'ja';
    }
  }
  const base = rawLang.split(/[-_]/)[0];
  if (SUPPORTED_MAJOR_LANGUAGES[base]) {
    return base;
  }
  return 'en';
}

function getEffectiveAppUiLanguage() {
  const savedPref = localStorage.getItem('narou_app_ui_lang') || 'auto';
  if (savedPref !== 'auto' && SUPPORTED_MAJOR_LANGUAGES[savedPref]) {
    return savedPref;
  }
  return detectDeviceMajorLanguage();
}

