function applyExtendedDomLocalization(effectiveLang, dict) {
  try {
    // 0. 静的テキストリーフノードとプレースホルダーの可逆多言語変換（動的リストコンテナ内は除外して高速化）
    document.querySelectorAll('span, button, h1, h2, h3, h4, p, label, option, a').forEach((el) => {
      if (el.children.length > 0 || el.hasAttribute('data-i18n')) return;
      if (el.closest('#segmentsContainer, #aozoraCatalogGrid, #tocEpisodeList, #novelResultsList, #downloadsNovelsList, #docPreviewContent')) return;
      const raw = (el.textContent || '').replace(/\s+/g, ' ').trim();
      if (!el.dataset.origJaText && raw && /[\u3040-\u30ff\u4e00-\u9faf]/.test(raw) && STATIC_JA_PHRASE_I18N[raw]) {
        el.dataset.origJaText = raw;
      }
      const orig = el.dataset.origJaText;
      if (!orig) return;
      if (effectiveLang === 'ja') {
        if (el.textContent !== orig) el.textContent = orig;
      } else {
        const entry = STATIC_JA_PHRASE_I18N[orig];
        if (entry) {
          const targetTxt = entry[effectiveLang] || entry.en || orig;
          if (el.textContent !== targetTxt) el.textContent = targetTxt;
        }
      }
    });

    // 1. ドキュメント読込セクション
    const docSec = document.getElementById('documentImportSection');
    if (docSec) {
      const h3Span = docSec.querySelector('h3 span');
      if (h3Span && dict.doc_import_title) h3Span.textContent = dict.doc_import_title;
      const descP = docSec.querySelector('p.text-\\[11px\\]');
      if (descP && dict.doc_import_subtitle) descP.textContent = dict.doc_import_subtitle;
      const fileBtnSpan = docSec.querySelector('button[onclick*="documentFileInput"] span');
      if (fileBtnSpan && dict.doc_file_select_btn) fileBtnSpan.textContent = dict.doc_file_select_btn;
      const startBtnSpan = docSec.querySelector('button[onclick*="importCustomDocumentAndPlay"] span');
      if (startBtnSpan && dict.doc_start_reading_btn) startBtnSpan.textContent = dict.doc_start_reading_btn;
      const clearBtn = docSec.querySelector('button[onclick*="clearCustomDocumentInput"]');
      if (clearBtn && dict.doc_clear_btn) clearBtn.textContent = dict.doc_clear_btn;
    }
    const docTitleInput = document.getElementById('docImportTitle') || document.getElementById('customDocTitleInput') || document.getElementById('docTitleInput');
    if (docTitleInput && dict.doc_title_placeholder) docTitleInput.placeholder = dict.doc_title_placeholder;
    const docTextArea = document.getElementById('docImportBody') || document.getElementById('customDocTextInput') || document.getElementById('docTextInput');
    if (docTextArea && dict.doc_text_placeholder) docTextArea.placeholder = dict.doc_text_placeholder;
    const docAuthorInput = document.getElementById('docImportAuthor');
    if (docAuthorInput) {
      docAuthorInput.placeholder = effectiveLang === 'ja' ? '著者・作成者（任意）' : (dict.cast_title ? 'Author (optional)' : 'Author');
    }

    // 2. 目次タブ (#tab-toc)
    const tocFilterInput = document.getElementById('tocEpisodeSearchInput');
    if (tocFilterInput && dict.toc_search_placeholder) tocFilterInput.placeholder = dict.toc_search_placeholder;
    const tocSortLbl = document.getElementById('tocSortOrderLabel') || document.getElementById('tocSortText');
    if (tocSortLbl) {
      const isDesc = typeof state !== 'undefined' && (state.tocSortDesc || state.tocSortAscending === false);
      tocSortLbl.textContent = isDesc ? dict.toc_sort_desc : dict.toc_sort_asc;
    }
    const tocEmptyMsg = document.querySelector('#tocEmptyState p');
    if (tocEmptyMsg && dict.toc_empty_msg) tocEmptyMsg.textContent = dict.toc_empty_msg;
    const tocSearchBtn = document.querySelector('#tocEmptyState button[onclick*="switchTab(\'search\')"] span');
    if (tocSearchBtn && dict.tab_search) tocSearchBtn.textContent = dict.tab_search;

    // 3. 朗読タブ (#tab-player) の前後話ボタン・自動追従ラベル
    const prevEpBtnSpan = document.querySelector('#prevEpisodeBtn span');
    if (prevEpBtnSpan && dict.toc_prev_ep) prevEpBtnSpan.textContent = dict.toc_prev_ep;
    const nextEpBtnSpan = document.querySelector('#nextEpisodeBtn span');
    if (nextEpBtnSpan && dict.toc_next_ep) nextEpBtnSpan.textContent = dict.toc_next_ep;
    const autoScrollLbl = document.getElementById('autoScrollBtnText') || document.querySelector('label[for="autoScrollToggle"] span, #autoScrollToggle + span');
    if (autoScrollLbl && dict.player_auto_scroll) autoScrollLbl.textContent = dict.player_auto_scroll;

    // 4. 配役タブ (#tab-cast)
    const castTab = document.getElementById('tab-cast');
    if (castTab) {
      const castTitle = castTab.querySelector('h2 span');
      if (castTitle && dict.cast_title) castTitle.textContent = dict.cast_title;
      const reanalyzeSpan = document.getElementById('castReanalyzeBtnText') || castTab.querySelector('button[onclick*="reanalyzeCurrentEpisode"] span');
      if (reanalyzeSpan && dict.cast_ai_reset_btn) reanalyzeSpan.textContent = dict.cast_ai_reset_btn;
      const saveCastSpan = castTab.querySelector('button[onclick*="saveAndApplyCast"] span');
      if (saveCastSpan && dict.cast_apply_btn) saveCastSpan.textContent = dict.cast_apply_btn;
    }

    // 5. 本棚タブ (#tab-downloads)
    const dlTab = document.getElementById('tab-downloads');
    if (dlTab) {
      const dlTitle = dlTab.querySelector('h2 span, h3 span');
      if (dlTitle && dict.dl_title) dlTitle.textContent = dict.dl_title;
      const dlFilterInput = document.getElementById('downloadsFilterInput');
      if (dlFilterInput) {
        dlFilterInput.placeholder = effectiveLang === 'ja' ? 'タイトル・作者・Nコードで絞り込み...' : (dict.toc_search_placeholder || 'Filter by title, author, ID...');
      }
      const refreshSpan = dlTab.querySelector('button[onclick*="loadDownloadsData"] span');
      if (refreshSpan && dict.dl_refresh_btn) refreshSpan.textContent = dict.dl_refresh_btn;
      const batchVoiceSpan = document.getElementById('downloadsUncachedAudioBatchBtnLabel') || document.getElementById('batchAllNovelsVoiceBtnLabel');
      if (batchVoiceSpan && dict.dl_batch_voice_btn && !batchVoiceSpan.dataset.busy) {
        batchVoiceSpan.textContent = dict.dl_batch_voice_btn;
      }
      const clearVoiceSpan = dlTab.querySelector('button[onclick*="confirmCleanAudioCache"] span, button[onclick*="clearAllVoiceCache"] span');
      if (clearVoiceSpan && dict.dl_clear_voice_btn) clearVoiceSpan.textContent = dict.dl_clear_voice_btn;
      const clearAllSpan = dlTab.querySelector('button[onclick*="confirmDeleteAllDownloads"] span, button[onclick*="clearAllAppStorage"] span');
      if (clearAllSpan && dict.dl_clear_all_btn) clearAllSpan.textContent = dict.dl_clear_all_btn;
    }

    // 6. カーモード (#carModeOverlay)
    const carOverlay = document.getElementById('carModeOverlay');
    if (carOverlay) {
      const exitSpan = carOverlay.querySelector('button[onclick*="toggleCarMode(false)"] span, button[onclick*="exitCarMode"] span');
      if (exitSpan && dict.carmode_exit_btn) exitSpan.textContent = dict.carmode_exit_btn;
      const prevEpCar = carOverlay.querySelector('button[onclick*="navigateEpisode(-1)"] span, button[onclick*="playPreviousEpisode"] span');
      if (prevEpCar && dict.carmode_prev_ep) prevEpCar.textContent = dict.carmode_prev_ep;
      const nextEpCar = carOverlay.querySelector('button[onclick*="navigateEpisode(1)"] span, button[onclick*="playNextEpisode"] span');
      if (nextEpCar && dict.carmode_next_ep) nextEpCar.textContent = dict.carmode_next_ep;
      const prevSegCar = carOverlay.querySelector('button[onclick*="jumpSegment(-1)"] span, button[onclick*="skipSegment(-1)"] span');
      if (prevSegCar && dict.carmode_prev_line) prevSegCar.textContent = dict.carmode_prev_line;
      const nextSegCar = carOverlay.querySelector('button[onclick*="jumpSegment(1)"] span, button[onclick*="skipSegment(1)"] span');
      if (nextSegCar && dict.carmode_next_line) nextSegCar.textContent = dict.carmode_next_line;
    }

    // 7. 動的ビューの再描画（既に表示されている場合）
    if (typeof state !== 'undefined') {
      if (!state.currentSegments || state.currentSegments.length === 0) {
        if (typeof renderPlayerEmptyState === 'function') renderPlayerEmptyState();
      } else {
        if (typeof renderSegments === 'function') renderSegments();
        if (typeof updatePlayerAiStatusBadge === 'function') updatePlayerAiStatusBadge();
        if (typeof updatePlayerAudioCacheStatusBar === 'function') updatePlayerAudioCacheStatusBar();
      }
      if (typeof updatePlayerStatusUI === 'function') updatePlayerStatusUI();
      if (typeof renderCastEditor === 'function') renderCastEditor();
      if (typeof updateCarModeUI === 'function') updateCarModeUI();
      if (typeof updateHeroResumeCard === 'function') updateHeroResumeCard();
      if (typeof syncTypographyModalUI === 'function') syncTypographyModalUI();
      if (typeof updateStorageSummaryUI === 'function' && state._lastStorageSummary) {
        updateStorageSummaryUI(state._lastStorageSummary);
      }
      if (typeof renderDownloadedNovels === 'function' && Array.isArray(loadedDownloadedNovelsList) && loadedDownloadedNovelsList.length > 0) {
        renderDownloadedNovels(loadedDownloadedNovelsList);
      }
    }
  } catch (err) {
    console.warn('[i18n] Extended DOM localization error:', err);
  }
}

let _lastAppliedEffectiveUiLang = null;

function applyAppUiLanguage(prefValue) {
  const pref = prefValue || localStorage.getItem('narou_app_ui_lang') || 'auto';
  localStorage.setItem('narou_app_ui_lang', pref);

  const detectedLang = detectDeviceMajorLanguage();
  const effectiveLang = (pref === 'auto' || !SUPPORTED_MAJOR_LANGUAGES[pref]) ? detectedLang : pref;
  const langChanged = _lastAppliedEffectiveUiLang !== null && _lastAppliedEffectiveUiLang !== effectiveLang;
  _lastAppliedEffectiveUiLang = effectiveLang;
  if (langChanged && typeof pauseAudio === 'function') {
    pauseAudio();
  }
  const langMeta = SUPPORTED_MAJOR_LANGUAGES[effectiveLang] || SUPPORTED_MAJOR_LANGUAGES.ja;
  const dict = APP_UI_I18N_DICT[effectiveLang] || APP_UI_I18N_DICT.en || APP_UI_I18N_DICT.ja;

  try {
    document.documentElement.lang = effectiveLang;
    document.documentElement.setAttribute('dir', effectiveLang === 'ar' ? 'rtl' : 'ltr');
  } catch (e) {}

  // data-i18n 属性を持つ全要素を更新
  document.querySelectorAll('[data-i18n]').forEach((el) => {
    const key = el.getAttribute('data-i18n');
    if (key && dict[key]) {
      el.textContent = dict[key];
    }
  });

  // 主要ナビタブとヘッダーのラベル更新
  const headerTitle = document.querySelector('header h1');
  if (headerTitle && dict.app_title) headerTitle.textContent = dict.app_title;

  const tabMap = [
    { id: 'tabBtn-search', key: 'tab_search' },
    { id: 'tabBtn-toc', key: 'tab_toc' },
    { id: 'tabBtn-player', key: 'tab_player' },
    { id: 'tabBtn-cast', key: 'tab_cast' },
    { id: 'tabBtn-downloads', key: 'tab_downloads' },
    { id: 'tabBtn-carmode', key: 'tab_carmode' }
  ];
  tabMap.forEach(({ id, key }) => {
    const btn = document.getElementById(id);
    if (btn && dict[key]) {
      const span = btn.querySelector('.nav-tab-label, span[data-i18n], span:last-of-type');
      if (span) span.textContent = dict[key];
      btn.setAttribute('aria-label', dict[key]);
      btn.setAttribute('title', dict[key]);
    }
  });

  // ヘッダーの言語バッジ更新 (headerLangSwitchLabel と headerLangBadgeText の両方を同期)
  const headerLangLbl = document.getElementById('headerLangSwitchLabel');
  if (headerLangLbl) {
    headerLangLbl.textContent = `${langMeta.flag} ${effectiveLang.toUpperCase()}`;
  }
  const headerLangBadge = document.getElementById('headerLangBadgeText');
  if (headerLangBadge) {
    headerLangBadge.textContent = `${langMeta.flag} ${effectiveLang.toUpperCase()}`;
  }

  // 設定画面のセレクトボックス同期
  const settingSelect = document.getElementById('settingAppUiLanguage');
  if (settingSelect) {
    settingSelect.value = pref;
  }

  const detectedBadge = document.getElementById('modalDetectedDeviceLangBadge');
  if (detectedBadge) {
    const detMeta = SUPPORTED_MAJOR_LANGUAGES[detectedLang] || SUPPORTED_MAJOR_LANGUAGES.ja;
    const dispName = detMeta.uiName || detMeta.nativeName;
    detectedBadge.textContent = `${detMeta.flag} ${dispName} (${detectedLang})`;
  }

  // モーダル内のUI言語選択ボタンのハイライト更新 (.is-selected クラスで4テーマ対応)
  ['auto', 'ja', 'en', 'zh', 'ko', 'es', 'fr', 'pt', 'de', 'th', 'ar'].forEach((code) => {
    const btn = document.getElementById(`uiLangBtn-${code}`);
    if (!btn) return;
    btn.classList.toggle('is-selected', code === pref);
  });

  const jaActiveBadge = document.getElementById('uiLangCurrentActiveBadge-ja');
  if (jaActiveBadge) {
    jaActiveBadge.classList.toggle('hidden', effectiveLang !== 'ja');
  }

  // 選択言語に応じてデフォルトの翻訳先言語（日本語UI時は 'ja' = 現代語超訳モード、外国語UI時はその言語）をセット
  if (SUPPORTED_MAJOR_LANGUAGES[effectiveLang]) {
    _selectedTargetTranslationLang = effectiveLang;
  }

  // 拡張DOMローカライズを適用
  applyExtendedDomLocalization(effectiveLang, dict);

  // 青空文庫の国別優先作家ボタン・現代語超訳/自動翻訳バナー・名作カタログを選択言語で再描画
  try {
    if (typeof renderAozoraAuthorButtons === 'function') {
      renderAozoraAuthorButtons();
    }
    if (typeof updateAozoraReadingModeBanner === 'function') {
      updateAozoraReadingModeBanner();
    }
    if (typeof renderAozoraCatalog === 'function') {
      renderAozoraCatalog(typeof currentAozoraAuthorFilter !== 'undefined' ? currentAozoraAuthorFilter : 'all');
    }
    // 検索結果が表示中なら選択言語で再描画
    const resultsListEl = document.getElementById('novelResultsList');
    if (resultsListEl && !resultsListEl.classList.contains('hidden') && window.__lastSearchResultsMap) {
      const cachedNovels = Object.values(window.__lastSearchResultsMap);
      if (cachedNovels.length > 0 && typeof renderSearchResults === 'function') {
        renderSearchResults({ novels: cachedNovels, total_count: cachedNovels.length });
      }
    }
    // 目次 (TOC) が読み込み済みなら選択言語で再描画（タブは切り替えず、全話キャストスキャンも再実行しない）
    if (typeof state !== 'undefined' && state.currentNovel && typeof displayNovelTOC === 'function') {
      displayNovelTOC(state.currentNovel, { keepCurrentTab: true, skipFullCastScan: true });
    }
    // 詳細・試し読みモーダルが開いていれば選択言語で再描画
    const previewModal = document.getElementById('webPreviewModal');
    if (previewModal && !previewModal.classList.contains('hidden') && typeof modalCurrentNcode === 'string' && modalCurrentNcode) {
      openWebPreviewModal(modalCurrentNcode);
    }
    // 全文プレビューモーダルが開いていれば選択言語で再描画
    const docModal = document.getElementById('documentFullPreviewModal');
    if (docModal && !docModal.classList.contains('hidden') && typeof currentPreviewNovelData !== 'undefined' && currentPreviewNovelData) {
      openDocumentFullPreview(currentPreviewNovelData.ncode || currentPreviewNovelData.novel_id);
    }
    // すでに朗読エピソードが読み込まれており、かつ言語が切り替わった場合は自動翻訳
    if (langChanged && typeof state !== 'undefined' && Array.isArray(state.currentSegments) && state.currentSegments.length > 0) {
      if (effectiveLang !== 'ja' && typeof maybeAutoTranslateCurrentEpisode === 'function') {
        maybeAutoTranslateCurrentEpisode({ forceTargetLang: effectiveLang });
      } else if (effectiveLang === 'ja') {
        if (typeof isAozoraModernSuperTranslateEnabled === 'function' && isAozoraModernSuperTranslateEnabled() && typeof maybeAutoTranslateCurrentEpisode === 'function') {
          maybeAutoTranslateCurrentEpisode({ forceTargetLang: 'ja' });
        } else {
          state.currentTranslatedLang = null;
          if (typeof renderSegments === 'function') renderSegments();
          if (typeof updateMiniPlayer === 'function') updateMiniPlayer();
          if (typeof updateCarModeUI === 'function') updateCarModeUI();
          if (typeof updatePlayerStatusUI === 'function') updatePlayerStatusUI();
        }
      }
    }
  } catch (e) {
    console.warn('[i18n] Failed to refresh Aozora localized UI:', e);
  }

  // モーダルが開いている場合はゲート表示も即座に選択言語へ更新
  try {
    if (typeof refreshAiTranslationModalGateUI === 'function') {
      refreshAiTranslationModalGateUI();
    }
  } catch (e) {}
  if (typeof refreshSwitchStateIndicators === 'function') refreshSwitchStateIndicators();
}

function onChangeAppUiLanguage(newPref) {
  if (typeof pauseAudio === 'function') {
    pauseAudio();
  }
  applyAppUiLanguage(newPref);
  const effectiveLang = getEffectiveAppUiLanguage();
  const meta = SUPPORTED_MAJOR_LANGUAGES[effectiveLang] || SUPPORTED_MAJOR_LANGUAGES.ja;
  if (typeof showToast === 'function') {
    const modeNote = tUi('toast_lang_switched', {
      flag: meta.flag,
      name: meta.uiName || meta.nativeName
    });
    showToast(modeNote, 'success');
  }
}

/**
 * 翻訳・多言語読み上げ・現代語超訳に使用可能なAIエンジン (クラウドAPI / ローカルLLM / オンデバイスLLM) を取得
 */
function getAvailableTranslationCloudKey() {
  const stored = typeof getSettingsFromStorage === 'function' ? getSettingsFromStorage() : {};
  const geminiKey = (document.getElementById('settingGeminiKey')?.value || stored.gemini_api_key || localStorage.getItem('narou_gemini_key') || '').trim();
  const openaiKey = (document.getElementById('settingOpenaiKey')?.value || stored.openai_api_key || localStorage.getItem('narou_openai_key') || '').trim();
  const claudeKey = (document.getElementById('settingClaudeKey')?.value || stored.claude_api_key || localStorage.getItem('narou_claude_key') || '').trim();

  const preferredProvider = document.getElementById('settingLlmProvider')?.value
    || document.getElementById('settingAiProvider')?.value
    || stored.llm_provider
    || localStorage.getItem('narou_ai_provider')
    || 'gemini';

  const hasPremium = typeof isPremiumPurchased === 'function' ? isPremiumPurchased() : false;

  // 明示的にローカルサーバーまたはオンデバイスLLMが選択されている場合はそれを優先
  if (preferredProvider === 'local_llm') {
    const localModel = sanitizeCommercialLocalLlmModel(document.getElementById('settingLocalLlmModel')?.value || stored.local_llm_model || localStorage.getItem('narou_local_llm_model') || 'phi4-mini');
    return { hasKey: true, provider: 'local_llm', providerLabel: tUi('gate_local_llm_label', { model: localModel }), apiKey: 'local', isOnDevice: true };
  }
  if (preferredProvider === 'embedded_llm' || preferredProvider === 'rules') {
    const installedModel = normalizeInstalledOnDeviceProfileId(localStorage.getItem('narou_installed_local_llm'));
    const label = installedModel === 'builtin-fast-lite'
      ? tUi('gate_ondevice_fast_label')
      : tUi('gate_ondevice_multi_label');
    return { hasKey: true, provider: 'ondevice_llm', providerLabel: label, apiKey: 'ondevice', isOnDevice: true };
  }

  // クラウドAPIキーが設定されており、かつプレミアム購入済みの場合はクラウドAIを使用
  if (hasPremium) {
    if (preferredProvider === 'gemini' && geminiKey.length >= 12) {
      return { hasKey: true, provider: 'gemini', providerLabel: 'Google Gemini', apiKey: geminiKey, isOnDevice: false };
    }
    if (preferredProvider === 'openai' && openaiKey.length >= 12) {
      return { hasKey: true, provider: 'openai', providerLabel: 'OpenAI GPT', apiKey: openaiKey, isOnDevice: false };
    }
    if (preferredProvider === 'claude' && claudeKey.length >= 12) {
      return { hasKey: true, provider: 'claude', providerLabel: 'Anthropic Claude', apiKey: claudeKey, isOnDevice: false };
    }
    if (geminiKey.length >= 12) {
      return { hasKey: true, provider: 'gemini', providerLabel: 'Google Gemini', apiKey: geminiKey, isOnDevice: false };
    }
    if (openaiKey.length >= 12) {
      return { hasKey: true, provider: 'openai', providerLabel: 'OpenAI GPT', apiKey: openaiKey, isOnDevice: false };
    }
    if (claudeKey.length >= 12) {
      return { hasKey: true, provider: 'claude', providerLabel: 'Anthropic Claude', apiKey: claudeKey, isOnDevice: false };
    }
  }

  // クラウドAPIキー未設定時、または非プレミアム時はオンデバイスAIで多言語翻訳・現代語超訳を常時利用可能にする
  const installedOnDevice = normalizeInstalledOnDeviceProfileId(localStorage.getItem('narou_installed_local_llm'));
  const fallbackLabel = installedOnDevice === 'builtin-fast-lite'
    ? tUi('gate_ondevice_fast_label')
    : tUi('gate_ondevice_multi_label');
  return { hasKey: true, provider: 'ondevice_llm', providerLabel: fallbackLabel, apiKey: 'ondevice', isOnDevice: true };
}

/**
 * AI翻訳・多言語読み上げ・現代語超訳機能の利用可否を判定する（オンデバイスLLM稼働時はAPIキー・課金不要で利用可能）
 */
function checkAiTranslationGateStatus() {
  const keyInfo = getAvailableTranslationCloudKey();
  const hasPremium = typeof isPremiumPurchased === 'function' ? isPremiumPurchased() : false;
  const isOnDevice = !!keyInfo.isOnDevice;
  return {
    hasApiKey: keyInfo.hasKey,
    keyProvider: keyInfo.provider,
    keyProviderLabel: keyInfo.providerLabel,
    apiKey: keyInfo.apiKey,
    isOnDevice,
    hasPremium,
    allowed: !!(isOnDevice || (keyInfo.hasKey && hasPremium))
  };
}

function refreshAiTranslationModalGateUI() {
  const gate = checkAiTranslationGateStatus();
  const effectiveUiLang = getEffectiveAppUiLanguage();
  const dict = APP_UI_I18N_DICT[effectiveUiLang] || APP_UI_I18N_DICT.en || APP_UI_I18N_DICT.ja;

  const iconKey = document.getElementById('gateIconApiKey');
  const txtKey = document.getElementById('gateStatusApiKeyText');
  if (iconKey && txtKey) {
    if (gate.hasApiKey) {
      iconKey.className = 'ph-fill ph-check-circle text-emerald-500 text-base shrink-0';
      txtKey.textContent = gate.isOnDevice
        ? tUi('gate_apikey_active_ondevice', { provider: gate.keyProviderLabel })
        : tUi('gate_apikey_active_cloud', { provider: gate.keyProviderLabel });
      txtKey.className = 'trans-status-emerald text-[10px] text-emerald-300 truncate font-bold';
    } else {
      iconKey.className = 'ph-fill ph-x-circle text-rose-500 text-base shrink-0';
      txtKey.textContent = tUi('gate_apikey_missing');
      txtKey.className = 'trans-status-rose text-[10px] text-rose-300 truncate font-semibold';
    }
  }

  const iconPrem = document.getElementById('gateIconPremium');
  const txtPrem = document.getElementById('gateStatusPremiumText');
  if (iconPrem && txtPrem) {
    if (gate.hasPremium) {
      iconPrem.className = 'ph-fill ph-check-circle text-emerald-500 text-base shrink-0';
      txtPrem.textContent = tUi('gate_premium_active');
      txtPrem.className = 'trans-status-emerald text-[10px] text-emerald-300 truncate font-bold';
    } else if (gate.isOnDevice) {
      iconPrem.className = 'ph-fill ph-check-circle text-emerald-500 text-base shrink-0';
      txtPrem.textContent = tUi('gate_premium_ondevice_free');
      txtPrem.className = 'trans-status-emerald text-[10px] text-emerald-300 truncate font-bold';
    } else {
      iconPrem.className = 'ph-fill ph-x-circle text-rose-500 text-base shrink-0';
      txtPrem.textContent = tUi('gate_premium_missing');
      txtPrem.className = 'trans-status-rose text-[10px] text-rose-300 truncate font-semibold';
    }
  }

  const badge = document.getElementById('aiTranslationGateOverallBadge');
  const execBtn = document.getElementById('executeAiTranslateBtn');
  if (badge) {
    if (gate.allowed) {
      badge.textContent = gate.isOnDevice ? tUi('gate_overall_ondevice') : tUi('gate_overall_cloud');
      badge.className = 'trans-badge-emerald shrink-0 whitespace-nowrap px-2.5 py-0.5 rounded-full text-[10px] font-extrabold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40';
    } else {
      badge.textContent = tUi('gate_overall_locked');
      badge.className = 'trans-badge-rose shrink-0 whitespace-nowrap px-2.5 py-0.5 rounded-full text-[10px] font-extrabold bg-rose-500/20 text-rose-300 border border-rose-500/40';
    }
  }

  if (execBtn && !_isAiTranslationRunning) {
    if (gate.allowed) {
      execBtn.className = 'trans-primary-exec-btn flex-1 py-2.5 px-4 rounded-xl bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold text-xs shadow-lg flex items-center justify-center space-x-1.5 transition active:scale-95';
    } else {
      execBtn.className = 'trans-locked-exec-btn flex-1 py-2.5 px-4 rounded-xl bg-slate-800 border border-rose-500/50 text-slate-200 font-bold text-xs flex items-center justify-center space-x-1.5 transition';
    }
  }

  const currBadge = document.getElementById('currentEpisodeTransBadge');
  const restoreBtn = document.getElementById('restoreOriginalLangBtn');
  const quickBadge = document.getElementById('aiTranslateQuickBadge');
  const origJaBtn = document.getElementById('transTargetBtn-orig-ja');
  const origJaBadge = document.getElementById('origJaStatusBadge');
  const isOriginal = !state.currentTranslatedLang;

  if (origJaBtn) {
    origJaBtn.classList.toggle('is-selected', isOriginal);
  }
  if (origJaBadge) {
    if (isOriginal) {
      origJaBadge.textContent = tUi('orig_status_active') || '原文表示中';
      origJaBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 shrink-0';
    } else {
      origJaBadge.textContent = tUi('orig_status_restore') || 'タップで復元';
      origJaBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded bg-amber-500/20 text-amber-300 border border-amber-500/40 shrink-0 animate-pulse';
    }
  }

  if (state.currentTranslatedLang && SUPPORTED_MAJOR_LANGUAGES[state.currentTranslatedLang]) {
    const m = SUPPORTED_MAJOR_LANGUAGES[state.currentTranslatedLang];
    if (currBadge) {
      currBadge.textContent = state.currentTranslatedLang === 'ja'
        ? tUi('curr_badge_modern_ja')
        : tUi('curr_badge_translating', { flag: m.flag, name: m.uiName || m.nativeName });
      currBadge.className = 'trans-badge-indigo shrink-0 whitespace-nowrap px-2.5 py-0.5 rounded-md bg-indigo-500/20 border border-indigo-500/40 text-indigo-300 text-[10px] font-mono font-bold';
    }
    if (restoreBtn) restoreBtn.classList.remove('hidden');
    if (quickBadge) {
      quickBadge.textContent = state.currentTranslatedLang === 'ja'
        ? tUi('quick_badge_modern_ja')
        : tUi('quick_badge_translating', { flag: m.flag, code: m.code.toUpperCase() });
    }
  } else {
    if (currBadge) {
      currBadge.textContent = tUi('trans_original_badge');
      currBadge.className = 'shrink-0 whitespace-nowrap px-2.5 py-0.5 rounded-md bg-slate-800 border border-slate-700 text-slate-200 text-[10px] font-mono font-bold';
    }
    if (restoreBtn) restoreBtn.classList.add('hidden');
    if (quickBadge) {
      quickBadge.textContent = dict.quick_ai_translate || 'AI Translate';
    }
  }

  selectTargetTranslationLang(_selectedTargetTranslationLang, true);
  if (typeof refreshSwitchStateIndicators === 'function') refreshSwitchStateIndicators();
}

function selectTargetTranslationLang(langCode, silent = false) {
  if (!SUPPORTED_MAJOR_LANGUAGES[langCode]) return;
  if (!silent && typeof pauseAudio === 'function') {
    pauseAudio();
  }
  _selectedTargetTranslationLang = langCode;
  ['en', 'zh', 'ko', 'es', 'fr', 'pt', 'de', 'th', 'ar', 'ja'].forEach((code) => {
    const btn = document.getElementById(`transTargetBtn-${code}`);
    if (!btn) return;
    btn.classList.toggle('is-selected', code === langCode);
  });
  const m = SUPPORTED_MAJOR_LANGUAGES[langCode];
  const lbl = document.getElementById('executeAiTranslateBtnLabel');
  if (lbl && !_isAiTranslationRunning) {
    lbl.textContent = langCode === 'ja'
      ? tUi('exec_btn_modern_ja')
      : tUi('exec_btn_translate_to', { flag: m.flag, nativeName: m.uiName || m.nativeName, name: m.name });
  }
  if (!silent && typeof vibrateFeedback === 'function') {
    vibrateFeedback(8);
  }
}

function onToggleBilingualDisplay(checked) {
  state.bilingualDisplay = !!checked;
  localStorage.setItem('narou_ai_trans_bilingual', checked ? 'true' : 'false');
  if (typeof refreshSwitchStateIndicators === 'function') refreshSwitchStateIndicators();
  if (typeof renderSegments === 'function') {
    renderSegments();
  }
}

function switchTransModalTab(tabKey) {
  const isUi = (tabKey === 'ui_lang' || tabKey === 'ui');
  const btnUi = document.getElementById('transModalTabBtn-ui');
  const btnNovel = document.getElementById('transModalTabBtn-novel');
  const paneUi = document.getElementById('transModalPane-ui');
  const paneNovel = document.getElementById('transModalPane-novel');

  if (btnUi) btnUi.classList.toggle('is-active', isUi);
  if (btnNovel) btnNovel.classList.toggle('is-active', !isUi);
  if (paneUi) paneUi.classList.toggle('hidden', !isUi);
  if (paneNovel) paneNovel.classList.toggle('hidden', isUi);
}

function openAiTranslationModal(initialTab = 'novel') {
  const modal = document.getElementById('aiTranslationModal');
  if (!modal) return;
  modal.classList.remove('hidden');

  const targetTab = (initialTab === 'ui_lang' || initialTab === 'ui') ? 'ui' : 'novel';
  switchTransModalTab(targetTab);

  const biToggle = document.getElementById('aiTransBilingualToggle');
  if (biToggle) {
    biToggle.checked = state.bilingualDisplay !== false;
  }
  const autoToggle = document.getElementById('aiTransAutoEpisodeToggle');
  if (autoToggle && typeof isAutoEpisodeTranslateEnabled === 'function') {
    autoToggle.checked = isAutoEpisodeTranslateEnabled();
  }
  const pref = localStorage.getItem('narou_app_ui_lang') || 'auto';
  ['auto', 'ja', 'en', 'zh', 'ko', 'es', 'fr', 'pt', 'de', 'th', 'ar'].forEach((code) => {
    const btn = document.getElementById(`uiLangBtn-${code}`);
    if (btn) btn.classList.toggle('is-selected', code === pref);
  });
  const effectiveLang = getEffectiveAppUiLanguage();
  const jaActiveBadge = document.getElementById('uiLangCurrentActiveBadge-ja');
  if (jaActiveBadge) {
    jaActiveBadge.classList.toggle('hidden', effectiveLang !== 'ja');
  }
  const detectedLang = detectDeviceMajorLanguage();
  const detectedBadge = document.getElementById('modalDetectedDeviceLangBadge');
  if (detectedBadge) {
    const detMeta = SUPPORTED_MAJOR_LANGUAGES[detectedLang] || SUPPORTED_MAJOR_LANGUAGES.ja;
    const dispName = detMeta.uiName || detMeta.nativeName;
    detectedBadge.textContent = `${detMeta.flag} ${dispName} (${detectedLang})`;
  }
  refreshAiTranslationModalGateUI();
}

function closeAiTranslationModal() {
  const modal = document.getElementById('aiTranslationModal');
  if (modal) modal.classList.add('hidden');
}

function restoreOriginalEpisodeLanguage() {
  _aiTranslationRunId++;
  _isAiTranslationRunning = false;
  if (typeof pauseAudio === 'function') {
    pauseAudio();
  }
  state.currentTranslatedLang = null;
  if (typeof renderSegments === 'function') {
    renderSegments();
  }
  if (typeof updateMiniPlayer === 'function') updateMiniPlayer();
  if (typeof updateCarModeUI === 'function') updateCarModeUI();
  if (typeof updatePlayerStatusUI === 'function') updatePlayerStatusUI();
  refreshAiTranslationModalGateUI();
  closeAiTranslationModal();
  if (typeof showToast === 'function') {
    showToast(tUi('toast_restored_original'), 'info');
  }
}

