/**
 * 青空文庫などの古風な日本語文を、現代人が耳で聴いて直感的にわかる現代日本語へ超訳する（オフライン対応・一文も省略しない）
 */
function translateSegmentToModernJapaneseOffline(rawText, speaker) {
  let t = String(rawText || '').trim();
  if (!t) return t;

  // ルビタグや青空文庫注記が残っている場合は先に綺麗にする（文章の誤削除を防止）
  t = resolveAozoraRubyAndNotesJs(t).displayText;

  for (const [pattern, replacement] of MODERN_JAPANESE_SUPER_TRANSLATION_RULES) {
    t = t.replace(pattern, replacement);
  }

  // 文末の古風な表現をさらに耳馴染みのよい現代小説調に整える
  t = t.replace(/であつた/g, 'であった')
       .replace(/あつた/g, 'あった')
       .replace(/言つた/g, '言った')
       .replace(/思つた/g, '思った')
       .replace(/行つた/g, '行った')
       .replace(/なつた/g, 'なった')
       .replace(/立つた/g, '立った')
       .replace(/持つた/g, '持った')
       .replace(/知つた/g, '知った')
       .replace(/笑つた/g, '笑った')
       .replace(/云つた/g, '言った')
       .replace(/やう/g, 'よう')
       .replace(/さう/g, 'そう');

  return t;
}

