function katakanaToHiraganaJs(str) {
  return String(str || '').replace(/[\u30a1-\u30f6]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0x60));
}

function japaneseToRomajiJs(str) {
  const hira = katakanaToHiraganaJs(str);
  let out = '';
  let i = 0;
  while (i < hira.length) {
    if (hira[i] === 'っ' && i + 1 < hira.length) {
      const nextPair = hira.slice(i + 1, i + 3);
      const nextOne = hira[i + 1];
      const rom = ON_DEVICE_KANA_TO_ROMAJI[nextPair] || ON_DEVICE_KANA_TO_ROMAJI[nextOne] || '';
      if (rom) out += rom[0];
      i++;
      continue;
    }
    const pair = hira.slice(i, i + 2);
    if (ON_DEVICE_KANA_TO_ROMAJI[pair] !== undefined) {
      out += ON_DEVICE_KANA_TO_ROMAJI[pair];
      i += 2;
      continue;
    }
    const one = hira[i];
    if (ON_DEVICE_KANA_TO_ROMAJI[one] !== undefined) {
      out += ON_DEVICE_KANA_TO_ROMAJI[one];
      i++;
      continue;
    }
    out += one;
    i++;
  }
  return out;
}

