function translateSpeakerOnDevice(speaker, targetLang) {
  const s = String(speaker || '').trim();
  if (!s) return '';
  if (ON_DEVICE_SPEAKER_DICT[s] && ON_DEVICE_SPEAKER_DICT[s][targetLang]) {
    return ON_DEVICE_SPEAKER_DICT[s][targetLang];
  }
  if (targetLang === 'ja' || targetLang === 'zh') return s;
  const rom = japaneseToRomajiJs(s);
  if (targetLang === 'ko') {
    let koStr = rom.toLowerCase();
    for (const [k, v] of ON_DEVICE_ROMAJI_TO_HANGUL) {
      koStr = koStr.split(k).join(v);
    }
    return koStr || s;
  }
  return rom ? rom.charAt(0).toUpperCase() + rom.slice(1) : s;
}

function translateSegmentOnDeviceOffline(rawText, speaker, targetLang) {
  let t = String(rawText || '').trim();
  if (!t) return t;

  // 日本語 ('ja') が選択された場合は「現代語超訳モード」として明治・大正文語体をわかりやすい現代日本語に変換
  if (targetLang === 'ja') {
    return translateSegmentToModernJapaneseOffline(t, speaker);
  }

  // 先に古風な表記を現代日本語に正規化してから多言語辞書を適用すると青空文庫の翻訳精度が大幅に向上
  t = translateSegmentToModernJapaneseOffline(t, speaker);

  // 引用符の正規化
  t = t.replace(/^[「『]/, '"').replace(/[」』]$/, '"')
       .replace(/^《/, '[').replace(/》$/, ']')
       .replace(/^【/, '[').replace(/】$/, ']');

  // 既知キャラ名を先に対象言語表記へ置換
  for (const [jpName, map] of Object.entries(ON_DEVICE_SPEAKER_DICT)) {
    if (jpName.length >= 2 && map[targetLang] && t.includes(jpName)) {
      t = t.split(jpName).join(map[targetLang] + (targetLang === 'zh' || targetLang === 'ko' ? '' : ' '));
    }
  }

  // 文節・表現辞書の適用
  for (const entry of ON_DEVICE_NOVEL_LEXICON) {
    const rep = entry[targetLang];
    if (rep !== undefined) {
      t = t.replace(entry.re, rep);
    }
  }

  // 助詞・句読点の整理（未知の漢字・語彙は絶対に消去せずそのまま保持し、単語・文の欠落を防止）
  if (targetLang === 'en' || targetLang === 'es' || targetLang === 'fr' || targetLang === 'pt') {
    t = t.replace(/、/g, ', ').replace(/。/g, '. ').replace(/！/g, '! ').replace(/？/g, '? ').replace(/……|…/g, '... ');
    if (/[\u3040-\u30ff]/.test(t)) {
      t = t.replace(/[\u3040-\u30ffー]+/g, m => ' ' + japaneseToRomajiJs(m) + ' ');
    }
    t = t.replace(/\s+/g, ' ').replace(/\s+([.,!?])/g, '$1').trim();
  } else if (targetLang === 'ko') {
    t = t.replace(/、/g, ', ').replace(/。/g, '. ').replace(/！/g, '! ').replace(/？/g, '? ');
    if (/[\u3040-\u30ff]/.test(t)) {
      t = t.replace(/[\u3040-\u30ffー]+/g, m => {
        let r = japaneseToRomajiJs(m).toLowerCase();
        for (const [k, v] of ON_DEVICE_ROMAJI_TO_HANGUL) {
          r = r.split(k).join(v);
        }
        return r;
      });
    }
    t = t.replace(/\s+/g, ' ').trim();
  } else if (targetLang === 'zh') {
    t = t.replace(/\s+/g, ' ').trim();
  }

  return t || String(rawText || '').trim();
}

const _previewTranslationCache = {};

let _gtxActiveRequests = 0;
const _gtxWaitQueue = [];

async function _acquireGtxSlot() {
  if (_gtxActiveRequests < 3) {
    _gtxActiveRequests++;
    return;
  }
  await new Promise(resolve => _gtxWaitQueue.push(resolve));
  _gtxActiveRequests++;
}

function _releaseGtxSlot() {
  _gtxActiveRequests = Math.max(0, _gtxActiveRequests - 1);
  if (_gtxWaitQueue.length > 0) {
    const next = _gtxWaitQueue.shift();
    if (next) next();
  }
}

/**
 * 複数行テキストをAPIキー不要の翻訳エンドポイント(POST + チャンク分割)で確実に多言語翻訳する内部ヘルパー
 */
async function _translateLinesViaGtx(lines, targetLangCode) {
  if (!Array.isArray(lines) || lines.length === 0) return [];
  if (targetLangCode === 'ja') {
    const isModernOn = typeof isAozoraModernSuperTranslateEnabled === 'function' ? isAozoraModernSuperTranslateEnabled() : false;
    return lines.map(l => {
      const s = String(l || '');
      return (isModernOn && typeof translateSegmentToModernJapaneseOffline === 'function')
        ? translateSegmentToModernJapaneseOffline(s, '地の文')
        : s;
    });
  }
  const tlMap = { en: 'en', zh: 'zh-CN', ko: 'ko', es: 'es', fr: 'fr', pt: 'pt' };
  const tl = tlMap[targetLangCode] || targetLangCode;
  const gtxEndpoint = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=ja&tl=${encodeURIComponent(tl)}&dt=t`;

  const requestGtxChunk = async (joinedText) => {
    const bodyStr = `q=${encodeURIComponent(joinedText)}`;
    await _acquireGtxSlot();
    try {
      const useAndroidNative = (isAndroidApp || isAndroidAppNow()) && window.AndroidBridge;
      try {
        let res;
        if (useAndroidNative) {
          res = await nativeFetch(gtxEndpoint, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
            body: bodyStr,
            timeoutMs: 7500
          });
        } else {
          const controller = new AbortController();
          const timer = setTimeout(() => controller.abort(), 6500);
          try {
            res = await fetch(gtxEndpoint, {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
              body: bodyStr,
              signal: controller.signal
            });
          } finally {
            clearTimeout(timer);
          }
        }
        if (res && res.ok) {
          const data = await res.json();
          if (Array.isArray(data) && Array.isArray(data[0])) {
            return data[0].map(part => (Array.isArray(part) ? (part[0] || '') : '')).join('');
          }
        }
      } catch (postErr) {}

      // 短文時のみGETフォールバック
      if (joinedText.length <= 500) {
        const getUrl = `${gtxEndpoint}&q=${encodeURIComponent(joinedText)}`;
        try {
          let res2;
          if (useAndroidNative) {
            res2 = await nativeFetch(getUrl, { method: 'GET', timeoutMs: 5500 });
          } else {
            const controller2 = new AbortController();
            const timer2 = setTimeout(() => controller2.abort(), 5000);
            try {
              res2 = await fetch(getUrl, { signal: controller2.signal });
            } finally {
              clearTimeout(timer2);
            }
          }
          if (res2 && res2.ok) {
            const data2 = await res2.json();
            if (Array.isArray(data2) && Array.isArray(data2[0])) {
              return data2[0].map(part => (Array.isArray(part) ? (part[0] || '') : '')).join('');
            }
          }
        } catch (getErr) {}
      }
      return null;
    } finally {
      _releaseGtxSlot();
    }
  };

  // URL長制限・HTTP 400を完全に防ぐため最大8文・1200文字ごとにチャンク分割してPOST送信
  const results = new Array(lines.length).fill('');
  const chunks = [];
  let chunkIndices = [];
  let chunkTexts = [];
  let chunkCharLen = 0;

  for (let i = 0; i < lines.length; i++) {
    const cleanLine = String(lines[i] || '').replace(/\r?\n+/g, ' ').trim();
    if (!cleanLine) continue;
    if (chunkIndices.length >= 8 || (chunkCharLen + cleanLine.length > 1200 && chunkIndices.length > 0)) {
      chunks.push({ indices: chunkIndices, texts: chunkTexts });
      chunkIndices = [];
      chunkTexts = [];
      chunkCharLen = 0;
    }
    chunkIndices.push(i);
    chunkTexts.push(cleanLine);
    chunkCharLen += cleanLine.length;
  }
  if (chunkIndices.length > 0) {
    chunks.push({ indices: chunkIndices, texts: chunkTexts });
  }

  await Promise.all(chunks.map(async (chunk) => {
    const joined = chunk.texts.join('\n');
    const translatedJoined = await requestGtxChunk(joined);
    if (translatedJoined) {
      const splitLines = translatedJoined.replace(/\r/g, '').replace(/\n+$/, '').split('\n');
      if (splitLines.length === chunk.indices.length) {
        chunk.indices.forEach((origIdx, i) => {
          results[origIdx] = (splitLines[i] || '').trim();
        });
      } else {
        // 行数がずれた場合は1行ずつ確実に翻訳
        await Promise.all(chunk.indices.map(async (origIdx, i) => {
          const singleTrans = await requestGtxChunk(chunk.texts[i]);
          results[origIdx] = (singleTrans || '').trim();
        }));
      }
    }
  }));

  return results;
}

/**
 * 小説の冒頭プレビュー・試し読み・あらすじ等の任意テキストを選択言語（または現代語超訳）へ非同期翻訳する共通関数
 */
async function translatePreviewTextAsync(rawText, targetLangCode = null) {
  if (!rawText || typeof rawText !== 'string') return rawText || '';
  const lang = targetLangCode || (typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja');
  let cleaned = typeof resolveAozoraRubyAndNotesJs === 'function'
    ? resolveAozoraRubyAndNotesJs(rawText).displayText
    : rawText;
  cleaned = String(cleaned || '').trim();
  if (!cleaned) return '';

  // 日本語UI時: 現代語超訳モードがONなら現代日本語に変換、OFFならルビ除去済み原文を返す
  if (lang === 'ja') {
    if (typeof isAozoraModernSuperTranslateEnabled === 'function' && isAozoraModernSuperTranslateEnabled()) {
      return cleaned
        .split(/\r?\n/)
        .map(line => line.trim() ? translateSegmentToModernJapaneseOffline(line, '地の文') : '')
        .join('\n');
    }
    return cleaned;
  }

  const cacheKey = `${lang}::${cleaned.slice(0, 600)}`;
  if (_previewTranslationCache[cacheKey]) {
    return _previewTranslationCache[cacheKey];
  }

  const paragraphs = cleaned.split(/\r?\n/).map(p => p.trim());
  const nonEmptyIndices = [];
  const modernJaLines = [];
  paragraphs.forEach((p, idx) => {
    if (p) {
      nonEmptyIndices.push(idx);
      modernJaLines.push(translateSegmentToModernJapaneseOffline(p, '地の文'));
    }
  });

  if (nonEmptyIndices.length === 0) return cleaned;

  try {
    const translatedLines = await _translateLinesViaGtx(modernJaLines, lang);
    const outParagraphs = [...paragraphs];
    let hasValidTranslation = false;
    nonEmptyIndices.forEach((pIdx, i) => {
      const tr = translatedLines[i];
      if (tr) {
        outParagraphs[pIdx] = tr;
        hasValidTranslation = true;
      } else {
        outParagraphs[pIdx] = translateSegmentOnDeviceOffline(paragraphs[pIdx], '地の文', lang);
      }
    });
    const finalResult = outParagraphs.join('\n');
    if (hasValidTranslation) {
      _previewTranslationCache[cacheKey] = finalResult;
    }
    return finalResult;
  } catch (e) {
    console.warn('[PreviewTranslate] Fallback to offline lexicon:', e.message);
    return paragraphs
      .map(p => p ? translateSegmentOnDeviceOffline(p, '地の文', lang) : '')
      .join('\n');
  }
}

/**
 * オンデバイスLLM / ローカルLLM によるバッチ多言語翻訳・現代語超訳
 */
async function translateSegmentsWithOnDeviceLlm(batchItems, targetLangCode, systemPrompt, userPayload) {
  // 1. 外部ローカルLLMサーバー (Ollama / LM Studio) が選択・到達可能な場合は試行
  const preferred = document.getElementById('settingLlmProvider')?.value || localStorage.getItem('narou_ai_provider') || '';
  if (preferred === 'local_llm' && (typeof isLocalLlmInCooldown !== 'function' || !isLocalLlmInCooldown())) {
    const localUrl = (document.getElementById('settingLocalLlmUrl')?.value || localStorage.getItem('narou_local_llm_url') || 'http://127.0.0.1:11434/v1').replace(/\/+$/, '');
    const localModel = sanitizeCommercialLocalLlmModel(document.getElementById('settingLocalLlmModel')?.value || localStorage.getItem('narou_local_llm_model') || 'phi4-mini');
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 8000);
      const res = await fetch(`${localUrl}/chat/completions`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: localModel,
          temperature: 0.2,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPayload }
          ]
        }),
        signal: controller.signal
      });
      clearTimeout(timer);
      if (res.ok) {
        const data = await res.json();
        const rawText = data?.choices?.[0]?.message?.content || '[]';
        const cleaned = String(rawText).replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
        const parsed = JSON.parse(cleaned);
        const arr = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.segments) ? parsed.segments : []);
        if (arr.length > 0) return arr;
      }
    } catch (e) {
      console.warn('[OnDeviceLLM] Local server unreachable, using built-in translation engine:', e.message);
    }
  }

  // 2. 外国語翻訳 (en/zh/ko/es/fr/pt) でネットワーク接続がある場合は、POST + チャンク分割でHTTP 400を防ぎ全文を確実に翻訳
  if (targetLangCode && targetLangCode !== 'ja' && (typeof navigator === 'undefined' || navigator.onLine !== false)) {
    try {
      const modernLines = batchItems.map(item =>
        translateSegmentToModernJapaneseOffline(item.text, item.speaker).replace(/\r?\n+/g, ' ')
      );
      const transLines = await _translateLinesViaGtx(modernLines, targetLangCode);
      if (Array.isArray(transLines) && transLines.some(Boolean)) {
        return batchItems.map((item, idx) => ({
          i: item.idx,
          s: translateSpeakerOnDevice(item.speaker, targetLangCode),
          t: (transLines[idx] || '').trim() || translateSegmentOnDeviceOffline(item.text, item.speaker, targetLangCode)
        }));
      }
    } catch (gtxErr) {
      console.warn('[OnDeviceLLM] Free web translation fallback notice:', gtxErr.message);
    }
  }

  // 3. アプリ内包 オンデバイスAI 現代語超訳・オフライン多言語パイプライン（完全オフライン・即時応答）
  return batchItems.map((item) => ({
    i: item.idx,
    s: translateSpeakerOnDevice(item.speaker, targetLangCode),
    t: translateSegmentOnDeviceOffline(item.text, item.speaker, targetLangCode)
  }));
}

/**
 * 1バッチ分のセグメント配列をAI（クラウドAPI / ローカルLLM / オンデバイスLLM）で指定言語または現代語超訳に変換する
 */
async function translateSegmentsBatchWithCloudAi(batchItems, targetLangCode, gateInfo) {
  const langMeta = SUPPORTED_MAJOR_LANGUAGES[targetLangCode] || SUPPORTED_MAJOR_LANGUAGES.en;
  const novelTitle = state.currentNovel?.title || '';
  const systemPrompt = targetLangCode === 'ja'
    ? [
        `あなたは日本近代文学（青空文庫の明治・大正・昭和初期の小説）を、現代の読者・リスナーが耳で聴いてすぐ理解できる自然で魅力的な「現代日本語」に超訳する熟練の文芸翻訳家です。`,
        `【絶対厳守ルール】原文の文章を要約・省略・短縮・統合することは絶対に禁止です。一文一文すべての内容・描写・セリフを漏らさず1対1で現代日本語に書き換えてください。`,
        `旧仮名遣いや文語体、難解な古語・言い回しを、原作の情緒やキャラクターの個性・口調を保ったまま、わかりやすい現代日本語に書き換えてください。`,
        `必ず入力の segments と同じ要素数の有効なJSON配列のみを出力してください: [{"i": <number>, "s": "<話者名>", "t": "<要約・省略なしの現代語超訳テキスト>"}]。`,
        `Markdownコードブロックや説明文は一切含めないでください。`
      ].join(' ')
    : [
        `You are an expert literary novel translator.`,
        `Translate the following Japanese novel segments into ${langMeta.aiTargetName}.`,
        `CRITICAL RULE: NEVER summarize, abridge, omit, skip, or combine any sentences or details. Translate every single segment completely and faithfully 1-to-1.`,
        `Preserve character personalities, tone of dialogue, and emotional nuance.`,
        `Return ONLY a valid JSON array of objects with exact keys matching all input indices: [{"i": <number>, "s": "<translated speaker name>", "t": "<complete unabridged translated text>"}].`,
        `Do not wrap in markdown or add explanations.`
      ].join(' ');

  const userPayload = JSON.stringify({
    novel_title: novelTitle,
    target_language: langMeta.aiTargetName,
    segments: batchItems.map((item) => ({
      i: item.idx,
      s: item.speaker || '',
      t: item.text || ''
    }))
  });

  if (gateInfo.keyProvider === 'ondevice_llm' || gateInfo.keyProvider === 'local_llm') {
    return await translateSegmentsWithOnDeviceLlm(batchItems, targetLangCode, systemPrompt, userPayload);
  }

  const stored = typeof getSettingsFromStorage === 'function' ? getSettingsFromStorage() : {};
  let rawResponseText = '';

  if (gateInfo.keyProvider === 'gemini') {
    const modelName = document.getElementById('settingGeminiModel')?.value
      || document.getElementById('settingGeminiModelSelect')?.value
      || stored.gemini_model
      || localStorage.getItem('narou_gemini_model')
      || 'gemini-2.5-flash';
    const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(modelName)}:generateContent?key=${encodeURIComponent(gateInfo.apiKey)}`;
    const res = await nativeFetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ role: 'user', parts: [{ text: `${systemPrompt}\n\nINPUT JSON:\n${userPayload}` }] }],
        generationConfig: {
          temperature: 0.3,
          responseMimeType: 'application/json'
        }
      })
    });
    if (!res.ok) {
      const errTxt = await res.text().catch(() => '');
      throw new Error(`Gemini API Error (${res.status}): ${errTxt.slice(0, 140)}`);
    }
    const data = await res.json();
    rawResponseText = data?.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
  } else if (gateInfo.keyProvider === 'openai') {
    const modelName = (typeof resolveOpenaiModel === 'function' ? resolveOpenaiModel() : '')
      || document.getElementById('settingOpenaiModel')?.value
      || stored.openai_model
      || localStorage.getItem('narou_openai_model')
      || 'gpt-4o-mini';
    const res = await nativeFetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${gateInfo.apiKey}`
      },
      body: JSON.stringify({
        model: modelName,
        temperature: 0.3,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPayload }
        ]
      })
    });
    if (!res.ok) {
      const errTxt = await res.text().catch(() => '');
      throw new Error(`OpenAI API Error (${res.status}): ${errTxt.slice(0, 140)}`);
    }
    const data = await res.json();
    rawResponseText = data?.choices?.[0]?.message?.content || '[]';
  } else if (gateInfo.keyProvider === 'claude') {
    const modelName = (typeof resolveClaudeModel === 'function' ? resolveClaudeModel() : '')
      || document.getElementById('settingClaudeModel')?.value
      || stored.claude_model
      || localStorage.getItem('narou_claude_model')
      || 'claude-3-5-haiku-latest';
    const res = await nativeFetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': gateInfo.apiKey,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true'
      },
      body: JSON.stringify({
        model: modelName,
        max_tokens: 4096,
        system: systemPrompt,
        messages: [{ role: 'user', content: userPayload }]
      })
    });
    if (!res.ok) {
      const errTxt = await res.text().catch(() => '');
      throw new Error(`Claude API Error (${res.status}): ${errTxt.slice(0, 140)}`);
    }
    const data = await res.json();
    rawResponseText = data?.content?.[0]?.text || '[]';
  } else {
    return await translateSegmentsWithOnDeviceLlm(batchItems, targetLangCode, systemPrompt, userPayload);
  }

  const cleaned = String(rawResponseText).replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  const parsed = JSON.parse(cleaned);
  return Array.isArray(parsed) ? parsed : (Array.isArray(parsed.segments) ? parsed.segments : []);
}

let _aiTranslationRunId = 0;
let _activeAiTranslationCacheKey = '';

/**
 * 現在のエピソードをAI（クラウドまたはオンデバイスLLM）で選択言語または現代語超訳へ変換して読み上げを有効化する
 */
async function executeAiEpisodeTranslation(options = {}) {
  const gate = checkAiTranslationGateStatus();
  refreshAiTranslationModalGateUI();

  if (!gate.allowed) {
    if (!gate.hasApiKey && !gate.hasPremium) {
      if (typeof showToast === 'function') {
        showToast(tUi('toast_gate_both_required'), 'warning');
      }
      return;
    }
    if (!gate.hasApiKey) {
      if (typeof showToast === 'function') {
        showToast(tUi('toast_gate_key_required'), 'warning');
      }
      return;
    }
    if (!gate.hasPremium) {
      if (typeof showToast === 'function') {
        showToast(tUi('toast_gate_premium_required'), 'warning');
      }
      return;
    }
  }

  const targetLang = _selectedTargetTranslationLang || getEffectiveAppUiLanguage() || 'en';
  const shouldResumePlayback = options?.resumeIfWasPlaying !== undefined ? !!options.resumeIfWasPlaying : !!state.isPlaying;
  if (typeof pauseAudio === 'function') {
    pauseAudio();
  }
  if (!state.currentSegments || state.currentSegments.length === 0) {
    if (SUPPORTED_MAJOR_LANGUAGES[targetLang]) {
      onChangeAppUiLanguage(targetLang);
      closeAiTranslationModal();
      return;
    }
    if (typeof showToast === 'function') {
      showToast(tUi('toast_open_episode_first'), 'warning');
    }
    return;
  }

  const langMeta = SUPPORTED_MAJOR_LANGUAGES[targetLang] || SUPPORTED_MAJOR_LANGUAGES.en;
  const isModernJa = targetLang === 'ja';
  const actionLabel = isModernJa
    ? tUi('action_modern_ja')
    : tUi('action_translate_to', { name: langMeta.uiName || langMeta.nativeName });
  const ncode = state.currentNovel?.ncode || 'local';
  const epNum = state.currentEpisodeNum || 1;
  const cacheKey = `${ncode}_${epNum}_${targetLang}`;

  // 進行中の同一言語翻訳があれば重複起動を防止し、別言語への切替なら世代IDを進めて上書き実行
  if (_isAiTranslationRunning && _activeAiTranslationCacheKey === cacheKey) {
    return;
  }
  const myRunId = ++_aiTranslationRunId;
  _activeAiTranslationCacheKey = cacheKey;

  // キャッシュヒット確認
  if (_episodeTranslationMemoryCache[cacheKey]) {
    _isAiTranslationRunning = false;
    const cachedMap = _episodeTranslationMemoryCache[cacheKey];
    state.currentSegments.forEach((seg, idx) => {
      if (cachedMap[idx]) {
        seg.translated_text = cachedMap[idx].t;
        seg.translated_speaker = cachedMap[idx].s;
        seg.translated_lang = targetLang;
      }
    });
    state.currentTranslatedLang = targetLang;
    renderSegments();
    if (typeof updateMiniPlayer === 'function') updateMiniPlayer();
    if (typeof updateCarModeUI === 'function') updateCarModeUI();
    if (typeof updatePlayerStatusUI === 'function') updatePlayerStatusUI();
    refreshAiTranslationModalGateUI();
    if (!options?.isAuto) {
      closeAiTranslationModal();
      if (typeof showToast === 'function') {
        showToast(tUi('toast_applied_from_cache', { flag: langMeta.flag, action: actionLabel }), 'success');
      }
    }
    if (shouldResumePlayback && myRunId === _aiTranslationRunId) {
      state.isPlaying = true;
      if (typeof updatePlayPauseIcons === 'function') updatePlayPauseIcons();
      if (typeof playSegment === 'function') {
        playSegment(Number(state.currentSegmentIndex) || 0);
      }
    }
    return;
  }

  _isAiTranslationRunning = true;
  const progBox = document.getElementById('aiTranslationProgressBox');
  const progTxt = document.getElementById('aiTranslationProgressText');
  const progPct = document.getElementById('aiTranslationProgressPercent');
  const progBar = document.getElementById('aiTranslationProgressBar');
  const execBtn = document.getElementById('executeAiTranslateBtn');

  if (progBox) progBox.classList.remove('hidden');
  if (execBtn) execBtn.disabled = true;

  const total = state.currentSegments.length;
  const isInstantOnDeviceJa = (gate.keyProvider === 'ondevice_llm' && isModernJa);
  const translatedMap = {};

  const translateAndApplyBatch = async (batchStart, batchSize) => {
    if (myRunId !== _aiTranslationRunId) return false;
    const slice = state.currentSegments.slice(batchStart, batchStart + batchSize).map((seg, offset) => ({
      idx: batchStart + offset,
      speaker: seg.speaker || (seg.type === 'dialogue' ? '登場人物' : '地の文'),
      text: seg.display_text || ''
    }));

    const pct = Math.min(95, Math.round((batchStart / total) * 100));
    const rowMsg = tUi('prog_translating_rows', {
      flag: langMeta.flag,
      provider: gate.keyProviderLabel,
      action: actionLabel,
      start: batchStart + 1,
      end: Math.min(total, batchStart + batchSize),
      total
    });
    if (progTxt) progTxt.innerHTML = `<i class="ph-bold ph-spinner animate-spin"></i><span>${escapeHtml(rowMsg)}</span>`;
    if (progPct) progPct.textContent = `${pct}%`;
    if (progBar) progBar.style.width = `${pct}%`;

    let translatedItems;
    try {
      translatedItems = await translateSegmentsBatchWithCloudAi(slice, targetLang, gate);
    } catch (cloudErr) {
      console.warn('[AI Translation] Cloud API failed, falling back to On-Device LLM:', cloudErr);
      translatedItems = await translateSegmentsWithOnDeviceLlm(slice, targetLang, '', '');
    }
    if (myRunId !== _aiTranslationRunId) return false;

    const updatedIndices = [];
    translatedItems.forEach((row) => {
      const idx = Number(row.i);
      if (!Number.isNaN(idx) && state.currentSegments[idx] && row.t) {
        state.currentSegments[idx].translated_text = String(row.t).trim();
        state.currentSegments[idx].translated_speaker = String(row.s || state.currentSegments[idx].speaker || '').trim();
        state.currentSegments[idx].translated_lang = targetLang;
        translatedMap[idx] = {
          t: state.currentSegments[idx].translated_text,
          s: state.currentSegments[idx].translated_speaker
        };
        updatedIndices.push(idx);
      }
    });

    state.currentTranslatedLang = targetLang;
    if (typeof updateTranslatedSegmentsInDom === 'function' && document.querySelector('#segmentsContainer .segment-card')) {
      updateTranslatedSegmentsInDom(updatedIndices);
    } else if (!options?.awaitFirstBatchOnly || batchStart > 0) {
      renderSegments();
    }
    if (typeof updateMiniPlayer === 'function') updateMiniPlayer();
    if (typeof updateCarModeUI === 'function') updateCarModeUI();
    return true;
  };

  let start = 0;
  let manualNotifiedEarly = false;
  try {
    // 冒頭バッチ（最初の6文、現代語超訳時は40文）を優先翻訳して即座に画面反映する
    const firstBatchSize = Math.min(isInstantOnDeviceJa ? 40 : 6, total);
    const firstOk = await translateAndApplyBatch(0, firstBatchSize);
    if (!firstOk || myRunId !== _aiTranslationRunId) {
      if (myRunId === _aiTranslationRunId) {
        _isAiTranslationRunning = false;
        if (execBtn) execBtn.disabled = false;
        refreshAiTranslationModalGateUI();
      }
      return;
    }
    const curSegIdx = Number(state.currentSegmentIndex) || 0;
    if (curSegIdx >= firstBatchSize && curSegIdx < total) {
      await translateAndApplyBatch(curSegIdx, Math.min(isInstantOnDeviceJa ? 40 : 6, total - curSegIdx));
    }
    start = firstBatchSize;
    renderSegments();
    if (typeof updatePlayerStatusUI === 'function') updatePlayerStatusUI();
    refreshAiTranslationModalGateUI();
    if (!options?.isAuto) {
      manualNotifiedEarly = true;
      closeAiTranslationModal();
      if (typeof showToast === 'function') {
        showToast(
          isModernJa
            ? tUi('toast_completed_modern_ja', { provider: gate.keyProviderLabel })
            : tUi('toast_completed_lang', {
                flag: langMeta.flag,
                provider: gate.keyProviderLabel,
                nativeName: langMeta.uiName || langMeta.nativeName
              }),
          'success'
        );
      }
    }
    if (shouldResumePlayback && myRunId === _aiTranslationRunId) {
      state.isPlaying = true;
      if (typeof updatePlayPauseIcons === 'function') updatePlayPauseIcons();
      if (typeof playSegment === 'function') {
        playSegment(curSegIdx);
      }
    }
  } catch (firstErr) {
    if (myRunId === _aiTranslationRunId) {
      _isAiTranslationRunning = false;
      if (execBtn) execBtn.disabled = false;
      refreshAiTranslationModalGateUI();
    }
    console.error('[AI Translation First Batch Error]', firstErr);
    return;
  }

  const runRemainingBatches = async () => {
    try {
      const defaultBatchSize = isInstantOnDeviceJa ? 60 : 12;
      while (start < total) {
        // UIスレッドへ制御を返してスクロール・タップ操作のフリーズを防止
        await new Promise(r => setTimeout(r, 16));
        if (myRunId !== _aiTranslationRunId) return;
        const ok = await translateAndApplyBatch(start, defaultBatchSize);
        if (!ok || myRunId !== _aiTranslationRunId) return;
        start += defaultBatchSize;
      }

      if (myRunId !== _aiTranslationRunId) return;

      _episodeTranslationMemoryCache[cacheKey] = translatedMap;
      if (progPct) progPct.textContent = '100%';
      if (progBar) progBar.style.width = '100%';
      const doneMsg = tUi('prog_completed', {
        flag: langMeta.flag,
        action: actionLabel,
        provider: gate.keyProviderLabel
      });
      if (progTxt) progTxt.innerHTML = `<i class="ph-fill ph-check-circle text-emerald-400"></i><span>${escapeHtml(doneMsg)}</span>`;

      state.currentTranslatedLang = targetLang;
      if (typeof updateMiniPlayer === 'function') updateMiniPlayer();
      if (typeof updateCarModeUI === 'function') updateCarModeUI();
      if (typeof updatePlayerStatusUI === 'function') updatePlayerStatusUI();
      refreshAiTranslationModalGateUI();

      if (!options?.isAuto && !manualNotifiedEarly && typeof showToast === 'function') {
        showToast(
          isModernJa
            ? tUi('toast_completed_modern_ja', { provider: gate.keyProviderLabel })
            : tUi('toast_completed_lang', {
                flag: langMeta.flag,
                provider: gate.keyProviderLabel,
                nativeName: langMeta.uiName || langMeta.nativeName
              }),
          'success'
        );
      }
    } catch (err) {
      if (myRunId !== _aiTranslationRunId) return;
      console.error('[AI Translation Error]', err);
      if (progTxt) {
        progTxt.innerHTML = `<i class="ph-fill ph-warning-circle text-rose-400"></i><span class="text-rose-300">${escapeHtml(tUi('prog_error_prefix') + (err.message || String(err)))}</span>`;
      }
      if (typeof showToast === 'function') {
        showToast(`${tUi('toast_error_prefix')}${err.message || err}`, 'error');
      }
    } finally {
      if (myRunId === _aiTranslationRunId) {
        _isAiTranslationRunning = false;
        if (execBtn) execBtn.disabled = false;
        refreshAiTranslationModalGateUI();
      }
    }
  };

  if ((options?.awaitFirstBatchOnly || !options?.isAuto) && start < total) {
    // 冒頭バッチ完了後は即座に呼び出し元へ制御を返し、残りの文はバックグラウンドで差分更新する
    runRemainingBatches();
    return;
  }

  await runRemainingBatches();
}

function initMultiLanguageAndTranslationOnStartup() {
  state.bilingualDisplay = localStorage.getItem('narou_ai_trans_bilingual') !== 'false';
  const savedUiLang = localStorage.getItem('narou_app_ui_lang') || 'auto';
  applyAppUiLanguage(savedUiLang);
}

/* =========================================================
 * 切り替え状態の可視化 (Switch State Visibility)
 * - 設定上部の「現在の設定」サマリー (表示言語 / 音声エンジン / 本文)
 * - 表示言語・音声エンジン直下の「現在値」ライン
 * - 音声エンジンのカード型ラジオ (タップで即時反映)
 * - 翻訳モーダル: 「表示中」(実際に本文に適用中) と「選択中」(次に実行する対象) を区別
 * ========================================================= */
var SWITCH_STATE_I18N = {
  ja: {
    summary_title: '現在の設定', chip_ui_lang: '表示言語', chip_engine: '音声エンジン', chip_novel: '本文',
    mode_auto: '端末に自動追従', mode_fixed: '手動で固定',
    lang_line: '現在の表示: {flag} {name}',
    engine_line: '使用中: {icon} {name}',
    engine_hybrid: 'ハイブリッド', engine_native: '標準TTSのみ', engine_voicevox: 'VOICEVOXのみ',
    engine_hybrid_sub: 'セリフだけVOICEVOX', engine_native_sub: '即時再生・省電力', engine_voicevox_sub: '全編キャラボイス',
    novel_original: '原文 (日本語)', novel_modern: '現代語超訳', novel_translated: '{flag} {name}',
    auto_on: '自動翻訳 ON', auto_off: '自動翻訳 OFF',
    badge_showing: '表示中', badge_in_use: '✓ 使用中',
    toast_engine: '音声エンジンを「{name}」に切り替えました',
    toast_auto_trans_on: '自動AI翻訳を ON にしました', toast_auto_trans_off: '自動AI翻訳を OFF にしました',
    switch_on: 'ON', switch_off: 'OFF'
  },
  en: {
    summary_title: 'Current Settings', chip_ui_lang: 'Language', chip_engine: 'Voice Engine', chip_novel: 'Text',
    mode_auto: 'Follows device', mode_fixed: 'Set manually',
    lang_line: 'Now showing: {flag} {name}',
    engine_line: 'In use: {icon} {name}',
    engine_hybrid: 'Hybrid', engine_native: 'Standard TTS', engine_voicevox: 'VOICEVOX only',
    engine_hybrid_sub: 'Narration: TTS / Lines: VOICEVOX', engine_native_sub: 'Instant & battery saving', engine_voicevox_sub: 'All character voices',
    novel_original: 'Original (JA)', novel_modern: 'Modern JA', novel_translated: '{flag} {name}',
    auto_on: 'Auto-translate ON', auto_off: 'Auto-translate OFF',
    badge_showing: 'Showing', badge_in_use: '✓ In use',
    toast_engine: 'Voice engine switched to "{name}"',
    toast_auto_trans_on: 'Auto AI translation ON', toast_auto_trans_off: 'Auto AI translation OFF',
    switch_on: 'ON', switch_off: 'OFF'
  }
};

function sst(key, vars = {}) {
  if (!SWITCH_STATE_I18N) return key;
  const lang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const dict = lang === 'ja' ? SWITCH_STATE_I18N.ja : SWITCH_STATE_I18N.en;
  let str = dict[key] !== undefined ? dict[key] : (SWITCH_STATE_I18N.en[key] || key);
  Object.keys(vars).forEach((k) => { str = str.split(`{${k}}`).join(vars[k]); });
  return str;
}

var TTS_ENGINE_STATE_META = {
  hybrid_mix: { icon: '✨', key: 'engine_hybrid' },
  android_native: { icon: '📱', key: 'engine_native' },
  voicevox: { icon: '🎙️', key: 'engine_voicevox' }
};

function _setText(id, text) {
  const el = document.getElementById(id);
  if (el && el.textContent !== text) el.textContent = text;
}

function _flashStateEl(el) {
  if (!el) return;
  el.classList.remove('state-flash');
  void el.offsetWidth; // アニメーション再生用リフロー
  el.classList.add('state-flash');
}

var _lastSwitchStateSnapshot = null;

function refreshSwitchStateIndicators() {
  try {
    // 1. 表示言語
    const pref = localStorage.getItem('narou_app_ui_lang') || 'auto';
    const isAuto = pref === 'auto' || !SUPPORTED_MAJOR_LANGUAGES[pref];
    const effLang = getEffectiveAppUiLanguage();
    const lm = SUPPORTED_MAJOR_LANGUAGES[effLang] || SUPPORTED_MAJOR_LANGUAGES.ja;
    const langName = lm.uiName || lm.nativeName;
    const modeText = isAuto ? sst('mode_auto') : sst('mode_fixed');

    // 2. 音声エンジン (設定画面の選択値 → 未初期化時は保存値)
    const engineSel = document.getElementById('settingTtsEngine');
    const engine = (engineSel && engineSel.value) || getPreferredTtsEngine();
    const em = TTS_ENGINE_STATE_META[engine] || TTS_ENGINE_STATE_META.hybrid_mix;
    const engineName = sst(em.key);

    // 3. 本文 (原文 / 翻訳中) + 自動翻訳 ON/OFF
    const curTr = (typeof state !== 'undefined' && state) ? state.currentTranslatedLang : null;
    let novelText = sst('novel_original');
    if (curTr && SUPPORTED_MAJOR_LANGUAGES[curTr]) {
      const tm = SUPPORTED_MAJOR_LANGUAGES[curTr];
      novelText = curTr === 'ja' ? sst('novel_modern') : sst('novel_translated', { flag: tm.flag, name: tm.uiName || tm.nativeName });
    }
    const autoOn = typeof isAutoEpisodeTranslateEnabled === 'function' ? isAutoEpisodeTranslateEnabled() : false;

    // サマリー
    _setText('stateSummaryTitle', sst('summary_title'));
    _setText('stateChipUiLangLabel', sst('chip_ui_lang'));
    _setText('stateChipEngineLabel', sst('chip_engine'));
    _setText('stateChipNovelLabel', sst('chip_novel'));
    _setText('stateChipUiLang', `${lm.flag} ${langName}`);
    _setText('stateChipUiLangSub', modeText);
    _setText('stateChipEngine', `${em.icon} ${engineName}`);
    _setText('stateChipEngineSub', sst(`${em.key}_sub`));
    _setText('stateChipNovel', novelText);
    _setText('stateChipNovelSub', autoOn ? sst('auto_on') : sst('auto_off'));
    const novelChip = document.getElementById('stateChipNovelBtn');
    if (novelChip) novelChip.classList.toggle('is-active-state', !!curTr);

    // 表示言語の現在値ライン
    const langLine = document.getElementById('uiLangStatusLine');
    if (langLine) {
      langLine.innerHTML = '';
      const ic = document.createElement('i'); ic.className = 'ph-fill ph-check-circle';
      const main = document.createElement('span'); main.textContent = sst('lang_line', { flag: lm.flag, name: langName });
      const mode = document.createElement('span'); mode.className = 'ssl-mode'; mode.textContent = modeText;
      langLine.append(ic, main, mode);
    }

    // 音声エンジン: カード選択状態 + 現在値ライン
    document.querySelectorAll('.tts-engine-card[data-engine]').forEach((card) => {
      const on = card.getAttribute('data-engine') === engine;
      card.classList.toggle('is-selected', on);
      card.setAttribute('aria-checked', on ? 'true' : 'false');
      card.setAttribute('data-state-label', sst('badge_in_use'));
    });
    const engLine = document.getElementById('ttsEngineStatusLine');
    if (engLine) {
      engLine.innerHTML = '';
      const ic = document.createElement('i'); ic.className = 'ph-fill ph-check-circle';
      const main = document.createElement('span'); main.textContent = sst('engine_line', { icon: em.icon, name: engineName });
      engLine.append(ic, main);
    }

    // スイッチの ON/OFF 文言 (CSS ::before が参照)
    document.documentElement.style.setProperty('--switch-on-label', JSON.stringify(sst('switch_on')));
    document.documentElement.style.setProperty('--switch-off-label', JSON.stringify(sst('switch_off')));

    // 翻訳モーダル: 実際に本文へ適用中の言語に「表示中」バッジ
    ['en', 'zh', 'ko', 'es', 'fr', 'pt', 'de', 'th', 'ar', 'ja'].forEach((code) => {
      const btn = document.getElementById(`transTargetBtn-${code}`);
      if (!btn) return;
      btn.classList.toggle('is-current', code === curTr);
      btn.setAttribute('data-state-label', sst('badge_showing'));
    });
    // UI言語ボタン: 選択中に「✓ 使用中」バッジ
    document.querySelectorAll('.ui-lang-choice-btn').forEach((btn) => {
      btn.setAttribute('data-state-label', sst('badge_in_use'));
    });

    // 変化したチップを一瞬光らせて「切り替わった」ことを伝える
    const snap = { lang: `${effLang}|${isAuto}`, engine, novel: `${curTr}|${autoOn}` };
    if (_lastSwitchStateSnapshot) {
      if (snap.lang !== _lastSwitchStateSnapshot.lang) { _flashStateEl(document.getElementById('stateChipUiLangBtn')); _flashStateEl(langLine); }
      if (snap.engine !== _lastSwitchStateSnapshot.engine) { _flashStateEl(document.getElementById('stateChipEngineBtn')); _flashStateEl(engLine); }
      if (snap.novel !== _lastSwitchStateSnapshot.novel) { _flashStateEl(novelChip); }
    }
    _lastSwitchStateSnapshot = snap;
  } catch (e) {
    console.warn('[switch-state] refresh failed:', e);
  }
}

/** 音声エンジンカード: タップで即時反映 (保存ボタンを押さなくても次の発話から適用) */
function selectTtsEngineCard(engine) {
  if (!TTS_ENGINE_STATE_META[engine]) return;
  const sel = document.getElementById('settingTtsEngine');
  const prev = (sel && sel.value) || getPreferredTtsEngine();
  if (sel) sel.value = engine;
  try { localStorage.setItem('narou_tts_engine', engine); } catch (e) {}
  toggleTtsEngineFields();
  if (typeof scheduleImmediateSettingsSave === 'function') {
    scheduleImmediateSettingsSave({ debounceMs: 50 });
  }
  if (prev !== engine) {
    if (typeof vibrateFeedback === 'function') vibrateFeedback(10);
    if (typeof showMiniToast === 'function') {
      showMiniToast(sst('toast_engine', { name: `${TTS_ENGINE_STATE_META[engine].icon} ${sst(TTS_ENGINE_STATE_META[engine].key)}` }));
    }
  }
}

function scrollSettingIntoView(id) {
  const el = document.getElementById(id);
  if (!el) return;
  try { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (e) { el.scrollIntoView(); }
  _flashStateEl(el);
}

