function _getMasterWorksList() {
  if (typeof window !== 'undefined' && Array.isArray(window.AOZORA_MASTER_WORKS) && window.AOZORA_MASTER_WORKS.length > 0) {
    return window.AOZORA_MASTER_WORKS;
  }
  if (typeof AOZORA_MASTER_WORKS !== 'undefined' && Array.isArray(AOZORA_MASTER_WORKS)) {
    return AOZORA_MASTER_WORKS;
  }
  return [];
}

/** 文字数からおおよその読了・朗読時間を計算 (1分あたり約360文字) */
function _estimateReadingMinutes(lengthText) {
  if (!lengthText) return null;
  const m = String(lengthText).replace(/,/g, '').match(/約?(\d+)字/);
  if (!m) return null;
  const chars = parseInt(m[1], 10);
  if (isNaN(chars) || chars <= 0) return null;
  const mins = Math.max(1, Math.round(chars / 360));
  return mins;
}

/** ① 小説のランダム紹介 (5作品) の抽選＆レンダリング */
function renderRandomNovels(forceReshuffle = false) {
  const container = document.getElementById('randomNovelsContainer');
  if (!container) return;

  const masterList = _getMasterWorksList();
  if (!masterList || masterList.length === 0) return;

  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = effectiveLang === 'ja';

  // シャッフルまたは初回選出
  let selected = [];
  if (!forceReshuffle && _lastRandomWorkIds.length === 5) {
    selected = _lastRandomWorkIds.map(id => masterList.find(w => (w.id === id || w.ncode === id))).filter(Boolean);
  }
  if (selected.length < 5) {
    const pool = [...masterList];
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    // 前回の5作品と重複しすぎないように先頭5作品を取得
    selected = pool.slice(0, 5);
    _lastRandomWorkIds = selected.map(w => w.id || w.ncode);
  }

  const html = selected.map((w, idx) => {
    const loc = typeof getLocalizedAozoraWork === 'function' ? getLocalizedAozoraWork(w, effectiveLang) : { displayTitle: w.title, displayAuthor: w.author, displaySynopsis: w.synopsis, displayGenre: w.genre };
    const workId = w.id || w.ncode;
    const mins = _estimateReadingMinutes(w.lengthText);
    const readTimeBadge = mins ? `⏱️ 約${mins}分` : (w.lengthText || '名作短編');

    return `
      <div class="random-novel-card random-card-anim" style="animation-delay: ${idx * 0.05}s">
        <span class="random-card-badge">#${idx + 1}</span>
        <div onclick="openAozoraNovelToc('${workId}')" class="cursor-pointer">
          <h4 class="random-card-title" title="${escapeHtml(loc.displayTitle)}">${escapeHtml(loc.displayTitle)}</h4>
          <p class="random-card-author">${escapeHtml(loc.displayAuthor)}</p>
          <p class="random-card-synopsis">${escapeHtml(loc.displaySynopsis || w.synopsis || '')}</p>
        </div>
        <div>
          <div class="random-card-meta">
            <span class="truncate">${escapeHtml(loc.displayGenre || w.genre || '名作文学')}</span>
            <span class="font-mono shrink-0">${escapeHtml(readTimeBadge)}</span>
          </div>
          <div class="random-card-actions">
            <button type="button" onclick="quickReadAozoraNovel('${workId}')" class="random-card-play-btn" title="1タップですぐ朗読開始">
              <i class="ph-fill ph-play-circle text-sm"></i>
              <span>${isJa ? 'すぐ聴く' : 'Listen'}</span>
            </button>
            <button type="button" onclick="openAozoraNovelToc('${workId}')" class="random-card-toc-btn" title="目次・詳細を開く">
              <i class="ph-bold ph-list-dashes"></i>
              <span>${isJa ? '目次' : 'TOC'}</span>
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');

  container.innerHTML = html;
}

function shuffleRandomNovels(showFeedback = true) {
  if (typeof vibrateFeedback === 'function') vibrateFeedback(10);
  renderRandomNovels(true);
  if (showFeedback && typeof showMiniToast === 'function') {
    const isJa = (typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja') === 'ja';
    showMiniToast(isJa ? '🎲 新しい5作品をピックアップしました' : '🎲 Picked 5 new novels!');
  }
}

/** ② 気分を選択して小説を検索 */
function selectMoodAndSearch(moodKey) {
  if (!MOOD_PRESETS[moodKey]) return;
  if (typeof vibrateFeedback === 'function') vibrateFeedback(10);

  // 同じ気分の場合はトグル解除
  if (_activeMoodKey === moodKey) {
    clearMoodFilter();
    return;
  }

  _activeMoodKey = moodKey;
  const mood = MOOD_PRESETS[moodKey];
  const effectiveLang = typeof getEffectiveAppUiLanguage === 'function' ? getEffectiveAppUiLanguage() : 'ja';
  const isJa = effectiveLang === 'ja';
  const moodLabel = isJa ? mood.labelJa : mood.labelEn;
  const moodDesc = isJa ? mood.descJa : mood.descEn;

  // ボタンのハイライト更新
  document.querySelectorAll('.mood-picker-btn').forEach(btn => {
    btn.classList.toggle('is-active', btn.getAttribute('data-mood') === moodKey);
  });

  const clearBtn = document.getElementById('clearMoodBtn');
  if (clearBtn) clearBtn.classList.remove('hidden');

  const resultsArea = document.getElementById('moodResultsArea');
  const resultsGrid = document.getElementById('moodResultsGrid');
  const badgeEl = document.getElementById('moodResultBadge');
  const countEl = document.getElementById('moodResultCount');

  if (!resultsArea || !resultsGrid) return;

  const masterList = _getMasterWorksList();
  const matchedWorks = [];
  const seenIds = new Set();

  // workIds に完全一致する作品を優先
  mood.workIds.forEach(id => {
    const found = masterList.find(w => (w.id === id || w.ncode === id));
    if (found && !seenIds.has(found.id || found.ncode)) {
      seenIds.add(found.id || found.ncode);
      matchedWorks.push(found);
    }
  });

  if (badgeEl) {
    badgeEl.textContent = `${mood.icon} ${moodLabel}`;
  }
  if (countEl) {
    countEl.textContent = isJa ? `${matchedWorks.length}作品 (${moodDesc})` : `${matchedWorks.length} works (${moodDesc})`;
  }

  const superModeOn = isJa && (typeof isAozoraModernSuperTranslateEnabled === 'function' && isAozoraModernSuperTranslateEnabled());
  const foreignAutoOn = !isJa && (typeof isAutoEpisodeTranslateEnabled === 'function' && isAutoEpisodeTranslateEnabled());

  resultsGrid.innerHTML = matchedWorks.map(w => {
    const loc = typeof getLocalizedAozoraWork === 'function' ? getLocalizedAozoraWork(w, effectiveLang) : { displayTitle: w.title, displayAuthor: w.author, displaySynopsis: w.synopsis, displayGenre: w.genre };
    const workId = w.id || w.ncode;
    const mins = _estimateReadingMinutes(w.lengthText);
    const readTimeBadge = mins ? `⏱️ 約${mins}分` : (w.lengthText || '名作');

    const primaryBtnLabel = isJa
      ? (superModeOn ? '超訳で聴く' : '今すぐ聴く')
      : (foreignAutoOn ? 'Listen AI' : 'Listen');

    return `
      <div class="bg-slate-950/80 border border-slate-800 hover:border-rose-500/50 rounded-2xl p-3.5 flex flex-col justify-between transition shadow-md group">
        <div onclick="openAozoraNovelToc('${workId}')" class="cursor-pointer">
          <div class="flex items-center justify-between mb-1.5">
            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-900/60 text-rose-300 border border-rose-600/40 flex items-center space-x-1">
              <span>${mood.icon}</span>
              <span>${escapeHtml(moodLabel)}</span>
            </span>
            <span class="text-[10px] font-mono text-slate-400">${escapeHtml(readTimeBadge)}</span>
          </div>
          <h4 class="text-sm font-bold text-slate-100 group-hover:text-rose-400 transition leading-snug mb-0.5" title="${escapeHtml(loc.displayTitle)}">
            ${escapeHtml(loc.displayTitle)}
          </h4>
          <p class="text-xs text-slate-400 mb-2 font-medium">${escapeHtml(loc.displayAuthor)}</p>
          <p class="text-[11px] text-slate-300 leading-relaxed line-clamp-3 mb-3">
            ${escapeHtml(loc.displaySynopsis || w.synopsis || '')}
          </p>
        </div>
        <div class="pt-2 border-t border-slate-800/80 grid grid-cols-2 gap-2">
          <button type="button" onclick="quickReadAozoraNovel('${workId}')" class="w-full py-2 bg-gradient-to-r from-rose-600 to-indigo-600 hover:from-rose-500 hover:to-indigo-500 text-white rounded-xl text-xs font-bold shadow-md shadow-rose-600/25 flex items-center justify-center space-x-1.5 transition active:scale-95">
            <i class="ph-fill ph-play-circle text-sm"></i>
            <span>${primaryBtnLabel}</span>
          </button>
          <button type="button" onclick="openAozoraNovelToc('${workId}')" class="w-full py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-xl text-xs font-semibold flex items-center justify-center space-x-1 transition active:scale-95">
            <i class="ph-bold ph-list-dashes text-sm"></i>
            <span>${isJa ? '目次・詳細' : 'TOC'}</span>
          </button>
        </div>
      </div>
    `;
  }).join('');

  resultsArea.classList.remove('hidden');

  // スムーズスクロール
  try {
    resultsArea.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  } catch (e) {}

  if (typeof showMiniToast === 'function') {
    showMiniToast(isJa ? `${mood.icon} 【${moodLabel}】作品を${matchedWorks.length}作ピックアップ` : `${mood.icon} Picked ${matchedWorks.length} works for ${moodLabel}`);
  }
}

function clearMoodFilter() {
  _activeMoodKey = null;
  document.querySelectorAll('.mood-picker-btn').forEach(btn => btn.classList.remove('is-active'));
  const clearBtn = document.getElementById('clearMoodBtn');
  if (clearBtn) clearBtn.classList.add('hidden');
  const resultsArea = document.getElementById('moodResultsArea');
  if (resultsArea) resultsArea.classList.add('hidden');
}

// 起動フックとグローバル公開
window.renderRandomNovels = renderRandomNovels;
window.shuffleRandomNovels = shuffleRandomNovels;
window.selectMoodAndSearch = selectMoodAndSearch;
window.clearMoodFilter = clearMoodFilter;

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    setTimeout(renderRandomNovels, 100);
  });
} else {
  setTimeout(renderRandomNovels, 100);
}

