// =========================================================
// 🍔 ハンバーガーメニュー (Offcanvas Navigation Drawer) 制御
// =========================================================
function updateHamburgerDrawerStatus() {
  try {
    const langElem = document.getElementById('drawerStatusLang');
    if (langElem) {
      const curLang = (typeof currentUiLang !== 'undefined' ? currentUiLang : (localStorage.getItem('ui_language') || 'ja')).toUpperCase();
      const langNames = {
        JA: '日本語 (JA)',
        EN: 'English (EN)',
        ZH: '中文 (ZH)',
        KO: '한국어 (KO)',
        ES: 'Español (ES)',
        FR: 'Français (FR)',
        PT: 'Português (PT)'
      };
      langElem.textContent = langNames[curLang] || curLang;
    }

    const engineElem = document.getElementById('drawerStatusVoiceEngine');
    if (engineElem) {
      const engineMode = typeof state !== 'undefined' && state.ttsEngine ? state.ttsEngine : (localStorage.getItem('tts_engine') || 'voicevox');
      engineElem.textContent = engineMode.toUpperCase() === 'NATIVE' ? 'Native OS TTS' : 'VOICEVOX Native';
    }

    // テーマボタンのアクティブ状態同期
    const curTheme = (typeof state !== 'undefined' && state.readerTheme) ? state.readerTheme : (localStorage.getItem('narou_reader_theme') || 'dark');
    ['paper', 'sepia', 'dark', 'oled'].forEach(t => {
      const b = document.getElementById(`drawerThemeBtn-${t}`);
      if (b) {
        if (t === curTheme) {
          b.classList.add('active-theme');
        } else {
          b.classList.remove('active-theme');
        }
      }
    });

    // スリープタイマーの表示同期
    if (typeof updateSleepTimerUI === 'function') {
      updateSleepTimerUI();
    }

    // スリープタイマーボタンのアクティブ状態同期
    const isTimerActive = (typeof _sleepTimerTargetTimeMs !== 'undefined' && _sleepTimerTargetTimeMs > Date.now()) || (typeof window._sleepTimerEndOfEpisode !== 'undefined' && window._sleepTimerEndOfEpisode);
    const activeMins = isTimerActive && typeof _sleepTimerOriginalDurationMins !== 'undefined' ? _sleepTimerOriginalDurationMins : 0;
    [0, 15, 30, 60].forEach(m => {
      const b = document.getElementById(`drawerSleepBtn-${m}`);
      if (b) {
        if ((!isTimerActive && m === 0) || (isTimerActive && m === activeMins)) {
          b.classList.add('active-timer');
        } else {
          b.classList.remove('active-timer');
        }
      }
    });
  } catch (e) {
    console.debug('Drawer status update error:', e);
  }
}

function openHamburgerMenu() {
  const container = document.getElementById('hamburgerMenuContainer');
  const backdrop = document.getElementById('hamburgerBackdrop');
  const drawer = document.getElementById('hamburgerDrawer');
  const btn = document.getElementById('hamburgerMenuBtn');
  if (!container || !drawer) return;

  updateHamburgerDrawerStatus();
  container.classList.remove('hidden');

  requestAnimationFrame(() => {
    if (backdrop) backdrop.classList.remove('opacity-0');
    drawer.classList.remove('translate-x-full');
  });

  if (btn) btn.setAttribute('aria-expanded', 'true');
  document.body.style.overflow = 'hidden';
}

function closeHamburgerMenu() {
  const container = document.getElementById('hamburgerMenuContainer');
  const backdrop = document.getElementById('hamburgerBackdrop');
  const drawer = document.getElementById('hamburgerDrawer');
  const btn = document.getElementById('hamburgerMenuBtn');
  if (!container || !drawer) return;

  if (backdrop) backdrop.classList.add('opacity-0');
  drawer.classList.add('translate-x-full');
  if (btn) btn.setAttribute('aria-expanded', 'false');
  document.body.style.overflow = '';

  setTimeout(() => {
    container.classList.add('hidden');
  }, 280);
}

function toggleHamburgerMenu() {
  const container = document.getElementById('hamburgerMenuContainer');
  if (container && !container.classList.contains('hidden')) {
    closeHamburgerMenu();
  } else {
    openHamburgerMenu();
  }
}

// キーボードESCキーでハンバーガーメニューを閉じる
window.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    const container = document.getElementById('hamburgerMenuContainer');
    if (container && !container.classList.contains('hidden')) {
      closeHamburgerMenu();
    }
    const specModal = document.getElementById('featureSpecGuideModal');
    if (specModal && !specModal.classList.contains('hidden')) {
      closeFeatureSpecGuideModal();
    }
  }
});

// 公式全機能仕様書モーダル
function openFeatureSpecGuideModal() {
  const modal = document.getElementById('featureSpecGuideModal');
  if (modal) modal.classList.remove('hidden');
}

function closeFeatureSpecGuideModal() {
  const modal = document.getElementById('featureSpecGuideModal');
  if (modal) modal.classList.add('hidden');
}

// グローバル公開
window.openHamburgerMenu = openHamburgerMenu;
window.closeHamburgerMenu = closeHamburgerMenu;
window.toggleHamburgerMenu = toggleHamburgerMenu;
window.updateHamburgerDrawerStatus = updateHamburgerDrawerStatus;
window.openFeatureSpecGuideModal = openFeatureSpecGuideModal;
window.closeFeatureSpecGuideModal = closeFeatureSpecGuideModal;
window.updateReadingModeUI = updateReadingModeUI;
window.handleReadingModeQuickSwitch = handleReadingModeQuickSwitch;


